import tower;
import context;
import disassembly;
import import_bindings;
import import_values;
import text;
import .compiler.foundation_tags;
import .compiler.foundation_types;
import .library.vector;

// Disposable LLVM->entity associations only. There is no second Tower IR.
struct BackendImport {
    backend: Backend*;
    root: void*;
    function: void*;
    block: void*;
    declarations: void*;
    values: vector(BackendAssociation);
    literals: vector(BackendAssociation);
    blocks: vector(BackendAssociation);
    serial: u64;
}

fn bi_node(c: BackendImport*, kind: u32, scalar: u32): void* {
    var entity = sem_create(c.root);
    var n = sem_attach(entity, kind);
    n.type.scalar = scalar;
    n.type.pointer_bytes = c.backend.pointer_bytes;
    if scalar == 10 {
        n.type.scalar = 5;
        n.type.pointers = 1;
    }
    return entity;
}

fn bi_scalar(c: BackendImport*, type: void*): u32 {
    var kind = LLVMGetTypeKind(type);
    if kind == 0 {
        return 3;
    }
    if kind == 12 {
        return 10;
    }
    if kind == 8 {
        var width = LLVMGetIntTypeWidth(type);
        if width == 1 {
            return 2;
        }
        if width == 8 {
            return 5;
        }
        if width <= 32 {
            return 1;
        }
        if width <= 64 {
            return 7;
        }
    }
    backend_fail(c.backend, "LLVM return path requires a supported scalar type");
    return 7;
}

fn bi_name(c: BackendImport*, entity: void*, prefix: u8*): void {
    var n = sem_get(entity);
    loop {
        n.name.length = 0;
        backend_text(&n.name, prefix);
        backend_decimal(&n.name, c.serial);
        c.serial++;
        var collision = false;
        for(var i: usize = 0; i != c.backend.source_functions.length; i++) {
            var original = sem_get(c.backend.source_functions.data[i]);
            if backend_equal(backend_name(original), n.name.data) {
                collision = true;
            }
        }
        if !collision {
            return;
        }
    }
}

fn bi_append(c: BackendImport*, block: void*, entity: void*): void {
    var n = sem_get(block);
    backend_require(c.backend, vector_push(void*, &n.items, entity));
}

fn bi_const(c: BackendImport*, scalar: u32, value: u64): void* {
    var entity = bi_node(c, 5, scalar);
    var n = sem_get(entity);
    n.constant = true;
    n.bits = value;
    return entity;
}

// An LLVM constant needs a typed Foundation binding: a bare literal loses its
// source width in bits/convert and in comparisons during text reconstruction.
// Initialize each distinct literal once in the function's declaration prefix,
// so every branch can reuse it without depending on which branch executes first.
fn bi_literal(c: BackendImport*, key: void*, scalar: u32, bits: u64): void* {
    var local = backend_find(&c.literals, key);
    if local == null {
        local = bi_decl(c, scalar);
        var declaration = sem_get(local);
        declaration.value = bi_const(c, scalar, bits);
        backend_require(c.backend, backend_associate(&c.literals, key, local));
    }
    return bi_ref(c, local);
}

fn bi_ref(c: BackendImport*, binding: void*): void* {
    var b = sem_get(binding);
    var entity = bi_node(c, 5, b.type.scalar);
    var n = sem_get(entity);
    copy(&n.type, &b.type, sizeof(FoundationType));
    n.binding = binding;
    return entity;
}

fn bi_decl(c: BackendImport*, scalar: u32): void* {
    var entity = bi_node(c, 3, scalar);
    bi_name(c, entity, "v");
    bi_append(c, c.declarations, entity);
    return entity;
}

fn bi_assign(c: BackendImport*, target: void*, value: void*): void {
    var entity = bi_node(c, 4, 3);
    var n = sem_get(entity);
    n.target = target;
    n.value = value;
    bi_append(c, c.block, entity);
}

// Materialize every non-operand expression: foundation remains three-address.
fn bi_temp(c: BackendImport*, expression: void*): void* {
    var n = sem_get(expression);
    var local = bi_decl(c, n.type.scalar);
    var d = sem_get(local);
    copy(&d.type, &n.type, sizeof(FoundationType));
    bi_assign(c, bi_ref(c, local), expression);
    return bi_ref(c, local);
}

// Each LLVM instruction already has a destination local for forward references.
// Use it for the final temporary produced while importing this instruction,
// instead of emitting a second declaration, assignment and read of the result.
// Only the freshly created, final assignment qualifies; branch results, shared
// literals and existing bindings retain their ordinary copy.
fn bi_result(c: BackendImport*, destination: void*, value: void*, first_local: usize): void {
    var result = sem_get(value);
    var declarations = sem_get(c.declarations);
    var block = sem_get(c.block);
    var candidate = result.kind == KOperand();
    if result.constant {
        candidate = false;
    }
    if !(declarations.items.length > first_local) {
        candidate = false;
    }
    if block.items.length == 0 {
        candidate = false;
    }
    if candidate {
        var last_local = declarations.items.length -1;
        var local = declarations.items.data[last_local];
        var matches = result.binding == local;
        if matches {
            var last_statement = block.items.length -1;
            var assignment = sem_get(block.items.data[last_statement]);
            matches = assignment.kind == KAssign();
            if matches {
                var target = sem_get(assignment.target);
                matches = target.kind == KOperand();
                matches &&= target.binding == local;
                var original = sem_get(destination);
                matches &&= semantic_type_equal(&original.type, &result.type);
                if matches {
                    assignment.target = bi_ref(c, destination);
                    declarations.items.length = last_local;
                    return;
                }
            }
        }
    }
    bi_assign(c, bi_ref(c, destination), value);
}

fn bi_cast(c: BackendImport*, value: void*, scalar: u32, reinterpret: bool): void* {
    var entity = bi_node(c, 9, scalar);
    var n = sem_get(entity);
    if reinterpret {
        n.kind = 10;
    }
    n.value = value;
    var v = sem_get(value);
    var boolean = n.type.scalar == 2;
    if v.type.scalar == 2 {
        boolean = true;
    }
    var numeric = n.type.pointers == 0;
    numeric &&= v.type.pointers == 0;
    if boolean {
        if numeric {
            reinterpret = false;
            n.kind = 9;
        }
    }
    var same = n.type.scalar == v.type.scalar;
    var pointers = n.type.pointers == v.type.pointers;
    if same {
        if pointers {
            return value;
        }
    }
    if !reinterpret {
        var width = semantic_width(&n.type);
        var source_width = semantic_width(&v.type);
        if width < source_width {
            // LLVM trunc is modular. Foundation convert is checked, so mask
            // before the conversion instead of introducing a range trap.
            var unsigned_value = bi_cast(c, value, 7, false);
            var mask = bi_pow2(width) -1;
            unsigned_value = bi_binary(c, 5, unsigned_value, bi_const(c, 7, mask), 7);
            n.value = unsigned_value;
        }
    }
    return bi_temp(c, entity);
}

fn bi_binary(c: BackendImport*, op: u32, left: void*, right: void*, scalar: u32): void* {
    var input = sem_get(left);
    var boolean = input.type.scalar == 2;
    var arithmetic = op < 8;
    if boolean {
        if arithmetic {
            left = bi_cast(c, left, 5, false);
            right = bi_cast(c, right, 5, false);
            var result = bi_binary(c, op, left, right, 5);
            result = bi_binary(c, 5, result, bi_const(c, 5, 1), 5);
            return bi_cast(c, result, scalar, false);
        }
    }
    var entity = bi_node(c, 6, scalar);
    var n = sem_get(entity);
    n.op = op;
    n.left = left;
    n.right = right;
    return bi_temp(c, entity);
}

fn bi_cast_type(c: BackendImport*, value: void*, type: FoundationType*): void* {
    var entity = bi_node(c, 10, type.scalar);
    var n = sem_get(entity);
    copy(&n.type, type, sizeof(FoundationType));
    n.value = value;
    var input = sem_get(value);
    var boolean = type.scalar == 2;
    if input.type.scalar == 2 {
        boolean = true;
    }
    var numeric = type.pointers == 0;
    numeric &&= input.type.pointers == 0;
    if boolean {
        if numeric {
            n.kind = 9;
        }
    }
    return bi_temp(c, entity);
}

fn bi_address(c: BackendImport*, object: void*): void* {
    var entity = bi_node(c, 7, 10);
    var n = sem_get(entity);
    var v = sem_get(object);
    copy(&n.type, &v.type, sizeof(FoundationType));
    n.type.pointers++;
    n.value = object;
    // The address of this fixed storage is already a Foundation operand.
    return bi_cast(c, entity, 10, true);
}

fn bi_storage(c: BackendImport*, bytes: u64, alignment: u32, global: bool): void* {
    var scalar: u32 = 5;
    var unit: u64 = 1;
    var wide = alignment > 4;
    if wide {
        scalar = 7;
        unit = 8;
    }
    else {
        wide = alignment > 1;
        if wide {
            scalar = 1;
            unit = 4;
        }
    }
    if alignment > 8 {
        backend_fail(c.backend, "LLVM allocation alignment exceeds foundation layout");
    }
    var array = bi_node(c, 19, 9);
    var a = sem_get(array);
    a.element.scalar = scalar;
    a.element.pointer_bytes = c.backend.pointer_bytes;
    bytes = bytes + unit;
    bytes--;
    var count = bytes / unit;
    if count == 0 {
        count = 1;
    }
    a.length = convert(usize, count);
    a.type.record = array;
    var entity = bi_node(c, 3, 9);
    var n = sem_get(entity);
    n.type.record = array;
    bi_name(c, entity, "storage");
    if global {
        bi_append(c, c.root, entity);
    }
    else {
        bi_append(c, c.declarations, entity);
    }
    return entity;
}

fn bi_typed_pointer(c: BackendImport*, value: void*, scalar: u32): void* {
    var entity = bi_node(c, 10, scalar);
    var n = sem_get(entity);
    n.type.pointers++;
    n.value = value;
    return bi_temp(c, entity);
}

fn bi_load(c: BackendImport*, address: void*, scalar: u32): void* {
    var pointer = bi_typed_pointer(c, address, scalar);
    var entity = bi_node(c, 8, scalar);
    var n = sem_get(entity);
    n.value = pointer;
    return bi_temp(c, entity);
}

fn bi_store(c: BackendImport*, address: void*, value: void*): void {
    var v = sem_get(value);
    var scalar = v.type.scalar;
    if v.type.pointers != 0 {
        scalar = 10;
    }
    var typed = bi_typed_pointer(c, address, scalar);
    var target = bi_node(c, 8, scalar);
    var n = sem_get(target);
    n.value = typed;
    bi_assign(c, target, value);
}

fn bi_offset(c: BackendImport*, pointer: void*, bytes: void*): void* {
    var integer = bi_cast(c, pointer, 8, true);
    bytes = bi_cast(c, bytes, 8, false);
    integer = bi_binary(c, 0, integer, bytes, 8);
    return bi_cast(c, integer, 10, true);
}

fn bi_if(c: BackendImport*, condition: void*): void* {
    var entity = bi_node(c, 13, 3);
    var n = sem_get(entity);
    n.value = condition;
    n.body = bi_node(c, 12, 3);
    n.otherwise = bi_node(c, 12, 3);
    bi_append(c, c.block, entity);
    return entity;
}

import tower;
import bindings;
import context;
import disassembly;
import import_bindings;
import import_foundation;
import import_values;
import text;
import .compiler.foundation_tags;
import .compiler.foundation_types;
import .library.vector;

fn bi_edge(c: BackendImport*, from: void*, to: void*): void {
    var copies: vector(BackendAssociation);
    vector_init(BackendAssociation, &copies);
    var instruction = LLVMGetFirstInstruction(to);
    loop {
        var done = instruction == null;
        if done {
            break;
        }
        done = LLVMGetInstructionOpcode(instruction) != 44;
        if done {
            break;
        }
        var count = LLVMCountIncoming(instruction);
        var i: u32 = 0;
        loop {
            done = i == count;
            if done {
                break;
            }
            if LLVMGetIncomingBlock(instruction, i) == from {
                var value = bi_value(c, LLVMGetIncomingValue(instruction, i));
                var snapshot = bi_decl(c, bi_scalar(c, LLVMTypeOf(instruction)));
                bi_assign(c, bi_ref(c, snapshot), value);
                var destination = backend_find(&c.values, instruction);
                backend_require(c.backend, backend_associate(&copies, destination, snapshot));
                break;
            }
            i++;
        }
        instruction = LLVMGetNextInstruction(instruction);
    }
    var index: usize = 0;
    for(; index != copies.length; index++) {
        var pair = &copies.data[index];
        bi_assign(c, bi_ref(c, pair.entity), bi_ref(c, pair.value));
    }
    vector_dispose(BackendAssociation, &copies);
    var target = backend_find(&c.blocks, to);
    var label = sem_get(target);
    var entity = bi_node(c, 32, 3);
    var jump = sem_get(entity);
    backend_text(&jump.name, label.name.data);
    jump.binding = target;
    bi_append(c, c.block, entity);
}

fn bi_print(c: BackendImport*, value: void*, code: u32): void {
    var scalar = code;
    if code == 3 {
        value = bi_cast(c, value, 8, false);
        value = bi_cast(c, value, 10, true);
    } else {
        var signed = code == 0;
        if signed {
            value = bi_cast(c, value, 1, false);
            value = bi_cast(c, value, 0, true);
        } else {
            signed = code == 6;
            value = bi_cast(c, value, scalar, signed);
        }
    }
    var entity = bi_node(c, 17, 3);
    var n = sem_get(entity);
    n.value = value;
    bi_append(c, c.block, entity);
}

fn bi_call(c: BackendImport*, instruction: void*): void* {
    var callee = LLVMGetCalledValue(instruction);
    var length: usize = 0;
    var name = LLVMGetValueName2(callee, &length);
    if backend_equal(name, "tower_print") {
        var code = LLVMGetOperand(instruction, 0);
        var value = bi_value(c, LLVMGetOperand(instruction, 1));
        if LLVMGetValueKind(code) == 18 {
            bi_print(c, value, convert(u32, LLVMConstIntGetZExtValue(code)));
        }
        else {
            code = bi_value(c, code);
            for(var i: u32 = 0; i != 9; i++) {
                if i != 4 {
                    var test = bi_binary(c, 8, code, bi_const(c, 1, convert(u64, i)), 2);
                    var outer = c.block;
                    var branch = sem_get(bi_if(c, test));
                    c.block = branch.body;
                    bi_print(c, value, i);
                    c.block = outer;
                }
            }
        }
        return null;
    }
    if backend_equal(name, "tower_trap") {
        var entity = bi_node(c, 33, 3);
        var n = sem_get(entity);
        n.left = bi_value(c, LLVMGetOperand(instruction, 0));
        n.right = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, 1)), 1, false);
        bi_append(c, c.block, entity);
        return null;
    }
    var allocating = backend_equal(name, "tower_allocate");
    var reallocating = backend_equal(name, "tower_reallocate");
    var deallocating = backend_equal(name, "tower_deallocate");
    var memory = allocating;
    if reallocating {
        memory = true;
    }
    if deallocating {
        memory = true;
    }
    if memory {
        var kind: u32 = 26;
        if reallocating {
            kind = 27;
        }
        if deallocating {
            kind = 28;
        }
        var entity = bi_node(c, kind, 10);
        var n = sem_get(entity);
        var offset: u32 = 0;
        n.element.scalar = 5;
        n.element.pointer_bytes = c.backend.pointer_bytes;
        if !allocating {
            n.left = bi_value(c, LLVMGetOperand(instruction, 0));
            offset = 1;
        }
        if deallocating {
            n.type.scalar = 3;
            n.type.pointers = 0;
            bi_append(c, c.block, entity);
            return null;
        }
        var count = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, offset)), 8, false);
        offset++;
        var size = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, offset)), 8, false);
        // The generated runtime guards this product. Preserve failure as null
        // for overflow without allocating a wrapped, smaller object.
        var product = bi_binary(c, 2, count, size, 8);
        var safe_size = bi_select(c, bi_binary(c, 8, size, bi_const(c, 8, 0), 2), bi_const(c, 8, 1), size, 8);
        var restored = bi_binary(c, 3, product, safe_size, 8);
        var overflow = bi_binary(c, 9, restored, count, 2);
        var nonzero_size = bi_binary(c, 9, size, bi_const(c, 8, 0), 2);
        overflow = bi_binary(c, 5, overflow, nonzero_size, 2);
        var result = bi_decl(c, 10);
        var outer = c.block;
        var branch = sem_get(bi_if(c, overflow));
        c.block = branch.body;
        bi_assign(c, bi_ref(c, result), bi_const(c, 10, 0));
        c.block = branch.otherwise;
        n.right = product;
        bi_assign(c, bi_ref(c, result), entity);
        c.block = outer;
        return bi_ref(c, result);
    }
    var copy = backend_prefix(name, "llvm.memcpy.");
    if backend_prefix(name, "llvm.memmove.") {
        copy = true;
    }
    var fill_memory = backend_prefix(name, "llvm.memset.");
    memory = copy;
    if fill_memory {
        memory = true;
    }
    if memory {
        var kind: u32 = 29;
        if fill_memory {
            kind = 30;
        }
        var entity = bi_node(c, kind, 3);
        var n = sem_get(entity);
        n.left = bi_value(c, LLVMGetOperand(instruction, 0));
        n.right = bi_value(c, LLVMGetOperand(instruction, 1));
        n.value = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, 2)), 8, false);
        var volatile_flag = LLVMGetOperand(instruction, 3);
        if LLVMIsNull(volatile_flag) == 0 {
            backend_fail(c.backend, "Volatile LLVM memory requires an explicit foundation contract");
        }
        bi_append(c, c.block, entity);
        return null;
    }
    var ignored = backend_prefix(name, "llvm.lifetime.");
    if backend_equal(name, "llvm.assume") {
        ignored = true;
    }
    if ignored {
        return null;
    }
    // InstCombine recognizes these ordinary scalar idioms even without target
    // vectorization. Legalize their bit semantics; do not re-optimize the graph.
    if backend_prefix(name, "llvm.ctpop.") {
        var type = LLVMTypeOf(instruction);
        if !(LLVMGetTypeKind(type) == 8) {
            backend_fail(c.backend, "Population count reconstruction requires a scalar integer");
            return null;
        }
        var width = LLVMGetIntTypeWidth(type);
        if !(width <= 64) {
            backend_fail(c.backend, "Population count reconstruction supports up to 64 bits");
            return null;
        }
        var scalar = bi_scalar(c, type);
        var value = bi_mask(c, bi_value(c, LLVMGetOperand(instruction, 0)), type);
        // Sum adjacent bit groups, doubling their width each step. The masks
        // also cover non-power-of-two LLVM widths without out-of-range shifts.
        var group: u32 = 1;
        while group < width {
            var mask: u64 = 0;
            var bit: u64 = 1;
            for(var position: u32 = 0; position < width; position++) {
                var part = position / group;
                part = part % 2;
                var low = part == 0;
                if low {
                    mask = mask | bit;
                }
                bit = bit * 2;
            }
            var low = bi_binary(c, OAnd(), value, bi_const(c, scalar, mask), scalar);
            var high = bi_binary(c, ODiv(), value, bi_const(c, scalar, bi_pow2(group)), scalar);
            high = bi_binary(c, OAnd(), high, bi_const(c, scalar, mask), scalar);
            value = bi_binary(c, OAdd(), low, high, scalar);
            group = group * 2;
        }
        return value;
    }
    if backend_prefix(name, "llvm.abs.") {
        var type = LLVMTypeOf(instruction);
        var scalar = bi_scalar(c, type);
        var a = bi_value(c, LLVMGetOperand(instruction, 0));
        var sign_width = LLVMGetIntTypeWidth(type) -1;
        var negative = bi_binary(c, 13, a, bi_const(c, scalar, bi_pow2(sign_width)), 2);
        var negated = bi_mask(c, bi_binary(c, 1, bi_const(c, scalar, 0), a, scalar), type);
        return bi_select(c, negative, negated, a, scalar);
    }
    var unsigned_add = backend_prefix(name, "llvm.uadd.sat.");
    var unsigned_subtract = backend_prefix(name, "llvm.usub.sat.");
    var signed_add = backend_prefix(name, "llvm.sadd.sat.");
    var signed_subtract = backend_prefix(name, "llvm.ssub.sat.");
    var saturating = unsigned_add;
    if unsigned_subtract {
        saturating = true;
    }
    if signed_add {
        saturating = true;
    }
    if signed_subtract {
        saturating = true;
    }
    if saturating {
        var type = LLVMTypeOf(instruction);
        var scalar = bi_scalar(c, type);
        var a = bi_value(c, LLVMGetOperand(instruction, 0));
        var b = bi_value(c, LLVMGetOperand(instruction, 1));
        var subtract = unsigned_subtract;
        if signed_subtract {
            subtract = true;
        }
        var operation: u32 = 0;
        if subtract {
            operation = 1;
        }
        var result = bi_mask(c, bi_binary(c, operation, a, b, scalar), type);
        var width = LLVMGetIntTypeWidth(type);
        if unsigned_add {
            var overflow = bi_binary(c, 10, result, a, 2);
            var maximum = bi_pow2(width) -1;
            return bi_select(c, overflow, bi_const(c, scalar, maximum), result, scalar);
        }
        if unsigned_subtract {
            var overflow = bi_binary(c, 10, a, b, 2);
            return bi_select(c, overflow, bi_const(c, scalar, 0), result, scalar);
        }
        var changed = bi_binary(c, 7, a, result, scalar);
        var other = bi_binary(c, 7, b, result, scalar);
        if subtract {
            other = bi_binary(c, 7, a, b, scalar);
        }
        changed = bi_binary(c, 5, changed, other, scalar);
        var sign_width = width -1;
        var sign = bi_pow2(sign_width);
        var overflow = bi_binary(c, 13, changed, bi_const(c, scalar, sign), 2);
        var negative = bi_binary(c, 13, a, bi_const(c, scalar, sign), 2);
        var maximum = sign -1;
        var limit = bi_select(c, negative, bi_const(c, scalar, sign), bi_const(c, scalar, maximum), scalar);
        return bi_select(c, overflow, limit, result, scalar);
    }
    var minimum = backend_prefix(name, "llvm.umin.");
    var maximum = backend_prefix(name, "llvm.umax.");
    var signed_minimum = backend_prefix(name, "llvm.smin.");
    var signed_maximum = backend_prefix(name, "llvm.smax.");
    var minmax = minimum;
    if maximum {
        minmax = true;
    }
    if signed_minimum {
        minmax = true;
    }
    if signed_maximum {
        minmax = true;
    }
    if minmax {
        var a = bi_value(c, LLVMGetOperand(instruction, 0));
        var b = bi_value(c, LLVMGetOperand(instruction, 1));
        var predicate: u32 = 36;
        if maximum {
            predicate = 34;
        }
        if signed_minimum {
            predicate = 40;
        }
        if signed_maximum {
            predicate = 38;
        }
        var type = LLVMTypeOf(instruction);
        var condition = bi_compare(c, predicate, a, b, type);
        return bi_select(c, condition, a, b, bi_scalar(c, type));
    }
    var binding = backend_find(&c.values, callee);
    if binding == null {
        backend_fail(c.backend, "Unsupported LLVM intrinsic or indirect call: ");
        backend_text(&c.backend.error, name);
        return null;
    }
    var entity = bi_node(c, 11, bi_scalar(c, LLVMTypeOf(instruction)));
    var n = sem_get(entity);
    n.binding = binding;
    var function = sem_get(binding);
    copy(&n.type, &function.type, sizeof(FoundationType));
    var count = LLVMGetNumArgOperands(instruction);
    var i: u32 = 0;
    for(; i != count; i++) {
        var value = bi_value(c, LLVMGetOperand(instruction, i));
        var parameter = sem_get(function.parameters.data[convert(usize, i)]);
        value = bi_cast_type(c, value, &parameter.type);
        backend_require(c.backend, vector_push(void*, &n.items, value));
    }
    if n.type.scalar == 3 {
        bi_append(c, c.block, entity);
        return null;
    }
    return bi_cast(c, bi_temp(c, entity), bi_scalar(c, LLVMTypeOf(instruction)), true);
}

fn bi_instruction(c: BackendImport*, instruction: void*, block: void*): void* {
    var op = LLVMGetInstructionOpcode(instruction);
    var type = LLVMTypeOf(instruction);
    var scalar = bi_scalar(c, type);
    var selected = op == 1;
    if selected {
        var entity = bi_node(c, 18, 3);
        var n = sem_get(entity);
        if LLVMGetNumOperands(instruction) != 0 {
            n.value = bi_value(c, LLVMGetOperand(instruction, 0));
            var function = sem_get(c.function);
            n.value = bi_cast_type(c, n.value, &function.type);
        }
        bi_append(c, c.block, entity);
        return null;
    }
    selected = op == 2;
    if selected {
        if LLVMGetNumSuccessors(instruction) == 2 {
            var condition = bi_value(c, LLVMGetCondition(instruction));
            var outer = c.block;
            var branch = sem_get(bi_if(c, condition));
            c.block = branch.body;
            bi_edge(c, block, LLVMGetSuccessor(instruction, 0));
            c.block = branch.otherwise;
            bi_edge(c, block, LLVMGetSuccessor(instruction, 1));
            c.block = outer;
        } else {
            bi_edge(c, block, LLVMGetSuccessor(instruction, 0));
        }
        return null;
    }
    selected = op == 7;
    if selected {
        // A defined Tower execution reaches unreachable only after an explicit
        // trap. Retain a deterministic diagnostic for corrupted/undefined input.
        var entity = bi_node(c, 33, 3);
        var n = sem_get(entity);
        var message = bi_node(c, 23, 10);
        var text = sem_get(message);
        backend_text(&text.name, "Reached unreachable LLVM block");
        n.left = message;
        n.right = bi_const(c, 1, 0);
        bi_append(c, c.block, entity);
        return null;
    }
    selected = op == 44;
    if selected {
        return null;
    }
    selected = op == 45;
    if selected {
        return bi_call(c, instruction);
    }
    selected = op == 29;
    if selected {
        return bi_gep(c, instruction);
    }
    selected = op == 26;
    if selected {
        var count = LLVMGetOperand(instruction, 0);
        if !(LLVMGetValueKind(count) == 18) {
            backend_fail(c.backend, "Dynamic LLVM alloca cannot be represented by a static foundation local");
            return bi_const(c, 10, 0);
        }
        var bytes = LLVMABISizeOfType(c.backend.layout, LLVMGetAllocatedType(instruction));
        bytes = bytes * LLVMConstIntGetZExtValue(count);
        var storage = bi_storage(c, bytes, LLVMGetAlignment(instruction), false);
        return bi_address(c, bi_ref(c, storage));
    }
    selected = op == 28;
    var load = op == 27;
    if load {
        selected = true;
    }
    if selected {
        var invalid = LLVMGetVolatile(instruction) != 0;
        if LLVMGetOrdering(instruction) != 0 {
            invalid = true;
        }
        if invalid {
            backend_fail(c.backend, "Atomic/volatile LLVM memory requires an explicit foundation contract");
        }
        if load {
            return bi_memory_load(c, bi_value(c, LLVMGetOperand(instruction, 0)), type);
        }
        var stored = LLVMGetOperand(instruction, 0);
        bi_memory_store(c, bi_value(c, LLVMGetOperand(instruction, 1)), bi_value(c, stored), LLVMTypeOf(stored));
        return null;
    }
    // Diagnose before querying operands: some unsupported instructions have no
    // operands, and LLVM's C API requires valid indices even in release builds.
    var supported_shape = op >= 8;
    supported_shape &&= op <= 25;
    var cast_shape = op >= 30;
    cast_shape &&= op <= 32;
    if cast_shape {
        supported_shape = true;
    }
    cast_shape = op >= 39;
    cast_shape &&= op <= 42;
    if cast_shape {
        supported_shape = true;
    }
    selected = op == 46;
    if selected {
        supported_shape = true;
    }
    selected = op == 68;
    if selected {
        supported_shape = true;
    }
    if !supported_shape {
        backend_fail(c.backend, "Unsupported LLVM instruction in foundation return path: ");
        backend_decimal(&c.backend.error, convert(u64, op));
        return null;
    }
    var a_value = LLVMGetOperand(instruction, 0);
    var a = bi_value(c, a_value);
    selected = op == 68;
    if selected {
        return a;
    }
    selected = op == 30;
    if op == 31 {
        selected = true;
    }
    if selected {
        return bi_mask(c, a, type);
    }
    selected = op == 32;
    if selected {
        a = bi_signed(c, a, LLVMTypeOf(a_value));
        a = bi_cast(c, a, 7, true);
        return bi_mask(c, a, type);
    }
    selected = op == 39;
    if selected {
        a = bi_cast(c, a, 8, true);
        return bi_mask(c, a, type);
    }
    selected = op == 40;
    if selected {
        a = bi_cast(c, a, 8, false);
        return bi_cast(c, a, 10, true);
    }
    selected = op == 41;
    if selected {
        return bi_cast(c, a, scalar, true);
    }
    var b = bi_value(c, LLVMGetOperand(instruction, 1));
    selected = op == 42;
    if selected {
        return bi_compare(c, LLVMGetICmpPredicate(instruction), a, b, LLVMTypeOf(a_value));
    }
    selected = op == 46;
    if selected {
        var no = bi_value(c, LLVMGetOperand(instruction, 2));
        return bi_select(c, a, b, no, scalar);
    }
    selected = op >= 20;
    selected &&= op <= 22;
    if selected {
        return bi_shift(c, op, a, b, type, LLVMGetOperand(instruction, 1));
    }
    var binary: u32 = 99;
    selected = op == 8;
    if selected {
        binary = 0;
    }
    selected = op == 10;
    if selected {
        binary = 1;
    }
    selected = op == 12;
    if selected {
        binary = 2;
    }
    selected = op == 14;
    if selected {
        binary = 3;
    }
    selected = op == 15;
    if selected {
        binary = 3;
    }
    selected = op == 17;
    if selected {
        binary = 4;
    }
    selected = op == 18;
    if selected {
        binary = 4;
    }
    selected = op == 23;
    if selected {
        binary = 5;
    }
    selected = op == 24;
    if selected {
        binary = 6;
    }
    selected = op == 25;
    if selected {
        binary = 7;
    }
    if binary != 99 {
        var signed = op == 15;
        selected = op == 18;
        if selected {
            signed = true;
        }
        if signed {
            a = bi_signed(c, a, type);
            b = bi_signed(c, b, type);
            a = bi_binary(c, binary, a, b, 6);
            a = bi_cast(c, a, 7, true);
        } else {
            a = bi_binary(c, binary, a, b, scalar);
        }
        return bi_mask(c, a, type);
    }
    backend_fail(c.backend, "Unsupported LLVM instruction in foundation return path: ");
    backend_decimal(&c.backend.error, convert(u64, op));
    return bi_const(c, scalar, 0);
}

