fn bi_pow2(width: u32): u64 {
    var result: u64 = 1;
    var i: u32 = 0;
    loop {
        if i == width {
            return result;
        }
        result = result * 2;
        i++;
    }
}

fn bi_narrow_memory(type: void*): bool {
    if LLVMGetTypeKind(type) == 8 {
        var width = LLVMGetIntTypeWidth(type);
        var direct = width == 8;
        if direct {
            return false;
        }
        direct = width == 32;
        if direct {
            return false;
        }
        direct = width == 64;
        if direct {
            return false;
        }
        return true;
    }
    return false;
}

fn bi_memory_load(c: BackendImport*, address: void*, type: void*): void* {
    if bi_narrow_memory(type) {
        var width = LLVMGetIntTypeWidth(type);
        var count = width + 7;
        count = count / 8;
        var result = bi_const(c, 7, 0);
        for(var i: u32 = 0; i != count; i++) {
            var at = bi_offset(c, address, bi_const(c, 8, convert(u64, i)));
            var byte = bi_cast(c, bi_load(c, at, 5), 7, false);
            var shift = i *8;
            byte = bi_binary(c, 2, byte, bi_const(c, 7, bi_pow2(shift)), 7);
            result = bi_binary(c, 6, result, byte, 7);
        }
        return bi_mask(c, result, type);
    }
    return bi_load(c, address, bi_scalar(c, type));
}

fn bi_memory_store(c: BackendImport*, address: void*, value: void*, type: void*): void {
    if bi_narrow_memory(type) {
        var width = LLVMGetIntTypeWidth(type);
        var count = width + 7;
        count = count / 8;
        value = bi_cast(c, value, 7, false);
        var i: u32 = 0;
        loop {
            if i == count {
                return;
            }
            var byte = bi_binary(c, 5, value, bi_const(c, 7, 255), 7);
            byte = bi_cast(c, byte, 5, false);
            var at = bi_offset(c, address, bi_const(c, 8, convert(u64, i)));
            bi_store(c, at, byte);
            value = bi_binary(c, 3, value, bi_const(c, 7, 256), 7);
            i++;
        }
    }
    bi_store(c, address, value);
}

fn bi_mask(c: BackendImport*, value: void*, type: void*): void* {
    if LLVMGetTypeKind(type) == 8 {
        var width = LLVMGetIntTypeWidth(type);
        var scalar = bi_scalar(c, type);
        if width == 1 {
            value = bi_cast(c, value, 7, false);
            value = bi_binary(c, 5, value, bi_const(c, 7, 1), 7);
        }
        value = bi_cast(c, value, scalar, false);
        var ordinary = width == 1;
        if ordinary {
            return value;
        }
        ordinary = width == 8;
        if ordinary {
            return value;
        }
        ordinary = width == 32;
        if ordinary {
            return value;
        }
        ordinary = width == 64;
        if ordinary {
            return value;
        }
        var mask = bi_pow2(width) -1;
        return bi_binary(c, 5, value, bi_const(c, scalar, mask), scalar);
    }
    return value;
}

fn bi_signed(c: BackendImport*, value: void*, type: void*): void* {
    var width = LLVMGetIntTypeWidth(type);
    value = bi_cast(c, value, 7, false);
    if !(width == 64) {
        var sign_width = width -1;
        var sign = bi_const(c, 7, bi_pow2(sign_width));
        value = bi_binary(c, 7, value, sign, 7);
        value = bi_binary(c, 1, value, sign, 7);
    }
    return bi_cast(c, value, 6, true);
}

fn bi_gep(c: BackendImport*, instruction: void*): void* {
    var value = bi_value(c, LLVMGetOperand(instruction, 0));
    var type = LLVMGetGEPSourceElementType(instruction);
    var count = LLVMGetNumOperands(instruction);
    var i: i32 = 1;
    loop {
        if i == count {
            return value;
        }
        var index = LLVMGetOperand(instruction, convert(u32, i));
        var bytes: void* = null;
        var first = i == 1;
        var record = LLVMGetTypeKind(type) == 10;
        if first {
            record = false;
        }
        if record {
            var field = convert(u32, LLVMConstIntGetZExtValue(index));
            bytes = bi_const(c, 8, LLVMOffsetOfElement(c.backend.layout, type, field));
            type = LLVMStructGetTypeAtIndex(type, field);
        } else {
            if !first {
                type = LLVMGetElementType(type);
            }
            var stride = LLVMABISizeOfType(c.backend.layout, type);
            var index_width = LLVMGetIntTypeWidth(LLVMTypeOf(index));
            var pointer_width = c.backend.pointer_bytes *8;
            var wider_pointer = pointer_width > index_width;
            bytes = bi_value(c, index);
            if wider_pointer {
                bytes = bi_signed(c, bytes, LLVMTypeOf(index));
                bytes = bi_cast(c, bytes, 7, true);
            }
            bytes = bi_cast(c, bytes, 8, false);
            bytes = bi_binary(c, 2, bytes, bi_const(c, 8, stride), 8);
        }
        value = bi_offset(c, value, bytes);
        i++;
    }
}

fn bi_value(c: BackendImport*, value: void*): void* {
    var entity = backend_find(&c.values, value);
    if entity != null {
        var n = sem_get(entity);
        if n.global {
            return bi_address(c, bi_ref(c, entity));
        }
        return bi_cast(c, bi_ref(c, entity), bi_scalar(c, LLVMTypeOf(value)), true);
    }
    var type = LLVMTypeOf(value);
    var scalar = bi_scalar(c, type);
    var zero = LLVMIsNull(value) != 0;
    if LLVMIsUndef(value) != 0 {
        zero = true;
    }
    if LLVMIsPoison(value) != 0 {
        zero = true;
    }
    if zero {
        return bi_literal(c, value, scalar, 0);
    }
    var kind = LLVMGetValueKind(value);
    var integer = kind == 18;
    if integer {
        return bi_literal(c, value, scalar, LLVMConstIntGetZExtValue(value));
    }
    if kind == 10 {
        var op = LLVMGetConstOpcode(value);
        if op == 29 {
            return bi_gep(c, value);
        }
        var cast = op == 39;
        var other = op == 40;
        if other {
            cast = true;
        }
        other = op == 41;
        if other {
            cast = true;
        }
        if cast {
            var operand = bi_value(c, LLVMGetOperand(value, 0));
            if scalar == 10 {
                var input = sem_get(operand);
                var integer = input.type.pointers == 0;
                if integer {
                    operand = bi_cast(c, operand, 8, false);
                }
                return bi_cast(c, operand, scalar, true);
            }
            operand = bi_cast(c, operand, 8, true);
            return bi_cast(c, operand, scalar, false);
        }
    }
    backend_fail(c.backend, "Unsupported LLVM value in foundation return path");
    return bi_const(c, scalar, 0);
}

fn bi_select(c: BackendImport*, condition: void*, yes: void*, no: void*, scalar: u32): void* {
    var result = bi_decl(c, scalar);
    var outer = c.block;
    var entity = bi_if(c, condition);
    var branch = sem_get(entity);
    c.block = branch.body;
    bi_assign(c, bi_ref(c, result), yes);
    c.block = branch.otherwise;
    bi_assign(c, bi_ref(c, result), no);
    c.block = outer;
    return bi_ref(c, result);
}

fn bi_compare(c: BackendImport*, predicate: u32, a: void*, b: void*, type: void*): void* {
    var op: u32 = 8;
    if predicate >= 38 {
        if LLVMGetIntTypeWidth(type) == 32 {
            a = bi_cast(c, a, 0, true);
            b = bi_cast(c, b, 0, true);
        } else {
            a = bi_signed(c, a, type);
            b = bi_signed(c, b, type);
        }
        predicate = predicate - 4;
    }
    var selected = predicate == 33;
    if selected {
        op = 9;
    }
    selected = predicate == 34;
    if selected {
        op = 12;
    }
    selected = predicate == 35;
    if selected {
        op = 13;
    }
    selected = predicate == 36;
    if selected {
        op = 10;
    }
    selected = predicate == 37;
    if selected {
        op = 11;
    }
    return bi_binary(c, op, a, b, 2);
}

fn bi_shift(c: BackendImport*, op: u32, a: void*, b: void*, type: void*, shift: void*): void* {
    // Totalized LLVM shifts: out-of-range poison may choose any value. Never
    // introduce a trap into speculative, subsequently unused LLVM operations.
    var width = LLVMGetIntTypeWidth(type);
    if LLVMGetValueKind(shift) == 18 {
        // Immediate shift legalization needs a constant scale, not a runtime
        // exponentiation loop. This translates an opcode; LLVM owns folding.
        var count = LLVMConstIntGetZExtValue(shift);
        var scalar = bi_scalar(c, type);
        if count >= convert(u64, width) {
            return bi_const(c, scalar, 0);
        }
        var factor = bi_const(c, scalar, bi_pow2(convert(u32, count)));
        var left = op == 20;
        if left {
            return bi_mask(c, bi_binary(c, 2, a, factor, scalar), type);
        }
        if op == 21 {
            return bi_binary(c, 3, a, factor, scalar);
        }
        var sign_width = width -1;
        var negative = bi_binary(c, 13, a, bi_const(c, scalar, bi_pow2(sign_width)), 2);
        var mask_bits = bi_pow2(width) -1;
        var mask = bi_const(c, scalar, mask_bits);
        var inverted = bi_binary(c, 7, a, mask, scalar);
        inverted = bi_binary(c, 3, inverted, factor, scalar);
        inverted = bi_binary(c, 7, inverted, mask, scalar);
        var positive = bi_binary(c, 3, a, factor, scalar);
        return bi_select(c, negative, inverted, positive, scalar);
    }
    a = bi_cast(c, a, 7, false);
    b = bi_cast(c, b, 7, false);
    b = bi_binary(c, 5, b, bi_const(c, 7, 63), 7);
    var power = bi_decl(c, 7);
    bi_assign(c, bi_ref(c, power), bi_const(c, 7, 1));
    for(var i: u32 = 0; i != 6; i++) {
        var bit = bi_pow2(i);
        var test = bi_binary(c, 5, b, bi_const(c, 7, bit), 7);
        test = bi_binary(c, 9, test, bi_const(c, 7, 0), 2);
        var outer = c.block;
        var branch = sem_get(bi_if(c, test));
        c.block = branch.body;
        var factor = bi_const(c, 7, bi_pow2(convert(u32, bit)));
        var product = bi_binary(c, 2, bi_ref(c, power), factor, 7);
        bi_assign(c, bi_ref(c, power), product);
        c.block = outer;
    }
    var left = op == 20;
    if left {
        return bi_mask(c, bi_binary(c, 2, a, bi_ref(c, power), 7), type);
    }
    if op == 22 {
        var sign_width = width -1;
        var sign = bi_pow2(sign_width);
        var negative = bi_binary(c, 13, a, bi_const(c, 7, sign), 2);
        var mask = bi_pow2(width) -1;
        var inverted = bi_binary(c, 7, a, bi_const(c, 7, mask), 7);
        inverted = bi_binary(c, 3, inverted, bi_ref(c, power), 7);
        inverted = bi_binary(c, 7, inverted, bi_const(c, 7, mask), 7);
        var positive = bi_binary(c, 3, a, bi_ref(c, power), 7);
        return bi_mask(c, bi_select(c, negative, inverted, positive, 7), type);
    }
    return bi_mask(c, bi_binary(c, 3, a, bi_ref(c, power), 7), type);
}

import tower;
import coff_import;
import context;
import file_api;
import foreign_api;
import foreign_reader;
import foreign_symbol;
import text;
import .library.vector;

// Link plans are transport-independent argument lists for upstream LLD.
// Native hosts execute the bundled upstream tool; WASI invokes its pinned ABI.
struct BackendLinkInput {
    name: vector(u8);
    bytes: vector(u8);
}

struct BackendLink {
    arguments: vector(u8*);
    inputs: vector(BackendLinkInput);
    error: vector(u8);
    output: vector(u8);
}

extern fn fopen(path: u8*, mode: u8*): void*;

extern fn fclose(file: void*): i32;

extern fn fread(bytes: u8*, size: usize, count: usize, file: void*): usize;

extern fn fwrite(bytes: u8*, size: usize, count: usize, file: void*): usize;

extern fn fileno(file: void*): i32;

extern fn remove(path: u8*): i32;

fn backend_link_argument(link: BackendLink*, prefix: u8*, value: u8*): void {
    var text: vector(u8);
    vector_init(u8, &text);
    backend_text(&text, prefix);
    backend_text(&text, value);
    if !vector_push(u8*, &link.arguments, text.data) {
        vector_dispose(u8, &text);
        backend_text(&link.error, "Unable to allocate linker arguments");
    }
}

export fn backend_link_reset_plan(link: BackendLink*): void {
    remove("tower-stack-probe.lib");
    remove("tower-platform.tbd");
    for(var i: usize = 0; i != link.arguments.length; i++) {
        free(link.arguments.data[i]);
    }
    link.arguments.length = 0;
    link.error.length = 0;
    link.output.length = 0;
}

export fn backend_link_clear_inputs(link: BackendLink*): void {
    var i: usize = 0;
    for(; i != link.inputs.length; i++) {
        var input = &link.inputs.data[i];
        remove(input.name.data);
        vector_dispose(u8, &input.name);
        vector_dispose(u8, &input.bytes);
    }
    link.inputs.length = 0;
}

export fn backend_link_close(link: BackendLink*): void {
    if link == null {
        return;
    }
    backend_link_reset_plan(link);
    backend_link_clear_inputs(link);
    vector_dispose(u8*, &link.arguments);
    vector_dispose(BackendLinkInput, &link.inputs);
    vector_dispose(u8, &link.error);
    vector_dispose(u8, &link.output);
    free(link);
}

fn backend_filename(name: u8*): bool {
    var length = backend_length(name);
    var invalid = length == 0;
    if invalid {
        return false;
    }
    invalid = length > 128;
    if invalid {
        return false;
    }
    var i: usize = 0;
    loop {
        if i == length {
            return true;
        }
        var byte = name[i];
        var valid = byte >= 97;
        valid &&= byte <= 122;
        var upper = byte >= 65;
        upper &&= byte <= 90;
        if upper {
            valid = true;
        }
        var number = byte >= 48;
        number &&= byte <= 57;
        if number {
            valid = true;
        }
        var punctuation = byte == 46;
        if punctuation {
            valid = true;
        }
        punctuation = byte == 95;
        if punctuation {
            valid = true;
        }
        punctuation = byte == 45;
        if punctuation {
            valid = true;
        }
        invalid = !valid;
        if invalid {
            return false;
        }
        i++;
    }
}

export fn backend_link_add_input(link: BackendLink*, name: u8*, data: u8*, length: usize): bool {
    var invalid = name == null;
    if invalid {
        return false;
    }
    invalid = data == null;
    if invalid {
        return false;
    }
    invalid = length > 67108864;
    if invalid {
        return false;
    }
    invalid = link.inputs.length >= 64;
    if invalid {
        return false;
    }
    invalid = backend_filename(name) == false;
    if invalid {
        return false;
    }
    invalid = backend_prefix(name, "tower-");
    if invalid {
        return false;
    }
    var i: usize = 0;
    var found: BackendLinkInput* = null;
    for(; i != link.inputs.length; i++) {
        if backend_equal(link.inputs.data[i].name.data, name) {
            found = &link.inputs.data[i];
            break;
        }
    }
    if found == null {
        var needed = link.inputs.length + 1;
        var ok = vector_reserve(BackendLinkInput, &link.inputs, needed);
        invalid = !ok;
        if invalid {
            return false;
        }
        found = &link.inputs.data[link.inputs.length];
        fill(found, 0, sizeof(BackendLinkInput));
        backend_text(&found.name, name);
        link.inputs.length = needed;
    }
    found.bytes.length = 0;
    backend_text_append(&found.bytes, data, length);
    var complete = found.bytes.length == length;
    return complete;
}

fn backend_write_file(link: BackendLink*, path: u8*, data: u8*, length: usize): bool {
    var file = fopen(path, "wb");
    if file == null {
        backend_text(&link.error, "Cannot open linker input: ");
        backend_text(&link.error, path);
        return false;
    }
    var written = fwrite(data, 1, length, file);
    var status = fclose(file);
    var ok = written == length;
    ok &&= status == 0;
    if !ok {
        backend_text(&link.error, "Cannot write linker input: ");
        backend_text(&link.error, path);
    }
    return ok;
}

fn backend_read_file(output: vector(u8)*, path: u8*): bool {
    var file = fopen(path, "rb");
    if file == null {
        return false;
    }
    var status = backend_file_seek(file, 0, 2);
    var length = backend_file_position(file);
    var invalid = length < 0;
    if status != 0 {
        invalid = true;
    }
    if invalid {
        fclose(file);
        return false;
    }
    backend_file_seek(file, 0, 0);
    var count = convert(usize, length);
    var needed = count + 1;
    var ok = vector_reserve(u8, output, needed);
    if ok {
        var read = fread(output.data, 1, count, file);
        ok = read == count;
        if ok {
            output.length = count;
            output.data[count] = 0;
        }
    }
    fclose(file);
    return ok;
}

export fn backend_link_plan(link: BackendLink*, triple: u8*, functions: void**, count: usize, object: u8*, object_size: usize, runtime: u8*, runtime_size: usize): bool {
    backend_link_reset_plan(link);
    // A failed invocation cannot expose output left by a prior request.
    remove("tower-output.bin");
    var ok = backend_write_file(link, "tower-input.o", object, object_size);
    var failed = !ok;
    if failed {
        return false;
    }
    var wasm = backend_prefix(triple, "wasm");
    var windows = backend_contains(triple, "windows");
    var mac = backend_contains(triple, "apple");
    if wasm {
        ok = backend_write_file(link, "tower-runtime.o", runtime, runtime_size);
        failed = !ok;
        if failed {
            return false;
        }
        var allowed: vector(u8);
        vector_init(u8, &allowed);
        backend_text(&allowed, "tower_print\ntower_trap\n");
        var i: usize = 1;
        for(; i < count; i++) {
            var n = sem_get(functions[i]);
            if n.external {
                var spelling = foreign_symbol(foreign_profile_for_target(triple), backend_name(n));
                backend_text(&allowed, foreign_name_text(spelling));
                foreign_name_close(spelling);
                backend_text(&allowed, "\n");
            }
        }
        ok = backend_write_file(link, "tower-allowed.txt", allowed.data, allowed.length);
        vector_dispose(u8, &allowed);
        failed = !ok;
        if failed {
            return false;
        }
        backend_link_argument(link, "", "wasm-ld");
        backend_link_argument(link, "", "--no-entry");
        backend_link_argument(link, "", "--export=tower_main");
        backend_link_argument(link, "", "--export-memory");
        backend_link_argument(link, "", "--allow-undefined-file=tower-allowed.txt");
        backend_link_argument(link, "", "--threads=1");
        backend_link_argument(link, "", "--stack-first");
        backend_link_argument(link, "", "-z");
        backend_link_argument(link, "", "stack-size=4194304");
        backend_link_argument(link, "", "--initial-memory=8388608");
        backend_link_argument(link, "", "--max-memory=268435456");
        backend_link_argument(link, "", "tower-input.o");
        backend_link_argument(link, "", "tower-runtime.o");
    } else {
        if windows {
            backend_link_argument(link, "", "lld-link");
            backend_link_argument(link, "", "/entry:mainCRTStartup");
            backend_link_argument(link, "", "/subsystem:console");
            backend_link_argument(link, "", "/machine:x64");
            backend_link_argument(link, "", "/timestamp:0");
            backend_link_argument(link, "", "/threads:1");
            backend_link_argument(link, "", "/out:tower-output.bin");
        } else {
            if mac {
                backend_link_argument(link, "", "ld64.lld");
                backend_link_argument(link, "", "-arch");
                if backend_prefix(triple, "x86_64") {
                    backend_link_argument(link, "", "x86_64");
                }
                else {
                    backend_link_argument(link, "", "arm64");
                }
                backend_link_argument(link, "", "-platform_version");
                backend_link_argument(link, "", "macos");
                backend_link_argument(link, "", "11.0");
                backend_link_argument(link, "", "11.0");
                backend_link_argument(link, "", "-e");
                backend_link_argument(link, "", "_main");
            } else {
                backend_link_argument(link, "", "ld.lld");
                backend_link_argument(link, "", "--threads=1");
                backend_link_argument(link, "", "-static");
                backend_link_argument(link, "", "--build-id=none");
                backend_link_argument(link, "", "-e");
                backend_link_argument(link, "", "_start");
            }
        }
        backend_link_argument(link, "", "tower-input.o");
    }
    // Preserve deterministic lexical input order, matching the former map.
    var order: vector(usize);
    vector_init(usize, &order);
    var i: usize = 0;
    loop {
        var done = i == link.inputs.length;
        if done {
            break;
        }
        vector_push(usize, &order, i);
        var j = i;
        loop {
            done = j == 0;
            if done {
                break;
            }
            var previous = j -1;
            var a = order.data[previous];
            var b = order.data[j];
            var left = link.inputs.data[a].name.data;
            var right = link.inputs.data[b].name.data;
            var k: usize = 0;
            loop {
                var different = left[k] != right[k];
                if left[k] == 0 {
                    different = true;
                }
                if different {
                    break;
                }
                k++;
            }
            if left[k] <= right[k] {
                break;
            }
            order.data[previous] = b;
            order.data[j] = a;
            j = previous;
        }
        i++;
    }
    i = 0;
    for(; i != order.length; i++) {
        var input = &link.inputs.data[order.data[i]];
        ok = backend_write_file(link, input.name.data, input.bytes.data, input.bytes.length);
        backend_link_argument(link, "", input.name.data);
    }
    vector_dispose(usize, &order);
    if windows {
        // LLVM's Windows x64 prologue calls the OS stack probe for large frames.
        // Keep guard-page probing and its special ABI; never replace it with a
        // normal Tower-call wrapper or disable probes to silence a link error.
        var archive: vector(u8);
        vector_init(u8, &archive);
        ok = coff_import_archive(&archive, CoffMachineAmd64(), "__chkstk", "kernelbase.dll");
        if ok {
            ok = backend_write_file(link, "tower-stack-probe.lib", archive.data, archive.length);
        } else {
            backend_text(&link.error, "Unable to allocate Windows stack-probe import metadata");
        }
        vector_dispose(u8, &archive);
        if !ok {
            return false;
        }
        backend_link_argument(link, "", "tower-stack-probe.lib");
    }
    if mac {
        // LLVM may lower zero-fill to Darwin's __bzero. Supplement the caller's
        // SDK description with that existing libSystem symbol; no replacement
        // implementation or additional runtime library is introduced.
        var symbols: u8* = "--- !tapi-tbd\ntbd-version: 4\ntargets: [ x86_64-macos, arm64-macos ]\ninstall-name: '/usr/lib/libSystem.B.dylib'\ncurrent-version: 1\ncompatibility-version: 1\nexports:\n  - targets: [ x86_64-macos ]\n    symbols: [ ___bzero, _bzero ]\n  - targets: [ arm64-macos ]\n    symbols: [ _bzero ]\n...\n";
        ok = backend_write_file(link, "tower-platform.tbd", symbols, backend_length(symbols));
        if !ok {
            return false;
        }
        backend_link_argument(link, "", "tower-platform.tbd");
    }
    i = 1;
    for(; i < count; i++) {
        var n = sem_get(functions[i]);
        if n.exported {
            var spelling = foreign_symbol(foreign_profile_for_target(triple), backend_name(n));
            if wasm {
                backend_link_argument(link, "--export=", foreign_name_text(spelling));
            }
            if windows {
                backend_link_argument(link, "/export:", foreign_name_text(spelling));
            }
            foreign_name_close(spelling);
        }
    }
    if wasm {
        backend_link_argument(link, "", "--export=tower_allocate");
        backend_link_argument(link, "", "--export=tower_deallocate");
    }
    if !windows {
        backend_link_argument(link, "", "-o");
        backend_link_argument(link, "", "tower-output.bin");
    }
    ok = link.error.length == 0;
    return ok;
}

export fn backend_link_arguments(link: BackendLink*): u8** {
    return link.arguments.data;
}

export fn backend_link_argument_count(link: BackendLink*): usize {
    return link.arguments.length;
}

export fn backend_link_read_output(link: BackendLink*): bool {
    var ok = backend_read_file(&link.output, "tower-output.bin");
    if !ok {
        backend_text(&link.error, "Cannot read linked executable");
    }
    return ok;
}

export fn backend_link_create(): BackendLink* {
    var link = alloc(BackendLink, 1);
    if link != null {
        fill(link, 0, sizeof(BackendLink));
    }
    return link;
}

import tower;
import lld_api;
import linker;
import text;
import .library.vector;

// Pinned LLVM/lld 20 wasm32 library ABI. ArrayRef is passed indirectly; constructors
// and destructors are upstream implementations. No owned native adapter.
struct BackendLldArguments {
    data: u8**;
    count: usize;
}

struct BackendLldStream {
    opaque: u64[8];
}

extern fn `cpp_name(ctor(base) llvm::raw_fd_ostream(int, bool, bool, llvm::raw_ostream::OStreamKind))`(self: BackendLldStream*, fd: i32, close: bool, unbuffered: bool, kind: u32): void*;

extern fn `cpp_name(dtor(base) llvm::raw_fd_ostream())`(self: BackendLldStream*): void*;

extern fn `cpp_name(bool lld::wasm::link(llvm::ArrayRef<char const*>, llvm::raw_ostream&, llvm::raw_ostream&, bool, bool))`(args: BackendLldArguments*, output: BackendLldStream*, error: BackendLldStream*, exit_early: bool, disable_output: bool): bool;

extern fn `cpp_name(static void lld::CommonLinkerContext::destroy())`(): void;

extern fn `cpp_name(llvm::raw_ostream& llvm::nulls())`(): BackendLldStream*;

export fn backend_link_wasi(link: BackendLink*, triple: u8*): bool {
    var error_file = fopen("tower-link.stderr", "wb");
    var failed = error_file == null;
    if failed {
        backend_text(&link.error, "Cannot open linker diagnostics");
        return false;
    }
    var error: BackendLldStream;
    `cpp_name(ctor(base) llvm::raw_fd_ostream(int, bool, bool, llvm::raw_ostream::OStreamKind))`(&error, fileno(error_file), false, true, 0);
    var args: BackendLldArguments;
    args.data = link.arguments.data;
    args.count = link.arguments.length;
    var linked = backend_lld_dispatch(triple, &args, `cpp_name(llvm::raw_ostream& llvm::nulls())`(), &error);
    // Destroy LLD before stream storage. Repeated requests have no shared linker
    // state; unrecoverable errors terminate the disposable worker instance.
    `cpp_name(static void lld::CommonLinkerContext::destroy())`();
    `cpp_name(dtor(base) llvm::raw_fd_ostream())`(&error);
    fclose(error_file);
    failed = !linked;
    if failed {
        backend_text(&link.error, "Link failed: ");
        var diagnostics: vector(u8);
        vector_init(u8, &diagnostics);
        backend_read_file(&diagnostics, "tower-link.stderr");
        backend_text_append(&link.error, diagnostics.data, diagnostics.length);
        vector_dispose(u8, &diagnostics);
    }
    remove("tower-link.stderr");
    linked &&= backend_link_read_output(link);
    return linked;
}

