fn format_semantic_name(f: FormatEngine*, entity: void*, fallback: vector(u8)*): void {
    // Display summaries may use a declaration's original spelling. Canonical
    // Foundation always retains its unique resolved name, with the same
    // identifier escaping engine in both modes. Specializations retain their
    // concrete generated names rather than displaying an unbound template name.
    if f.source_names {
        var node = entity_child_at(entity, entity_member_index(entity, "name"));
        while node != null {
            var parsed = format_match(f, node);
            var terminal = parsed != null;
            if terminal {
                var invalid: usize = 0;
                invalid--;
                terminal = parsed.rule == invalid;
            }
            if terminal {
                var original: vector(u8);
                vector_init(u8, &original);
                if bytes_assign_text(&original, parsed.label.data, parsed.label.length) {
                    original.length = syntax_identifier_decode_in_place(original.data, original.length);
                    var same = original.length < fallback.length;
                    for(var i: usize = 0; i < original.length; i++) {
                        same &&= original.data[i] == fallback.data[i];
                    }
                    same &&= fallback.data[original.length] == 64;
                    if same {
                        format_identifier(f, &original);
                        vector_dispose(u8, &original);
                        return;
                    }
                }
                vector_dispose(u8, &original);
                break;
            }
            if entity_child_count(node) == 1 {
                node = entity_child_at(node, 0);
            } else {
                break;
            }
        }
    }
    format_identifier(f, fallback);
}

fn format_type(f: FormatEngine*, t: FoundationType*): void {
    if format_array(t) {
        var a = format_foundation(f, t.record);
        format_type(f, &a.element);
        format_text(f, "[");
        format_unsigned(f, convert(u64, a.length));
        format_text(f, "]");
    } else {
        if format_record(t) {
            var record = format_foundation(f, t.record);
            format_semantic_name(f, t.record, &record.name);
        } else {
            var view: vector(u8);
            vector_init(u8, &view);
            if !format_scalar_name(t, &view) {
                f.result.failed = true;
            }
            format_identifier(f, &view);
            vector_dispose(u8, &view);
        }
    }
    format_repeat(f, 42, convert(usize, t.pointers));
}

fn format_number(f: FormatEngine*, n: FoundationNode*): void {
    var mask = format_mask(&n.type);
    var value = n.bits &mask;
    if format_signed(&n.type) {
        var sign = format_sign(&n.type);
        sign = value & sign;
        if sign != 0 {
            format_text(f, "-");
            var zero: u64 = 0;
            value = zero - value;
            value = value & mask;
        }
    }
    format_unsigned(f, value);
}

fn format_expression(f: FormatEngine*, entity: void*): void {
    var n = format_foundation(f, entity);
    var builtin = format_builtin(n);
    if builtin != null {
        format_text(f, builtin);
        format_text(f, "(");
        if n.kind == 33 {
            format_expression(f, n.left);
            format_text(f, ", ");
            format_expression(f, n.right);
        }
        if format_is_Print(n) {
            format_expression(f, n.value);
        }
        var size = format_is_SizeOf(n);
        var align = format_is_AlignOf(n);
        if format_or(size, align) {
            format_type(f, &n.element);
        }
        var allocate = format_is_Allocate(n);
        var reallocate = format_is_Reallocate(n);
        if format_or(allocate, reallocate) {
            format_type(f, &n.element);
            format_text(f, ", ");
            if n.left != null {
                format_expression(f, n.left);
                format_text(f, ", ");
            }
            format_expression(f, n.right);
        }
        var conversion = format_is_Convert(n);
        var reinterpret = format_is_Bits(n);
        conversion = format_or(conversion, reinterpret);
        if conversion {
            format_type(f, &n.type);
            format_text(f, ", ");
            format_expression(f, n.value);
        }
        if format_is_Free(n) {
            format_expression(f, n.left);
        }
        var copy = format_is_Copy(n);
        var fill = format_is_Fill(n);
        if format_or(copy, fill) {
            format_expression(f, n.left);
            format_text(f, ", ");
            format_expression(f, n.right);
            format_text(f, ", ");
            format_expression(f, n.value);
        }
        format_text(f, ")");
        return;
    }
    if format_is_Operand(n) {
        if n.constant {
            var nominal = n.type.pointers == 0;
            nominal &&= semantic_enum(&n.type);
            if nominal {
                var member = format_foundation(f, n.binding);
                var definition = format_foundation(f, n.type.record);
                format_identifier(f, &definition.name);
                format_text(f, ".");
                format_identifier(f, &member.name);
                return;
            }
            if n.type.pointers != 0 {
                format_text(f, "null");
            }
            else {
                if format_boolean(&n.type) {
                    if n.bits != 0 {
                        format_text(f, "true");
                    }
                    else {
                        format_text(f, "false");
                    }
                } else {
                    format_number(f, n);
                }
            }
        } else {
            var binding = format_foundation(f, n.binding);
            format_identifier(f, &binding.name);
        }
        return;
    }
    if format_is_String(n) {
        format_quote(f, &n.name);
        return;
    }
    if format_is_Binary(n) {
        format_expression(f, n.left);
        format_text(f, " ");
        format_text(f, format_operator(n));
        format_text(f, " ");
        format_expression(f, n.right);
        return;
    }
    if format_is_Field(n) {
        format_expression(f, n.left);
        format_text(f, ".");
        format_identifier(f, &n.name);
        return;
    }
    if format_is_Index(n) {
        format_expression(f, n.left);
        format_text(f, "[");
        format_expression(f, n.right);
        format_text(f, "]");
        return;
    }
    if format_is_Address(n) {
        format_text(f, "&");
        format_expression(f, n.value);
        return;
    }
    if format_is_Load(n) {
        format_text(f, "*");
        format_expression(f, n.value);
        return;
    }
    if format_is_Call(n) {
        var binding = format_foundation(f, n.binding);
        format_identifier(f, &binding.name);
        format_text(f, "(");
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            if i != 0 {
                format_text(f, ", ");
            }
            format_expression(f, n.items.data[i]);
            i++;
        }
        format_text(f, ")");
        return;
    }
    f.result.failed = true;
}

fn format_block(f: FormatEngine*, entity: void*): void {
    var n = format_foundation(f, entity);
    if n.items.length == 0 {
        format_text(f, "{}");
        return;
    }
    format_text(f, "{\n");
    f.result.depth++;
    var i: usize = 0;
    loop {
        if i == n.items.length {
            break;
        }
        format_statement(f, n.items.data[i]);
        i++;
    }
    f.result.depth--;
    format_indent(f);
    format_text(f, "}");
}

fn format_function_header(f: FormatEngine*, entity: void*, n: FoundationNode*): void {
    if n.external {
        format_text(f, "extern ");
    } else {
        if n.exported {
            format_text(f, "export ");
        }
    }
    format_text(f, "fn ");
    format_semantic_name(f, entity, &n.name);
    format_text(f, "(");
    var i: usize = 0;
    for(; i != n.parameters.length; i++) {
        if i != 0 {
            format_text(f, ", ");
        }
        var p = format_foundation(f, n.parameters.data[i]);
        format_identifier(f, &p.name);
        format_text(f, ": ");
        format_type(f, &p.type);
    }
    format_text(f, "): ");
    format_type(f, &n.type);
}

// A display fragment, not an alternative program serializer. All identifiers,
// types and function signatures use the canonical formatter's own rules.
export fn format_summary(result: FormatResult*, entity: void*, syntax: void*, foundation: void*, `match`: void*): void {
    var f: FormatEngine;
    f.source_names = true;
    f.result = result;
    f.syntax_kind = syntax;
    f.foundation_kind = foundation;
    f.match_kind = `match`;
    if format_syntax(&f, entity) != null {
        format_grammar(&f, entity);
        return;
    }
    var n = format_foundation(&f, entity);
    if n == null {
        return;
    }
    if format_is_Function(n) {
        format_function_header(&f, entity, n);
        return;
    }
    if format_is_Type(n) {
        format_type(&f, &n.type);
        return;
    }
    // A declared enum member has no access-site binding of its own. Its
    // nominal type and declaration name still have a canonical spelling.
    var member = format_is_Operand(n);
    member &&= n.constant;
    member &&= semantic_enum(&n.type);
    member &&= n.name.length != 0;
    if member {
        format_type(&f, &n.type);
        format_text(&f, ".");
        format_identifier(&f, &n.name);
        return;
    }
    var named = format_is_Declare(n);
    if named {
        format_text(&f, "var ");
    }
    if format_is_Parameter(n) {
        named = true;
    }
    if n.kind == KFieldDeclaration() {
        named = true;
    }
    if named {
        format_semantic_name(&f, entity, &n.name);
        format_text(&f, ": ");
        format_type(&f, &n.type);
        return;
    }
    format_expression(&f, entity);
}

fn format_statement_body(f: FormatEngine*, entity: void*): void {
    var n = format_foundation(f, entity);
    var label = n.kind == 31;
    var jump = n.kind == 32;
    if format_or(label, jump) {
        if label {
            format_text(f, "label(");
        } else {
            format_text(f, "jump(");
        }
        format_identifier(f, &n.name);
        format_text(f, ");");
        return;
    }
    if format_is_Declare(n) {
        format_text(f, "var ");
        format_identifier(f, &n.name);
        format_text(f, ": ");
        format_type(f, &n.type);
        if n.value != null {
            format_text(f, " = ");
            format_expression(f, n.value);
        }
        format_text(f, ";");
        return;
    }
    if format_is_Assign(n) {
        format_expression(f, n.target);
        format_text(f, " = ");
        format_expression(f, n.value);
        format_text(f, ";");
        return;
    }
    if format_is_Return(n) {
        format_text(f, "return");
        if n.value != null {
            format_text(f, " ");
            format_expression(f, n.value);
        }
        format_text(f, ";");
        return;
    }
    var builtin = format_builtin(n);
    var expression = builtin != null;
    var call = format_is_Call(n);
    expression = format_or(expression, call);
    if expression {
        format_expression(f, entity);
        format_text(f, ";");
        return;
    }
    if format_is_Break(n) {
        format_text(f, "break;");
        return;
    }
    if format_is_Continue(n) {
        format_text(f, "continue;");
        return;
    }
    if format_is_Block(n) {
        format_block(f, entity);
        return;
    }
    if format_is_Loop(n) {
        format_text(f, "loop ");
        format_block(f, n.body);
        return;
    }
    if format_is_If(n) {
        format_text(f, "if ");
        format_expression(f, n.value);
        format_text(f, " ");
        format_block(f, n.body);
        if n.otherwise != null {
            format_text(f, " else ");
            format_block(f, n.otherwise);
        }
        return;
    }
    if format_is_Function(n) {
        format_function_header(f, entity, n);
        if n.external {
            format_text(f, ";");
        }
        else {
            format_text(f, " ");
            format_block(f, n.body);
        }
        return;
    }
    if format_is_Type(n) {
        if semantic_enum(&n.type) {
            format_text(f, "enum ");
            format_identifier(f, &n.name);
            format_text(f, ": ");
            format_type(f, &n.element);
            format_text(f, " {\n");
            f.result.depth++;
            var i: usize = 0;
            for(; i != n.items.length; i++) {
                var member = format_foundation(f, n.items.data[i]);
                format_indent(f);
                format_identifier(f, &member.name);
                format_text(f, " = ");
                format_number(f, member);
                format_text(f, ",\n");
            }
            f.result.depth--;
            format_indent(f);
            format_text(f, "}");
            return;
        }
        format_text(f, "struct ");
        format_identifier(f, &n.name);
        format_text(f, " {\n");
        f.result.depth++;
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            var field = format_foundation(f, n.items.data[i]);
            format_indent(f);
            format_identifier(f, &field.name);
            format_text(f, ": ");
            format_type(f, &field.type);
            format_text(f, ";\n");
            i++;
        }
        f.result.depth--;
        format_indent(f);
        format_text(f, "}");
        return;
    }
    f.result.failed = true;
}

fn format_statement(f: FormatEngine*, entity: void*): void {
    var n = format_foundation(f, entity);
    format_node_comments(f, n);
    format_indent(f);
    var begin = f.result.text.length;
    format_statement_body(f, entity);
    format_span(f, begin, n.start);
    format_text(f, "\n");
}

fn format_node_comments(f: FormatEngine*, n: FoundationNode*): void {
    var i: usize = 0;
    var line = true;
    for(; i != n.comments.length; i++) {
        if line {
            format_indent(f);
        }
        var byte = n.comments.data[i];
        format_char(f, byte);
        line = byte == 10;
    }
}

fn format_node(f: FormatEngine*, entity: void*): void {
    var syntax = format_syntax(f, entity);
    if syntax != null {
        format_grammar(f, entity);
        return;
    }
    var n = format_foundation(f, entity);
    if format_is_Program(n) {
        format_node_comments(f, n);
        var previous = false;
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            var item = n.items.data[i];
            var child = format_foundation(f, item);
            var function = format_is_Function(child);
            var type = format_is_Type(child);
            var declaration = format_or(function, type);
            var separate = format_or(previous, declaration);
            if i == 0 {
                separate = false;
            }
            if separate {
                format_newline(f, true);
            }
            format_node(f, item);
            previous = declaration;
            i++;
        }
    } else {
        format_statement(f, entity);
    }
}

import tower;
import format_foundation;
import format_types;
import format;
import syntax_tags;
import syntax_types;

// Grammar terms, alternatives and declarations retain shared entity identity.
fn format_grammar_term(f: FormatEngine*, entity: void*): void {
    var term = format_syntax(f, entity);
    if term.capture.length != 0 {
        format_text(f, "$");
        format_identifier(f, &term.capture);
        var same = term.capture.length == term.text.length;
        var i: usize = 0;
        loop {
            if i == term.capture.length {
                break;
            }
            if !same {
                break;
            }
            same = term.capture.data[i] == term.text.data[i];
            i++;
        }
        if same {
            if term.repetition != 0 {
                format_char(f, term.repetition);
            }
            return;
        }
        format_text(f, ":");
    }
    if term.terminal_set {
        format_text(f, "[^");
        var i: usize = 0;
        loop {
            if i == term.items.length {
                break;
            }
            if i != 0 {
                format_text(f, " ");
            }
            var item = format_syntax(f, term.items.data[i]);
            format_quote(f, &item.text);
            i++;
        }
        format_text(f, "]");
    } else {
        if term.literal {
            format_quote(f, &term.text);
        }
        else {
            format_identifier(f, &term.text);
        }
    }
    if term.repetition != 0 {
        format_char(f, term.repetition);
    }
}

fn format_alternative(f: FormatEngine*, entity: void*): void {
    var n = format_syntax(f, entity);
    var i: usize = 0;
    loop {
        if i == n.items.length {
            break;
        }
        if i != 0 {
            format_text(f, " ");
        }
        format_grammar_term(f, n.items.data[i]);
        i++;
    }
}

fn format_precedence(f: FormatEngine*, n: SyntaxNode*): void {
    if n.precedence == 0 {
        return;
    }
    format_text(f, " @ ");
    format_unsigned(f, convert(u64, n.precedence));
    if n.associativity == 1 {
        format_text(f, " left");
    }
    else {
        if n.associativity == 2 {
            format_text(f, " right");
        }
        else {
            format_text(f, " nonassoc");
        }
    }
}

fn format_comments(f: FormatEngine*, n: SyntaxNode*): void {
    var i: usize = 0;
    loop {
        if i == n.comments.length {
            break;
        }
        format_indent(f);
        format_bytes(f, &n.comments.data[i]);
        format_text(f, "\n");
        i++;
    }
}

fn format_replacement(f: FormatEngine*, n: SyntaxNode*): void {
    if n.replacement == null {
        return;
    }
    format_text(f, "\n");
    f.result.depth++;
    format_indent(f);
    f.result.depth--;
    format_text(f, "=> replace {");
    var replacement = format_syntax(f, n.replacement);
    format_bytes(f, &replacement.text);
    format_text(f, "}");
}

fn format_grammar(f: FormatEngine*, entity: void*): void {
    var n = format_syntax(f, entity);
    if n.kind == 0 {
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            format_node(f, n.items.data[i]);
            i++;
        }
        format_comments(f, n);
        return;
    }
    format_comments(f, n);
    format_indent(f);
    var begin = f.result.text.length;
    if n.kind == 7 {
        format_text(f, "import ");
        if n.literal {
            format_quote(f, &n.name);
        }
        else {
            if n.items.length == 0 {
                format_identifier(f, &n.name);
            } else {
                var i: usize = 0;
                var separator: bool = false;
                loop {
                    if i == n.items.length {
                        break;
                    }
                    var segment = format_syntax(f, n.items.data[i]);
                    if segment.literal {
                        format_text(f, ".");
                        i = i + 1;
                        continue;
                    }
                    if separator {
                        format_text(f, ".");
                    }
                    format_identifier(f, &segment.text);
                    separator = true;
                    i++;
                }
            }
        }
        if n.capture.length != 0 {
            format_text(f, " as ");
            format_identifier(f, &n.capture);
        }
        format_text(f, ";\n");
        format_span(f, begin, n.start);
        return;
    }
    if n.kind == 1 {
        format_text(f, "parse ");
        format_identifier(f, &n.name);
        if n.append {
            format_text(f, " |=");
        }
        else {
            format_text(f, " =");
        }
        var continuation = format_column(f);
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            if i != 0 {
                var output: FormatResult;
                fill(&output, 0, sizeof(FormatResult));
                var probe: FormatEngine;
                probe.source_names = false;
                probe.result = &output;
                probe.syntax_kind = f.syntax_kind;
                probe.foundation_kind = f.foundation_kind;
                probe.match_kind = f.match_kind;
                format_alternative(&probe, n.items.data[i]);
                f.result.failed = format_or(f.result.failed, output.failed);
                var column = format_column(f);
                column = column + 3;
                column = column + output.text.length;
                format_dispose(&output);
                if column > 110 {
                    format_text(f, "\n");
                    format_repeat(f, 32, continuation);
                    format_text(f, "|");
                } else {
                    format_text(f, " |");
                }
            }
            var alternative = format_syntax(f, n.items.data[i]);
            if alternative.items.length != 0 {
                format_text(f, " ");
            }
            format_alternative(f, n.items.data[i]);
            i++;
        }
        format_precedence(f, n);
        format_replacement(f, n);
        if n.replacement == null {
            if n.items.length != 0 {
                var last = n.items.length -1;
                var alternative = format_syntax(f, n.items.data[last]);
                if alternative.items.length == 0 {
                    format_text(f, " ");
                }
            }
        }
        format_text(f, ";\n");
    } else {
        var entry = n.kind == 2;
        var skipped = n.kind == 3;
        if format_or(entry, skipped) {
            if skipped {
                format_text(f, "skip ");
            } else {
                format_text(f, "token ");
            }
            format_identifier(f, &n.name);
            format_text(f, " = /");
            format_bytes(f, &n.text);
            format_text(f, "/");
            if n.contextual {
                format_text(f, " when expected");
            }
            if n.style.length != 0 {
                format_text(f, " as ");
                format_identifier(f, &n.style);
            }
            format_text(f, ";\n");
        } else {
            if n.kind == 4 {
                format_alternative(f, entity);
                format_replacement(f, n);
            }
            else {
                if n.kind == 5 {
                    format_grammar_term(f, entity);
                }
                else {
                    format_bytes(f, &n.text);
                }
            }
        }
    }
    var invalid: usize = 0;
    invalid--;
    if n.start != invalid {
        format_span(f, begin, n.start);
    }
}

// Compact grammar previews share canonical spelling without enclosing comments
// or replacement bodies. Hover descriptions are emitted by the language query.
export fn format_grammar_preview(result: FormatResult*, entity: void*, syntax: void*): void {
    var f: FormatEngine;
    f.source_names = false;
    fill(&f, 0, sizeof(FormatEngine));
    f.result = result;
    f.syntax_kind = syntax;
    var n = format_syntax(&f, entity);
    if n == null {
        return;
    }
    if n.kind == SyntaxAlternative() {
        format_alternative(&f, entity);
        format_precedence(&f, n);
        return;
    }
    if n.kind == SyntaxTerm() {
        format_grammar_term(&f, entity);
        return;
    }
    if n.kind == SyntaxToken() {
        format_text(&f, "token ");
    }
    if n.kind == SyntaxSkip() {
        format_text(&f, "skip ");
    }
    format_identifier(&f, &n.name);
    if n.kind == SyntaxToken() {
        format_text(&f, " = /");
        format_bytes(&f, &n.text);
        format_text(&f, "/");
    }
    if n.kind == SyntaxSkip() {
        format_text(&f, " = /");
        format_bytes(&f, &n.text);
        format_text(&f, "/");
    }
}

import tower;
import format_types;
import .library.vector;
import format_api;
import parser_types;
import format_parser_table;
import format_syntax_preview;
import format_diagnostic;

// Diagnostic views use the shared formatter and graph. They are not program
// serialization; format_entity remains the canonical foundation spelling.
struct FormatTreeEntry {
    node: void*;
    depth: usize;
    member: u8*;
}

extern fn entity_child_index(parent: void*, child: void*): usize;

extern fn entity_parent(node: void*): void*;

extern fn entity_child_name(parent: void*, index: usize): u8*;

extern fn entity_child_count(parent: void*): usize;

extern fn entity_child_at(parent: void*, index: usize): void*;

extern fn parser_match_get_type(): void*;

extern fn tower_memory_allocate(bytes: usize): void*;

extern fn abort(): void;

fn format_parser_no_rule(): usize {
    var invalid: usize = 0;
    invalid--;
    return invalid;
}

fn format_tree_push(pending: vector(FormatTreeEntry)*, node: void*, depth: usize, member: u8*): bool {
    var needed = pending.length + 1;
    if needed == 0 {
        return false;
    }
    var ok = vector_reserve(FormatTreeEntry, pending, needed);
    if ok {
        var entry = &pending.data[pending.length];
        entry.node = node;
        entry.depth = depth;
        entry.member = member;
        pending.length = needed;
    }
    return ok;
}

// The caller keeps the graph and component kind alive and immutable for this
// query. No global world lookup, graph mutation or borrowed pointer escapes.
export fn format_parser_tree(result: FormatResult*, root: void*, kind: void*): void {
    var f: FormatEngine;
    fill(&f, 0, sizeof(FormatEngine));
    f.result = result;
    f.match_kind = kind;
    if root == null {
        format_text(&f, "<empty tree>\n");
        return;
    }
    var member: u8* = null;
    var parent = entity_parent(root);
    if parent != null {
        member = entity_child_name(parent, entity_child_index(parent, root));
    }
    var pending: vector(FormatTreeEntry);
    vector_init(FormatTreeEntry, &pending);
    var ok = format_tree_push(&pending, root, 0, member);
    if !ok {
        result.failed = true;
    }
    while pending.length != 0 {
        if result.failed {
            break;
        }
        pending.length--;
        var entry = &pending.data[pending.length];
        var node = entry.node;
        var depth = entry.depth;
        member = entry.member;
        var indent = depth *2;
        if indent < depth {
            result.failed = true;
            break;
        }
        format_repeat(&f, 32, indent);
        var named = member != null;
        named &&= *member != 0;
        if named {
            format_text(&f, member);
            format_text(&f, ": ");
        }
        var span = format_match(&f, node);
        if span != null {
            var rule = span.rule != format_parser_no_rule();
            if rule {
                format_text(&f, "rule ");
            } else {
                format_text(&f, "token ");
            }
            var label = span.label.length != 0;
            if label {
                format_bytes(&f, &span.label);
            } else {
                format_unsigned(&f, convert(u64, span.id));
            }
            if rule {
                format_text(&f, " #");
                format_unsigned(&f, convert(u64, span.rule));
            }
            format_text(&f, " [");
            format_unsigned(&f, convert(u64, span.start));
            format_text(&f, ", ");
            var end = span.start + span.length;
            format_unsigned(&f, convert(u64, end));
            format_text(&f, ")");
        } else {
            format_text(&f, "node");
        }
        format_char(&f, 10);
        var count = entity_child_count(node);
        var next_depth = depth + 1;
        while count != 0 {
            count--;
            ok = format_tree_push(&pending, entity_child_at(node, count), next_depth, entity_child_name(node, count));
            if !ok {
                result.failed = true;
                break;
            }
        }
    }
    vector_dispose(FormatTreeEntry, &pending);
}

enum ParserScalar: u32 {
    Nul = 0,
    Tab = 9,
    LineFeed = 10,
    CarriageReturn = 13,
    Quote = 39,
    Backslash = 92
}

fn format_parser_escape(id: u32): u8* {
    var scalar = convert(ParserScalar, id);
    match scalar {
        ParserScalar.Nul => {
            return "'\\0'";
        }
        ParserScalar.Tab => {
            return "'\\t'";
        }
        ParserScalar.LineFeed => {
            return "'\\n'";
        }
        ParserScalar.CarriageReturn => {
            return "'\\r'";
        }
        ParserScalar.Quote => {
            return "'\\\''";
        }
        ParserScalar.Backslash => {
            return "'\\\\'";
        }
        _ => {
            return null;
        }
    }
}

extern fn tower_utf8_encode(id: u32, output: u8*, capacity: usize): usize;

// Invalid scalars leave the result unchanged. Allocation failure is reported
// through FormatResult.failed, as with the other shared formatting operations.
export fn format_parser_scalar(result: FormatResult*, id: u32): bool {
    var encoded: u8[4];
    var count = tower_utf8_encode(id, &encoded[0], 4);
    if count == 0 {
        return false;
    }
    var f: FormatEngine;
    fill(&f, 0, sizeof(FormatEngine));
    f.result = result;
    var escaped = format_parser_escape(id);
    if escaped != null {
        format_text(&f, escaped);
    } else {
        format_char(&f, convert(u8, ParserScalar.Quote));
        format_write(&f, &encoded[0], count);
        format_char(&f, convert(u8, ParserScalar.Quote));
    }
    return true;
}

export fn format_parser_host_text(result: FormatResult*): u8* {
    var size = result.text.length + 1;
    if size == 0 {
        result.failed = true;
    }
    if result.failed {
        format_dispose(result);
        abort();
        return null;
    }
    var text = bits(u8*, tower_memory_allocate(size));
    if text == null {
        format_dispose(result);
        abort();
        return null;
    }
    copy(text, result.text.data, result.text.length);
    text[result.text.length] = 0;
    format_dispose(result);
    return text;
}

// Existing host ABI and allocator ownership. The implementation stays in Tower.
// Labels already have their spelling; allocate only the final host-owned string.
// This is the same direct-output approach as the bounded scalar formatter below.
export fn format_parser_label_text(text: u8*, length: usize, prefix: u8*, suffix: u8*): u8* {
    var before: usize = 0;
    while prefix[before] != 0 {
        ++before;
    }
    var after: usize = 0;
    while suffix[after] != 0 {
        ++after;
    }
    var size = length + before;
    var end = size + after;
    var capacity = end + 1;
    if size < length || end < size || capacity == 0 {
        abort();
        return null;
    }
    var output = bits(u8*, tower_memory_allocate(capacity));
    if output is null {
        abort();
        return null;
    }
    copy(output, prefix, before);
    copy(&output[before], text, length);
    copy(&output[size], suffix, after);
    output[end] = 0;
    return output;
}

export fn parser_tree_debug_string(root: void*): u8* {
    var result: FormatResult;
    fill(&result, 0, sizeof(FormatResult));
    var kind: void* = null;
    if root != null {
        kind = parser_match_get_type();
    }
    format_parser_tree(&result, root, kind);
    return format_parser_host_text(&result);
}

export fn parser_table_utf8_id_to_string(userdata: void*, id: u32): u8* {
    // One scalar needs at most four UTF-8 bytes plus quotes. Use bounded scratch
    // storage so this hot host path still allocates only its returned string.
    var scratch: u8[6];
    var result: FormatResult;
    fill(&result, 0, sizeof(FormatResult));
    result.text.data = &scratch[0];
    result.text.capacity = 6;
    if !format_parser_scalar(&result, id) {
        return null;
    }
    var size = result.text.length + 1;
    var text = bits(u8*, tower_memory_allocate(size));
    if text == null {
        abort();
        return null;
    }
    copy(text, result.text.data, result.text.length);
    text[result.text.length] = 0;
    return text;
}

import tower;
import format_api;
import format_parser_table_types;
import lr_api;
import lr_types;
import format_types;
import parser_table_types;
import parser_markers;
import .library.vector;

extern fn parser_table_rule_next(table: ParserHostTable*, owner: usize, begin: usize): usize;

const ParserConflictAlternatives: usize = 3;

fn parser_format_push(request: ParserFormat*, kind: ParserFormatTask, a: usize, b: usize, c: usize, text: u8*): void {
    if request.result.failed {
        return;
    }
    var size = request.frames.length + 1;
    var ok = size != 0;
    ok &&= vector_reserve(ParserFormatFrame, &request.frames, size);
    if ok {
        var frame = &request.frames.data[request.frames.length];
        frame.kind = kind;
        frame.a = a;
        frame.b = b;
        frame.c = c;
        frame.text = text;
        request.frames.length = size;
    } else {
        request.result.failed = true;
    }
}

fn parser_format_text_later(request: ParserFormat*, text: u8*): void {
    parser_format_push(request, ParserFormatTask.Text, 0, 0, 0, text);
}

fn parser_format_item_later(request: ParserFormat*, rule: usize, dot: usize): void {
    parser_format_push(request, ParserFormatTask.Item, rule, dot, 0, null);
}

fn parser_format_state_valid(request: ParserFormat*, index: usize): bool {
    var ok = request.table != null;
    ok &&= index < request.table.states.length;
    if !ok {
        request.result.failed = true;
    }
    return ok;
}

fn parser_format_rule_valid(request: ParserFormat*, index: usize): bool {
    var ok = request.table != null;
    ok &&= index < lr_grammar_rule_count(request.table.grammar);
    if !ok {
        request.result.failed = true;
    }
    return ok;
}

// Frames are popped before execution; a paused callback never retains a pointer
// into the growable frame storage. Iterators schedule one child at a time.
fn parser_format_frame(request: ParserFormat*, frame: ParserFormatFrame*): void {
    var f: FormatEngine;
    fill(&f, 0, sizeof(FormatEngine));
    f.result = &request.result;
    var table = request.table;
    match frame.kind {
        ParserFormatTask.Text => {
            format_text(&f, frame.text);
        }
        ParserFormatTask.Scalar => {
            var id = convert(u32, frame.a);
            var end = id == ParserStreamEnd();
            var lookahead = id == ParserLookahead();
            if end {
                format_text(&f, "$");
            }
            else {
                if lookahead {
                    format_text(&f, "#");
                }
                else {
                    if request.names {
                        request.need = ParserFormatNeed.Name;
                        request.index = frame.a;
                    } else {
                        format_unsigned(&f, convert(u64, id));
                    }
                }
            }
        }
        ParserFormatTask.Range => {
            if frame.a != frame.b {
                format_text(&f, "[");
                parser_format_text_later(request, "]");
                parser_format_push(request, ParserFormatTask.Scalar, frame.b, 0, 0, null);
                parser_format_text_later(request, "-");
            }
            parser_format_push(request, ParserFormatTask.Scalar, frame.a, 0, 0, null);
        }
        ParserFormatTask.Symbol => {
            var valid = frame.a < lr_grammar_symbol_count(table.grammar);
            if !valid {
                request.result.failed = true;
                return;
            }
            var symbols = lr_grammar_symbol_data(table.grammar);
            var symbol = &symbols[frame.a];
            var terminal = symbol.nonterminal == ParserNoIndex();
            if terminal {
                parser_format_push(request, ParserFormatTask.Range, convert(usize, symbol.first), convert(usize, symbol.last), 0, null);
            } else {
                format_text(&f, lr_grammar_name(table.grammar, symbol.nonterminal));
            }
        }
        ParserFormatTask.Item => {
            var valid = parser_format_rule_valid(request, frame.a);
            if !valid {
                return;
            }
            var rules = lr_grammar_rule_data(table.grammar);
            var rule = &rules[frame.a];
            format_text(&f, lr_grammar_name(table.grammar, rule.owner));
            format_text(&f, " =");
            parser_format_push(request, ParserFormatTask.ItemTail, frame.a, 0, frame.b, null);
        }
        ParserFormatTask.ItemTail => {
            var rules = lr_grammar_rule_data(table.grammar);
            var rule = &rules[frame.a];
            format_text(&f, " ");
            if frame.b == frame.c {
                format_text(&f, "•");
            }
            var inside = frame.b < rule.count;
            if inside {
                var next = frame.b + 1;
                var symbol = rule.begin + frame.b;
                parser_format_push(request, ParserFormatTask.ItemTail, frame.a, next, frame.c, null);
                parser_format_push(request, ParserFormatTask.Symbol, symbol, 0, 0, null);
            }
        }
        ParserFormatTask.Rules => {
            var inside = frame.a < lr_grammar_rule_count(table.grammar);
            if inside {
                var next = frame.a + 1;
                parser_format_push(request, ParserFormatTask.Rules, next, 0, 0, null);
                parser_format_text_later(request, "\n");
                parser_format_item_later(request, frame.a, ParserNoIndex());
            }
        }
        ParserFormatTask.Names => {
            var inside = frame.a < lr_grammar_name_count(table.grammar);
            if inside {
                format_text(&f, "non_terminal(");
                format_unsigned(&f, convert(u64, frame.a));
                format_text(&f, ", ");
                format_text(&f, lr_grammar_name(table.grammar, frame.a));
                format_text(&f, ")\n");
                var next = frame.a + 1;
                parser_format_push(request, ParserFormatTask.Names, next, 0, 0, null);
                parser_format_push(request, ParserFormatTask.NamedRules, frame.a, 0, 0, null);
            }
        }
        ParserFormatTask.NamedRules => {
            var rule = parser_table_rule_next(table, frame.a, frame.b);
            var present = rule != ParserNoIndex();
            if present {
                format_text(&f, "  ");
                var next = rule + 1;
                parser_format_push(request, ParserFormatTask.NamedRules, frame.a, next, 0, null);
                parser_format_text_later(request, "\n");
                parser_format_item_later(request, rule, ParserNoIndex());
            }
        }
        ParserFormatTask.Header => {
            var valid = parser_format_state_valid(request, frame.a);
            if !valid {
                return;
            }
            format_text(&f, frame.text);
            format_text(&f, "(");
            format_unsigned(&f, convert(u64, frame.a));
            parser_format_text_later(request, ")");
            var origin = table.states.data[frame.a].origin;
            var present = origin != ParserNoIndex();
            if present {
                format_text(&f, ", ");
                parser_format_push(request, ParserFormatTask.Symbol, origin, 0, 0, null);
            }
        }
        ParserFormatTask.State => {
            var valid = parser_format_state_valid(request, frame.a);
            if !valid {
                return;
            }
            parser_format_push(request, ParserFormatTask.Gotos, frame.a, 0, 0, null);
            parser_format_push(request, ParserFormatTask.Actions, frame.a, 0, 0, null);
            parser_format_text_later(request, ":\n");
            parser_format_push(request, ParserFormatTask.Header, frame.a, 0, 0, "state");
        }
        ParserFormatTask.States => {
            var inside = frame.a < table.states.length;
            if inside {
                var next = frame.a + 1;
                parser_format_push(request, ParserFormatTask.States, next, 0, 0, null);
                parser_format_text_later(request, "\n");
                parser_format_push(request, ParserFormatTask.State, frame.a, 0, 0, null);
            }
        }
        ParserFormatTask.Actions => {
            var inside = frame.b < lr_runtime_action_count(table.runtime, frame.a);
            if inside {
                var actions = lr_runtime_actions(table.runtime, frame.a);
                var action = &actions[frame.b];
                format_text(&f, "  edge(");
                var next = frame.b + 1;
                parser_format_push(request, ParserFormatTask.Actions, frame.a, next, 0, null);
                parser_format_text_later(request, ")\n");
                parser_format_push(request, ParserFormatTask.Edge, action.rule, action.state, 0, null);
                parser_format_text_later(request, ", ");
                parser_format_push(request, ParserFormatTask.Range, convert(usize, action.first), convert(usize, action.last), 0, null);
            }
        }
        ParserFormatTask.Gotos => {
            var inside = frame.b < lr_runtime_goto_count(table.runtime, frame.a);
            if inside {
                var gotos = lr_runtime_goto_data(table.runtime, frame.a);
                var entry = &gotos[frame.b];
                format_text(&f, "  goto(");
                format_text(&f, lr_grammar_name(table.grammar, entry.nonterminal));
                format_text(&f, ", ");
                var next = frame.b + 1;
                parser_format_push(request, ParserFormatTask.Gotos, frame.a, next, 0, null);
                parser_format_text_later(request, ")\n");
                parser_format_push(request, ParserFormatTask.Header, entry.state, 0, 0, "state");
            }
        }
        ParserFormatTask.Edge => {
            var reduce = frame.a != ParserNoIndex();
            if reduce {
                var valid = parser_format_rule_valid(request, frame.a);
                if !valid {
                    return;
                }
                var rules = lr_grammar_rule_data(table.grammar);
                var count = rules[frame.a].count;
                format_text(&f, "reduce(");
                format_unsigned(&f, convert(u64, frame.a));
                format_text(&f, ", ");
                parser_format_text_later(request, ")");
                parser_format_item_later(request, frame.a, count);
            } else {
                parser_format_push(request, ParserFormatTask.Header, frame.b, 0, 0, "shift");
            }
        }
        ParserFormatTask.Describe => {
            if request.descriptions {
                request.need = ParserFormatNeed.Description;
                request.index = frame.a;
            } else {
                parser_format_item_later(request, frame.a, ParserNoIndex());
            }
        }
        ParserFormatTask.Conflict => {
            var failed = table.error != null;
            if failed {
                format_text(&f, table.error);
                return;
            }
            var conflict: LRConflict;
            if !lr_runtime_conflict(table.runtime, &conflict) {
                return;
            }
            var left = conflict.left.rule != ParserNoIndex();
            var right = conflict.right.rule != ParserNoIndex();
            format_text(&f, "Grammar conflict (");
            if left {
                if right {
                    format_text(&f, "reduce/reduce");
                }
                else {
                    format_text(&f, "shift/reduce");
                }
            } else {
                if right {
                    format_text(&f, "shift/reduce");
                }
                else {
                    format_text(&f, "shift/shift");
                }
            }
            format_text(&f, ") on ");
            parser_format_text_later(request, ". Make these alternatives distinct; their order does not resolve the conflict.");
            parser_format_push(request, ParserFormatTask.Alternative, 1, 0, 0, null);
            parser_format_text_later(request, ", or ");
            parser_format_push(request, ParserFormatTask.Alternative, 0, 0, 0, null);
            parser_format_text_later(request, ": the parser could ");
            parser_format_push(request, ParserFormatTask.Range, convert(usize, conflict.right.first), convert(usize, conflict.right.last), 0, null);
        }
        ParserFormatTask.Alternative => {
            var conflict: LRConflict;
            lr_runtime_conflict(table.runtime, &conflict);
            var action = &conflict.left;
            var right = frame.a != 0;
            if right {
                action = &conflict.right;
            }
            var reduce = action.rule != ParserNoIndex();
            if reduce {
                format_text(&f, "finish ");
                parser_format_push(request, ParserFormatTask.Describe, action.rule, 0, 0, null);
            } else {
                format_text(&f, "continue ");
                parser_format_push(request, ParserFormatTask.Continue, frame.a, 0, 0, null);
            }
        }
        ParserFormatTask.Continue => {
            var conflict: LRConflict;
            lr_runtime_conflict(table.runtime, &conflict);
            var action = &conflict.left;
            var right = frame.a != 0;
            if right {
                action = &conflict.right;
            }
            var state = &table.states.data[conflict.state];
            var index = frame.b;
            while index < state.contexts.length {
                if index == state.kernels {
                    if frame.c != 0 {
                        return;
                    }
                }
                var item = &state.contexts.data[index];
                var selected = item.terminal;
                var outside = item.last < action.first;
                if outside {
                    selected = false;
                }
                outside = action.last < item.first;
                if outside {
                    selected = false;
                }
                index++;
                if selected {
                    if frame.c != 0 {
                        format_text(&f, " or ");
                    }
                    var count = frame.c + 1;
                    if count < ParserConflictAlternatives() {
                        parser_format_push(request, ParserFormatTask.Continue, frame.a, index, count, null);
                    }
                    parser_format_push(request, ParserFormatTask.Describe, item.production, 0, 0, null);
                    return;
                }
            }
        }
        ParserFormatTask.Expected => {
            var end = frame.a == convert(usize, ParserStreamEnd());
            if end {
                format_text(&f, "end of input");
            }
            else {
                parser_format_push(request, ParserFormatTask.Scalar, frame.a, 0, 0, null);
            }
        }
        ParserFormatTask.Unexpected => {
            format_text(&f, "Unexpected ");
            parser_format_text_later(request, ".");
            parser_format_push(request, ParserFormatTask.Expected, frame.a, 0, 0, null);
        }
        ParserFormatTask.Missing => {
            var valid = frame.a < lr_grammar_missing_count(table.grammar);
            if valid {
                format_text(&f, "Unresolved grammar rule: ");
                format_text(&f, lr_grammar_missing_name(table.grammar, frame.a));
            } else {
                request.result.failed = true;
            }
        }
        _ => {
            request.result.failed = true;
        }
    }
}

export fn parser_format_destroy(request: ParserFormat*): void {
    if request == null {
        return;
    }
    format_dispose(&request.result);
    vector_dispose(ParserFormatFrame, &request.frames);
    free(request);
}

// No callback is invoked here. The caller pins the table and answers requests
// until Done; destroy also supports cancellation while a request is pending.
export fn parser_format_create(table: ParserHostTable*, kind: ParserFormatKind, first: usize, second: usize, names: bool, descriptions: bool): ParserFormat* {
    var request = alloc(ParserFormat, 1);
    var absent = request == null;
    if absent {
        return null;
    }
    fill(request, 0, sizeof(ParserFormat));
    request.table = table;
    request.names = names;
    request.descriptions = descriptions;
    match kind {
        ParserFormatKind.Scalar => {
            parser_format_push(request, ParserFormatTask.Scalar, first, 0, 0, null);
        }
        ParserFormatKind.Range => {
            parser_format_push(request, ParserFormatTask.Range, first, second, 0, null);
        }
        ParserFormatKind.Expected => {
            parser_format_push(request, ParserFormatTask.Expected, first, 0, 0, null);
        }
        ParserFormatKind.Unexpected => {
            parser_format_push(request, ParserFormatTask.Unexpected, first, 0, 0, null);
        }
        _ => {
            absent = table == null;
            if absent {
                request.result.failed = true;
                return request;
            }
            absent = table.grammar == null;
            if absent {
                request.result.failed = true;
                return request;
            }
            match kind {
                ParserFormatKind.Item => {
                    parser_format_item_later(request, first, second);
                }
                ParserFormatKind.Rule => {
                    parser_format_item_later(request, first, ParserNoIndex());
                }
                ParserFormatKind.Grammar => {
                    parser_format_push(request, ParserFormatTask.Names, 0, 0, 0, null);
                    parser_format_push(request, ParserFormatTask.Rules, 0, 0, 0, null);
                }
                ParserFormatKind.State => {
                    parser_format_push(request, ParserFormatTask.State, first, 0, 0, null);
                }
                ParserFormatKind.Tables => {
                    parser_format_text_later(request, "..........\n");
                    parser_format_push(request, ParserFormatTask.States, 0, 0, 0, null);
                    parser_format_text_later(request, "~~~~~~~~~~\n");
                }
                ParserFormatKind.Edge => {
                    parser_format_push(request, ParserFormatTask.Edge, first, second, 0, null);
                }
                ParserFormatKind.Conflict => {
                    parser_format_push(request, ParserFormatTask.Conflict, 0, 0, 0, null);
                }
                ParserFormatKind.Missing => {
                    parser_format_push(request, ParserFormatTask.Missing, first, 0, 0, null);
                }
                _ => {
                    request.result.failed = true;
                }
            }
        }
    }
    return request;
}

export fn parser_format_next(request: ParserFormat*): ParserFormatNeed {
    if request.result.failed {
        return ParserFormatNeed.Done;
    }
    var pending = request.need != ParserFormatNeed.Done;
    if pending {
        return request.need;
    }
    while request.frames.length != 0 {
        request.frames.length--;
        var frame: ParserFormatFrame;
        copy(&frame, &request.frames.data[request.frames.length], sizeof(ParserFormatFrame));
        parser_format_frame(request, &frame);
        if request.result.failed {
            return ParserFormatNeed.Done;
        }
        pending = request.need != ParserFormatNeed.Done;
        if pending {
            return request.need;
        }
    }
    return ParserFormatNeed.Done;
}

export fn parser_format_index(request: ParserFormat*): usize {
    return request.index;
}

// Text is copied, never retained. A null name requests numeric fallback; an
// empty description requests the grammar production. Embedded bytes survive.
export fn parser_format_reply(request: ParserFormat*, text: u8*, length: usize): void {
    var need = request.need;
    request.need = ParserFormatNeed.Done;
    if request.result.failed {
        return;
    }
    var absent = text == null;
    if absent {
        if length != 0 {
            request.result.failed = true;
            return;
        }
    }
    var f: FormatEngine;
    fill(&f, 0, sizeof(FormatEngine));
    f.result = &request.result;
    match need {
        ParserFormatNeed.Name => {
            if absent {
                format_unsigned(&f, convert(u64, request.index));
            }
            else {
                format_write(&f, text, length);
            }
        }
        ParserFormatNeed.Description => {
            if length == 0 {
                parser_format_item_later(request, request.index, ParserNoIndex());
            }
            else {
                format_write(&f, text, length);
            }
        }
        _ => {
            request.result.failed = true;
        }
    }
}

export fn parser_format_result(request: ParserFormat*): FormatResult* {
    return &request.result;
}

import format_types;
import tower;
import .library.vector;
import parser_table_types;

enum ParserFormatKind: u32 {
    Scalar, Range, Item, Rule, Grammar, State, Tables, Edge, Conflict,
    Expected, Unexpected, Missing
}

enum ParserFormatNeed: u32 {
    Done, Name, Description
}

// Private formatter traversal frames, not grammar/semantic nodes or a program
// encoding. Input records stay borrowed and immutable until the request ends.
enum ParserFormatTask: u32 {
    Text, Scalar, Range, Symbol, Item, ItemTail, Rules, Names, NamedRules,
    Header, State, States, Actions, Gotos, Edge, Describe, Conflict,
    Alternative, Continue, Expected, Unexpected, Missing
}

struct ParserFormatFrame {
    kind: ParserFormatTask;
    a: usize;
    b: usize;
    c: usize;
    text: u8*;
}

struct ParserFormat {
    result: FormatResult;
    table: ParserHostTable*;
    frames: vector(ParserFormatFrame);
    need: ParserFormatNeed;
    index: usize;
    names: bool;
    descriptions: bool;
}

import tower;
import format_grammar;
import format_types;
import format;
import regex_lowering;
import .library.vector;

// Temporary token positions/spacing flags derived from parser matches.
// Comments come exclusively from the lexer; no second token grammar.
// The checked sorted-input fast path replaces rescanning every comment for
// every root. This is a derived lookup, never authoritative syntax.
fn format_comments_ordered(comments: FormatComment*, count: usize): bool {
    var i: usize = 1;
    loop {
        if i >= count {
            return true;
        }
        var previous = i -1;
        if comments[previous].start > comments[i].start {
            return false;
        }
        i++;
    }
}

fn format_comment_bound(comments: FormatComment*, count: usize, start: usize): usize {
    var low: usize = 0;
    var high = count;
    loop {
        if low == high {
            return low;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = low + middle;
        if comments[middle].start < start {
            low = middle + 1;
        }
        else {
            high = middle;
        }
    }
}

struct FormatToken {
    start: usize;
    end: usize;
    comment: bool;
    pointer: bool;
    unary: bool;
    call: bool;
    prefix: bool;
    postfix: bool;
}

struct FormatComment {
    start: usize;
    end: usize;
}

fn format_symbolic(source: u8*, start: usize, end: usize): bool {
    if start == end {
        return false;
    }
    loop {
        if start == end {
            return true;
        }
        var c = source[start];
        var symbols = "+-*/%&|^~!<>=?";
        var i: usize = 0;
        var found = false;
        loop {
            if symbols[i] == 0 {
                break;
            }
            if symbols[i] == c {
                found = true;
                break;
            }
            i++;
        }
        if !found {
            return false;
        }
        start++;
    }
}

fn format_operator_leaf(f: FormatEngine*, entity: void*, source: u8*): bool {
    // Grouped operator alternatives are transparent single-child rules.
    for(var depth: usize = 0; entity_child_count(entity) == 1 && depth < 128; depth++) {
        entity = entity_child_at(entity, 0);
    }
    var `match` = format_match(f, entity);
    if `match` == null {
        return false;
    }
    var invalid: usize = 0;
    invalid--;
    if `match`.rule != invalid {
        return false;
    }
    var end = `match`.start + `match`.length;
    return format_symbolic(source, `match`.start, end);
}

fn format_token_push(f: FormatEngine*, tokens: vector(FormatToken)*, start: usize, end: usize,
comment: bool, pointer: bool, unary: bool, call: bool): void {
    var needed = tokens.length + 1;
    if vector_reserve(FormatToken, tokens, needed) {
        var t = &tokens.data[tokens.length];
        t.start = start;
        t.end = end;
        t.comment = comment;
        t.pointer = pointer;
        t.unary = unary;
        t.call = call;
        t.prefix = false;
        t.postfix = false;
        tokens.length = needed;
    } else {
        f.result.failed = true;
    }
}

fn format_tokens(f: FormatEngine*, entity: void*, source: u8*, tokens: vector(FormatToken)*,
pointer: bool, unary: bool, call: bool): void {
    var `match` = format_match(f, entity);
    if `match` == null {
        return;
    }
    if format_name_is(&`match`.label, "CoreType") {
        pointer = true;
    }
    if format_name_is(&`match`.label, "CorePointerArgument") {
        pointer = true;
    }
    if format_name_is(&`match`.label, "CoreAddress") {
        unary = true;
    }
    if format_name_is(&`match`.label, "CoreLoad") {
        unary = true;
    }
    if format_name_is(&`match`.label, "CoreTarget") {
        unary = true;
    }
    if format_name_is(&`match`.label, "CoreOperand") {
        unary = true;
    }
    if format_name_is(&`match`.label, "CoreCall") {
        call = true;
    }
    if format_name_is(&`match`.label, "CoreFunction") {
        call = true;
    }
    if format_name_is(&`match`.label, "CoreExternal") {
        call = true;
    }
    if format_name_is(&`match`.label, "CoreExport") {
        call = true;
    }
    if format_name_is(&`match`.label, "CoreType") {
        call = true;
    }
    var invalid: usize = 0;
    invalid--;
    if `match`.rule == invalid {
        var end = `match`.start + `match`.length;
        if end > `match`.start {
            format_token_push(f, tokens, `match`.start, end, false, pointer, unary, call);
        }
        return;
    }
    var begin = tokens.length;
    var children = entity_child_count(entity);
    var i: usize = 0;
    loop {
        if i == children {
            break;
        }
        format_tokens(f, entity_child_at(entity, i), source, tokens, pointer, unary, call);
        i++;
    }
    if children == 2 {
        var minimum = begin + 1;
        if tokens.length > minimum {
            var first = format_operator_leaf(f, entity_child_at(entity, 0), source);
            var last = format_operator_leaf(f, entity_child_at(entity, 1), source);
            if first != last {
                if first {
                    tokens.data[begin].prefix = true;
                }
                else {
                    var back = tokens.length -1;
                    tokens.data[back].postfix = true;
                }
            }
        }
    }
}

fn format_source_declaration(f: FormatEngine*, entity: void*): bool {
    var `match` = format_match(f, entity);
    if `match` == null {
        return false;
    }
    if format_name_is(&`match`.label, "CoreFunction") {
        return true;
    }
    if format_name_is(&`match`.label, "CoreExternal") {
        return true;
    }
    if format_name_is(&`match`.label, "CoreExport") {
        return true;
    }
    if format_name_is(&`match`.label, "CoreStruct") {
        return true;
    }
    var children = entity_child_count(entity);
    if children == 1 {
        return format_source_declaration(f, entity_child_at(entity, 0));
    }
    return false;
}

fn format_token_swap(a: FormatToken*, b: FormatToken*): void {
    var temporary: FormatToken;
    copy(&temporary, a, sizeof(FormatToken));
    copy(a, b, sizeof(FormatToken));
    copy(b, &temporary, sizeof(FormatToken));
}

fn format_sift(tokens: vector(FormatToken)*, root: usize, end: usize): void {
    loop {
        var child = root *2;
        child++;
        if child >= end {
            return;
        }
        var next = child + 1;
        if next < end {
            if tokens.data[child].start < tokens.data[next].start {
                child = next;
            }
        }
        if tokens.data[root].start >= tokens.data[child].start {
            return;
        }
        format_token_swap(&tokens.data[root], &tokens.data[child]);
        root = child;
    }
}

fn format_sort(tokens: vector(FormatToken)*): void {
    // Parser leaves are already ordered in the usual no-comment case.
    var next: usize = 1;
    loop {
        if next >= tokens.length {
            return;
        }
        var previous = next -1;
        if tokens.data[previous].start > tokens.data[next].start {
            break;
        }
        next++;
    }
    var at = tokens.length / 2;
    loop {
        if at == 0 {
            break;
        }
        at--;
        format_sift(tokens, at, tokens.length);
    }
    var end = tokens.length;
    loop {
        if end <= 1 {
            break;
        }
        end--;
        format_token_swap(&tokens.data[0], &tokens.data[end]);
        format_sift(tokens, 0, end);
    }
}

fn format_lines(source: u8*, start: usize, end: usize): usize {
    var count: usize = 0;
    loop {
        if start >= end {
            return count;
        }
        if source[start] == 10 {
            count++;
        }
        start++;
    }
}

fn format_token_is(source: u8*, entry: FormatToken*, text: u8*): bool {
    var length = entry.end -entry.start;
    return format_equal(&source[entry.start], length, text);
}

fn format_source_statement(f: FormatEngine*, entity: void*, source: u8*, from: usize, end: usize,
comments: FormatComment*, comment_count: usize, ordered: bool): void {
    var tokens: vector(FormatToken);
    vector_init(FormatToken, &tokens);
    format_tokens(f, entity, source, &tokens, false, false, false);
    var i: usize = 0;
    if ordered {
        i = format_comment_bound(comments, comment_count, from);
    }
    loop {
        if i == comment_count {
            break;
        }
        var comment = &comments[i];
        if ordered {
            if comment.start > end {
                break;
            }
        }
        var after = comment.start >= from;
        var before = comment.end <= end;
        if format_and(after, before) {
            format_token_push(f, &tokens, comment.start, comment.end, true, false, false, false);
        }
        i++;
    }
    format_sort(&tokens);
    var previous: FormatToken;
    fill(&previous, 0, sizeof(FormatToken));
    var previous_end = from;
    var parentheses: usize = 0;
    i = 0;
    loop {
        if i == tokens.length {
            break;
        }
        var entry = &tokens.data[i];
        var lines = format_lines(source, previous_end, entry.start);
        var close = format_token_is(source, entry, "}");
        if !entry.comment {
            if close {
                if f.result.depth != 0 {
                    f.result.depth--;
                }
            }
        }
        var last_open = format_token_is(source, &previous, "{");
        var last_close = format_token_is(source, &previous, "}");
        var close_empty = format_and(close, last_open);
        var break_line = false;
        if previous.end != previous.start {
            if !close_empty {
                var semicolon = format_token_is(source, &previous, ";");
                if parentheses != 0 {
                    semicolon = false;
                }
                if entry.comment {
                    if lines == 0 {
                        semicolon = false;
                    }
                }
                var after_close = last_close;
                if format_token_is(source, entry, ";") {
                    after_close = false;
                }
                if format_token_is(source, entry, "else") {
                    after_close = false;
                }
                if format_token_is(source, entry, ",") {
                    after_close = false;
                }
                if format_token_is(source, entry, ")") {
                    after_close = false;
                }
                break_line = format_or(previous.comment, semicolon);
                break_line = format_or(break_line, last_open);
                break_line = format_or(break_line, close);
                break_line = format_or(break_line, after_close);
                var gap_lines = lines != 0;
                break_line = format_or(break_line, gap_lines);
            }
        }
        if break_line {
            var blank = lines > 1;
            if last_open {
                blank = false;
            }
            format_newline(f, blank);
        }
        var line_start = f.result.text.length == 0;
        if !line_start {
            var last = f.result.text.length -1;
            line_start = f.result.text.data[last] == 10;
        }
        if line_start {
            format_indent(f);
        }
        else {
            if !close_empty {
                var tight = false;
                if format_token_is(source, entry, ";") {
                    tight = true;
                }
                if format_token_is(source, entry, ",") {
                    tight = true;
                }
                if format_token_is(source, entry, ")") {
                    tight = true;
                }
                if format_token_is(source, entry, "]") {
                    tight = true;
                }
                if format_token_is(source, entry, ".") {
                    tight = true;
                }
                if format_token_is(source, entry, ":") {
                    tight = true;
                }
                if format_token_is(source, entry, "[") {
                    tight = true;
                }
                if format_token_is(source, &previous, "(") {
                    tight = true;
                }
                if format_token_is(source, &previous, "[") {
                    tight = true;
                }
                if format_token_is(source, &previous, ".") {
                    tight = true;
                }
                if format_token_is(source, entry, "(") {
                    var empty_gap = previous_end == entry.start;
                    var call = format_or(entry.call, empty_gap);
                    tight = format_or(tight, call);
                }
                if format_token_is(source, entry, "*") {
                    tight = format_or(tight, entry.pointer);
                }
                var affix = format_or(previous.prefix, entry.postfix);
                if previous.comment {
                    affix = false;
                }
                if affix {
                    var left = format_symbolic(source, previous.start, previous.end);
                    var right = format_symbolic(source, entry.start, entry.end);
                    if !format_and(left, right) {
                        tight = true;
                    }
                }
                var unary = false;
                if format_token_is(source, &previous, "*") {
                    unary = true;
                }
                if format_token_is(source, &previous, "&") {
                    unary = true;
                }
                if format_token_is(source, &previous, "-") {
                    unary = true;
                }
                unary = format_and(unary, previous.unary);
                if previous.pointer {
                    unary = false;
                }
                tight = format_or(tight, unary);
                if entry.comment {
                    tight = false;
                }
                if !tight {
                    format_text(f, " ");
                }
            }
        }
        var begin = f.result.text.length;
        var length = entry.end -entry.start;
        format_write(f, &source[entry.start], length);
        format_span(f, begin, entry.start);
        if !entry.comment {
            if format_token_is(source, entry, "{") {
                f.result.depth++;
            }
            if format_token_is(source, entry, "(") {
                parentheses++;
            }
            if format_token_is(source, entry, ")") {
                if parentheses != 0 {
                    parentheses--;
                }
            }
        }
        copy(&previous, entry, sizeof(FormatToken));
        previous_end = entry.end;
        i++;
    }
    format_newline(f, false);
    vector_dispose(FormatToken, &tokens);
}

export fn format_source(result: FormatResult*, roots: void**, count: usize, source: u8*, length: usize,
comments: FormatComment*, comment_count: usize, syntax: void*, foundation: void*, match_kind: void*): void {
    var engine: FormatEngine;
    engine.source_names = false;
    var f = &engine;
    f.result = result;
    f.syntax_kind = syntax;
    f.foundation_kind = foundation;
    f.match_kind = match_kind;
    var previous_end: usize = 0;
    var previous_declaration = false;
    // Lexer trivia is ordered. Check eligibility once, retaining the original
    // behavior for arbitrary caller-supplied comment order.
    var ordered = format_comments_ordered(comments, comment_count);
    var i: usize = 0;
    loop {
        if i == count {
            break;
        }
        var root = roots[i];
        var `match` = format_match(f, root);
        var end = `match`.start + `match`.length;
        var first = `match`.start;
        var j: usize = 0;
        if ordered {
            j = format_comment_bound(comments, comment_count, previous_end);
        }
        loop {
            if j == comment_count {
                break;
            }
            var comment = &comments[j];
            if ordered {
                if comment.start >= first {
                    break;
                }
            }
            var after = comment.start >= previous_end;
            var before = comment.start < first;
            if format_and(after, before) {
                first = comment.start;
            }
            j++;
        }
        var declaration = format_source_declaration(f, root);
        if format_or(previous_declaration, declaration) {
            format_newline(f, true);
        }
        var lines = format_lines(source, previous_end, first);
        if lines > 1 {
            format_newline(f, true);
        }
        var grammar = root;
        loop {
            var syntax_node = format_syntax(f, grammar);
            if syntax_node != null {
                break;
            }
            var children = entity_child_count(grammar);
            if children != 1 {
                break;
            }
            grammar = entity_child_at(grammar, 0);
        }
        var syntax_node = format_syntax(f, grammar);
        if syntax_node != null {
            format_grammar(f, grammar);
        }
        else {
            format_source_statement(f, root, source, previous_end, end, comments, comment_count, ordered);
        }
        previous_end = end;
        previous_declaration = declaration;
        i++;
    }
    i = 0;
    loop {
        if i == comment_count {
            break;
        }
        var comment = &comments[i];
        if comment.start >= previous_end {
            var count = comment.end -comment.start;
            format_write(f, &source[comment.start], count);
            format_newline(f, false);
        }
        i++;
    }
}

