// Immutable revision snapshots retain shared grammar entities. Cache slots are
// disposable host handles; no parser semantics or source is encoded in them.
export fn frontend_revision_release(revision: FrontendRevision*): void {
    if revision == null {
        return;
    }
    revision.references--;
    if revision.references != 0 {
        return;
    }
    var i: usize = 0;
    for(; i != revision.alternatives.length; i++) {
        entity_release(revision.alternatives.data[i]);
    }
    i = 0;
    for(; i != revision.tokens.length; i++) {
        entity_release(revision.tokens.data[i]);
    }
    vector_dispose(SyntaxRuleView, &revision.rules);
    vector_dispose(u8, &revision.names);
    vector_dispose(void*, &revision.alternatives);
    vector_dispose(void*, &revision.tokens);
    free(revision);
}

export fn frontend_revision_retain(revision: FrontendRevision*): FrontendRevision* {
    if revision is not null {
        ++revision.references;
    }
    return revision;
}

fn frontend_revision_nodes(target: vector(void*)*, nodes: void**, count: usize): bool {
    var needed = target.length + count;
    if needed < target.length {
        return false;
    }
    if !vector_reserve(void*, target, needed) {
        return false;
    }
    var i: usize = 0;
    loop {
        if i == count {
            return true;
        }
        entity_retain(nodes[i]);
        target.data[target.length] = nodes[i];
        target.length++;
        i++;
    }
}

fn frontend_revision_create(rules: SyntaxRuleView*, count: usize, tokens: void**, token_count: usize): FrontendRevision* {
    var revision = alloc(FrontendRevision, 1);
    if revision == null {
        return null;
    }
    fill(revision, 0, sizeof(FrontendRevision));
    revision.references = 1;
    // One names buffer and one retained-alternative buffer for the revision.
    // Rule views borrow these stable allocations; nothing grows after linking.
    var names: usize = 0;
    var alternatives: usize = 0;
    var ok: bool = true;
    var i: usize = 0;
    for(; i != count; i++) {
        var next = names + rules[i].name_length;
        var overflow = next < names;
        if next == lr_none() {
            overflow = true;
        }
        if overflow {
            ok = false;
            break;
        }
        names = next + 1;
        next = alternatives + rules[i].count;
        overflow = next < alternatives;
        if overflow {
            ok = false;
            break;
        }
        alternatives = next;
    }
    ok &&= vector_reserve(SyntaxRuleView, &revision.rules, count);
    ok &&= vector_reserve(u8, &revision.names, names);
    ok &&= vector_reserve(void*, &revision.alternatives, alternatives);
    i = 0;
    loop {
        if !ok {
            break;
        }
        if i == count {
            break;
        }
        var target = &revision.rules.data[i];
        target.name = &revision.names.data[revision.names.length];
        target.name_length = rules[i].name_length;
        target.count = rules[i].count;
        target.alternatives = null;
        if target.count != 0 {
            target.alternatives = &revision.alternatives.data[revision.alternatives.length];
        }
        ok = bytes_append(&revision.names, rules[i].name, rules[i].name_length);
        ok &&= vector_push(u8, &revision.names, 0);
        ok &&= frontend_revision_nodes(&revision.alternatives, rules[i].alternatives, rules[i].count);
        revision.rules.length++;
        i++;
    }
    ok &&= frontend_revision_nodes(&revision.tokens, tokens, token_count);
    if ok {
        return revision;
    }
    frontend_revision_release(revision);
    return null;
}

fn frontend_revision_same(revision: FrontendRevision*, rules: SyntaxRuleView*, count: usize,
tokens: void**, token_count: usize, kind: void*): bool {
    var different = revision.rules.length != count;
    if different {
        return false;
    }
    different = revision.tokens.length != token_count;
    if different {
        return false;
    }
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var previous = &revision.rules.data[i];
        var next = &rules[i];
        var order = syntax_bytes_compare(previous.name, previous.name_length, next.name, next.name_length);
        different = order != 0;
        if different {
            return false;
        }
        different = previous.count != next.count;
        if different {
            return false;
        }
        var j: usize = 0;
        loop {
            done = j == next.count;
            if done {
                break;
            }
            var same = syntax_nodes_equal(previous.alternatives[j], next.alternatives[j], kind, true);
            different = same != 1;
            if different {
                return false;
            }
            j++;
        }
        i++;
    }
    i = 0;
    loop {
        var done = i == token_count;
        if done {
            return true;
        }
        var same = syntax_nodes_equal(revision.tokens.data[i], tokens[i], kind, true);
        different = same != 1;
        if different {
            return false;
        }
        i++;
    }
}

export fn frontend_cache_dispose(cache: FrontendCache*): void {
    for(var i: usize = 0; i != cache.entries.length; i++) {
        frontend_revision_release(cache.entries.data[i]);
    }
    vector_dispose(FrontendRevision*, &cache.entries);
    cache.builds = 0;
    cache.hits = 0;
}

// Destination must be empty. Formatting forks share immutable snapshots but
// keep independent recency, counters and compiled-table handle ownership.
export fn frontend_cache_copy(target: FrontendCache*, source: FrontendCache*): bool {
    var count = source.entries.length;
    if !vector_reserve(FrontendRevision*, &target.entries, count) {
        return false;
    }
    for(var i: usize = 0; i != count; i++) {
        var revision = source.entries.data[i];
        revision.references++;
        target.entries.data[i] = revision;
    }
    target.entries.length = count;
    target.builds = source.builds;
    target.hits = source.hits;
    return true;
}

fn frontend_cache_touch(cache: FrontendCache*, index: usize): void {
    var entry = cache.entries.data[index];
    var last = cache.entries.length -1;
    loop {
        if index == last {
            break;
        }
        var next = index + 1;
        cache.entries.data[index] = cache.entries.data[next];
        index = next;
    }
    cache.entries.data[last] = entry;
}

export fn frontend_cache_find(cache: FrontendCache*, rules: SyntaxRuleView*, count: usize,
tokens: void**, token_count: usize, kind: void*): usize {
    var i: usize = 0;
    loop {
        if i == cache.entries.length {
            cache.builds++;
            return lr_none();
        }
        var revision = cache.entries.data[i];
        if frontend_revision_same(revision, rules, count, tokens, token_count, kind) {
            frontend_cache_touch(cache, i);
            cache.hits++;
            return revision.slot;
        }
        i++;
    }
}

// Store only after successful table construction. Allocation failure leaves
// every previous entry and slot unchanged; caching is optional for correctness.
export fn frontend_cache_store(cache: FrontendCache*, rules: SyntaxRuleView*, count: usize,
tokens: void**, token_count: usize): usize {
    var revision = frontend_revision_create(rules, count, tokens, token_count);
    if revision == null {
        return lr_none();
    }
    if cache.entries.length == FrontendCacheLimit() {
        revision.slot = cache.entries.data[0].slot;
        frontend_revision_release(cache.entries.data[0]);
        cache.entries.data[0] = revision;
        frontend_cache_touch(cache, 0);
    } else {
        revision.slot = cache.entries.length;
        if !vector_push(FrontendRevision*, &cache.entries, revision) {
            frontend_revision_release(revision);
            return lr_none();
        }
    }
    return revision.slot;
}

export fn frontend_cache_pattern(cache: FrontendCache*, entity: void*, kind: void*): void {
    var component = entity_component_get(entity, kind);
    var node = bits(SyntaxNode*, entity_component_data(component));
    var i = cache.entries.length;
    loop {
        var done = i == 0;
        if done {
            return;
        }
        i--;
        var revision = cache.entries.data[i];
        var j: usize = 0;
        loop {
            done = j == revision.tokens.length;
            if done {
                break;
            }
            component = entity_component_get(revision.tokens.data[j], kind);
            var previous = bits(SyntaxNode*, entity_component_data(component));
            if syntax_text_equal(&node.text, &previous.text) {
                syntax_node_pattern(node, previous.compiled);
                return;
            }
            j++;
        }
    }
}

import tower;
import semantic_program_types;
import semantic_context;
import semantic_lifecycle;
import semantic_modules;
import .library.vector;

// Source/module orchestration over the same semantic program and parse entities.
// Composed with the semantic declarations; no copied Foundation operation model.
extern fn frontend_module_session(module: void*): void*;

extern fn syntax_next(session: void*): void*;

extern fn syntax_get_error(session: void*): u8*;

extern fn syntax_get_revision(session: void*): usize;

extern fn syntax_get_error_offset(session: void*): usize;

extern fn bytes_append(target: vector(u8)*, data: u8*, count: usize): bool;

fn frontend_source_length(source: u8*): usize {
    var length: usize = 0;
    loop {
        if source[length] == 0 {
            return length;
        }
        length++;
    }
}

fn frontend_compile_error(program: SemanticProgram*, message: u8*): void {
    var length = frontend_source_length(message);
    sem_require(bytes_append(&program.error, message, length));
}

extern fn frontend_module_root(source: u8*, environment: void*): void*;

extern fn frontend_module_finish(module: void*): void;

extern fn frontend_module_count(module: void*): usize;

extern fn frontend_module_at(module: void*, index: usize): void*;

extern fn frontend_module_source(module: void*): u8*;

extern fn frontend_module_comments(module: void*, count: usize*): usize*;

extern fn frontend_module_size(module: void*): usize;

extern fn frontend_module_roots(module: void*): usize;

extern fn frontend_module_tree(module: void*, index: usize): void*;

extern fn frontend_module_destroy(module: void*): void;

extern fn frontend_module_position(module: void*, base: usize): void;

extern fn frontend_module_diagnostic(module: void*, offset: usize): void;

extern fn frontend_module_error(module: void*): u8*;

extern fn syntax_capture_comments(session: void*, module: void*): void;

extern fn frontend_module_attach_comments(module: void*, root: void*, base: usize): void;

export fn frontend_compile_sources(program: SemanticProgram*, sources: FrontendSource*, count: usize, environment: void*): void {
    var source: vector(u8);
    var roots: vector(void*);
    var bases: vector(usize);
    var modules: vector(void*);
    vector_init(u8, &source);
    vector_init(void*, &roots);
    vector_init(usize, &bases);
    vector_init(void*, &modules);
    var index: usize = 0;
    loop {
        var done = index == count;
        if done {
            break;
        }
        var module = frontend_module_root(sources[index].data, environment);
        sem_require(vector_push(void*, &modules, module));
        var session = frontend_module_session(module);
        loop {
            var root = syntax_next(session);
            if root == null {
                break;
            }
            entity_release(root);
        }
        var error = syntax_get_error(session);
        var failed = error[0] != 0;
        if failed {
            frontend_compile_error(program, error);
            program.error_offset = syntax_get_error_offset(session);
            frontend_module_diagnostic(module, program.error_offset);
        }
        if failed {
            break;
        }
        syntax_capture_comments(session, module);
        frontend_module_finish(module);
        error = frontend_module_error(module);
        failed = error[0] != 0;
        if failed {
            frontend_compile_error(program, error);
            break;
        }
        sem_module_graph(program, module);
        var dependency: usize = 0;
        var dependencies = frontend_module_count(module);
        loop {
            done = dependency == dependencies;
            if done {
                break;
            }
            var current = frontend_module_at(module, dependency);
            var base = source.length;
            frontend_module_position(current, base);
            sem_module_position(program, current, base);
            var data = frontend_module_source(current);
            var length = frontend_module_size(current);
            sem_require(bytes_append(&source, data, length));
            sem_require(vector_push(u8, &source, 10));
            var n: usize = 0;
            var trees = frontend_module_roots(current);
            loop {
                done = n == trees;
                if done {
                    break;
                }
                var root = frontend_module_tree(current, n);
                var node = sem_child(root, 0);
                var statement = sem_is(node, "Statement");
                if statement {
                    statement = sem_child_count(node) == 1;
                    if statement {
                        node = sem_child(node, 0);
                    }
                }
                sem_require(entity_attach(root, program.root, ""));
                var target = sem_get(program.root);
                sem_require(vector_push(void*, &target.items, node));
                sem_require(vector_push(void*, &roots, root));
                sem_require(vector_push(usize, &bases, base));
                n++;
            }
            dependency++;
        }
        index++;
    }
    sem_require(vector_push(u8, &source, 0));
    if program.error.length == 0 {
        semantic_compile(program, roots.data, bases.data, roots.length, source.data);
    }
    if program.error.length == 0 {
        var base: usize = 0;
        var m: usize = 0;
        loop {
            if m == modules.length {
                break;
            }
            var module = modules.data[m];
            var count = frontend_module_count(module);
            var d: usize = 0;
            loop {
                if d == count {
                    break;
                }
                var current = frontend_module_at(module, d);
                var ordinary = frontend_module_roots(current) != 0;
                // Grammar-only files keep trivia on their grammar/source nodes.
                // Do not substitute that source for executable Foundation output.
                if ordinary {
                    frontend_module_attach_comments(current, program.root, base);
                }
                base = base + frontend_module_size(current);
                base++;
                d++;
            }
            m++;
        }
    }
    index = 0;
    for(; index != modules.length; index++) {
        frontend_module_destroy(modules.data[index]);
    }
    vector_dispose(void*, &modules);
    vector_dispose(u8, &source);
    vector_dispose(void*, &roots);
    vector_dispose(usize, &bases);
}

