export fn core_component_type(): Entity* {
    return compiler_host_type(CompilerFoundation());
}

export fn syntax_component_type(): Entity* {
    return compiler_host_type(CompilerSyntax());
}

export fn syntax_get(owner: Entity*): SyntaxNode* {
    if owner == null {
        return null;
    }
    var component = entity_component_get(owner, syntax_component_type());
    return bits(SyntaxNode*, entity_component_data(component));
}

export fn syntax_component_attach(owner: Entity*, kind: u32): SyntaxNode* {
    var value = bits(SyntaxNode*, compiler_host_component(owner, CompilerSyntax()));
    value.kind = kind;
    return value;
}

extern fn syntax_nodes_equal(left: Entity*, right: Entity*, type: Entity*, locations: bool): i32;

export fn syntax_equal(left: Entity*, right: Entity*, locations: bool): bool {
    var result = syntax_nodes_equal(left, right, syntax_component_type(), locations);
    var valid = result >= 0;
    compiler_entity_require(valid);
    var equal = result != 0;
    return equal;
}

export fn syntax_kind_name(kind: u32): u8* {
    var tag = convert(SyntaxKind, kind);
    match tag {
        SyntaxKind.Document => {
            return "document";
        }
        SyntaxKind.Rule => {
            return "parse";
        }
        SyntaxKind.Token => {
            return "token";
        }
        SyntaxKind.Skip => {
            return "skip";
        }
        SyntaxKind.Alternative => {
            return "alternative";
        }
        SyntaxKind.Term => {
            return "term";
        }
        SyntaxKind.Template => {
            return "template";
        }
        SyntaxKind.Import => {
            return "import";
        }
        _ => {
            compiler_entity_require(false);
            return "";
        }
    }
}

