extern fn syntax_source_location(source: SyntaxSource*, offset: usize, line: usize*, column: usize*): void;

struct LanguageCandidate {
    node: void*;
    subject: void*;
    from: usize;
    to: usize;
    grammar: bool;
    generic: GenericInfo*;
    template: LanguageGrammar*;
    matched: LanguageGrammar*;
    capture: void*;
    capture_node: void*;
    description: u8*;
    structural: bool;
}

fn language_quote(q: CompletionQuery*, text: u8*, size: usize): void {
    if size > HoverPreviewByteLimit() {
        size = HoverPreviewByteLimit();
        loop {
            var byte = text[size] &192;
            if byte != 128 {
                break;
            }
            size--;
        }
    }
    sem_require(host_json_quote(&q.output, text, size));
}

fn language_string(q: CompletionQuery*, key: u8*, text: u8*): void {
    completion_text(&q.output, ",\"");
    completion_text(&q.output, key);
    completion_text(&q.output, "\":");
    language_quote(q, text, sem_length(text));
}

fn language_number(q: CompletionQuery*, key: u8*, value: usize): void {
    completion_text(&q.output, ",\"");
    completion_text(&q.output, key);
    completion_text(&q.output, "\":");
    sem_require(host_json_unsigned(&q.output, convert(u64, value)));
}

fn language_documentation(q: CompletionQuery*, value: FoundationNode*): void {
    // Consume the same attached metadata as Foundation/C formatting. Its
    // normalized block delimiters are presentation trivia, not documentation.
    var text: vector(u8);
    vector_init(u8, &text);
    var i: usize = 0;
    loop {
        var done = i >= value.comments.length;
        if done {
            break;
        }
        i = i + 2;
        var first = i;
        loop {
            var next = i + 1;
            done = next >= value.comments.length;
            if done {
                break;
            }
            var end = value.comments.data[i] == 42;
            end &&= value.comments.data[next] == 47;
            if end {
                break;
            }
            i = next;
        }
        var last = i;
        loop {
            var spaces = first < last;
            spaces &&= value.comments.data[first] == 32;
            if spaces {
                first++;
            } else {
                break;
            }
        }
        loop {
            var spaces = first < last;
            if spaces {
                var before = last -1;
                spaces = value.comments.data[before] == 32;
            }
            if spaces {
                last--;
            } else {
                break;
            }
        }
        if last > first {
            if text.length != 0 {
                sem_require(vector_push(u8, &text, 10));
            }
            var count = last -first;
            sem_require(bytes_append(&text, &value.comments.data[first], count));
        }
        i = i + 3;
    }
    if text.length != 0 {
        completion_text(&q.output, ",\"documentation\":");
        sem_require(host_json_quote(&q.output, text.data, text.length));
    }
    vector_dispose(u8, &text);
}

fn language_declaration_location(q: CompletionQuery*, subject: void*): void {
    var span = sem_match(subject);
    if span == null {
        return;
    }
    var base = sem_source_base(&q.context, subject);
    var i: usize = 0;
    loop {
        if i == q.comment_modules.length {
            return;
        }
        if base == q.comment_bases.data[i] {
            var module = q.comment_modules.data[i];
            var line: usize = 1;
            var column: usize = 1;
            var file = frontend_module_location(module, span.start, &line, &column);
            language_string(q, "declarationFile", file);
            language_number(q, "declarationLine", line);
            language_number(q, "declarationColumn", column);
            return;
        }
        i++;
    }
}

// The same walk handles every source leaf. The nearest entity with supported
// components owns its entire source span; no keyword or punctuation allow-list.
fn language_candidate(q: CompletionQuery*, node: void*, candidate: LanguageCandidate*, checked: bool): void {
    var span = sem_match(node);
    if span == null {
        return;
    }
    if span.length == 0 {
        return;
    }
    if span.start >= q.length {
        return;
    }
    var priority = LanguagePresentation.None;
    var i: usize = 0;
    var count = entity_component_count(node);
    for(; i != count; i++) {
        var component = entity_component_at(node, i);
        var presented: LanguageCandidate;
        copy(&presented, candidate, sizeof(LanguageCandidate));
        presented.from = span.start;
        presented.to = span.start + span.length;
        var rank = language_component_present(q, node, component, checked, &presented);
        if convert(u32, rank) > convert(u32, priority) {
            priority = rank;
            copy(candidate, &presented, sizeof(LanguageCandidate));
        }
    }
}

fn language_leaf(q: CompletionQuery*, leaf: void*, candidate: LanguageCandidate*): void {
    var span = sem_match(leaf);
    if span == null {
        return;
    }
    if span.length == 0 {
        return;
    }
    var end = span.start + span.length;
    if end > q.length {
        return;
    }
    var selected = candidate.subject != null;
    selected &&= span.start >= candidate.from;
    selected &&= end <= candidate.to;
    var subject = leaf;
    var node = leaf;
    var formatted: FormatResult;
    fill(&formatted, 0, sizeof(FormatResult));
    var value: FoundationNode* = null;
    if selected {
        subject = candidate.subject;
        node = candidate.node;
        value = sem_get(subject);
        if candidate.generic != null {
            value = null;
            language_generic_format(q, candidate.generic, &formatted, true);
        } else {
            if candidate.structural {
                value = null;
            } else {
                if candidate.grammar {
                    format_grammar_preview(&formatted, subject, syntax_component_type());
                } else {
                    if sem_is(subject, "TowerExpression") || sem_is(subject, "TowerComma") || sem_is(subject, "TowerNullAccess") {
                        format_dependent_summary(&formatted, subject, parser_match_get_type());
                    } else {
                        format_summary(&formatted, subject, syntax_component_type(), core_component_type(), parser_match_get_type());
                    }
                }
            }
        }
    }
    if q.count != 0 {
        completion_text(&q.output, ",");
    }
    completion_text(&q.output, "{\"from\":");
    sem_require(host_json_unsigned(&q.output, convert(u64, span.start)));
    language_number(q, "to", end);
    completion_text(&q.output, ",\"signature\":");
    var preview = formatted.text.length != 0;
    if formatted.failed {
        preview = false;
    }
    if preview {
        language_quote(q, formatted.text.data, formatted.text.length);
    } else {
        language_quote(q, &q.source[span.start], span.length);
    }
    format_dispose(&formatted);
    var kind = language_kind(value);
    if candidate.description != null {
        language_string(q, "description", candidate.description);
    }
    if selected {
        if candidate.grammar {
            kind = "grammar";
        }
        if candidate.generic != null {
            kind = language_generic_kind(candidate.generic);
        }
    }
    var grammar_details = selected;
    grammar_details &&= candidate.grammar;
    if grammar_details {
        language_grammar_details(q, leaf, node);
    } else {
        var template_details = candidate.template != null;
        var matched = candidate.matched != null;
        if selected {
            matched = false;
        }
        if matched {
            template_details = true;
        }
        if !template_details {
            language_string(q, "kind", kind);
        }
    }
    var matched_details = candidate.matched != null;
    if selected {
        matched_details = false;
    }
    if matched_details {
        language_match_details(q, candidate);
    }
    if candidate.template != null {
        language_template_details(q, leaf, candidate);
    }
    var syntax = sem_label(node);
    if node == leaf {
        var parent = sem_parent(leaf);
        if parent != null {
            syntax = sem_label(parent);
        }
    }
    language_string(q, "syntax", syntax);
    language_number(q, "entity", entity_id(node));
    language_number(q, "components", entity_component_count(node));
    var parent = sem_parent(node);
    if parent != null {
        language_number(q, "parent", entity_id(parent));
    }
    var hover_condition36 = value != null;
    if selected {
        if candidate.generic != null {
            language_generic_details(q, candidate.generic);
        }
    }
    if hover_condition36 {
        language_documentation(q, value);
        language_string(q, "type", sem_type_name(&q.context, &value.type));
        language_number(q, "binding", entity_id(subject));
        language_number(q, "size", semantic_size(&value.type));
        language_number(q, "alignment", semantic_alignment(&value.type));
        if value.kind == KFieldDeclaration() {
            language_number(q, "offset", value.byte_offset);
        }
        if sem_source_base(&q.context, subject) == 0 {
            var declaration = sem_match(subject);
            if declaration != null {
                language_number(q, "declaration", declaration.start);
            }
        }
        language_declaration_location(q, subject);
    }
    completion_text(&q.output, "}");
    q.count++;
}

fn language_walk(q: CompletionQuery*, node: void*, inherited: LanguageCandidate*, checked: bool, depth: usize, budget: usize*): void {
    if depth == InspectionDepthLimit() {
        q.truncated = true;
        return;
    }
    if *budget == 0 {
        q.truncated = true;
        return;
    }
    *budget = *budget - 1;
    var current: LanguageCandidate;
    copy(&current, inherited, sizeof(LanguageCandidate));
    language_candidate(q, node, &current, checked);
    // Keep syntax available for nodes that have no concrete specialization yet.
    // A selected semantic subject takes precedence when rendering the leaf.
    language_match_candidate(q, node, &current);
    var count = sem_child_count(node);
    var syntax = language_syntax(node);
    if syntax != null {
        if syntax.kind == SyntaxTemplate() {
            var template = language_grammar_find(q, node);
            if template != null && template.targets.length != 0 {
                language_leaf(q, sem_child(node, 0), &current);
                language_template_walk(q, template.targets.data[0], template, null, checked, depth, budget);
                var last = count -1;
                language_leaf(q, sem_child(node, last), &current);
                return;
            }
        }
    }
    if count == 0 {
        language_leaf(q, node, &current);
        return;
    }
    var i: usize = 0;
    for(; i != count; i++) {
        var child_depth = depth + 1;
        language_walk(q, sem_child(node, i), &current, checked, child_depth, budget);
    }
}

// Direct native/Wasm entry point. The handle owns its output and all temporary
// shared entities until completion_dispose; no server protocol or guest JIT.
export fn language_document(source: u8*, length: usize, mode: u32, pointer_bytes: u32): CompletionQuery* {
    var source_error = host_source_error(source, length);
    if source_error[0] != 0 {
        return null;
    }
    var valid_width = pointer_bytes == 4;
    if pointer_bytes == 8 {
        valid_width = true;
    }
    if !valid_width {
        return null;
    }
    if length > InspectionSourceByteLimit() {
        return null;
    }
    if mode > 2 {
        return null;
    }
    var q = completion_begin(source, length, 0, null, 0);
    if q == null {
        return null;
    }
    q.inspection = true;
    q.recovered.length = 0;
    sem_require(bytes_append(&q.recovered, source, length));
    sem_require(host_text_terminate(&q.recovered));
    q.source = q.recovered.data;
    var root = tower_node_create();
    semantic_initialize(&q.program, root, pointer_bytes);
    q.semantic = true;
    var complete = completion_parse(q, q.source, mode, false);
    sem_require(host_text_terminate(&q.input));
    var c = &q.context;
    sem_context_init(c, &q.program);
    sem_type_uses_begin(c);
    q.analyzed = true;
    language_grammar_index(q);
    c.source = q.input.data;
    c.generics = generic_begin(root);
    var i: usize = 0;
    for(; i != q.roots.length; i++) {
        var entry = sem_state(c, c.source_bases, q.roots.data[i]);
        entry.number = q.bases.data[i];
    }
    var checked = mode == 0;
    if checked {
        sem_run(c);
        checked = sem_ok(c);
        // A document diagnostic does not invalidate the declared parameters and
        // symbolic annotations of its registered templates. Inspect those even
        // when executable checking failed; keep Foundation presentation gated
        // by the original result so partially checked values are never exposed.
        q.program.error.length = 0;
        q.generic_info = sem_generic_inspect(c, checked, &q.truncated);
    }
    if checked {
        i = 0;
        for(; i != q.comment_modules.length; i++) {
            var module = q.comment_modules.data[i];
            if frontend_module_roots(module) != 0 {
                frontend_module_attach_comments(module, q.program.root, q.comment_bases.data[i]);
            }
        }
    }
    q.program.error.length = 0;
    q.output.length = 0;
    q.count = 0;
    completion_text(&q.output, "{\"entries\":[");
    var empty: LanguageCandidate;
    fill(&empty, 0, sizeof(LanguageCandidate));
    var budget = InspectionNodeLimit();
    i = 0;
    for(; i != q.roots.length; i++) {
        if q.bases.data[i] == 0 {
            language_walk(q, q.roots.data[i], &empty, checked, 0, &budget);
        }
    }
    completion_text(&q.output, "],\"complete\":");
    if q.truncated {
        complete = false;
    }
    if complete {
        completion_text(&q.output, "true");
    }
    else {
        completion_text(&q.output, "false");
    }
    completion_text(&q.output, "}");
    sem_require(host_text_terminate(&q.output));
    return q;
}

export fn language_document_result(q: CompletionQuery*): u8* {
    return q.output.data;
}

import tower;
import syntax_types;
import parser_nodes;
import .library.vector;

// Derived lexer tables only: token declarations remain on shared syntax entities.
// Flat transition rows and maximal-prefix matching are owned and executed by Tower.
// A finite-state chain over arbitrary integer symbols. State n accepts; each
// earlier state has one range transition to its successor. No parse stack.
struct SymbolRange {
    first: u32;
    last: u32;
}

struct SymbolSequence {
    symbols: SymbolRange*;
    count: usize;
}

export fn symbol_sequence_create(count: usize): SymbolSequence* {
    var sequence = alloc(SymbolSequence, 1);
    var failed = sequence == null;
    if failed {
        return null;
    }
    sequence.symbols = alloc(SymbolRange, count);
    failed = sequence.symbols == null;
    if failed {
        free(sequence);
        return null;
    }
    sequence.count = count;
    return sequence;
}

export fn symbol_sequence_destroy(sequence: SymbolSequence*): void {
    if sequence == null {
        return;
    }
    free(sequence.symbols);
    free(sequence);
}

export fn symbol_sequence_set(sequence: SymbolSequence*, state: usize, first: u32, last: u32): void {
    sequence.symbols[state].first = first;
    sequence.symbols[state].last = last;
}

export fn symbol_sequence_accepts(sequence: SymbolSequence*, state: usize, symbol: u32): bool {
    if state >= sequence.count {
        return false;
    }
    if symbol < sequence.symbols[state].first {
        return false;
    }
    var accepted = symbol <= sequence.symbols[state].last;
    return accepted;
}

export fn lex_table_create(): LexerTable* {
    var table = alloc(LexerTable, 1);
    if table != null {
        fill(table, 0, sizeof(LexerTable));
    }
    return table;
}

export fn lex_table_destroy(table: LexerTable*): void {
    if table == null {
        return;
    }
    vector_dispose(u32, &table.alphabet);
    vector_dispose(i32, &table.transitions);
    vector_dispose(u8, &table.accepting);
    free(table);
}

export fn lex_table_set_alphabet(table: LexerTable*, values: u32*, count: usize): bool {
    if count < 2 {
        return false;
    }
    if table.accepting.length != 0 {
        return false;
    }
    var ok = vector_reserve(u32, &table.alphabet, count);
    if ok {
        var bytes = count *sizeof(u32);
        copy(table.alphabet.data, values, bytes);
        table.alphabet.length = count;
    }
    return ok;
}

export fn lex_table_append(table: LexerTable*, transitions: i32*, count: usize, accepting: bool): bool {
    if table.alphabet.length < 2 {
        return false;
    }
    var columns = table.alphabet.length -1;
    if count != columns {
        return false;
    }
    var end = table.transitions.length + count;
    var wrapped = end < table.transitions.length;
    if wrapped {
        return false;
    }
    var rows = table.accepting.length + 1;
    wrapped = rows == 0;
    if wrapped {
        return false;
    }
    var ok = vector_reserve(i32, &table.transitions, end);
    if !ok {
        return false;
    }
    ok = vector_reserve(u8, &table.accepting, rows);
    if ok {
        var destination = table.transitions.data + table.transitions.length;
        var bytes = count *sizeof(i32);
        copy(destination, transitions, bytes);
        table.transitions.length = end;
        table.accepting.data[table.accepting.length] = convert(u8, accepting);
        table.accepting.length = rows;
    }
    return ok;
}

// The transition engine knows integer IDs, not UTF-8. Character decoding is one
// stream adapter; token grammar automata use these same rows directly.
export fn lex_table_step(table: LexerTable*, state: usize, symbol: u32): i32 {
    var invalid = state >= table.accepting.length;
    if invalid {
        return -1;
    }
    var columns = table.alphabet.length -1;
    invalid = symbol >= table.alphabet.data[columns];
    if invalid {
        return -1;
    }
    invalid = symbol < table.alphabet.data[0];
    if invalid {
        return -1;
    }
    var first: usize = 0;
    var count = table.alphabet.length;
    loop {
        if count == 0 {
            break;
        }
        var half = count / 2;
        var middle = first + half;
        if symbol < table.alphabet.data[middle] {
            count = half;
        }
        else {
            first = middle + 1;
            count = count - half;
            count--;
        }
    }
    var column = first -1;
    var index = state *columns;
    index = index + column;
    return table.transitions.data[index];
}

export fn lex_table_accepts(table: LexerTable*, state: usize): bool {
    if state >= table.accepting.length {
        return false;
    }
    var accepted = table.accepting.data[state] != 0;
    return accepted;
}

export fn lex_table_match(table: LexerTable*, source: u8*, length: usize, start: usize): usize {
    var position = start;
    var longest: usize = 0;
    var state: usize = 0;
    loop {
        var done = position >= length;
        if done {
            return longest;
        }
        var scalar: u32;
        var begin = source + position;
        var remaining = length -position;
        var bytes = tower_utf8_decode(begin, remaining, &scalar);
        if bytes == 0 {
            return longest;
        }
        var next = lex_table_step(table, state, scalar);
        done = next < 0;
        if done {
            return longest;
        }
        state = convert(usize, next);
        position = position + bytes;
        if table.accepting.data[state] != 0 {
            longest = position - start;
        }
    }
}

import tower;
import lr_types;
import lexer_table;
import .library.vector;

// Disposable FIRST/nullable and LR item indexes over the shared grammar entities.
// Character and token streams use the same integer ranges and closure algorithm.
struct LRNonterminal {
    nullable: bool;
    order: usize;
    first: vector(SymbolRange);
    productions: vector(usize);
}

struct LRAnalysis {
    rules: LRProduction*;
    rule_count: usize;
    symbols: LRSymbol*;
    symbol_count: usize;
    nonterminals: LRNonterminal*;
    nonterminal_count: usize;
    failed: bool;
}

struct LRItems {
    values: vector(LRItem);
    pending: vector(LRItem);
    failed: bool;
}

fn lr_none(): usize {
    var value: usize = 0;
    value--;
    return value;
}

fn lr_append(T: type, values: vector(T)*, value: T*): bool {
    var count = values.length + 1;
    if count == 0 {
        return false;
    }
    var ok = vector_reserve(T, values, count);
    if ok {
        copy(&values.data[values.length], value, sizeof(T));
        values.length = count;
    }
    return ok;
}

// Preserve distinct range identities here: overlapping ranges can represent
// different parse actions. Union/partition belongs to action construction.
fn lr_range_insert(values: vector(SymbolRange)*, first: u32, last: u32, changed: bool*): bool {
    var low: usize = 0;
    var high = values.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        var value = &values.data[middle];
        var less = value.first < first;
        if value.first == first {
            less = value.last < last;
        }
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if low < values.length {
        var value = &values.data[low];
        var same = value.first == first;
        var end_same = value.last == last;
        same &&= end_same;
        if same {
            return true;
        }
    }
    var count = values.length + 1;
    if !vector_reserve(SymbolRange, values, count) {
        return false;
    }
    var moved = values.length -low;
    var bytes = moved *sizeof(SymbolRange);
    var next = low + 1;
    copy(&values.data[next], &values.data[low], bytes);
    values.data[low].first = first;
    values.data[low].last = last;
    values.length = count;
    *changed = true;
    return true;
}

fn lr_range_merge(destination: vector(SymbolRange)*, source: vector(SymbolRange)*, changed: bool*): bool {
    if destination == source {
        return true;
    }
    var index: usize = 0;
    loop {
        if index == source.length {
            return true;
        }
        var range = &source.data[index];
        if !lr_range_insert(destination, range.first, range.last, changed) {
            return false;
        }
        index++;
    }
}

export fn lr_analysis_destroy(value: LRAnalysis*): void {
    if value == null {
        return;
    }
    var index: usize = 0;
    for(; index != value.nonterminal_count; index++) {
        var item = &value.nonterminals[index];
        vector_dispose(SymbolRange, &item.first);
        vector_dispose(usize, &item.productions);
    }
    free(value.nonterminals);
    free(value);
}

// Production/symbol arrays are borrowed and immutable for this analysis lifetime.
export fn lr_analysis_create(rules: LRProduction*, rule_count: usize, symbols: LRSymbol*, symbol_count: usize, nonterminal_count: usize): LRAnalysis* {
    var result = alloc(LRAnalysis, 1);
    var failed = result == null;
    if failed {
        return null;
    }
    fill(result, 0, sizeof(LRAnalysis));
    result.rules = rules;
    result.rule_count = rule_count;
    result.symbols = symbols;
    result.symbol_count = symbol_count;
    result.nonterminals = alloc(LRNonterminal, nonterminal_count);
    failed = result.nonterminals == null;
    if failed {
        free(result);
        return null;
    }
    result.nonterminal_count = nonterminal_count;
    var bytes = sizeof(LRNonterminal) *nonterminal_count;
    fill(result.nonterminals, 0, bytes);
    var index: usize = 0;
    for(; index != nonterminal_count; index++) {
        result.nonterminals[index].order = index;
    }
    index = 0;
    loop {
        if index == rule_count {
            return result;
        }
        var rule = &rules[index];
        var invalid = rule.owner >= nonterminal_count;
        if rule.begin > symbol_count {
            invalid = true;
        }
        if invalid {
            lr_analysis_destroy(result);
            return null;
        }
        var available = symbol_count -rule.begin;
        invalid = rule.count > available;
        if invalid {
            lr_analysis_destroy(result);
            return null;
        }
        if !vector_push(usize, &result.nonterminals[rule.owner].productions, index) {
            lr_analysis_destroy(result);
            return null;
        }
        index++;
    }
}

export fn lr_analysis_compute(value: LRAnalysis*): bool {
    loop {
        var changed: bool = false;
        var index: usize = 0;
        loop {
            var done = index == value.rule_count;
            if done {
                break;
            }
            var rule = &value.rules[index];
            var owner = &value.nonterminals[rule.owner];
            var nullable: bool = true;
            var position: usize = 0;
            loop {
                done = position == rule.count;
                if done {
                    break;
                }
                var symbol_index = rule.begin + position;
                var symbol = &value.symbols[symbol_index];
                var terminal = symbol.nonterminal == lr_none();
                var ok: bool = true;
                if terminal {
                    ok = lr_range_insert(&owner.first, symbol.first, symbol.last, &changed);
                    nullable = false;
                } else {
                    if symbol.nonterminal >= value.nonterminal_count {
                        value.failed = true;
                        return false;
                    }
                    var referenced = &value.nonterminals[symbol.nonterminal];
                    ok = lr_range_merge(&owner.first, &referenced.first, &changed);
                    nullable = referenced.nullable;
                }
                if !ok {
                    value.failed = true;
                    return false;
                }
                if !nullable {
                    break;
                }
                position++;
            }
            if nullable {
                if !owner.nullable {
                    owner.nullable = true;
                    changed = true;
                }
            }
            index++;
        }
        if !changed {
            return true;
        }
    }
}

export fn lr_analysis_failed(value: LRAnalysis*): bool {
    return value.failed;
}

export fn lr_analysis_order(value: LRAnalysis*, index: usize, order: usize): void {
    value.nonterminals[index].order = order;
}

export fn lr_analysis_nullable(value: LRAnalysis*, index: usize): bool {
    return value.nonterminals[index].nullable;
}

export fn lr_analysis_first_count(value: LRAnalysis*, index: usize): usize {
    return value.nonterminals[index].first.length;
}

export fn lr_analysis_first_data(value: LRAnalysis*, index: usize): SymbolRange* {
    return value.nonterminals[index].first.data;
}

export fn lr_items_create(): LRItems* {
    var result = alloc(LRItems, 1);
    if result != null {
        fill(result, 0, sizeof(LRItems));
    }
    return result;
}

export fn lr_items_destroy(value: LRItems*): void {
    if value == null {
        return;
    }
    vector_dispose(LRItem, &value.values);
    vector_dispose(LRItem, &value.pending);
    free(value);
}

fn lr_item_less(a: LRItem*, b: LRItem*): bool {
    var different = a.rule != b.rule;
    if different {
        var less = a.rule < b.rule;
        return less;
    }
    different = a.position != b.position;
    if different {
        var less = a.position < b.position;
        return less;
    }
    different = a.first != b.first;
    if different {
        var less = a.first < b.first;
        return less;
    }
    var less = a.last < b.last;
    return less;
}

export fn lr_items_insert(value: LRItems*, item: LRItem*): bool {
    if value.failed {
        return false;
    }
    // The caller may supply an item from this vector, which growth invalidates.
    var saved: LRItem;
    copy(&saved, item, sizeof(LRItem));
    var low: usize = 0;
    var high = value.values.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if lr_item_less(&value.values.data[middle], &saved) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if low < value.values.length {
        if !lr_item_less(&saved, &value.values.data[low]) {
            return true;
        }
    }
    var count = value.values.length + 1;
    var ok = vector_reserve(LRItem, &value.values, count);
    ok &&= lr_append(LRItem, &value.pending, &saved);
    if !ok {
        value.failed = true;
        return false;
    }
    var moved = value.values.length -low;
    var bytes = moved *sizeof(LRItem);
    var next = low + 1;
    copy(&value.values.data[next], &value.values.data[low], bytes);
    copy(&value.values.data[low], &saved, sizeof(LRItem));
    value.values.length = count;
    return true;
}

export fn lr_items_count(value: LRItems*): usize {
    return value.values.length;
}

export fn lr_items_data(value: LRItems*): LRItem* {
    return value.values.data;
}

fn lr_suffix(value: LRAnalysis*, rule: LRProduction*, position: usize, item: LRItem*, ranges: vector(SymbolRange)*): bool {
    var changed: bool = false;
    loop {
        if position >= rule.count {
            return lr_range_insert(ranges, item.first, item.last, &changed);
        }
        var index = rule.begin + position;
        var symbol = &value.symbols[index];
        if symbol.nonterminal == lr_none() {
            return lr_range_insert(ranges, symbol.first, symbol.last, &changed);
        }
        var next = &value.nonterminals[symbol.nonterminal];
        if !lr_range_merge(ranges, &next.first, &changed) {
            return false;
        }
        if !next.nullable {
            return true;
        }
        position++;
    }
}

export fn lr_items_close(value: LRAnalysis*, items: LRItems*, lookahead: bool): bool {
    var ranges: vector(SymbolRange);
    vector_init(SymbolRange, &ranges);
    // Many items reach the same nonterminal with identical lookahead. Expand
    // each pair once, rather than inserting every production for every incoming
    // item. Exact range identities and the sorted closure remain unchanged.
    var expanded: LRItems;
    fill(&expanded, 0, sizeof(LRItems));
    var ok: bool = true;
    loop {
        var done = items.pending.length == 0;
        if items.failed {
            done = true;
        }
        if value.failed {
            done = true;
        }
        if done {
            break;
        }
        items.pending.length--;
        var item: LRItem;
        copy(&item, &items.pending.data[items.pending.length], sizeof(LRItem));
        var rule = &value.rules[item.rule];
        done = item.position >= rule.count;
        if done {
            continue;
        }
        var index = rule.begin + item.position;
        var symbol = &value.symbols[index];
        if symbol.nonterminal == lr_none() {
            continue;
        }
        ranges.length = 0;
        if lookahead {
            var position = item.position + 1;
            ok = lr_suffix(value, rule, position, &item, &ranges);
        } else {
            var changed: bool = false;
            ok = lr_range_insert(&ranges, 0, 0, &changed);
        }
        if !ok {
            value.failed = true;
            break;
        }
        var productions = &value.nonterminals[symbol.nonterminal].productions;
        var range: usize = 0;
        loop {
            done = range == ranges.length;
            if items.failed {
                done = true;
            }
            if done {
                break;
            }
            var key: LRItem;
            key.rule = symbol.nonterminal;
            key.position = 0;
            key.first = ranges.data[range].first;
            key.last = ranges.data[range].last;
            range++;
            var previous = expanded.values.length;
            ok = lr_items_insert(&expanded, &key);
            // This set is only a membership index, never a closure work queue.
            expanded.pending.length = 0;
            if !ok {
                value.failed = true;
                break;
            }
            if previous == expanded.values.length {
                continue;
            }
            var production: usize = 0;
            loop {
                done = production == productions.length;
                if done {
                    break;
                }
                var next: LRItem;
                next.rule = productions.data[production];
                next.position = 0;
                next.first = key.first;
                next.last = key.last;
                ok = lr_items_insert(items, &next);
                if !ok {
                    break;
                }
                production++;
            }
        }
    }
    vector_dispose(LRItem, &expanded.values);
    vector_dispose(LRItem, &expanded.pending);
    vector_dispose(SymbolRange, &ranges);
    if items.failed {
        value.failed = true;
    }
    ok = !value.failed;
    return ok;
}

export fn lr_items_shift(value: LRAnalysis*, input: LRItems*, symbol: LRSymbol*, output: LRItems*): bool {
    var index: usize = 0;
    for(; index != input.values.length; index++) {
        var item: LRItem;
        copy(&item, &input.values.data[index], sizeof(LRItem));
        var rule = &value.rules[item.rule];
        if item.position < rule.count {
            var at = rule.begin + item.position;
            var next = &value.symbols[at];
            var matches = next.nonterminal == symbol.nonterminal;
            if next.nonterminal == lr_none() {
                var contained = symbol.first >= next.first;
                if !contained {
                    matches = false;
                }
                contained = symbol.last <= next.last;
                if !contained {
                    matches = false;
                }
            }
            if matches {
                item.position++;
                if !lr_items_insert(output, &item) {
                    value.failed = true;
                    return false;
                }
            }
        }
    }
    return true;
}

export fn lr_items_goto(value: LRAnalysis*, input: LRItems*, symbol: LRSymbol*, output: LRItems*, lookahead: bool): bool {
    if !lr_items_shift(value, input, symbol, output) {
        return false;
    }
    return lr_items_close(value, output, lookahead);
}

// LALR lookahead dependencies refer to kernel items by temporary dense indices.
// Propagate only changed sets; cyclic grammars converge without recursive calls.
struct LRPropagationNode {
    ranges: vector(SymbolRange);
    edges: vector(usize);
    queued: bool;
}

struct LRPropagation {
    nodes: LRPropagationNode*;
    count: usize;
    pending: vector(usize);
}

export fn lr_propagation_destroy(value: LRPropagation*): void {
    if value == null {
        return;
    }
    var index: usize = 0;
    for(; index != value.count; index++) {
        var node = &value.nodes[index];
        vector_dispose(SymbolRange, &node.ranges);
        vector_dispose(usize, &node.edges);
    }
    free(value.nodes);
    vector_dispose(usize, &value.pending);
    free(value);
}

export fn lr_propagation_create(count: usize): LRPropagation* {
    var value = alloc(LRPropagation, 1);
    var missing = value == null;
    if missing {
        return null;
    }
    fill(value, 0, sizeof(LRPropagation));
    value.nodes = alloc(LRPropagationNode, count);
    missing = value.nodes == null;
    if missing {
        lr_propagation_destroy(value);
        return null;
    }
    value.count = count;
    var bytes = sizeof(LRPropagationNode) *count;
    fill(value.nodes, 0, bytes);
    if !vector_reserve(usize, &value.pending, count) {
        lr_propagation_destroy(value);
        return null;
    }
    return value;
}

fn lr_propagation_queue(value: LRPropagation*, index: usize): void {
    var node = &value.nodes[index];
    if node.queued {
        return;
    }
    // At most count distinct nodes can be queued. Capacity was reserved once.
    value.pending.data[value.pending.length] = index;
    value.pending.length++;
    node.queued = true;
}

export fn lr_propagation_seed(value: LRPropagation*, index: usize, first: u32, last: u32): bool {
    var changed: bool = false;
    var ok = lr_range_insert(&value.nodes[index].ranges, first, last, &changed);
    if changed {
        lr_propagation_queue(value, index);
    }
    return ok;
}

export fn lr_propagation_edge(value: LRPropagation*, source: usize, destination: usize): bool {
    // Duplicate dependencies do not change the fixed point or queued work.
    var ok = vector_push(usize, &value.nodes[source].edges, destination);
    if ok {
        lr_propagation_queue(value, source);
    }
    return ok;
}

export fn lr_propagation_solve(value: LRPropagation*): bool {
    loop {
        var done = value.pending.length == 0;
        if done {
            return true;
        }
        value.pending.length--;
        var index = value.pending.data[value.pending.length];
        var source = &value.nodes[index];
        source.queued = false;
        var edge: usize = 0;
        loop {
            done = edge == source.edges.length;
            if done {
                break;
            }
            var destination = source.edges.data[edge];
            var target = &value.nodes[destination];
            var changed: bool = false;
            if !lr_range_merge(&target.ranges, &source.ranges, &changed) {
                return false;
            }
            if changed {
                lr_propagation_queue(value, destination);
            }
            edge++;
        }
    }
}

export fn lr_propagation_count(value: LRPropagation*, index: usize): usize {
    return value.nodes[index].ranges.length;
}

export fn lr_propagation_data(value: LRPropagation*, index: usize): SymbolRange* {
    return value.nodes[index].ranges.data;
}

