import .library.vector;
import lr_types;

// LR and proven finite-sequence control over integer symbols. Frames borrow
// forest handles; the shared entity forest retains ownership of syntax nodes.
// A pull protocol keeps stream callbacks outside the deterministic control loop.
struct LRFrame {
    state: usize;
    first: usize;
    last: usize;
    start: usize;
    length: usize;
}

struct LRStep {
    rule: usize;
    next: usize;
    pop: usize;
    start: usize;
    end: usize;
    id: u32;
    kind: u32;
}

struct LRWork {
    actions: usize;
    shifts: usize;
    reductions: usize;
    popped: usize;
}

struct LRParser {
    runtime: LRRuntime*;
    stack: vector(LRFrame);
    work: LRWork;
    prefix: bool;
    shifted: bool;
    finishing: bool;
    consumed: usize;
    sequence: bool;
    evidence: vector(u8);
    sequence_first: usize;
    sequence_last: usize;
    sequence_start: usize;
    sequence_end: usize;
}

export fn lr_parser_destroy(value: LRParser*): void {
    if value == null {
        return;
    }
    vector_dispose(LRFrame, &value.stack);
    vector_dispose(u8, &value.evidence);
    free(value);
}

export fn lr_parser_create(runtime: LRRuntime*, prefix: bool, specialize: bool): LRParser* {
    var value = alloc(LRParser, 1);
    if value == null {
        return null;
    }
    fill(value, 0, sizeof(LRParser));
    value.runtime = runtime;
    value.prefix = prefix;
    if specialize {
        value.sequence = runtime.sequence != null;
    }
    value.sequence_first = lr_none();
    value.sequence_last = lr_none();
    var frame: LRFrame;
    fill(&frame, 0, sizeof(LRFrame));
    frame.first = lr_none();
    frame.last = lr_none();
    if lr_append(LRFrame, &value.stack, &frame) {
        return value;
    }
    lr_parser_destroy(value);
    return null;
}

// Statuses are the private host pull protocol, not Foundation instructions:
// input, shift, reduce, accept, unexpected, empty-prefix, DFA shift/reduce, invalid.
fn lr_parser_sequence_step(value: LRParser*, ready: bool, id: u32, error: bool, result: LRStep*): u32 {
    var runtime = value.runtime;
    var position = value.evidence.length;
    var rule = &runtime.rules.data[runtime.sequence_rule];
    var complete = position == rule.count;
    var needs_input = true;
    if complete {
        if value.prefix {
            needs_input = false;
        }
    }
    if needs_input {
        if !ready {
            return 0;
        }
    }
    value.work.actions++;
    result.rule = runtime.sequence_rule;
    if complete {
        if needs_input {
            if id != LRTokenEnd() {
                return 4;
            }
            if error {
                return 4;
            }
        }
        result.next = lr_runtime_goto(runtime, 0, rule.owner);
        result.start = value.sequence_start;
        result.end = value.sequence_end;
        return 7;
    }
    if error {
        return 4;
    }
    if !symbol_sequence_accepts(runtime.sequence, position, id) {
        return 4;
    }
    var next = position + 1;
    result.next = runtime.sequence_states.data[next];
    result.pop = position;
    return 6;
}

fn lr_parser_decide(value: LRParser*, ready: bool, id: u32, error: bool, result: LRStep*): u32 {
    if value.sequence {
        return lr_parser_sequence_step(value, ready, id, error, result);
    }
    var top = value.stack.length -1;
    var state = value.stack.data[top].state;
    var action: LRAction;
    action.rule = lr_none();
    action.state = lr_none();
    var use_default = false;
    if value.prefix {
        if !ready {
            action.rule = lr_runtime_default(value.runtime, state);
            use_default = action.rule != lr_none();
        }
    }
    var found = use_default;
    if use_default {
        value.work.actions++;
    } else {
        if !ready {
            if !value.finishing {
                return 0;
            }
        }
        if value.finishing {
            id = LRTokenEnd();
            error = false;
        }
        if !error {
            value.work.actions++;
            found = lr_runtime_action(value.runtime, state, id, &action);
        }
        if !found {
            if value.prefix {
                if value.shifted {
                    if !value.finishing {
                        value.work.actions++;
                        found = lr_runtime_action(value.runtime, state, LRTokenEnd(), &action);
                        if found {
                            value.finishing = true;
                            id = LRTokenEnd();
                        }
                    }
                }
            }
        }
    }
    if !found {
        return 4;
    }
    result.id = id;
    result.rule = action.rule;
    result.next = action.state;
    if action.state != lr_none() {
        return 1;
    }
    if action.rule == 0 {
        if value.prefix {
            if !value.shifted {
                return 5;
            }
        }
        return 3;
    }
    var rule = &value.runtime.rules.data[action.rule];
    var invalid = rule.count >= value.stack.length;
    if invalid {
        return 8;
    }
    result.pop = rule.count;
    if !ready {
        result.start = value.consumed;
    }
    if value.finishing {
        result.start = value.consumed;
    }
    result.end = result.start;
    var begin = value.stack.length -rule.count;
    if rule.count != 0 {
        result.start = value.stack.data[begin].start;
        result.end = result.start;
        var index = begin;
        for(; index != value.stack.length; index++) {
            var frame = &value.stack.data[index];
            var end = frame.start + frame.length;
            if end > result.end {
                result.end = end;
            }
        }
    }
    var previous = begin -1;
    result.next = lr_runtime_goto(value.runtime, value.stack.data[previous].state, rule.owner);
    invalid = result.next == lr_none();
    if invalid {
        return 8;
    }
    return 2;
}

export fn lr_parser_step(value: LRParser*, ready: bool, id: u32, error: bool, start: usize, length: usize, result: LRStep*): u32 {
    fill(result, 0, sizeof(LRStep));
    result.rule = lr_none();
    result.next = lr_none();
    result.id = id;
    result.start = start;
    result.end = start + length;
    result.kind = lr_parser_decide(value, ready, id, error, result);
    return result.kind;
}

export fn lr_parser_commit(value: LRParser*, step: LRStep*, first: usize, last: usize): bool {
    if step.kind == 6 {
        var evidence = step.end != step.start;
        var byte = convert(u8, evidence);
        var ok = vector_push(u8, &value.evidence, byte);
        if !ok {
            return false;
        }
        if value.evidence.length == 1 {
            value.sequence_start = step.start;
        }
        if step.end > value.sequence_end {
            value.sequence_end = step.end;
        }
        value.sequence_first = first;
        value.sequence_last = last;
        value.consumed = step.end;
        value.shifted = true;
        value.work.shifts++;
        return true;
    }
    var length = value.stack.length -step.pop;
    var count = length + 1;
    var ok = vector_reserve(LRFrame, &value.stack, count);
    if !ok {
        return false;
    }
    var frame = &value.stack.data[length];
    frame.state = step.next;
    frame.first = first;
    frame.last = last;
    frame.start = step.start;
    frame.length = step.end - step.start;
    value.stack.length = count;
    if step.kind == 1 {
        value.consumed = step.end;
        value.shifted = true;
        value.work.shifts++;
    } else {
        value.work.reductions++;
        value.work.popped = value.work.popped + step.pop;
        value.sequence = false;
    }
    return true;
}

export fn lr_parser_frame_count(value: LRParser*): usize {
    if value.sequence {
        var count = value.evidence.length + 1;
        return count;
    }
    return value.stack.length;
}

export fn lr_parser_frame(value: LRParser*, index: usize, result: LRFrame*): void {
    if value.sequence {
        fill(result, 0, sizeof(LRFrame));
        result.first = lr_none();
        result.last = lr_none();
        result.state = value.runtime.sequence_states.data[index];
        if index != 0 {
            var previous = index -1;
            result.length = convert(usize, value.evidence.data[previous]);
        }
    } else {
        copy(result, &value.stack.data[index], sizeof(LRFrame));
    }
}

export fn lr_parser_frames(value: LRParser*): LRFrame* {
    return value.stack.data;
}

export fn lr_parser_sequence_forest(value: LRParser*, result: LRFrame*): void {
    fill(result, 0, sizeof(LRFrame));
    result.first = value.sequence_first;
    result.last = value.sequence_last;
    result.start = value.sequence_start;
    result.length = value.sequence_end - value.sequence_start;
}

export fn lr_parser_consumed(value: LRParser*): usize {
    return value.consumed;
}

export fn lr_parser_shifted(value: LRParser*): bool {
    return value.shifted;
}

export fn lr_parser_work(value: LRParser*, result: LRWork*): void {
    copy(result, &value.work, sizeof(LRWork));
}

// Error-path probes share one explicit work budget. They never execute semantic
// actions, consume a source stream, or mutate the real recognizer's stack.
struct LRProbeFrame {
    state: usize;
    consumed: bool;
}

struct LRProbeBudget {
    remaining: usize;
    complete: bool;
}

struct LRProbe {
    runtime: LRRuntime*;
    budget: LRProbeBudget*;
    frames: vector(LRProbeFrame);
}

export fn lr_probe_destroy(value: LRProbe*): void {
    if value == null {
        return;
    }
    vector_dispose(LRProbeFrame, &value.frames);
    free(value);
}

fn lr_probe_allocate(runtime: LRRuntime*, budget: LRProbeBudget*, count: usize): LRProbe* {
    var value = alloc(LRProbe, 1);
    if value == null {
        budget.complete = false;
        return null;
    }
    fill(value, 0, sizeof(LRProbe));
    value.runtime = runtime;
    value.budget = budget;
    if vector_reserve(LRProbeFrame, &value.frames, count) {
        value.frames.length = count;
        return value;
    }
    budget.complete = false;
    lr_probe_destroy(value);
    return null;
}

export fn lr_probe_create(parser: LRParser*, budget: LRProbeBudget*): LRProbe* {
    var count = lr_parser_frame_count(parser);
    var value = lr_probe_allocate(parser.runtime, budget, count);
    if value == null {
        return null;
    }
    var index: usize = 0;
    loop {
        if index == count {
            return value;
        }
        var frame: LRFrame;
        lr_parser_frame(parser, index, &frame);
        value.frames.data[index].state = frame.state;
        value.frames.data[index].consumed = frame.length != 0;
        index++;
    }
}

export fn lr_probe_clone(source: LRProbe*): LRProbe* {
    var count = source.frames.length;
    var value = lr_probe_allocate(source.runtime, source.budget, count);
    if value != null {
        var bytes = count *sizeof(LRProbeFrame);
        copy(value.frames.data, source.frames.data, bytes);
    }
    return value;
}

export fn lr_probe_reset(value: LRProbe*): void {
    value.frames.length = 1;
    value.frames.data[0].state = 0;
    value.frames.data[0].consumed = false;
}

export fn lr_probe_count(value: LRProbe*): usize {
    return value.frames.length;
}

export fn lr_probe_frames(value: LRProbe*): LRProbeFrame* {
    return value.frames.data;
}

export fn lr_probe_accepts(value: LRProbe*, id: u32): bool {
    var top = value.frames.length -1;
    var action: LRAction;
    return lr_runtime_action(value.runtime, value.frames.data[top].state, id, &action);
}

export fn lr_probe_step(value: LRProbe*, id: u32, before: usize*): u32 {
    *before = lr_none();
    var steps: usize = 0;
    loop {
        var exhausted = steps == 128;
        if exhausted {
            break;
        }
        exhausted = value.budget.remaining == 0;
        if exhausted {
            break;
        }
        value.budget.remaining--;
        var top = value.frames.length -1;
        var state = value.frames.data[top].state;
        var action: LRAction;
        if !lr_runtime_action(value.runtime, state, id, &action) {
            return 0;
        }
        var frame: LRProbeFrame;
        frame.state = action.state;
        frame.consumed = false;
        if action.state != lr_none() {
            *before = state;
            var ok = lr_append(LRProbeFrame, &value.frames, &frame);
            if ok {
                return 1;
            }
            break;
        }
        if action.rule == 0 {
            return 2;
        }
        var rule = &value.runtime.rules.data[action.rule];
        var invalid = rule.count >= value.frames.length;
        if invalid {
            return 0;
        }
        var begin = value.frames.length -rule.count;
        for(var index = begin; index != value.frames.length; index++) {
            if value.frames.data[index].consumed {
                frame.consumed = true;
            }
        }
        value.frames.length = begin;
        var previous = begin -1;
        frame.state = lr_runtime_goto(value.runtime, value.frames.data[previous].state, rule.owner);
        invalid = frame.state == lr_none();
        if invalid {
            return 0;
        }
        var ok = lr_append(LRProbeFrame, &value.frames, &frame);
        if !ok {
            break;
        }
        steps++;
    }
    value.budget.complete = false;
    return 0;
}

// Editor lookahead snapshots are derived indexes over the live LR stack. They
// never run semantic actions or alter the recognizer. Every query is bounded.
struct LRCompletion {
    budget: LRProbeBudget;
    original: LRProbe*;
}

struct LRCompletionPath {
    probe: LRProbe*;
    parent: usize;
    choice: usize;
    depth: usize;
}

export fn lr_completion_create(parser: LRParser*): LRCompletion* {
    var c = alloc(LRCompletion, 1);
    if c == null {
        return null;
    }
    fill(c, 0, sizeof(LRCompletion));
    c.budget.complete = true;
    c.original = lr_probe_create(parser, &c.budget);
    if c.original == null {
        free(c);
        return null;
    }
    return c;
}

export fn lr_completion_destroy(c: LRCompletion*): void {
    if c == null {
        return;
    }
    lr_probe_destroy(c.original);
    free(c);
}

export fn lr_completion_runtime(c: LRCompletion*): LRRuntime* {
    return c.original.runtime;
}

export fn lr_completion_state(c: LRCompletion*): usize {
    var top = c.original.frames.length -1;
    return c.original.frames.data[top].state;
}

export fn lr_completion_accepts(c: LRCompletion*, id: u32): bool {
    if c == null {
        return false;
    }
    if c.original == null {
        return false;
    }
    c.budget.remaining = 8192;
    c.budget.complete = true;
    var probe = lr_probe_clone(c.original);
    if probe == null {
        return false;
    }
    var before: usize;
    var result = lr_probe_step(probe, id, &before);
    lr_probe_destroy(probe);
    var editor_result20 = result == 1;
    return editor_result20;
}

export fn lr_completion_follows(c: LRCompletion*, first: u32, second: u32): bool {
    if c == null {
        return false;
    }
    if c.original == null {
        return false;
    }
    c.budget.remaining = 8192;
    c.budget.complete = true;
    var probe = lr_probe_clone(c.original);
    if probe == null {
        return false;
    }
    var before: usize;
    var result = lr_probe_step(probe, first, &before);
    if result == 1 {
        result = lr_probe_step(probe, second, &before);
    }
    lr_probe_destroy(probe);
    var editor_value_5 = result == 1;
    return editor_value_5;
}

// Try a terminating continuation first. Every transition is checked against
// the full LR stack; this avoids spending the search budget on new statements
// while several enclosing blocks still need to close.
fn lr_completion_terminators(c: LRCompletion*, ids: u32*, count: usize, result: usize*, capacity: usize): usize {
    var current = lr_probe_clone(c.original);
    var missing = current == null;
    if missing {
        return lr_none();
    }
    var length: usize = 0;
    var answer = lr_none();
    loop {
        if c.budget.remaining == 0 {
            break;
        }
        var eof: u32 = 0;
        eof = eof - 2;
        var before: usize;
        var trial = lr_probe_clone(current);
        missing = trial == null;
        if missing {
            break;
        }
        var status = lr_probe_step(trial, eof, &before);
        lr_probe_destroy(trial);
        if status == 2 {
            answer = length;
            break;
        }
        if length == capacity {
            break;
        }
        var found: bool = false;
        var i: usize = 0;
        for(; i != count; i++) {
            trial = lr_probe_clone(current);
            missing = trial == null;
            if missing {
                break;
            }
            status = lr_probe_step(trial, ids[i], &before);
            if status == 1 {
                lr_probe_destroy(current);
                current = trial;
                result[length] = i;
                length++;
                found = true;
                break;
            }
            lr_probe_destroy(trial);
        }
        if !found {
            break;
        }
    }
    lr_probe_destroy(current);
    return answer;
}

// If closure preference fails, breadth-first search supplies a continuation.
// Token spellings come from the active grammar/lexer; output is scratch source.
export fn lr_completion_suffix(c: LRCompletion*, ids: u32*, count: usize, result: usize*, capacity: usize): usize {
    if c == null {
        return lr_none();
    }
    if c.original == null {
        return lr_none();
    }
    c.budget.remaining = 65536;
    c.budget.complete = true;
    var terminated = lr_completion_terminators(c, ids, count, result, capacity);
    var complete = terminated != lr_none();
    if complete {
        return terminated;
    }
    var paths: vector(LRCompletionPath);
    vector_init(LRCompletionPath, &paths);
    var first: LRCompletionPath;
    fill(&first, 0, sizeof(LRCompletionPath));
    first.probe = lr_probe_clone(c.original);
    if first.probe == null {
        return lr_none();
    }
    var added = lr_append(LRCompletionPath, &paths, &first);
    var failed = !added;
    if failed {
        lr_probe_destroy(first.probe);
        return lr_none();
    }
    var at: usize = 0;
    var length = lr_none();
    for(; at != paths.length; at++) {
        if c.budget.remaining == 0 {
            break;
        }
        var path = &paths.data[at];
        var original = path.probe;
        var depth = path.depth;
        var probe = lr_probe_clone(original);
        if probe == null {
            break;
        }
        var before: usize;
        var eof: u32 = 0;
        eof = eof - 2;
        var status = lr_probe_step(probe, eof, &before);
        lr_probe_destroy(probe);
        if status == 2 {
            length = depth;
            var index = length;
            var parent = at;
            loop {
                if index == 0 {
                    break;
                }
                index--;
                result[index] = paths.data[parent].choice;
                parent = paths.data[parent].parent;
            }
            break;
        }
        if depth < capacity {
            var i: usize = 0;
            for(; i != count; i++) {
                if paths.length >= 512 {
                    break;
                }
                probe = lr_probe_clone(original);
                if probe == null {
                    break;
                }
                status = lr_probe_step(probe, ids[i], &before);
                if status == 1 {
                    var next: LRCompletionPath;
                    next.probe = probe;
                    next.parent = at;
                    next.choice = i;
                    next.depth++;
                    added = lr_append(LRCompletionPath, &paths, &next);
                    failed = !added;
                    if failed {
                        lr_probe_destroy(probe);
                        break;
                    }
                } else {
                    lr_probe_destroy(probe);
                }
            }
        }
    }
    at = 0;
    for(; at != paths.length; at++) {
        lr_probe_destroy(paths.data[at].probe);
    }
    vector_dispose(LRCompletionPath, &paths);
    return length;
}

import tower;
import lr_types;
import lexer_table;
import lr_analysis;
import lr_states;
import .library.vector;

// Disposable runtime indexes. Grammar entities and their provenance remain the
// source of truth; explicit precedence resolves eligible conflicts at build time.
struct LRRow {
    actions: vector(LRAction);
    direct: vector(usize);
    hash: usize;
    next: usize;
    reduction: usize;
}

struct LRRuntimeState {
    row: LRRow*;
    gotos: vector(LRGoto);
}

struct LRRuntime {
    states: vector(LRRuntimeState);
    rows: vector(LRRow*);
    rules: vector(LRProduction);
    sequence: SymbolSequence*;
    sequence_states: vector(usize);
    sequence_rule: usize;
    conflict: LRConflict;
}

fn lr_action_less(a: LRAction*, b: LRAction*): bool {
    var different = a.first != b.first;
    if different {
        var less = a.first < b.first;
        return less;
    }
    different = a.last != b.last;
    if different {
        var less = a.last < b.last;
        return less;
    }
    different = a.state != b.state;
    if different {
        var less = a.state < b.state;
        return less;
    }
    var less = a.rule < b.rule;
    return less;
}

fn lr_action_insert(values: vector(LRAction)*, value: LRAction*): bool {
    var low: usize = 0;
    var high = values.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if lr_action_less(&values.data[middle], value) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if low < values.length {
        if !lr_action_less(value, &values.data[low]) {
            return true;
        }
    }
    var count = values.length + 1;
    if !vector_reserve(LRAction, values, count) {
        return false;
    }
    var moved = values.length -low;
    var bytes = moved *sizeof(LRAction);
    var next = low + 1;
    copy(&values.data[next], &values.data[low], bytes);
    copy(&values.data[low], value, sizeof(LRAction));
    values.length = count;
    return true;
}

fn lr_row_destroy(value: LRRow*): void {
    vector_dispose(LRAction, &value.actions);
    vector_dispose(usize, &value.direct);
    free(value);
}

export fn lr_runtime_destroy(value: LRRuntime*): void {
    if value == null {
        return;
    }
    var index: usize = 0;
    for(; index != value.states.length; index++) {
        vector_dispose(LRGoto, &value.states.data[index].gotos);
    }
    index = 0;
    for(; index != value.rows.length; index++) {
        lr_row_destroy(value.rows.data[index]);
    }
    vector_dispose(LRRuntimeState, &value.states);
    vector_dispose(LRRow*, &value.rows);
    vector_dispose(LRProduction, &value.rules);
    vector_dispose(usize, &value.sequence_states);
    symbol_sequence_destroy(value.sequence);
    free(value);
}

// Only explicit, compatible production annotations resolve a shift/reduce pair.
// Decisions are made once during table construction; the parser has no operator
// dispatch or extra runtime tree. Unannotated and reduce/reduce conflicts remain.
fn lr_precedence_choice(source: LRStates*, state: usize, a: LRAction*, b: LRAction*): u32 {
    var exact = a.first == a.last;
    exact &&= b.first == b.last;
    exact &&= a.first == b.first;
    if !exact {
        return 0;
    }
    var a_shift = a.state != lr_none();
    var b_shift = b.state != lr_none();
    if a_shift == b_shift {
        return 0;
    }
    var reduction = a;
    if a_shift {
        reduction = b;
    }
    var rule = &source.analysis.rules[reduction.rule];
    if !(rule.precedence != 0) {
        return 0;
    }
    var power: u32 = 0;
    var direction: u32 = 0;
    var items = source.states.data[state].items;
    var index: usize = 0;
    loop {
        if index == items.values.length {
            break;
        }
        var item = &items.values.data[index];
        index++;
        var candidate = &source.analysis.rules[item.rule];
        var eligible = item.position < candidate.count;
        if !eligible {
            continue;
        }
        var position = candidate.begin + item.position;
        var symbol = &source.analysis.symbols[position];
        eligible = symbol.nonterminal == lr_none();
        eligible &&= symbol.first == a.first;
        eligible &&= symbol.last == a.last;
        if !eligible {
            continue;
        }
        var missing = candidate.precedence == 0;
        if missing {
            return 0;
        }
        if power != 0 {
            var incompatible = power != candidate.precedence;
            incompatible ||= direction != candidate.associativity;
            if incompatible {
                return 0;
            }
        }
        power = candidate.precedence;
        direction = candidate.associativity;
    }
    var missing = power == 0;
    if missing {
        return 0;
    }
    var reduce = rule.precedence > power;
    if rule.precedence == power {
        var incompatible = rule.associativity != direction;
        if incompatible {
            return 0;
        }
        if direction == 3 {
            return 3;
        }
        reduce = direction == 1;
    }
    if reduce != a_shift {
        return 1;
    }
    return 2;
}

fn lr_row_normalize(row: LRRow*, conflict: LRConflict*, state: usize, source: LRStates*): void {
    // Precedence never hides a reduce/reduce conflict behind a chosen shift.
    // Validate pairs before merging ranges or dropping a non-associative action.
    var first: usize = 0;
    for(; first < row.actions.length; first++) {
        var a = &row.actions.data[first];
        var second = first + 1;
        for(; second < row.actions.length; second++) {
            var b = &row.actions.data[second];
            if b.first > a.last {
                break;
            }
            var same_kind =(a.state == lr_none()) ==(b.state == lr_none());
            if same_kind &&(a.state != b.state || a.rule != b.rule) {
                conflict.state = state;
                copy(&conflict.left, a, sizeof(LRAction));
                copy(&conflict.right, b, sizeof(LRAction));
                return;
            }
        }
    }
    var read: usize = 0;
    var count: usize = 0;
    loop {
        if read == row.actions.length {
            break;
        }
        var action = &row.actions.data[read];
        var merged = false;
        if count != 0 {
            var previous = count -1;
            var last = &row.actions.data[previous];
            var same = last.rule == action.rule;
            same &&= last.state == action.state;
            if same {
                var first = convert(u64, action.first);
                var limit = convert(u64, last.last);
                limit++;
                merged = first <= limit;
                if merged {
                    if action.last > last.last {
                        last.last = action.last;
                    }
                }
            }
            if !merged {
                if action.first <= last.last {
                    var choice = lr_precedence_choice(source, state, last, action);
                    if choice != 0 {
                        var second = choice == 2;
                        if second {
                            copy(last, action, sizeof(LRAction));
                        }
                        if choice == 3 {
                            count--;
                        }
                        read++;
                        continue;
                    }
                    conflict.state = state;
                    copy(&conflict.left, last, sizeof(LRAction));
                    copy(&conflict.right, action, sizeof(LRAction));
                    return;
                }
            }
        }
        if !merged {
            copy(&row.actions.data[count], action, sizeof(LRAction));
            count++;
        }
        read++;
    }
    row.actions.length = count;
}

fn lr_row_equal(a: LRRow*, b: LRRow*): bool {
    var same = a.hash == b.hash;
    same &&= a.actions.length == b.actions.length;
    if !same {
        return false;
    }
    var index: usize = 0;
    loop {
        if index == a.actions.length {
            return true;
        }
        var left = &a.actions.data[index];
        var right = &b.actions.data[index];
        var different = lr_action_less(left, right);
        if different {
            return false;
        }
        different = lr_action_less(right, left);
        if different {
            return false;
        }
        index++;
    }
}

fn lr_row_hash(row: LRRow*): usize {
    var hash: usize = 2166136261;
    var index: usize = 0;
    loop {
        if index == row.actions.length {
            return hash;
        }
        var action = &row.actions.data[index];
        var first = convert(usize, action.first);
        var last = convert(usize, action.last);
        hash = hash ^ first;
        hash = hash * 16777619;
        hash = hash ^ last;
        hash = hash * 16777619;
        hash = hash ^ action.rule;
        hash = hash * 16777619;
        hash = hash ^ action.state;
        hash = hash * 16777619;
        index++;
    }
}

// Singleton tokens have a direct hash index; arbitrary character ranges use
// binary search. The grammar size determines table size, not source length.
fn lr_row_index(row: LRRow*): bool {
    var singles: usize = 0;
    var index: usize = 0;
    row.reduction = lr_none();
    for(; index != row.actions.length; index++) {
        var action = &row.actions.data[index];
        var single = action.first == action.last;
        if single {
            singles++;
            if action.first == LRTokenEnd() {
                row.reduction = action.rule;
            }
        }
    }
    var needed = singles *2;
    var size: usize = 1;
    loop {
        if size > needed {
            break;
        }
        size = size * 2;
    }
    if !vector_reserve(usize, &row.direct, size) {
        return false;
    }
    row.direct.length = size;
    var bytes = size *sizeof(usize);
    fill(row.direct.data, 255, bytes);
    var mask = size -1;
    index = 0;
    loop {
        if index == row.actions.length {
            return true;
        }
        var action = &row.actions.data[index];
        if action.rule != row.reduction {
            row.reduction = lr_none();
        }
        var single = action.first == action.last;
        if single {
            var bucket = convert(usize, action.first);
            bucket = bucket * 16777619;
            bucket = bucket & mask;
            loop {
                if row.direct.data[bucket] == lr_none() {
                    break;
                }
                bucket++;
                bucket = bucket & mask;
            }
            row.direct.data[bucket] = index;
        }
        index++;
    }
}

fn lr_runtime_gotos(state: LRRuntimeState*, input: LRState*, analysis: LRAnalysis*): bool {
    var index: usize = 0;
    loop {
        if index == input.edges.length {
            return true;
        }
        var edge = &input.edges.data[index];
        var symbol = &analysis.symbols[edge.symbol];
        if symbol.nonterminal != lr_none() {
            var entry: LRGoto;
            entry.nonterminal = symbol.nonterminal;
            entry.state = edge.state;
            var position = state.gotos.length;
            if !lr_append(LRGoto, &state.gotos, &entry) {
                return false;
            }
            loop {
                if position == 0 {
                    break;
                }
                var previous = position -1;
                if state.gotos.data[previous].nonterminal < entry.nonterminal {
                    break;
                }
                copy(&state.gotos.data[position], &state.gotos.data[previous], sizeof(LRGoto));
                position = previous;
            }
            copy(&state.gotos.data[position], &entry, sizeof(LRGoto));
        }
        index++;
    }
}

fn lr_runtime_build(value: LRRuntime*, source: LRStates*, buckets: vector(usize)*): bool {
    var rule_count = source.analysis.rule_count;
    var ok = vector_reserve(LRProduction, &value.rules, rule_count);
    if !ok {
        return false;
    }
    var rule_bytes = rule_count *sizeof(LRProduction);
    copy(value.rules.data, source.analysis.rules, rule_bytes);
    value.rules.length = rule_count;
    var count = source.states.length;
    ok = vector_reserve(LRRuntimeState, &value.states, count);
    if !ok {
        return false;
    }
    var bytes = count *sizeof(LRRuntimeState);
    fill(value.states.data, 0, bytes);
    value.states.length = count;
    var bucket_count = count *2;
    bucket_count++;
    ok = vector_reserve(usize, buckets, bucket_count);
    if !ok {
        return false;
    }
    buckets.length = bucket_count;
    bytes = bucket_count * sizeof(usize);
    fill(buckets.data, 255, bytes);
    var index: usize = 0;
    loop {
        var done = index == count;
        if done {
            return true;
        }
        var row = alloc(LRRow, 1);
        if row == null {
            return false;
        }
        fill(row, 0, sizeof(LRRow));
        var input = source.states.data[index];
        var position: usize = 0;
        loop {
            done = position == input.actions.length;
            if done {
                break;
            }
            ok = lr_action_insert(&row.actions, &input.actions.data[position]);
            if !ok {
                lr_row_destroy(row);
                return false;
            }
            position++;
        }
        lr_row_normalize(row, &value.conflict, index, source);
        var conflict = value.conflict.state != lr_none();
        if conflict {
            lr_row_destroy(row);
            return true;
        }
        row.hash = lr_row_hash(row);
        if bucket_count == 0 {
            lr_row_destroy(row);
            return false;
        }
        var bucket = row.hash % bucket_count;
        var existing = buckets.data[bucket];
        var shared = false;
        loop {
            done = existing == lr_none();
            if done {
                break;
            }
            var other = value.rows.data[existing];
            shared = lr_row_equal(row, other);
            if shared {
                lr_row_destroy(row);
                row = other;
                break;
            }
            existing = other.next;
        }
        if !shared {
            ok = lr_row_index(row);
            ok &&= vector_push(LRRow*, &value.rows, row);
            if !ok {
                lr_row_destroy(row);
                return false;
            }
            row.next = buckets.data[bucket];
            buckets.data[bucket] = value.rows.length - 1;
        }
        var state = &value.states.data[index];
        state.row = row;
        ok = lr_runtime_gotos(state, input, source.analysis);
        if !ok {
            return false;
        }
        index++;
    }
}

export fn lr_runtime_create(source: LRStates*): LRRuntime* {
    var value = alloc(LRRuntime, 1);
    if value == null {
        return null;
    }
    fill(value, 0, sizeof(LRRuntime));
    value.conflict.state = lr_none();
    value.sequence_rule = lr_none();
    var buckets: vector(usize);
    vector_init(usize, &buckets);
    var ok = lr_runtime_build(value, source, &buckets);
    vector_dispose(usize, &buckets);
    if ok {
        return value;
    }
    lr_runtime_destroy(value);
    return null;
}

export fn lr_runtime_conflict(value: LRRuntime*, result: LRConflict*): bool {
    copy(result, &value.conflict, sizeof(LRConflict));
    var present = value.conflict.state != lr_none();
    return present;
}

export fn lr_runtime_action_count(value: LRRuntime*, state: usize): usize {
    return value.states.data[state].row.actions.length;
}

export fn lr_runtime_actions(value: LRRuntime*, state: usize): LRAction* {
    return value.states.data[state].row.actions.data;
}

export fn lr_runtime_default(value: LRRuntime*, state: usize): usize {
    return value.states.data[state].row.reduction;
}

export fn lr_runtime_row_count(value: LRRuntime*): usize {
    return value.rows.length;
}

export fn lr_runtime_goto_count(value: LRRuntime*, state: usize): usize {
    return value.states.data[state].gotos.length;
}

export fn lr_runtime_goto_data(value: LRRuntime*, state: usize): LRGoto* {
    return value.states.data[state].gotos.data;
}

export fn lr_runtime_goto(value: LRRuntime*, state: usize, nonterminal: usize): usize {
    var gotos = &value.states.data[state].gotos;
    var low: usize = 0;
    var high = gotos.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if gotos.data[middle].nonterminal < nonterminal {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    var present = low < gotos.length;
    if present {
        present = gotos.data[low].nonterminal == nonterminal;
        if present {
            return gotos.data[low].state;
        }
    }
    return lr_none();
}

export fn lr_runtime_action(value: LRRuntime*, state: usize, id: u32, result: LRAction*): bool {
    var row = value.states.data[state].row;
    var mask = row.direct.length -1;
    var bucket = convert(usize, id);
    bucket = bucket * 16777619;
    bucket = bucket & mask;
    loop {
        var index = row.direct.data[bucket];
        if index == lr_none() {
            break;
        }
        var action = &row.actions.data[index];
        if action.first == id {
            copy(result, action, sizeof(LRAction));
            return true;
        }
        bucket++;
        bucket = bucket & mask;
    }
    var low: usize = 0;
    var high = row.actions.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if row.actions.data[middle].last < id {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    var present = low < row.actions.length;
    if present {
        var action = &row.actions.data[low];
        present = action.first <= id;
        if present {
            copy(result, action, sizeof(LRAction));
            return true;
        }
    }
    return false;
}

// One nonempty terminal-only root production is a proven finite-state chain.
// Keep its LR state correspondence for exactly the same lexical/error context.
export fn lr_runtime_specialize(value: LRRuntime*, source: LRStates*): void {
    var root: usize = lr_none();
    var index: usize = 0;
    for(; index != value.rules.length; index++) {
        if value.rules.data[index].owner == 1 {
            if root != lr_none() {
                return;
            }
            root = index;
        }
    }
    var missing = root == lr_none();
    if missing {
        return;
    }
    var rule = &value.rules.data[root];
    var invalid = rule.count == 0;
    if invalid {
        return;
    }
    invalid = rule.count > 4096;
    if invalid {
        return;
    }
    index = 0;
    for(; index != rule.count; index++) {
        var position = rule.begin + index;
        var symbol = &source.analysis.symbols[position];
        invalid = symbol.nonterminal != lr_none();
        if invalid {
            return;
        }
        invalid = symbol.last >= LRTokenPropagation();
        if invalid {
            return;
        }
    }
    var count = rule.count + 1;
    var ok = vector_reserve(usize, &value.sequence_states, count);
    if !ok {
        return;
    }
    var sequence = symbol_sequence_create(rule.count);
    missing = sequence == null;
    if missing {
        return;
    }
    value.sequence_states.data[0] = 0;
    index = 0;
    loop {
        if index == rule.count {
            break;
        }
        var position = rule.begin + index;
        var symbol = &source.analysis.symbols[position];
        var action: LRAction;
        ok = lr_runtime_action(value, value.sequence_states.data[index], symbol.first, &action);
        ok &&= action.state != lr_none();
        if !ok {
            symbol_sequence_destroy(sequence);
            return;
        }
        var next = index + 1;
        value.sequence_states.data[next] = action.state;
        symbol_sequence_set(sequence, index, symbol.first, symbol.last);
        index = next;
    }
    value.sequence_states.length = count;
    value.sequence = sequence;
    value.sequence_rule = root;
}

export fn lr_runtime_sequence(value: LRRuntime*): usize {
    return value.sequence_rule;
}

import tower;
import lr_types;
import lr_analysis;
import .library.vector;

// LR(0) state construction and kernel interning. The same item operations handle
// character ranges and token IDs; all records are disposable grammar indexes.
struct LRState {
    items: LRItems*;
    symbols: vector(usize);
    edges: vector(LRTransition);
    actions: vector(LRAction);
    base: usize;
    origin: usize;
    hash: usize;
    next: usize;
}

struct LRStates {
    analysis: LRAnalysis*;
    states: vector(LRState*);
    pending: vector(usize);
    buckets: vector(usize);
}

export fn lr_kernel(analysis: LRAnalysis*, item: LRItem*): bool {
    if item.position != 0 {
        return true;
    }
    if item.rule == 0 {
        return true;
    }
    var empty = analysis.rules[item.rule].count == 0;
    return empty;
}

fn lr_state_hash(analysis: LRAnalysis*, items: LRItems*): usize {
    var hash: usize = 2166136261;
    var index: usize = 0;
    loop {
        if index == items.values.length {
            return hash;
        }
        var item = &items.values.data[index];
        if lr_kernel(analysis, item) {
            hash = hash ^ item.rule;
            hash = hash * 16777619;
            hash = hash ^ item.position;
            hash = hash * 16777619;
        }
        index++;
    }
}

fn lr_state_equal(analysis: LRAnalysis*, a: LRItems*, b: LRItems*): bool {
    var left: usize = 0;
    var right: usize = 0;
    loop {
        for(; left != a.values.length; left++) {
            var kernel = lr_kernel(analysis, &a.values.data[left]);
            if kernel {
                break;
            }
        }
        for(; right != b.values.length; right++) {
            var kernel = lr_kernel(analysis, &b.values.data[right]);
            if kernel {
                break;
            }
        }
        var end = left == a.values.length;
        if end {
            var same = right == b.values.length;
            return same;
        }
        end = right == b.values.length;
        if end {
            return false;
        }
        var different = a.values.data[left].rule != b.values.data[right].rule;
        if different {
            return false;
        }
        different = a.values.data[left].position != b.values.data[right].position;
        if different {
            return false;
        }
        left++;
        right++;
    }
}

fn lr_symbol_less(analysis: LRAnalysis*, a: usize, b: usize): bool {
    var left = &analysis.symbols[a];
    var right = &analysis.symbols[b];
    var left_terminal = left.nonterminal == lr_none();
    var right_terminal = right.nonterminal == lr_none();
    var different = left_terminal != right_terminal;
    if different {
        return right_terminal;
    }
    if left_terminal {
        different = left.first != right.first;
        if different {
            var less = left.first < right.first;
            return less;
        }
        var less = left.last < right.last;
        return less;
    }
    var less = analysis.nonterminals[left.nonterminal].order < analysis.nonterminals[right.nonterminal].order;
    return less;
}

fn lr_state_symbol(analysis: LRAnalysis*, state: LRState*, symbol: usize): bool {
    var low: usize = 0;
    var high = state.symbols.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if lr_symbol_less(analysis, state.symbols.data[middle], symbol) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if low < state.symbols.length {
        if !lr_symbol_less(analysis, symbol, state.symbols.data[low]) {
            return true;
        }
    }
    var count = state.symbols.length + 1;
    if !vector_reserve(usize, &state.symbols, count) {
        return false;
    }
    var moved = state.symbols.length -low;
    var bytes = moved *sizeof(usize);
    var next = low + 1;
    copy(&state.symbols.data[next], &state.symbols.data[low], bytes);
    state.symbols.data[low] = symbol;
    state.symbols.length = count;
    return true;
}

fn lr_state_destroy(state: LRState*): void {
    lr_items_destroy(state.items);
    vector_dispose(usize, &state.symbols);
    vector_dispose(LRTransition, &state.edges);
    vector_dispose(LRAction, &state.actions);
    free(state);
}

export fn lr_states_destroy(value: LRStates*): void {
    if value == null {
        return;
    }
    for(var index: usize = 0; index != value.states.length; index++) {
        lr_state_destroy(value.states.data[index]);
    }
    vector_dispose(LRState*, &value.states);
    vector_dispose(usize, &value.pending);
    vector_dispose(usize, &value.buckets);
    free(value);
}

fn lr_states_rehash(value: LRStates*): bool {
    var needed = value.states.length *2;
    if value.buckets.length > needed {
        return true;
    }
    needed = value.buckets.length * 2;
    needed = needed + 17;
    if !vector_reserve(usize, &value.buckets, needed) {
        return false;
    }
    value.buckets.length = needed;
    var index: usize = 0;
    for(; index != needed; index++) {
        value.buckets.data[index] = lr_none();
    }
    index = 0;
    loop {
        if index == value.states.length {
            return true;
        }
        var state = value.states.data[index];
        var bucket = state.hash % needed;
        state.next = value.buckets.data[bucket];
        value.buckets.data[bucket] = index;
        index++;
    }
}

// Takes ownership of items on every path, including an existing kernel match.
fn lr_states_intern(value: LRStates*, items: LRItems*, origin: usize): usize {
    defer lr_items_destroy(items);
    var ok = lr_states_rehash(value);
    if !ok {
        return lr_none();
    }
    var hash = lr_state_hash(value.analysis, items);
    var bucket_count = value.buckets.length;
    if bucket_count == 0 {
        return lr_none();
    }
    var bucket = hash % bucket_count;
    var index = value.buckets.data[bucket];
    loop {
        if index == lr_none() {
            break;
        }
        var state = value.states.data[index];
        var same = hash == state.hash;
        if same {
            same = lr_state_equal(value.analysis, items, state.items);
            if same {
                return index;
            }
        }
        index = state.next;
    }
    var state = alloc(LRState, 1);
    if state == null {
        return lr_none();
    }
    fill(state, 0, sizeof(LRState));
    state.items = items;
    items = null; // Ownership moved to the state.
    state.origin = origin;
    state.hash = hash;
    state.next = value.buckets.data[bucket];
    index = value.states.length;
    ok = vector_push(usize, &value.pending, index);
    ok &&= vector_push(LRState*, &value.states, state);
    if !ok {
        lr_state_destroy(state);
        return lr_none();
    }
    value.buckets.data[bucket] = index;
    return index;
}

export fn lr_states_create(analysis: LRAnalysis*): LRStates* {
    var value = alloc(LRStates, 1);
    var missing = value == null;
    if missing {
        return null;
    }
    fill(value, 0, sizeof(LRStates));
    defer lr_states_destroy(value);
    value.analysis = analysis;
    var items = lr_items_create();
    missing = items == null;
    if missing {
        return null;
    }
    var seed: LRItem;
    fill(&seed, 0, sizeof(LRItem));
    var ok = lr_items_insert(items, &seed);
    ok &&= lr_items_close(analysis, items, false);
    if !ok {
        lr_items_destroy(items);
        return null;
    }
    var start = lr_states_intern(value, items, lr_none());
    missing = start == lr_none();
    if missing {
        return null;
    }
    loop {
        var done = value.pending.length == 0;
        if done {
            var result = value;
            value = null; // Transfer ownership to the caller.
            return result;
        }
        value.pending.length--;
        var index = value.pending.data[value.pending.length];
        var state = value.states.data[index];
        // Kernel items precede closure items, as in the ordinary LR builder.
        var pass: usize = 0;
        loop {
            done = pass == 2;
            if done {
                break;
            }
            var position: usize = 0;
            loop {
                done = position == state.items.values.length;
                if done {
                    break;
                }
                var item = &state.items.values.data[position];
                var kernel = lr_kernel(analysis, item);
                var want_kernel = pass == 0;
                var include = kernel == want_kernel;
                var rule = &analysis.rules[item.rule];
                var present = item.position < rule.count;
                if include {
                    if present {
                        var symbol = rule.begin + item.position;
                        ok = lr_state_symbol(analysis, state, symbol);
                        if !ok {
                            return null;
                        }
                    }
                }
                position++;
            }
            pass++;
        }
        var position: usize = 0;
        loop {
            done = position == state.symbols.length;
            if done {
                break;
            }
            var symbol = state.symbols.data[position];
            var next = lr_items_create();
            missing = next == null;
            if missing {
                return null;
            }
            ok = lr_items_goto(analysis, state.items, &analysis.symbols[symbol], next, false);
            if !ok {
                lr_items_destroy(next);
                return null;
            }
            var edge: LRTransition;
            edge.symbol = symbol;
            edge.state = lr_states_intern(value, next, symbol);
            missing = edge.state == lr_none();
            if missing {
                return null;
            }
            ok = lr_append(LRTransition, &state.edges, &edge);
            if !ok {
                return null;
            }
            position++;
        }
    }
}

export fn lr_states_count(value: LRStates*): usize {
    return value.states.length;
}

export fn lr_states_items(value: LRStates*, index: usize): LRItems* {
    return value.states.data[index].items;
}

export fn lr_states_origin(value: LRStates*, index: usize): usize {
    return value.states.data[index].origin;
}

export fn lr_states_edge_count(value: LRStates*, index: usize): usize {
    return value.states.data[index].edges.length;
}

export fn lr_states_edges(value: LRStates*, index: usize): LRTransition* {
    return value.states.data[index].edges.data;
}

