// A stream has one writer. Buffered input transfers one owned entity reference.
// Empty streams can be fed with parser_stream_return; no hidden host callbacks.
struct ParserStream {
    kind: ParserInputService;
    error: vector(u8);
    buffered: bool;
    buffered_node: void*;
    buffered_id: u32;
    buffered_start: usize;
    buffered_length: usize;
    buffered_error: vector(u8);
}

struct ParserUtf8Stream {
    source: vector(u8);
    cursor: usize;
    allocation_failed: bool;
}

struct ParserRecognizerStream {
    recognizer: void*;
    complete: bool;
}

extern fn tower_memory_allocate(bytes: usize): void*;

extern fn tower_memory_free(memory: void*): void;

fn parser_state_require(ok: bool): void {
    if !ok {
        abort();
    }
}

fn parser_state_text(value: vector(u8)*): u8* {
    if value.data == null {
        return "";
    }
    return value.data;
}

fn parser_state_clear(value: vector(u8)*): void {
    value.length = 0;
    if value.data != null {
        value.data[0] = 0;
    }
}

fn parser_state_assign(value: vector(u8)*, text: u8*): void {
    var length: usize = 0;
    for(; text[length] != 0; length++) {}
    if length == 0 {
        parser_state_clear(value);
        return;
    }
    parser_state_require(bytes_assign_text(value, text, length));
}

export fn parser_stream_create(bytes: usize, kind: ParserInputService): ParserStream* {
    var total = sizeof(ParserStream) + bytes;
    if total < bytes {
        return null;
    }
    var stream = bits(ParserStream*, tower_memory_allocate(total));
    if stream == null {
        return null;
    }
    fill(stream, 0, sizeof(ParserStream));
    stream.kind = kind;
    stream.buffered_id = ParserStreamEnd();
    return stream;
}

export fn parser_stream_get_userdata(stream: ParserStream*): void* {
    if stream == null {
        return null;
    }
    var data = bits(u8*, stream) + sizeof(ParserStream);
    return bits(void*, data);
}

export fn parser_stream_from_userdata(data: void*): ParserStream* {
    if data == null {
        return null;
    }
    var address = bits(u8*, data) -sizeof(ParserStream);
    return bits(ParserStream*, address);
}

export fn parser_stream_get_error(stream: ParserStream*): u8* {
    return parser_state_text(&stream.error);
}

export fn parser_stream_set_error(stream: ParserStream*, error: u8*): void {
    parser_state_assign(&stream.error, error);
}

// Discard returns ownership of buffered entities before disposing stream storage.
export fn parser_stream_discard(stream: ParserStream*): void {
    var node = stream.buffered_node;
    stream.buffered_node = null;
    stream.buffered = false;
    if node != null {
        entity_release(node);
    }
}

export fn parser_stream_dispose(stream: ParserStream*): void {
    if stream.kind == ParserInputService.Utf8 {
        var data = bits(ParserUtf8Stream*, parser_stream_get_userdata(stream));
        vector_dispose(u8, &data.source);
    }
    vector_dispose(u8, &stream.error);
    vector_dispose(u8, &stream.buffered_error);
    tower_memory_free(bits(void*, stream));
}

export fn parser_stream_utf8_create(begin: u8*, end: u8*): ParserStream* {
    var stream = parser_stream_create(sizeof(ParserUtf8Stream), ParserInputService.Utf8);
    if stream == null {
        return null;
    }
    var data = bits(ParserUtf8Stream*, parser_stream_get_userdata(stream));
    fill(data, 0, sizeof(ParserUtf8Stream));
    var length = bits(usize, end) -bits(usize, begin);
    var ok = bytes_assign_text(&data.source, begin, length);
    data.allocation_failed = !ok;
    return stream;
}

export fn parser_stream_utf8_null_terminated_create(text: u8*): ParserStream* {
    var length: usize = 0;
    for(; text[length] != 0; length++) {}
    var end = text + length;
    return parser_stream_utf8_create(text, end);
}

export fn parser_stream_recognizer_create(recognizer: void*): ParserStream* {
    var stream = parser_stream_create(sizeof(ParserRecognizerStream), ParserInputService.Recognizer);
    if stream == null {
        return null;
    }
    var data = bits(ParserRecognizerStream*, parser_stream_get_userdata(stream));
    data.recognizer = recognizer;
    data.complete = false;
    return stream;
}

// true supplies a token/EOF; false denotes an empty externally-fed stream.
// A returned node transfers exactly one reference to the reader.
export fn parser_stream_poll(stream: ParserStream*, id: u32*, start: usize*, length: usize*, node: void**): bool {
    *node = null;
    if stream.buffered {
        stream.buffered = false;
        *id = stream.buffered_id;
        *start = stream.buffered_start;
        *length = stream.buffered_length;
        vector_dispose(u8, &stream.error);
        copy(&stream.error, &stream.buffered_error, sizeof(vector(u8)));
        fill(&stream.buffered_error, 0, sizeof(vector(u8)));
        *node = stream.buffered_node;
        stream.buffered_node = null;
        return true;
    }
    parser_state_clear(&stream.error);
    if stream.kind == ParserInputService.Empty {
        return false;
    }
    *id = ParserStreamEnd();
    *start = convert(usize, ParserStreamEnd());
    *length = 0;
    if stream.kind == ParserInputService.Utf8 {
        var data = bits(ParserUtf8Stream*, parser_stream_get_userdata(stream));
        if data.allocation_failed {
            parser_stream_set_error(stream, "Unable to allocate UTF-8 stream source");
            return true;
        }
        var remaining = data.source.length -data.cursor;
        var at = data.source.data + data.cursor;
        var read = tower_utf8_decode(at, remaining, id);
        if read != 0 {
            *start = data.cursor;
            *length = read;
            data.cursor = data.cursor + read;
        } else {
            *id = ParserStreamEnd();
        }
        return true;
    }
    var syntax = stream.kind == ParserInputService.Syntax;
    var template = stream.kind == ParserInputService.Template;
    if syntax {
        *node = syntax_parser_read(stream, parser_stream_get_userdata(stream), id, start, length);
        return true;
    }
    if template {
        *node = syntax_parser_template_read(stream, parser_stream_get_userdata(stream), id, start, length);
        return true;
    }
    var data = bits(ParserRecognizerStream*, parser_stream_get_userdata(stream));
    var running = !data.complete;
    while running {
        *node = parser_recognizer_step(bits(ParserRequest*, data.recognizer), &running);
        var ready = *node != null;
        if ready {
            break;
        }
    }
    data.complete = !running;
    parser_stream_set_error(stream, parser_recognizer_get_error(data.recognizer));
    var ready = *node != null;
    if ready {
        var request = bits(ParserRequest*, data.recognizer);
        var span = lr_tree_match(*node, request.match_kind);
        var valid = span != null;
        parser_state_require(valid);
        *id = span.id;
        *start = span.start;
        *length = span.length;
    }
    return true;
}

// Consume the recognizer's lookahead and error storage, without allocating.
export fn parser_stream_return(stream: ParserStream*, node: void**, id: u32, start: usize, length: usize, error: vector(u8)*): void {
    var empty = !stream.buffered;
    parser_state_require(empty);
    stream.buffered = true;
    stream.buffered_node = *node;
    *node = null;
    stream.buffered_id = id;
    stream.buffered_start = start;
    stream.buffered_length = length;
    vector_dispose(u8, &stream.buffered_error);
    copy(&stream.buffered_error, error, sizeof(vector(u8)));
    fill(error, 0, sizeof(vector(u8)));
    parser_state_clear(&stream.error);
}

// These are the syntax owner's existing functions, mechanically exposed by name.
// Their request-local cursor/highlights remain outside the immutable table.
extern fn syntax_parser_read(stream: ParserStream*, data: void*, id: u32*, start: usize*, length: usize*): void*;

extern fn syntax_parser_template_read(stream: ParserStream*, data: void*, id: u32*, start: usize*, length: usize*): void*;

export fn parser_stream_read(stream: ParserStream*, id: u32*, start: usize*, length: usize*): void* {
    var node: void* = null;
    if !parser_stream_poll(stream, id, start, length, &node) {
        *id = ParserStreamEnd();
        *start = convert(usize, ParserStreamEnd());
        *length = 0;
    }
    return node;
}

export fn parser_stream_destroy(stream: ParserStream*): void {
    if stream == null {
        return;
    }
    parser_stream_discard(stream);
    parser_stream_dispose(stream);
}

import tower;
import parser_table_types;
import grammar_types;
import lr_api;
import lr_types;
import frontend_diagnostic_types;
import .library.vector;
import parser_markers;

extern fn entity_child_count(root: void*): usize;

extern fn tower_memory_allocate(size: usize): void*;

extern fn tower_memory_free(memory: void*): void;

extern fn abort(): void;

extern fn parser_rule_get_type(): void*;

extern fn parser_reference_get_type(): void*;

extern fn parser_string_get_type(): void*;

extern fn parser_range_get_type(): void*;

extern fn parser_match_get_type(): void*;

fn parser_table_none(): usize {
    var result: usize = 0;
    result--;
    return result;
}

fn parser_table_clear_runtime(table: ParserHostTable*): void {
    lr_runtime_destroy(table.runtime);
    table.runtime = null;
    var index: usize = 0;
    for(; index < table.states.length; index++) {
        vector_dispose(FrontendContextPosition, &table.states.data[index].contexts);
    }
    vector_dispose(ParserHostState, &table.states);
    table.built = false;
}

export fn parser_table_destroy(table: ParserHostTable*): void {
    if table == null {
        return;
    }
    parser_table_clear_runtime(table);
    lr_grammar_destroy(table.grammar);
    tower_memory_free(bits(void*, table));
}

// Input entities/kinds are borrowed for construction. LRGrammar owns immutable
// name/capture snapshots; successful build releases its source-node indexes.
export fn parser_table_open(root: void*, kinds: FrontendKinds*, userdata: void*, presentation: ParserPresentation, mode: u32): ParserHostTable* {
    var table = bits(ParserHostTable*, tower_memory_allocate(sizeof(ParserHostTable)));
    var missing = table == null;
    if missing {
        return null;
    }
    fill(table, 0, sizeof(ParserHostTable));
    table.userdata = userdata;
    table.presentation = presentation;
    table.match_kind = kinds.`match`;
    table.mode = mode;
    var empty = root == null;
    empty ||= entity_child_count(root) == 0;
    if empty {
        table.error = "Empty grammar";
        return table;
    }
    table.grammar = lr_grammar_create(root, kinds.rule, kinds.reference, kinds.string, kinds.range);
    missing = table.grammar == null;
    if missing {
        table.error = "Unable to allocate grammar indexes";
    }
    return table;
}

// Existing default-world transport API. Empty grammars do not create kind nodes.
export fn parser_table_open_host(root: void*, userdata: void*, presentation: ParserPresentation, mode: u32): ParserHostTable* {
    var kinds: FrontendKinds;
    fill(&kinds, 0, sizeof(FrontendKinds));
    var present = root != null;
    present &&= entity_child_count(root) != 0;
    if present {
        kinds.rule = parser_rule_get_type();
        kinds.reference = parser_reference_get_type();
        kinds.string = parser_string_get_type();
        kinds.range = parser_range_get_type();
        kinds.`match` = parser_match_get_type();
    }
    return parser_table_open(root, &kinds, userdata, presentation, mode);
}

fn parser_table_contexts(table: ParserHostTable*, analysis: void*, states: void*): bool {
    var count = lr_states_count(states);
    var ok = vector_reserve(ParserHostState, &table.states, count);
    if !ok {
        return false;
    }
    var state_size = sizeof(ParserHostState);
    var bytes = count *state_size;
    fill(table.states.data, 0, bytes);
    table.states.length = count;
    var rules = lr_grammar_rule_data(table.grammar);
    var symbols = lr_grammar_symbol_data(table.grammar);
    var index: usize = 0;
    for(; index < count; index++) {
        var state = &table.states.data[index];
        state.origin = lr_states_origin(states, index);
        var items = lr_states_items(states, index);
        var values = lr_items_data(items);
        var size = lr_items_count(items);
        ok = vector_reserve(FrontendContextPosition, &state.contexts, size);
        if !ok {
            return false;
        }
        var kernel: bool = true;
        loop {
            var position: usize = 0;
            for(; position < size; position++) {
                var item = &values[position];
                if lr_kernel(analysis, item) == kernel {
                    var context = &state.contexts.data[state.contexts.length];
                    fill(context, 0, sizeof(FrontendContextPosition));
                    context.production = item.rule;
                    context.term = item.position;
                    var rule = &rules[item.rule];
                    if item.position < rule.count {
                        var symbol_index = rule.begin + item.position;
                        var symbol = &symbols[symbol_index];
                        context.terminal = symbol.nonterminal == parser_table_none();
                        if context.terminal {
                            context.first = symbol.first;
                            context.last = symbol.last;
                        }
                    }
                    state.contexts.length++;
                }
            }
            if kernel {
                state.kernels = state.contexts.length;
                kernel = false;
            } else {
                break;
            }
        }
    }
    return true;
}

// Hosts resolve missing grammar names before building. This never calls a host
// callback. A failure leaves the grammar available for retry and owns no runtime.
// Conflicts retain their runtime for diagnostics; they are never specialized.
export fn parser_table_build(table: ParserHostTable*, specialize: bool): bool {
    if table.built {
        return true;
    }
    var grammar = table.grammar;
    var missing = grammar == null;
    if missing {
        return false;
    }
    parser_table_clear_runtime(table);
    table.error = null;
    if lr_grammar_pending(grammar) != parser_table_none() {
        table.error = "Unresolved grammar rule";
        return false;
    }
    var analysis = lr_analysis_create(lr_grammar_rule_data(grammar), lr_grammar_rule_count(grammar),
    lr_grammar_symbol_data(grammar), lr_grammar_symbol_count(grammar), lr_grammar_name_count(grammar));
    missing = analysis == null;
    if missing {
        table.error = "Unable to allocate LR grammar analysis";
        return false;
    }
    var names = lr_grammar_name_count(grammar);
    for(var index: usize = 0; index < names; index++) {
        lr_analysis_order(analysis, index, lr_grammar_name_order(grammar, index));
    }
    var ok = lr_analysis_compute(analysis);
    var states: void* = null;
    if ok {
        table.error = "Unable to construct LR parser tables";
        states = lr_states_create(analysis);
        ok = states != null;
        if ok {
            var constructs = table.mode == convert(u32, ParserReadMode.Constructs);
            ok = lr_states_lalr(states, constructs);
        }
    } else {
        table.error = "Unable to allocate LR grammar analysis";
    }
    ok &&= parser_table_contexts(table, analysis, states);
    if ok {
        table.error = "Unable to allocate LR runtime tables";
        table.runtime = lr_runtime_create(states);
        ok = table.runtime != null;
    }
    if ok {
        var conflict: LRConflict;
        if !lr_runtime_conflict(table.runtime, &conflict) {
            if specialize {
                lr_runtime_specialize(table.runtime, states);
            }
        }
        lr_grammar_detach(grammar);
        table.built = true;
        table.error = null;
    }
    lr_states_destroy(states);
    lr_analysis_destroy(analysis);
    if !ok {
        parser_table_clear_runtime(table);
    }
    return ok;
}

export fn parser_table_uses_dfa(table: ParserHostTable*): bool {
    var absent = table == null;
    if absent {
        return false;
    }
    absent = table.runtime == null;
    if absent {
        return false;
    }
    var specialized = lr_runtime_sequence(table.runtime) != parser_table_none();
    return specialized;
}

export fn parser_table_grammar(table: ParserHostTable*): void* {
    if table == null {
        return null;
    }
    return table.grammar;
}

// Iterate production ownership directly; debug-only queries need no copied
// nonterminal/rule lists. The returned index belongs to this table revision.
export fn parser_table_rule_next(table: ParserHostTable*, owner: usize, begin: usize): usize {
    var count = lr_grammar_rule_count(table.grammar);
    var rules = lr_grammar_rule_data(table.grammar);
    for(var index = begin; index < count; index++) {
        if rules[index].owner == owner {
            return index;
        }
    }
    return parser_table_none();
}

fn parser_table_require(table: ParserHostTable*): void {
    var valid = table != null;
    valid &&= table.built;
    if !valid {
        abort();
    }
}

export fn parser_table_non_terminal_resolve_reference(userdata: void*, name: u8*): u32 {
    var table = bits(ParserHostTable*, userdata);
    parser_table_require(table);
    var count = lr_grammar_name_count(table.grammar);
    for(var index: usize = 0; index < count; index++) {
        var candidate = lr_grammar_name(table.grammar, index);
        for(var position: usize = 0; !(candidate[position] != name[position]); position++) {
            if candidate[position] == 0 {
                return convert(u32, index);
            }
        }
    }
    return ParserStreamEnd();
}

export fn parser_table_non_terminal_id_to_string(userdata: void*, id: u32): u8* {
    var table = bits(ParserHostTable*, userdata);
    parser_table_require(table);
    var index = convert(usize, id);
    if index >= lr_grammar_name_count(table.grammar) {
        return null;
    }
    var source = lr_grammar_name(table.grammar, index);
    var length: usize = 0;
    for(; source[length] != 0; length++) {}
    var size = length + 1;
    var text = bits(u8*, tower_memory_allocate(size));
    if text == null {
        abort();
        return null;
    }
    copy(text, source, size);
    return text;
}

import tower;
import .library.vector;
import frontend_diagnostic_types;

enum ParserReadMode: u32 {
    WholeInput, Constructs
}

struct ParserHostState {
    origin: usize;
    kernels: usize;
    contexts: vector(FrontendContextPosition);
}

// Presentation services are explicit until Tower supports function values. The
// Syntax service calls the existing syntax owner's exported views; it does not
// own or mutate a SyntaxSession or grammar revision.
enum ParserPresentation: u32 {
    Numeric, Utf8, NonTerminal, Syntax
}

// The coordinator owns the table and pins it and its world for all requests.
// Build completes before publication. Requests borrow it without refcount/cache
// writes; it must not be rebuilt or destroyed until those requests have ended.
struct ParserHostTable {
    grammar: void*;
    runtime: void*;
    states: vector(ParserHostState);
    userdata: void*;
    presentation: ParserPresentation;
    mode: u32;
    error: u8*;
    built: bool;
    match_kind: void*;
    trace: bool;
}

import .library.vector;
import tower;

// Components stored on the same compiler entities. The native adapter borrows
// these payloads; all field layout, text and token-array ownership is Tower code.
// Built with library/vector.tower; public construction still uses entity APIs.
struct ParserRuleData {
    name: vector(u8);
    generated: bool;
    precedence: u32;
    associativity: u32;
}

struct ParserReferenceData {
    name: vector(u8);
    capture: vector(u8);
}

struct ParserStringData {
    ids: vector(u32);
}

struct ParserRangeData {
    start: u32;
    end: u32;
}

struct ParserMatchData {
    id: u32;
    start: usize;
    length: usize;
    rule: usize;
    label: vector(u8);
}

import tower;

// Regex notation is parsed by the ordinary LR engine over Unicode scalar IDs.
// These are the same Rule/Reference/String/Range components as other grammars.
import grammar_builder;
import grammar_types;

fn regex_reference(builder: GrammarBuilder*, name: u8*, child: u8*): void {
    var rule = grammar_builder_rule(builder, name, false);
    grammar_builder_reference(builder, rule, child, "value");
}

fn regex_symbols(builder: GrammarBuilder*, name: u8*, symbols: u8*): void {
    var i: usize = 0;
    loop {
        var value = symbols[i];
        if value == 0 {
            return;
        }
        var rule = grammar_builder_rule(builder, name, false);
        var scalar = convert(u32, value);
        grammar_builder_range(builder, rule, scalar, scalar);
        i++;
    }
}

fn regex_characters(builder: GrammarBuilder*, name: u8*, excluded: u8*): void {
    var blocked: u8[128];
    fill(&blocked, 0, 128);
    var i: usize = 0;
    loop {
        var value = excluded[i];
        if value == 0 {
            break;
        }
        blocked[value] = 1;
        i++;
    }
    var first: u32 = 0;
    for(var scalar: u32 = 0; scalar != 128; scalar++) {
        if blocked[scalar] != 0 {
            if first < scalar {
                var last = scalar -1;
                var rule = grammar_builder_rule(builder, name, false);
                grammar_builder_range(builder, rule, first, last);
            }
            first = scalar + 1;
        }
    }
    var rule = grammar_builder_rule(builder, name, false);
    grammar_builder_range(builder, rule, first, 1114111);
}

export fn regex_grammar_create(kinds: FrontendKinds*): void* {
    var storage: GrammarBuilder;
    var builder = &storage;
    grammar_builder_init(builder, kinds);
    regex_reference(builder, "Regex", "RegexChoice");

    var rule = grammar_builder_rule(builder, "RegexChoice", false);
    grammar_builder_reference(builder, rule, "RegexChoice", "left");
    grammar_builder_literal(builder, rule, "|");
    grammar_builder_reference(builder, rule, "RegexSequence", "right");
    regex_reference(builder, "RegexChoice", "RegexSequence");

    rule = grammar_builder_rule(builder, "RegexSequence", false);
    grammar_builder_reference(builder, rule, "RegexSequence", "left");
    grammar_builder_reference(builder, rule, "RegexRepeat", "right");
    grammar_builder_rule(builder, "RegexSequence", false);

    rule = grammar_builder_rule(builder, "RegexRepeat", false);
    grammar_builder_reference(builder, rule, "RegexAtom", "atom");
    grammar_builder_reference(builder, rule, "RegexSuffix", "suffix");
    regex_symbols(builder, "RegexSuffix", "*+?");
    grammar_builder_rule(builder, "RegexSuffix", false);

    rule = grammar_builder_rule(builder, "RegexAtom", false);
    grammar_builder_literal(builder, rule, "(");
    grammar_builder_reference(builder, rule, "RegexChoice", "group");
    grammar_builder_literal(builder, rule, ")");
    regex_reference(builder, "RegexAtom", "RegexClass");
    regex_reference(builder, "RegexAtom", "RegexCharacter");
    rule = grammar_builder_rule(builder, "RegexAtom", false);
    grammar_builder_literal(builder, rule, ".");

    // Class dashes remain character entries. Range grouping is a semantic step;
    // escaped dashes and leading/trailing dashes keep their literal meanings.
    rule = grammar_builder_rule(builder, "RegexClass", false);
    grammar_builder_literal(builder, rule, "[");
    grammar_builder_literal(builder, rule, "^");
    grammar_builder_reference(builder, rule, "RegexClassCharacters", "negated");
    grammar_builder_literal(builder, rule, "]");
    rule = grammar_builder_rule(builder, "RegexClass", false);
    grammar_builder_literal(builder, rule, "[");
    grammar_builder_reference(builder, rule, "RegexClassBody", "body");
    grammar_builder_literal(builder, rule, "]");
    rule = grammar_builder_rule(builder, "RegexClassBody", false);
    grammar_builder_reference(builder, rule, "RegexClassFirst", "first");
    grammar_builder_reference(builder, rule, "RegexClassCharacters", "rest");
    grammar_builder_rule(builder, "RegexClassBody", false);
    rule = grammar_builder_rule(builder, "RegexClassCharacters", false);
    grammar_builder_reference(builder, rule, "RegexClassCharacters", "left");
    grammar_builder_reference(builder, rule, "RegexClassCharacter", "right");
    grammar_builder_rule(builder, "RegexClassCharacters", false);
    regex_reference(builder, "RegexClassFirst", "RegexClassInitial");
    regex_reference(builder, "RegexClassFirst", "RegexEscape");
    regex_reference(builder, "RegexClassCharacter", "RegexClassPlain");
    regex_reference(builder, "RegexClassCharacter", "RegexEscape");
    regex_characters(builder, "RegexClassInitial", "^]\\");
    regex_characters(builder, "RegexClassPlain", "]\\");

    regex_reference(builder, "RegexCharacter", "RegexPlain");
    regex_reference(builder, "RegexCharacter", "RegexEscape");
    regex_characters(builder, "RegexPlain", "\\[()|.*+?^${}");
    rule = grammar_builder_rule(builder, "RegexEscape", false);
    grammar_builder_literal(builder, rule, "\\");
    grammar_builder_reference(builder, rule, "RegexEscapedSymbol", "symbol");
    regex_symbols(builder, "RegexEscapedSymbol", "nrt\\/[]()|*+?.^-{}$\"'");
    rule = grammar_builder_rule(builder, "RegexEscape", false);
    grammar_builder_literal(builder, rule, "\\x");
    grammar_builder_reference(builder, rule, "RegexHexDigit", "first");
    grammar_builder_reference(builder, rule, "RegexHexDigit", "second");
    rule = grammar_builder_rule(builder, "RegexEscape", false);
    grammar_builder_literal(builder, rule, "\\u{");
    grammar_builder_reference(builder, rule, "RegexHexDigits", "digits");
    grammar_builder_literal(builder, rule, "}");
    regex_reference(builder, "RegexHexDigits", "RegexHexDigit");
    rule = grammar_builder_rule(builder, "RegexHexDigits", false);
    grammar_builder_reference(builder, rule, "RegexHexDigits", "left");
    grammar_builder_reference(builder, rule, "RegexHexDigit", "right");
    rule = grammar_builder_rule(builder, "RegexHexDigit", false);
    grammar_builder_range(builder, rule, 48, 57);
    rule = grammar_builder_rule(builder, "RegexHexDigit", false);
    grammar_builder_range(builder, rule, 65, 70);
    rule = grammar_builder_rule(builder, "RegexHexDigit", false);
    grammar_builder_range(builder, rule, 97, 102);
    return grammar_builder_finish(builder);
}

import tower;
import automaton;
import parser_nodes;
import parser_types;
import syntax_types;
import .library.vector;

// Read the ordinary parser entities and lower their regex semantics into a
// disposable automaton. Work stacks hold borrowed entities, never another AST.
extern fn entity_component_get(node: void*, kind: void*): void*;

extern fn entity_component_data(component: void*): void*;

extern fn entity_member_index(node: void*, name: u8*): usize;

extern fn entity_child_at(node: void*, index: usize): void*;

extern fn entity_child_count(node: void*): usize;

struct RegexPatch {
    state: i32;
    other: bool;
    next: usize;
}

struct RegexFragment {
    start: i32;
    first: usize;
    last: usize;
}

struct RegexVisit {
    node: void*;
    depth: usize;
    finish: bool;
}

struct RegexLowering {
    source: u8*;
    match_type: void*;
    automaton: Automaton*;
    error: u8*;
    cursor: usize;
    visits: vector(RegexVisit);
    values: vector(RegexFragment);
    patches: vector(RegexPatch);
    pending: vector(void*);
    characters: vector(void*);
}

fn regex_none(): usize {
    var value: usize = 0;
    value--;
    return value;
}

fn regex_match(context: RegexLowering*, node: void*): ParserMatchData* {
    var component = entity_component_get(node, context.match_type);
    var data = entity_component_data(component);
    return bits(ParserMatchData*, data);
}

fn regex_member(node: void*, name: u8*): void* {
    var index = entity_member_index(node, name);
    return entity_child_at(node, index);
}

fn regex_named(context: RegexLowering*, node: void*, name: u8*): bool {
    if node == null {
        return false;
    }
    var `match` = regex_match(context, node);
    var label = node_text_get(&`match`.label);
    var i: usize = 0;
    loop {
        if label[i] != name[i] {
            return false;
        }
        if label[i] == 0 {
            return true;
        }
        i++;
    }
}

fn regex_fail(context: RegexLowering*, message: u8*): void {
    if context.error == null {
        context.error = message;
    }
}

fn regex_allocation(context: RegexLowering*, ok: bool): void {
    if !ok {
        regex_fail(context, "Unable to allocate regex lowering work");
    }
}

fn regex_empty(fragment: RegexFragment*): void {
    fragment.start = -1;
    fragment.first = regex_none();
    fragment.last = regex_none();
}

fn regex_visit(context: RegexLowering*, node: void*, depth: usize, finish: bool): void {
    var count = context.visits.length + 1;
    var ok = vector_reserve(RegexVisit, &context.visits, count);
    regex_allocation(context, ok);
    if ok {
        var visit = &context.visits.data[context.visits.length];
        visit.node = node;
        visit.depth = depth;
        visit.finish = finish;
        context.visits.length = count;
    }
}

fn regex_push(context: RegexLowering*, fragment: RegexFragment*): void {
    var count = context.values.length + 1;
    var ok = vector_reserve(RegexFragment, &context.values, count);
    regex_allocation(context, ok);
    if ok {
        copy(&context.values.data[context.values.length], fragment, sizeof(RegexFragment));
        context.values.length = count;
    }
}

fn regex_pop(context: RegexLowering*, fragment: RegexFragment*): void {
    context.values.length--;
    copy(fragment, &context.values.data[context.values.length], sizeof(RegexFragment));
}

fn regex_end(context: RegexLowering*, fragment: RegexFragment*, state: i32, other: bool): void {
    var index = context.patches.length;
    var count = index + 1;
    var ok = vector_reserve(RegexPatch, &context.patches, count);
    regex_allocation(context, ok);
    if ok {
        var end = &context.patches.data[index];
        end.state = state;
        end.other = other;
        end.next = regex_none();
        if fragment.first == regex_none() {
            fragment.first = index;
        }
        else {
            context.patches.data[fragment.last].next = index;
        }
        fragment.last = index;
        context.patches.length = count;
    }
}

fn regex_join(context: RegexLowering*, left: RegexFragment*, right: RegexFragment*): void {
    var empty = right.first == regex_none();
    if empty {
        return;
    }
    empty = left.first == regex_none();
    if empty {
        left.first = right.first;
    }
    else {
        context.patches.data[left.last].next = right.first;
    }
    left.last = right.last;
}

fn regex_patch(context: RegexLowering*, fragment: RegexFragment*, target: i32): void {
    var index = fragment.first;
    loop {
        if index == regex_none() {
            return;
        }
        var patch = &context.patches.data[index];
        automaton_patch(context.automaton, patch.state, patch.other, target);
        index = patch.next;
    }
}

fn regex_state(context: RegexLowering*, kind: u32, out: i32, other: i32, negated: bool): i32 {
    var index = automaton_add(context.automaton, kind, out, other, negated);
    if index < 0 {
        regex_fail(context, "Token pattern exceeds 512 NFA states");
    }
    return index;
}

fn regex_range(context: RegexLowering*, index: i32, first: u32, last: u32): void {
    var ok = automaton_range(context.automaton, index, first, last);
    regex_allocation(context, ok);
}

fn regex_scalar(context: RegexLowering*, node: void*): u32 {
    var `match` = regex_match(context, node);
    context.cursor = `match`.start;
    var text = context.source + `match`.start;
    if !(text[0] == 92) {
        var result: u32;
        tower_utf8_decode(text, `match`.length, &result);
        return result;
    }
    var escape = text[1];
    var selected = escape == 110;
    if selected {
        return 10;
    }
    selected = escape == 114;
    if selected {
        return 13;
    }
    selected = escape == 116;
    if selected {
        return 9;
    }
    var unicode = escape == 117;
    var hex = escape == 120;
    if !unicode {
        if !hex {
            return convert(u32, escape);
        }
    }
    var first: usize = 2;
    var end = `match`.length;
    if unicode {
        first = 3;
        end--;
    }
    var count = end -first;
    var invalid = count == 0;
    if invalid {
        regex_fail(context, "Invalid Unicode scalar escape");
        return 0;
    }
    invalid = count > 6;
    if invalid {
        regex_fail(context, "Invalid Unicode scalar escape");
        return 0;
    }
    var value: u32 = 0;
    for(; first != end; first++) {
        var digit = convert(u32, text[first]);
        if digit <= 57 {
            digit = digit - 48;
        }
        else {
            if digit <= 70 {
                digit = digit - 55;
            }
            else {
                digit = digit - 87;
            }
        }
        value = value * 16;
        value = value + digit;
    }
    invalid = value > 1114111;
    if invalid {
        regex_fail(context, "Invalid Unicode scalar escape");
    }
    var surrogate = value >= 55296;
    if surrogate {
        surrogate = value <= 57343;
        if surrogate {
            regex_fail(context, "Invalid Unicode scalar escape");
        }
    }
    return value;
}

fn regex_class(context: RegexLowering*, node: void*, index: i32, negated: void*): void {
    context.pending.length = 0;
    context.characters.length = 0;
    var body = negated;
    if body == null {
        body = regex_member(node, "body");
    }
    var ok = vector_push(void*, &context.pending, body);
    regex_allocation(context, ok);
    loop {
        if context.error != null {
            return;
        }
        var done = context.pending.length == 0;
        if done {
            break;
        }
        context.pending.length--;
        var at = context.pending.data[context.pending.length];
        var character = regex_named(context, at, "RegexClassFirst");
        character ||= regex_named(context, at, "RegexClassCharacter");
        if character {
            ok = vector_push(void*, &context.characters, at);
            regex_allocation(context, ok);
        } else {
            var children = entity_child_count(at);
            loop {
                done = children == 0;
                if done {
                    break;
                }
                children--;
                var child = entity_child_at(at, children);
                ok = vector_push(void*, &context.pending, child);
                regex_allocation(context, ok);
            }
        }
    }
    if context.characters.length == 0 {
        regex_fail(context, "Empty character class");
        return;
    }
    var i: usize = 0;
    loop {
        var done = i == context.characters.length;
        if done {
            return;
        }
        var first = regex_scalar(context, context.characters.data[i]);
        var last = first;
        i++;
        var after = i + 1;
        if after < context.characters.length {
            var dash = regex_match(context, context.characters.data[i]);
            var plain = dash.length == 1;
            if plain {
                plain = context.source[dash.start] == 45;
                if plain {
                    i++;
                    last = regex_scalar(context, context.characters.data[i]);
                    i++;
                    if last < first {
                        regex_fail(context, "Reversed character range");
                    }
                }
            }
        }
        regex_range(context, index, first, last);
    }
}

fn regex_atom(context: RegexLowering*, node: void*, result: RegexFragment*): void {
    var character_class = regex_named(context, node, "RegexClass");
    var dot = regex_named(context, node, "RegexAtom");
    var negated: void* = null;
    var complement = dot;
    if character_class {
        negated = regex_member(node, "negated");
        complement = negated != null;
    }
    var index = regex_state(context, 0, -1, -1, complement);
    if character_class {
        regex_class(context, node, index, negated);
    }
    else {
        if dot {
            regex_range(context, index, 10, 10);
            regex_range(context, index, 13, 13);
        } else {
            var value = regex_scalar(context, node);
            regex_range(context, index, value, value);
        }
    }
    result.start = index;
    regex_end(context, result, index, false);
}

fn regex_lower(context: RegexLowering*, root: void*, output: RegexFragment*): void {
    regex_visit(context, root, 0, false);
    loop {
        if context.error != null {
            return;
        }
        if context.visits.length == 0 {
            regex_pop(context, output);
            return;
        }
        context.visits.length--;
        var visit = &context.visits.data[context.visits.length];
        // Copy before pushing: growth can move the visit vector.
        var node = visit.node;
        var depth = visit.depth;
        var finish = visit.finish;
        var `match` = regex_match(context, node);
        context.cursor = `match`.start;
        if depth > 64 {
            regex_fail(context, "Token pattern nesting exceeds 64");
            return;
        }
        var top = regex_named(context, node, "Regex");
        var choice = regex_named(context, node, "RegexChoice");
        var sequence = regex_named(context, node, "RegexSequence");
        var repeat = regex_named(context, node, "RegexRepeat");
        var left = regex_member(node, "left");
        var group = regex_member(node, "group");
        var paired = left != null;
        var grouped = group != null;
        if !finish {
            regex_visit(context, node, depth, true);
            if top {
                regex_visit(context, regex_member(node, "value"), depth, false);
            }
            else {
                if choice {
                    if paired {
                        regex_visit(context, regex_member(node, "right"), depth, false);
                        regex_visit(context, left, depth, false);
                    } else {
                        regex_visit(context, regex_member(node, "value"), depth, false);
                    }
                } else {
                    if sequence {
                        if paired {
                            regex_visit(context, regex_member(node, "right"), depth, false);
                            regex_visit(context, left, depth, false);
                        }
                    } else {
                        if repeat {
                            regex_visit(context, regex_member(node, "atom"), depth, false);
                        }
                        else {
                            if grouped {
                                var deeper = depth + 1;
                                regex_visit(context, group, deeper, false);
                            }
                        }
                    }
                }
            }
            continue;
        }
        var result: RegexFragment;
        regex_empty(&result);
        if top {
            regex_pop(context, &result);
        }
        else {
            if choice {
                if paired {
                    var right: RegexFragment;
                    regex_pop(context, &right);
                    regex_pop(context, &result);
                    var empty_left = result.start < 0;
                    var empty_right = right.start < 0;
                    result.start = regex_state(context, 1, result.start, right.start, false);
                    regex_join(context, &result, &right);
                    if empty_left {
                        regex_end(context, &result, result.start, false);
                    }
                    if empty_right {
                        regex_end(context, &result, result.start, true);
                    }
                } else {
                    regex_pop(context, &result);
                }
            } else {
                if sequence {
                    if paired {
                        var right: RegexFragment;
                        regex_pop(context, &right);
                        regex_pop(context, &result);
                        var empty_left = result.start < 0;
                        var empty_right = right.start < 0;
                        if empty_left {
                            copy(&result, &right, sizeof(RegexFragment));
                        }
                        else {
                            if !empty_right {
                                regex_patch(context, &result, right.start);
                                result.first = right.first;
                                result.last = right.last;
                            }
                        }
                    }
                } else {
                    if repeat {
                        regex_pop(context, &result);
                        var suffix = regex_match(context, regex_member(node, "suffix"));
                        var nonempty = result.start >= 0;
                        var suffixed = suffix.length != 0;
                        if nonempty {
                            if suffixed {
                                var operation = context.source[suffix.start];
                                var split = regex_state(context, 1, result.start, -1, false);
                                if operation == 63 {
                                    regex_end(context, &result, split, true);
                                }
                                else {
                                    regex_patch(context, &result, split);
                                    result.first = regex_none();
                                    result.last = regex_none();
                                    regex_end(context, &result, split, true);
                                }
                                if !(operation == 43) {
                                    result.start = split;
                                }
                            }
                        }
                    } else {
                        if grouped {
                            regex_pop(context, &result);
                        }
                        else {
                            var value = regex_member(node, "value");
                            if value == null {
                                value = node;
                            }
                            regex_atom(context, value, &result);
                        }
                    }
                }
            }
        }
        regex_push(context, &result);
    }
}

export fn regex_compile_tree(root: void*, source: u8*, match_type: void*, table: LexerTable*, error_offset: usize*): u8* {
    var context = alloc(RegexLowering, 1);
    var failed = context == null;
    if failed {
        return "Unable to allocate regex lowering work";
    }
    defer free(context);
    fill(context, 0, sizeof(RegexLowering));
    context.source = source;
    context.match_type = match_type;
    context.automaton = automaton_create(1114112);
    failed = context.automaton == null;
    if failed {
        return "Unable to allocate token automaton";
    }
    var result: RegexFragment;
    regex_lower(context, root, &result);
    var ok = context.error == null;
    if ok {
        if result.start < 0 {
            regex_fail(context, "Token pattern must not match empty input");
        }
        else {
            var accept = regex_state(context, 2, -1, -1, false);
            regex_patch(context, &result, accept);
            ok = context.error == null;
            var valid_accept = accept >= 0;
            if !valid_accept {
                ok = false;
            }
            if ok {
                // The explicit branch bounds the checked signed conversion.
                if valid_accept {
                    var accepting = convert(usize, accept);
                    var status = automaton_compile(context.automaton, result.start, accepting, table, true);
                    var too_large = status == 3;
                    var nullable = status == 4;
                    var failure = status != 0;
                    if too_large {
                        regex_fail(context, "Token pattern exceeds DFA complexity limit");
                    }
                    else {
                        if nullable {
                            regex_fail(context, "Token pattern must not match empty input");
                        }
                        else {
                            if failure {
                                regex_fail(context, "Unable to allocate token automaton");
                            }
                        }
                    }
                }
            }
        }
    }
    *error_offset = context.cursor;
    var error = context.error;
    vector_dispose(RegexVisit, &context.visits);
    vector_dispose(RegexFragment, &context.values);
    vector_dispose(RegexPatch, &context.patches);
    vector_dispose(void*, &context.pending);
    vector_dispose(void*, &context.characters);
    automaton_destroy(context.automaton);
    return error;
}

import tower;
import frontend_compilation;
import foundation_types;
import foundation_tags;
import semantic_context;
import semantic_definitions;
import semantic_support;
import .library.vector;
import c_emitter;
import roku_runtime;

// Reuse the source emitters' disposable entity/owner index and text writer.
// Foundation nodes remain authoritative; no bytecode or alternate IR is read.
struct RokuEmitter {
    common: CEmitter;
    loop_id: usize;
    labels: usize;
    conditions: usize;
}

fn re_text(r: RokuEmitter*, text: u8*): void {
    ce_text(&r.common, text);
}

fn re_number(r: RokuEmitter*, n: usize): void {
    ce_number(&r.common, convert(u64, n));
}

fn re_fail(r: RokuEmitter*, message: u8*): void {
    ce_fail(&r.common, message);
}

fn re_id(r: RokuEmitter*, entity: void*): usize {
    return ce_id(&r.common, entity);
}

fn re_temp(r: RokuEmitter*, entity: void*): void {
    re_text(r, "t[");
    re_number(r, re_id(r, entity));
    re_text(r, "]");
}

fn re_slot(r: RokuEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.global {
        re_text(r, "s.g[");
    }
    else {
        re_text(r, "v[");
    }
    re_number(r, re_id(r, entity));
    re_text(r, "]");
}

fn re_width(r: RokuEmitter*, t: FoundationType*): void {
    var boolean = t.scalar == SBool();
    if t.pointers != 0 {
        boolean = false;
    }
    if boolean {
        re_text(r, "1");
        return;
    }
    re_number(r, convert(usize, semantic_width(t)));
}

fn re_signed(r: RokuEmitter*, t: FoundationType*): void {
    if semantic_signed(t) {
        re_text(r, "true");
    }
    else {
        re_text(r, "false");
    }
}

fn re_hex(r: RokuEmitter*, bits: u64): void {
    var digits: u8[16];
    var at: usize = 16;
    var alphabet = "0123456789abcdef";
    loop {
        at--;
        var c_step1 = bits % 16;
        var digit = convert(usize, c_step1);
        digits[at] = alphabet[digit];
        bits = bits / 16;
        if at == 0 {
            break;
        }
    }
    re_text(r, "&h");
    sem_require(bytes_append(r.common.text, &digits[0], 16));
    re_text(r, "&");
}

fn re_comments(r: RokuEmitter*, n: FoundationNode*): void {
    if !r.common.comments {
        return;
    }
    if n.comments.length == 0 {
        return;
    }
    re_text(r, "' ");
    var i: usize = 0;
    loop {
        if i == n.comments.length {
            break;
        }
        var b = n.comments.data[i];
        // Every physical line is a comment, including CR-only metadata.
        if b == 13 {
            b = 10;
        }
        sem_require(vector_push(u8, r.common.text, b));
        if b == 10 {
            re_text(r, "' ");
        }
        i++;
    }
    re_text(r, "\n");
}

fn re_prepare_address(r: RokuEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.kind == KLoad() {
        re_prepare(r, n.value);
        return;
    }
    var place = n.kind == KField();
    if n.kind == KIndex() {
        place = true;
    }
    if place {
        if n.indirect {
            re_prepare(r, n.left);
        }
        else {
            re_prepare_address(r, n.left);
        }
        if n.kind == KIndex() {
            re_prepare(r, n.right);
        }
    }
}

fn re_address(r: RokuEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.kind == KLoad() {
        re_temp(r, n.value);
        return;
    }
    var place = n.kind == KField();
    if n.kind == KIndex() {
        place = true;
    }
    if place {
        re_text(r, "tr_offset(");
        if n.indirect {
            re_temp(r, n.left);
        }
        else {
            re_address(r, n.left);
        }
        re_text(r, ", ");
        if n.kind == KIndex() {
            re_temp(r, n.right);
            re_text(r, ", ");
            re_number(r, semantic_size(&n.type));
        }
        else {
            re_number(r, n.byte_offset);
            re_text(r, ", 1");
        }
        re_text(r, ")");
        return;
    }
    var binding = n.binding;
    if binding == null {
        binding = entity;
    }
    re_slot(r, binding);
}

fn re_function(r: RokuEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.external {
        if sem_equal(sem_name(n), "platform_write") {
            var valid = n.parameters.length == 3;
            if valid {
                var stream = sem_get(n.parameters.data[0]);
                var data = sem_get(n.parameters.data[1]);
                var length = sem_get(n.parameters.data[2]);
                var wrong = stream.type.scalar != SU32();
                if wrong {
                    valid = false;
                }
                wrong = stream.type.pointers != 0;
                if wrong {
                    valid = false;
                }
                wrong = data.type.scalar != SU8();
                if wrong {
                    valid = false;
                }
                wrong = data.type.pointers != 1;
                if wrong {
                    valid = false;
                }
                wrong = length.type.scalar != SUSize();
                if wrong {
                    valid = false;
                }
                wrong = length.type.pointers != 0;
                if wrong {
                    valid = false;
                }
                wrong = n.type.scalar != SI64();
                if wrong {
                    valid = false;
                }
                wrong = n.type.pointers != 0;
                if wrong {
                    valid = false;
                }
            }
            if !valid {
                re_fail(r, "Roku platform_write requires (u32, u8*, usize): i64");
            }
            re_text(r, "tr_write");
            return;
        }
        re_fail(r, "Roku target supports only the platform_write foreign function; provide a Tower implementation");
    }
    re_text(r, "tr_fn_");
    re_number(r, re_id(r, entity));
}

fn re_expression(r: RokuEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.kind == KOperand() {
        if n.constant {
            var c_step15 = n.bits &semantic_mask(&n.type);
            re_hex(r, c_step15);
        }
        else {
            re_text(r, "tr_load(s, ");
            re_slot(r, n.binding);
            re_text(r, ", ");
            re_number(r, semantic_size(&n.type));
            re_text(r, ")");
        }
        return;
    }
    if n.kind == KString() {
        re_text(r, "s.g[");
        re_number(r, re_id(r, entity));
        re_text(r, "]");
        return;
    }
    if n.kind == KAddress() {
        re_address(r, n.value);
        return;
    }
    var load = n.kind == KLoad();
    if n.kind == KField() {
        load = true;
    }
    if n.kind == KIndex() {
        load = true;
    }
    if load {
        re_text(r, "tr_load(s, ");
        re_address(r, entity);
        re_text(r, ", ");
        re_number(r, semantic_size(&n.type));
        re_text(r, ")");
        return;
    }
    if n.kind == KCall() {
        re_function(r, n.binding);
        re_text(r, "(s, [");
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            if i != 0 {
                re_text(r, ", ");
            }
            re_temp(r, n.items.data[i]);
            i++;
        }
        re_text(r, "])");
        return;
    }
    if n.kind == KSizeOf() {
        re_number(r, semantic_size(&n.element));
        re_text(r, "&");
        return;
    }
    if n.kind == KAlignOf() {
        re_number(r, semantic_alignment(&n.element));
        re_text(r, "&");
        return;
    }
    if n.kind == KAllocate() {
        re_text(r, "tr_alloc(s, tr_count(");
        re_temp(r, n.right);
        re_text(r, ", ");
        re_number(r, semantic_size(&n.element));
        re_text(r, "))");
        return;
    }
    if n.kind == KReallocate() {
        re_text(r, "tr_realloc(s, ");
        re_temp(r, n.left);
        re_text(r, ", tr_count(");
        re_temp(r, n.right);
        re_text(r, ", ");
        re_number(r, semantic_size(&n.element));
        re_text(r, "))");
        return;
    }
    var conversion = n.kind == KConvert();
    if n.kind == KBits() {
        conversion = true;
    }
    if conversion {
        var from = sem_get(n.value);
        re_text(r, "tr_convert(");
        re_temp(r, n.value);
        re_text(r, ", ");
        re_width(r, &from.type);
        re_text(r, ", ");
        re_signed(r, &from.type);
        re_text(r, ", ");
        re_width(r, &n.type);
        re_text(r, ", ");
        re_signed(r, &n.type);
        re_text(r, ", ");
        if n.kind == KConvert() {
            re_text(r, "true");
        }
        else {
            re_text(r, "false");
        }
        re_text(r, ")");
        return;
    }
    if n.kind == KBinary() {
        var from = sem_get(n.left);
        var pointer_math = from.type.pointers != 0;
        if n.op > OSub() {
            pointer_math = false;
        }
        if pointer_math {
            var element: FoundationType;
            copy(&element, &from.type, sizeof(FoundationType));
            element.pointers--;
            re_text(r, "tr_offset(");
            re_temp(r, n.left);
            re_text(r, ", ");
            if n.op == OSub() {
                re_text(r, "tr_neg(");
            }
            re_temp(r, n.right);
            if n.op == OSub() {
                re_text(r, ")");
            }
            re_text(r, ", ");
            re_number(r, semantic_size(&element));
            re_text(r, ")");
            return;
        }
        // The emitter selects a helper from the shared operation definition.
        // There is no serialized instruction dispatch table or public opcode ABI.
        if n.op == OAdd() {
            re_text(r, "tr_add(");
        }
        if n.op == OSub() {
            re_text(r, "tr_sub(");
        }
        if n.op == OMul() {
            re_text(r, "tr_mul(");
        }
        if n.op == ODiv() {
            re_text(r, "tr_div(");
        }
        if n.op == ORem() {
            re_text(r, "tr_rem(");
        }
        if n.op == OAnd() {
            re_text(r, "tr_and(");
        }
        if n.op == OOr() {
            re_text(r, "tr_or(");
        }
        if n.op == OXor() {
            re_text(r, "tr_xor(");
        }
        if n.op >= OEq() {
            re_text(r, "tr_bool(tr_compare(");
        }
        re_temp(r, n.left);
        re_text(r, ", ");
        re_temp(r, n.right);
        re_text(r, ", ");
        re_width(r, &from.type);
        re_text(r, ", ");
        re_signed(r, &from.type);
        re_text(r, ")");
        if n.op >= OEq() {
            if n.op == OEq() {
                re_text(r, " = 0)");
            }
            if n.op == ONe() {
                re_text(r, " <> 0)");
            }
            if n.op == OLt() {
                re_text(r, " < 0)");
            }
            if n.op == OLe() {
                re_text(r, " <= 0)");
            }
            if n.op == OGt() {
                re_text(r, " > 0)");
            }
            if n.op == OGe() {
                re_text(r, " >= 0)");
            }
        }
        return;
    }
    re_fail(r, "Unsupported Foundation value in Roku emitter");
}

fn re_prepare(r: RokuEmitter*, entity: void*): void {
    if entity == null {
        return;
    }
    var n = sem_get(entity);
    if n.kind == KAddress() {
        re_prepare_address(r, n.value);
    }
    else {
        var place = n.kind == KField();
        if n.kind == KIndex() {
            place = true;
        }
        if n.kind == KLoad() {
            place = true;
        }
        if place {
            re_prepare_address(r, entity);
        }
        else {
            re_prepare(r, n.left);
            re_prepare(r, n.right);
            re_prepare(r, n.value);
            var i: usize = 0;
            loop {
                if i == n.items.length {
                    break;
                }
                re_prepare(r, n.items.data[i]);
                i++;
            }
        }
    }
    re_text(r, "    ");
    if ce_value_kind(n) {
        re_temp(r, entity);
        re_text(r, " = ");
    }
    re_expression(r, entity);
    re_text(r, "\n");
}

fn re_store(r: RokuEmitter*, target: void*, value: void*): void {
    var n = sem_get(target);
    re_text(r, "    tr_store(s, ");
    re_address(r, target);
    re_text(r, ", ");
    re_temp(r, value);
    re_text(r, ", ");
    re_number(r, semantic_size(&n.type));
    re_text(r, ")\n");
}

fn re_statement(r: RokuEmitter*, entity: void*): void {
    if entity == null {
        return;
    }
    var n = sem_get(entity);
    if n.kind == KFunction() {
        return;
    }
    re_comments(r, n);
    if n.kind == KType() {
        return;
    }
    var list = n.kind == KProgram();
    if n.kind == KBlock() {
        list = true;
    }
    if list {
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            re_statement(r, n.items.data[i]);
            i++;
        }
        return;
    }
    if n.kind == KDeclare() {
        if n.value != null {
            re_prepare(r, n.value);
            re_store(r, entity, n.value);
        }
        else {
            re_text(r, "    tr_fill(s, ");
            re_slot(r, entity);
            re_text(r, ", 0, ");
            re_number(r, semantic_size(&n.type));
            re_text(r, ")\n");
        }
        return;
    }
    if n.kind == KAssign() {
        re_prepare_address(r, n.target);
        re_prepare(r, n.value);
        re_store(r, n.target, n.value);
        return;
    }
    if n.kind == KIf() {
        r.conditions++;
        re_prepare(r, n.value);
        re_text(r, "    if ");
        re_temp(r, n.value);
        re_text(r, " <> 0 then\n");
        re_statement(r, n.body);
        if n.otherwise != null {
            re_text(r, "    else\n");
            re_statement(r, n.otherwise);
        }
        re_text(r, "    end if\n");
        return;
    }
    if n.kind == KLoop() {
        var parent = r.loop_id;
        r.loop_id = re_id(r, entity);
        r.labels = r.labels + 2;
        re_text(r, "tr_loop_");
        re_number(r, r.loop_id);
        re_text(r, ":\n");
        re_statement(r, n.body);
        re_text(r, "    goto tr_loop_");
        re_number(r, r.loop_id);
        re_text(r, "\ntr_break_");
        re_number(r, r.loop_id);
        re_text(r, ":\n");
        r.loop_id = parent;
        return;
    }
    if n.kind == KBreak() {
        re_text(r, "    goto tr_break_");
        re_number(r, r.loop_id);
        re_text(r, "\n");
        return;
    }
    if n.kind == KContinue() {
        re_text(r, "    goto tr_loop_");
        re_number(r, r.loop_id);
        re_text(r, "\n");
        return;
    }
    if n.kind == KReturn() {
        re_prepare(r, n.value);
        re_text(r, "    tr_free(s, frame)\n    return ");
        if n.value != null {
            re_temp(r, n.value);
        }
        else {
            re_text(r, "invalid");
        }
        re_text(r, "\n");
        return;
    }
    if n.kind == KLabel() {
        r.labels++;
        re_text(r, "tr_label_");
        re_number(r, re_id(r, entity));
        re_text(r, ":\n");
        return;
    }
    if n.kind == KJump() {
        re_text(r, "    goto tr_label_");
        re_number(r, re_id(r, n.binding));
        re_text(r, "\n");
        return;
    }
    if n.kind == KPrint() {
        re_prepare(r, n.value);
        var value = sem_get(n.value);
        re_text(r, "    tr_print(s, ");
        re_temp(r, n.value);
        re_text(r, ", ");
        re_width(r, &value.type);
        re_text(r, ", ");
        re_signed(r, &value.type);
        re_text(r, ", ");
        if value.type.pointers != 0 {
            re_text(r, "true");
        }
        else {
            re_text(r, "false");
        }
        re_text(r, ")\n");
        return;
    }
    if n.kind == KFree() {
        re_prepare(r, n.left);
        re_text(r, "    tr_free(s, ");
        re_temp(r, n.left);
        re_text(r, ")\n");
        return;
    }
    var memory = n.kind == KCopy();
    if n.kind == KFill() {
        memory = true;
    }
    if memory {
        re_prepare(r, n.left);
        re_prepare(r, n.right);
        re_prepare(r, n.value);
        if n.kind == KCopy() {
            re_text(r, "    tr_copy(s, ");
        }
        else {
            re_text(r, "    tr_fill(s, ");
        }
        re_temp(r, n.left);
        re_text(r, ", ");
        re_temp(r, n.right);
        re_text(r, ", ");
        re_temp(r, n.value);
        re_text(r, ")\n");
        return;
    }
    if n.kind == KTrap() {
        re_prepare(r, n.left);
        re_prepare(r, n.right);
        re_text(r, "    tr_trap(tr_string(s, ");
        re_temp(r, n.left);
        re_text(r, ", ");
        re_temp(r, n.right);
        re_text(r, "))\n");
        return;
    }
    if n.kind == KCall() {
        re_prepare(r, entity);
        return;
    }
    re_fail(r, "Unsupported Foundation statement in Roku emitter");
}

fn re_storage(r: RokuEmitter*, entity: void*, owner: void*, globals: bool): bool {
    var n = sem_get(entity);
    var variable = n.kind == KDeclare();
    if n.kind == KParameter() {
        variable = true;
    }
    if globals {
        if variable {
            return n.global;
        }
        return false;
    }
    if n.global {
        return false;
    }
    var id = re_id(r, entity);
    var same = r.common.owners.data[id] == owner;
    if variable {
        return same;
    }
    return false;
}

fn re_body(r: RokuEmitter*, entity: void*, program: bool): void {
    r.labels = 0;
    r.conditions = 0;
    var i: usize = 0;
    var size: usize = 0;
    loop {
        if i == r.common.nodes.length {
            break;
        }
        var item = r.common.nodes.data[i];
        var n = sem_get(item);
        if re_storage(r, item, entity, false) {
            var c_step82 = size + semantic_size(&n.type);
            size = c_step82 + 7;
            var c_step83 = size / 8;
            size = c_step83 * 8;
        }
        i++;
    }
    re_text(r, "    t = []\n    v = []\n    frame = tr_alloc(s, ");
    re_number(r, size);
    re_text(r, ")\n");
    i = 0;
    size = 0;
    loop {
        if i == r.common.nodes.length {
            break;
        }
        var item = r.common.nodes.data[i];
        var n = sem_get(item);
        if re_storage(r, item, entity, false) {
            re_text(r, "    ");
            re_slot(r, item);
            re_text(r, " = frame + ");
            re_number(r, size);
            re_text(r, "&\n");
            var c_step85 = size + semantic_size(&n.type);
            size = c_step85 + 7;
            var c_step86 = size / 8;
            size = c_step86 * 8;
        }
        i++;
    }
    var n = sem_get(entity);
    i = 0;
    loop {
        if i == n.parameters.length {
            break;
        }
        var item = n.parameters.data[i];
        var param = sem_get(item);
        re_text(r, "    tr_store(s, ");
        re_slot(r, item);
        re_text(r, ", args[");
        re_number(r, i);
        re_text(r, "], ");
        re_number(r, semantic_size(&param.type));
        re_text(r, ")\n");
        i++;
    }
    if program {
        re_statement(r, entity);
    }
    else {
        re_statement(r, n.body);
    }
    re_text(r, "    tr_free(s, frame)\n    return invalid\nend function\n\n");
    // Conservative limits from wasm2brs device findings. Arrays avoid local and
    // parameter limits; diagnose large control flow instead of emitting bad BRS.
    if r.labels > 240 {
        re_fail(r, "Roku function exceeds the 240-label profile limit; split the function or enable optimization");
    }
    if r.conditions > 200 {
        re_fail(r, "Roku function exceeds the 200-conditional profile limit; split the function or enable optimization");
    }
}

export fn roku_emit(text: vector(u8)*, error: vector(u8)*, root: void*, pointer_bytes: u32, comments: bool): void {
    var r: RokuEmitter;
    fill(&r, 0, sizeof(RokuEmitter));
    r.common.text = text;
    r.common.error = error;
    r.common.comments = comments;
    if pointer_bytes != 4 {
        re_fail(&r, "Roku source requires the explicit 32-bit little endian profile");
        return;
    }
    ce_collect(&r.common, root, root);
    re_text(&r, "' Tower Roku profile 1: 32-bit byte addresses, exact integer arithmetic.\n' Generated platform source; canonical Foundation remains the program format.\n' Call TowerRun() from Main or a SceneGraph Task. Physical-device validation pending.\n\n");
    re_runtime(&r);
    re_text(&r, "function TowerRun(output = invalid as dynamic, memoryLimit = 67108864 as integer) as object\n    s = tr_state(output, memoryLimit)\n");
    var i: usize = 0;
    loop {
        if i == r.common.nodes.length {
            break;
        }
        var item = r.common.nodes.data[i];
        var n = sem_get(item);
        if re_storage(&r, item, root, true) {
            re_text(&r, "    ");
            re_slot(&r, item);
            re_text(&r, " = tr_alloc(s, ");
            re_number(&r, semantic_size(&n.type));
            re_text(&r, ")\n");
        }
        if n.kind == KString() {
            re_text(&r, "    s.g[");
            re_number(&r, i);
            re_text(&r, "] = tr_alloc(s, ");
            var c_step93 = n.name.length + 1;
            re_number(&r, c_step93);
            re_text(&r, ")\n");
            var at: usize = 0;
            loop {
                if at == n.name.length {
                    break;
                }
                re_text(&r, "    tr_store(s, s.g[");
                re_number(&r, i);
                re_text(&r, "] + ");
                re_number(&r, at);
                re_text(&r, ", ");
                re_number(&r, convert(usize, n.name.data[at]));
                re_text(&r, ", 1)\n");
                at++;
            }
        }
        i++;
    }
    re_text(&r, "    tr_entry(s, [])\n    return s\nend function\n\n");
    i = 0;
    loop {
        if i == r.common.nodes.length {
            break;
        }
        var item = r.common.nodes.data[i];
        var n = sem_get(item);
        if n.kind == KFunction() {
            if !n.external {
                re_comments(&r, n);
                re_text(&r, "function ");
                re_function(&r, item);
                re_text(&r, "(s as object, args as object) as dynamic\n");
                re_body(&r, item, false);
            }
        }
        i++;
    }
    re_text(&r, "function tr_entry(s as object, args as object) as dynamic\n");
    re_body(&r, root, true);
    if text.length > 1900000 {
        re_fail(&r, "Roku source exceeds the single-file profile limit (1.9 MB); split the program");
    }
    var lines: usize = 0;
    i = 0;
    loop {
        if i == text.length {
            break;
        }
        if text.data[i] == 10 {
            lines++;
        }
        i++;
    }
    if lines > 60000 {
        re_fail(&r, "Roku source exceeds the 60000-line profile limit; split the program");
    }
    vector_dispose(void*, &r.common.nodes);
    vector_dispose(void*, &r.common.owners);
    vector_dispose(bool, &r.common.active);
    vector_dispose(bool, &r.common.returning);
    if error.length != 0 {
        text.length = 0;
    }
}

import tower;
import roku_emitter;

// Platform runtime text. Full-width integers retain exact bit patterns; masked
// limb extraction uses only exactly representable powers-of-two scaling.
fn re_runtime(r: RokuEmitter*): void {
    re_text(r, "function tr_clz(x as longinteger, width as integer) as longinteger\n");
    re_text(r, "    count = 0&\n");
    re_text(r, "    for i = width - 1 to 0 step -1\n");
    re_text(r, "        digit% = tr_limb(x, i \\ 16)\n");
    re_text(r, "        if (digit% and (1 << (i mod 16))) <> 0 then return count\n");
    re_text(r, "        count = count + 1&\n");
    re_text(r, "    end for\n");
    re_text(r, "    return count\n");
    re_text(r, "end function\n");
    re_text(r, "\n");
    re_text(r, "function tr_ctz(x as longinteger, width as integer) as longinteger\n");
    re_text(r, "    count = 0&\n");
    re_text(r, "    for i = 0 to width - 1\n");
    re_text(r, "        digit% = tr_limb(x, i \\ 16)\n");
    re_text(r, "        if (digit% and (1 << (i mod 16))) <> 0 then return count\n");
    re_text(r, "        count = count + 1&\n");
    re_text(r, "    end for\n");
    re_text(r, "    return count\n");
    re_text(r, "end function\n");
    re_text(r, "\n");
    re_text(r, "function tr_popcnt(x as longinteger, width as integer) as longinteger\n");
    re_text(r, "    count = 0&\n");
    re_text(r, "    for i = 0 to width \\ 16 - 1\n");
    re_text(r, "        digit% = tr_limb(x, i)\n");
    re_text(r, "        while digit% <> 0\n");
    re_text(r, "            digit% = digit% and (digit% - 1)\n");
    re_text(r, "            count = count + 1&\n");
    re_text(r, "        end while\n");
    re_text(r, "    end for\n");
    re_text(r, "    return count\n");
    re_text(r, "end function\n");
    re_text(r, "\n");
    re_text(r, "' Masked powers-of-two scaling of 16 significant bits is exact in Double.\n");
    re_text(r, "' No full-width value is ever converted to floating point.\n");
    re_text(r, "function tr_limb(x as longinteger, index as integer) as longinteger\n");
    re_text(r, "    if index = 0 then return x and &hffff&\n");
    re_text(r, "    if index = 1 then return (x and &hffff0000&) / 65536#\n");
    re_text(r, "    if index = 2 then return (x and &hffff00000000&) / 4294967296#\n");
    re_text(r, "    if index = 3 then\n");
    re_text(r, "        part& = (x and &h7fff000000000000&) / 281474976710656#\n");
    re_text(r, "        if x < 0& then part& = part& + 32768&\n");
    re_text(r, "        return part&\n");
    re_text(r, "    end if\n");
    re_text(r, "    return 0&\n");
    re_text(r, "end function\n");
    re_text(r, "\n");
    re_text(r, "function tr_pack(parts as object) as longinteger\n");
    re_text(r, "    x = parts[0] or (parts[1] * 65536&) or (parts[2] * 4294967296&) or ((parts[3] and 32767&) * 281474976710656&)\n");
    re_text(r, "    if (parts[3] and 32768&) <> 0& then x = x or &h8000000000000000&\n");
    re_text(r, "    return x\n");
    re_text(r, "end function\n");
    re_text(r, "\n");
    re_text(r, "function tr_shr(x as longinteger, count as longinteger) as longinteger\n");
    re_text(r, "    count = count and 63&\n");
    re_text(r, "    words = count \\ 16&\n");
    re_text(r, "    bits = count and 15&\n");
    re_text(r, "    factor& = 1 << bits\n");
    re_text(r, "    parts = []\n");
    re_text(r, "    for i = 0 to 3\n");
    re_text(r, "        part& = tr_limb(x, i + words) \\ factor&\n");
    re_text(r, "        if bits <> 0& then part& = part& + (tr_limb(x, i + words + 1) and (factor& - 1&)) * (65536& \\ factor&)\n");
    re_text(r, "        parts.push(part&)\n");
    re_text(r, "    end for\n");
    re_text(r, "    return tr_pack(parts)\n");
    re_text(r, "end function\n");
    re_text(r, "\n");
    re_text(r, "function tr_shl(x as longinteger, count as longinteger) as longinteger\n");
    re_text(r, "    count = count and 63&\n");
    re_text(r, "    words = count \\ 16&\n");
    re_text(r, "    bits = count and 15&\n");
    re_text(r, "    factor& = 1 << bits\n");
    re_text(r, "    parts = []\n");
    re_text(r, "    for i = 0 to 3\n");
    re_text(r, "        part& = (tr_limb(x, i - words) * factor&) and 65535&\n");
