// Transitional native boundary uses these exact layouts. Semantic results live
// on FoundationNode components; lists below are derived indexes, never an IR.
import semantic_program_types;

struct SemanticEntry {
    text: u8*;
    entity: void*;
    value: void*;
    number: usize;
}

struct SemanticTable {
    entries: SemanticEntry**;
    capacity: usize;
    count: usize;
}

struct SemanticScope {
    parent: SemanticScope*;
    names: SemanticTable*;
}

// Optional inspection metadata on the syntax entity used as a type. The target
// is the ordinary reflected type entity, not another type representation.
struct SemanticTypeUse {
    target: void*;
}

const EditorEnumMembers: u32 = 5;

// Default resource policy for attached semantic payloads, not a language/node
// index limit or a bound on the entire process heap. Callers may supply another
// explicit budget through semantic_compile_budget.
const SemanticComponentBudgetBytes: usize = 67108864;

// Optional editor observation of ordinary resolution. The hole is identified by
// source coordinates, never by a reserved identifier or an independent AST.
struct SemanticEditor {
    offset: usize;
    length: usize;
    found: bool;
    kind: u32;
    has_expected: bool;
    value_required: bool;
    require_pointer: bool;
    require_integer: bool;
    current: void*;
    loops: usize;
    blocks: usize;
    type: FoundationType;
    receiver: FoundationType;
    scope: SemanticScope*;
    node: void*;
    module: void*;
}

struct SemanticContext {
    editor: SemanticEditor*;
    type_uses: void*;
    program: SemanticProgram*;
    current: void*;
    count: usize;
    node_limit: usize;
    loops: usize;
    value_depth: u32;
    type_depth: u32;
    generics: void*;
    source: u8*;
    functions: SemanticTable*;
    types: SemanticTable*;
    globals: SemanticTable*;
    templates: SemanticTable*;
    type_functions: SemanticTable*;
    type_results: SemanticTable*;
    source_names: SemanticTable*;
    source_bases: SemanticTable*;
    output_names: SemanticTable*;
    fields_done: SemanticTable*;
    layout_work: WorkGraph;
    declaration_state: SemanticTable*;
    control_names: SemanticTable*;
    scope: SemanticScope*;
    labels: SemanticTable*;
    type_arguments: vector(void*);
    constant_arguments: vector(void*);
    generated: vector(void*);
    template_nodes: vector(void*);
    inferring: vector(void*);
    allocations: vector(void*);
    lists: vector(void*);
    // Non-reentrant tree scans reuse scratch storage. Results remain owned by
    // allocations/lists; no caller receives a pointer into either scratch buffer.
    scan: stack(void*);
    token_text: vector(u8);
    surface_expressions: bool;
    deferred: void*;
    deferring: usize;
    defer_bindings: SemanticTable*;
    defer_order: vector(void*)*;
    has_defer: bool;
}

fn sem_editor_contains(c: SemanticContext*, n: void*): bool {
    if c.editor == null {
        return false;
    }
    if n == null {
        return false;
    }
    if sem_source_base(c, n) != 0 {
        return false;
    }
    var span = sem_match(n);
    if span == null {
        return false;
    }
    if span.start > c.editor.offset {
        return false;
    }
    var end = span.start + span.length;
    var hole_end = c.editor.offset + c.editor.length;
    var editor_result9 = hole_end <= end;
    return editor_result9;
}

fn sem_editor_capture(c: SemanticContext*, n: void*, kind: u32, receiver: FoundationType*): bool {
    if !sem_editor_contains(c, n) {
        return false;
    }
    var span = sem_match(n);
    if span.start != c.editor.offset {
        return false;
    }
    if span.length != c.editor.length {
        return false;
    }
    if c.editor.found {
        return true;
    }
    c.editor.found = true;
    c.editor.kind = kind;
    c.editor.scope = c.scope;
    c.editor.node = n;
    c.editor.current = c.current;
    c.editor.loops = c.loops;
    var parent = n;
    loop {
        if parent == null {
            break;
        }
        if sem_is(parent, "CoreBlock") {
            c.editor.blocks++;
        }
        parent = sem_parent(parent);
    }
    if receiver != null {
        sem_set_type(&c.editor.receiver, receiver);
    }
    sem_fail(c, n, "Editor resolution boundary");
    return true;
}

// Accessors only: adapters neither resolve nor validate semantic operations.
extern fn core_component_type(): void*;

extern fn entity_component_get(node: void*, type: void*): void*;

extern fn entity_component_data(component: void*): void*;

extern fn entity_component_add(node: void*, type: void*): void*;

extern fn entity_register(type: void*, size: usize, alignment: usize, lifecycle: usize): bool;

extern fn tower_node_create(): void*;

extern fn entity_attach(child: void*, parent: void*, name: u8*): bool;

extern fn entity_release(node: void*): usize;

extern fn entity_child_at(node: void*, index: usize): void*;

extern fn entity_child_count(node: void*): usize;

extern fn entity_parent(node: void*): void*;

extern fn entity_member_index(node: void*, name: u8*): usize;

extern fn foundation_node_init(value: FoundationNode*): void;

extern fn syntax_identifier_decode_in_place(text: u8*, length: usize): usize;

extern fn abort(): void;

// The component identity is supplied explicitly for reusable compiler contexts.
// Its payload and ownership are the existing entity model, with no copied graph.
export fn semantic_component_get(node: void*, type: void*): FoundationNode* {
    if node == null {
        return null;
    }
    return bits(FoundationNode*, entity_component_data(entity_component_get(node, type)));
}

// Allocation failure leaves both the existing component and owner unchanged.
export fn semantic_component_attach(node: void*, type: void*, kind: u32): FoundationNode* {
    var value = semantic_component_get(node, type);
    var present = value != null;
    if present {
        value.kind = kind;
        return value;
    }
    var lifecycle: usize = 0;
    lifecycle--;
    if !entity_register(type, sizeof(FoundationNode), alignof(FoundationNode), lifecycle) {
        return null;
    }
    value = bits(FoundationNode*, entity_component_data(entity_component_add(node, type)));
    present = value != null;
    if present {
        foundation_node_init(value);
        value.kind = kind;
    }
    return value;
}

export fn sem_get(node: void*): FoundationNode* {
    return semantic_component_get(node, core_component_type());
}

export fn sem_attach(node: void*, kind: u32): FoundationNode* {
    var value = semantic_component_attach(node, core_component_type(), kind);
    var present = value != null;
    sem_require(present);
    return value;
}

export fn sem_create(parent: void*): void* {
    var node = tower_node_create();
    sem_require(entity_attach(node, parent, null));
    entity_release(node);
    return node;
}

extern fn sem_match(node: void*): ParserMatchData*;

export fn sem_child(node: void*, index: usize): void* {
    if node == null {
        return null;
    }
    return entity_child_at(node, index);
}

export fn sem_child_count(node: void*): usize {
    if node == null {
        return 0;
    }
    return entity_child_count(node);
}

export fn sem_parent(node: void*): void* {
    return entity_parent(node);
}

export fn sem_member(node: void*, name: u8*): void* {
    if node == null {
        return null;
    }
    return entity_child_at(node, entity_member_index(node, name));
}

export fn sem_decode_identifier(text: u8*): void {
    var length = syntax_identifier_decode_in_place(text, sem_length(text));
    text[length] = 0;
}

export fn sem_require(ok: bool): void {
    if !ok {
        abort();
    }
}

extern fn generic_begin(root: void*): void*;

extern fn generic_error(context: void*): u8*;

extern fn generic_register(context: void*, definition: void*): u32;

extern fn generic_parameter_count(context: void*, definition: void*): usize;

extern fn generic_type_parameter(context: void*, definition: void*, index: usize): bool;

extern fn generic_instantiate(context: void*, definition: void*, use: void*, arguments: void**, count: usize): void*;

extern fn generic_lookup(context: void*, node: void*, name: void*): void*;

extern fn generic_type_result(context: void*, instance: void*): void*;

extern fn generic_origin(context: void*, node: void*): void*;

extern fn generic_definition(context: void*, node: void*): void*;

fn sem_label(node: void*): u8* {
    var `match` = sem_match(node);
    var present = `match` != null;
    if present {
        present = `match`.label.data != null;
        if present {
            return `match`.label.data;
        }
    }
    return "";
}

fn sem_is(node: void*, name: u8*): bool {
    return sem_equal(sem_label(node), name);
}

extern fn foundation_name_append(value: vector(u8)*, byte: u8): bool;

extern fn foundation_nodes_prepend(values: vector(void*)*, source: void**, count: usize): bool;

import tower;
import foundation_tags;
import semantic_context;
import semantic_expressions;
import semantic_statements;
import semantic_support;
import semantic_types;
import semantic_values;

// Control-flow outcomes are a private analysis bit set, not program opcodes.
const FlowNext: u32 = 1;
const FlowBreak: u32 = 2;
const FlowContinue: u32 = 4;
const FlowReturn: u32 = 8;
const MatchArmLimit: usize = 128;

// Capture every spelling, including quoted/free uses, before generating names.
// Bind operands directly; unique serialized names also preserve reparse hygiene.
fn sem_control_name(c: SemanticContext*): u8* {
    if c.control_names == null {
        c.control_names = sem_table(c);
        var pending = sem_list(c);
        sem_push(pending, c.program.root);
        loop {
            var done = pending.length == 0;
            if done {
                break;
            }
            pending.length--;
            var node = pending.data[pending.length];
            var terminal = sem_match(node);
            var leaf = terminal != null;
            leaf &&= terminal.rule == sem_maximum();
            if leaf {
                // Token leaves store their spelling, not the label Identifier.
                // Including other terminals is conservative and also supports
                // local Identifier overrides without duplicating terminal rules.
                var name = sem_text(c, terminal.label.data, terminal.label.length);
                sem_decode_identifier(name);
                sem_put(c, c.control_names, name, node);
            } else {
                var i: usize = 0;
                var count = sem_child_count(node);
                loop {
                    done = i == count;
                    if done {
                        break;
                    }
                    sem_push(pending, sem_child(node, i));
                    i++;
                }
            }
        }
    }
    var index = c.control_names.count;
    loop {
        var name = sem_cat(c, "control value ", sem_decimal(c, convert(u64, index)));
        if sem_lookup_table(c.control_names, name) == null {
            sem_put(c, c.control_names, name, c.program.root);
            return name;
        }
        index++;
    }
}

fn sem_control_node(c: SemanticContext*, parent: void*, kind: u32): void* {
    var entity = sem_create(parent);
    sem_node(c, entity, kind);
    return entity;
}

fn sem_control_read(c: SemanticContext*, parent: void*, local: void*): void* {
    var entity = sem_control_node(c, parent, KOperand());
    var value = sem_get(entity);
    value.binding = local;
    var binding = sem_get(local);
    sem_set_type(&value.type, &binding.type);
    return entity;
}

fn sem_control_literal(c: SemanticContext*, parent: void*, bit: u64): void* {
    var entity = sem_control_node(c, parent, KOperand());
    var value = sem_get(entity);
    sem_set_type(&value.type, sem_type_new(c, SBool(), 0, null));
    value.constant = true;
    value.bits = bit;
    return entity;
}

fn sem_control_local(c: SemanticContext*, block: void*, initial: void*): void* {
    var entity = sem_control_node(c, block, KDeclare());
    var value = sem_get(entity);
    sem_set_name(value, sem_control_name(c));
    var initializer = sem_get(initial);
    sem_set_type(&value.type, &initializer.type);
    value.value = initial;
    sem_add_local(c, entity);
    var owner = sem_get(block);
    if block != c.current {
        sem_push(&owner.locals, entity);
    }
    var global = block == c.program.root;
    if global {
        value.global = true;
    }
    sem_push(&owner.items, entity);
    return entity;
}

fn sem_control_branch(c: SemanticContext*, block: void*, condition: void*, body: void*): void* {
    var entity = sem_control_node(c, block, KIf());
    var value = sem_get(entity);
    value.value = condition;
    value.body = body;
    value.otherwise = sem_control_node(c, entity, KBlock());
    var owner = sem_get(block);
    sem_push(&owner.items, entity);
    return value.otherwise;
}

fn sem_control_equal(c: SemanticContext*, block: void*, subject: void*, pattern: void*): void* {
    var entity = sem_control_node(c, block, KBinary());
    var value = sem_get(entity);
    value.op = OEq();
    value.left = sem_control_read(c, entity, subject);
    value.right = pattern;
    sem_set_type(&value.type, sem_type_new(c, SBool(), 0, null));
    var local = sem_control_local(c, block, entity);
    return sem_control_read(c, block, local);
}

fn sem_control_match(c: SemanticContext*, n: void*, depth: u32): u32 {
    var initial = sem_expression(c, sem_member(n, "value"), null);
    if !sem_ok(c) {
        return FlowNext();
    }
    var initializer = sem_get(initial);
    var type = &initializer.type;
    var eligible = semantic_integer(type);
    var boolean = type.scalar == SBool();
    var scalar = type.pointers == 0;
    if boolean {
        eligible = scalar;
    }
    if !eligible {
        sem_fail(c, n, "match requires an integer or bool subject");
        return FlowNext();
    }
    var arms = sem_collect(c, sem_member(n, "arms"), "TowerMatchArm");
    if arms.length > MatchArmLimit() {
        sem_fail(c, n, "match supports at most 128 arms");
        return FlowNext();
    }
    var lowered_depth = convert(usize, depth) + arms.length;
    lowered_depth = lowered_depth + 3;
    if lowered_depth > 128 {
        sem_fail(c, n, "match lowering exceeds Foundation block nesting limit of 128");
        return FlowNext();
    }
    var fallback = sem_member(n, "fallback");
    if !sem_shape(c, fallback, "body") {
        return FlowNext();
    }
    sem_node(c, n, KBlock());
    var subject = sem_control_local(c, n, initial);
    var patterns = sem_list(c);
    var block = n;
    var flow: u32 = 0;
    var i: usize = 0;
    loop {
        var done = i == arms.length;
        if done {
            break;
        }
        var arm = arms.data[i];
        var choices = sem_collect(c, sem_member(arm, "patterns"), "TowerMatchLiteral");
        if choices.length == 0 {
            sem_fail(c, arm, "A match arm needs a literal pattern");
            return FlowNext();
        }
        var multiple = choices.length > 1;
        var selected: void* = null;
        if multiple {
            selected = sem_control_local(c, block, sem_control_literal(c, block, 0));
        }
        var condition: void* = null;
        var j: usize = 0;
        loop {
            done = j == choices.length;
            if done {
                break;
            }
            var syntax = choices.data[j];
            if sem_child_count(syntax) == 1 {
                syntax = sem_child(syntax, 0);
            }
            var pattern = sem_operand(c, syntax, type);
            if !sem_ok(c) {
                return FlowNext();
            }
            var literal = sem_get(pattern);
            if !literal.constant {
                sem_fail(c, syntax, "Match patterns must be literals or enum members");
                return FlowNext();
            }
            var k: usize = 0;
            loop {
                done = k == patterns.length;
                if done {
                    break;
                }
                var literal = sem_get(pattern);
                var previous = sem_get(patterns.data[k]);
                if literal.bits == previous.bits {
                    sem_fail(c, choices.data[j], "Duplicate match pattern");
                    return FlowNext();
                }
                k++;
            }
            sem_push(patterns, pattern);
            condition = sem_control_equal(c, block, subject, pattern);
            if multiple {
                var hit = sem_control_node(c, block, KBlock());
                var store = sem_control_node(c, hit, KAssign());
                var assignment = sem_get(store);
                assignment.target = sem_control_read(c, store, selected);
                assignment.value = sem_control_literal(c, store, 1);
                var hit_node = sem_get(hit);
                sem_push(&hit_node.items, store);
                sem_control_branch(c, block, condition, hit);
            }
            j++;
        }
        if multiple {
            condition = sem_control_read(c, block, selected);
        }
        var body = sem_member(arm, "body");
        var arm_depth = depth + convert(u32, i);
        arm_depth++;
        var next = sem_block(c, body, arm_depth);
        flow = flow | next;
        if !sem_ok(c) {
            return FlowNext();
        }
        block = sem_control_branch(c, block, condition, body);
        i++;
    }
    var body = sem_member(fallback, "body");
    var fallback_depth = depth + convert(u32, arms.length);
    fallback_depth++;
    var next = sem_block(c, body, fallback_depth);
    flow = flow | next;
    var tail = sem_get(block);
    sem_push(&tail.items, body);
    return flow;
}

fn sem_control_while(c: SemanticContext*, n: void*, depth: u32): u32 {
    var condition = sem_expression(c, sem_member(n, "condition"), sem_type_new(c, SBool(), 0, null));
    if !sem_ok(c) {
        return FlowNext();
    }
    var value = sem_node(c, n, KLoop());
    var block = sem_control_node(c, n, KBlock());
    value.body = block;
    var known = sem_get(condition);
    var guard = condition;
    // Keep literal conditions visible to Foundation's definite-return analysis.
    // Nonliteral values need a local so a binary condition has a legal spelling.
    if !known.constant {
        var local = sem_control_local(c, block, condition);
        guard = sem_control_read(c, block, local);
    }
    var body = sem_member(n, "body");
    c.loops++;
    var body_depth = depth + 1;
    var flow = sem_block(c, body, body_depth);
    c.loops--;
    var otherwise = sem_control_branch(c, block, guard, body);
    var stop = sem_control_node(c, otherwise, KBreak());
    var failure = sem_get(otherwise);
    sem_push(&failure.items, stop);
    var result = flow &FlowReturn();
    if known.constant {
        if known.bits == 0 {
            return FlowNext();
        }
        var exits = flow &FlowBreak();
        if exits != 0 {
            result = result | FlowNext();
        }
        return result;
    }
    result = result | FlowNext();
    return result;
}

// The header owns a scope; body locals never affect binding of the test/update.
// Only existing Foundation nodes survive lowering. Most counted loops append the
// update directly. A reachable continue requires moving it to the next loop head,
// guarded on the first entry; this preserves effects without duplicating updates
// or rewriting continues belonging to nested loops.
fn sem_control_for(c: SemanticContext*, n: void*, depth: u32): u32 {
    if depth > 125 {
        sem_fail(c, n, "for lowering exceeds Foundation block nesting limit of 128");
        return FlowNext();
    }
    var value = sem_node(c, n, KBlock());
    var saved = c.scope;
    c.scope = sem_scope(c, saved);
    var initial = sem_child(sem_member(n, "initial"), 0);
    var initial_flow = FlowNext();
    if !sem_is(initial, ";") {
        initial_flow = sem_statement(c, initial, depth + 1);
        // The statement checker attaches jump semantics to its call entity,
        // exactly as ordinary block statements do.
        var jump = sem_control_call(c, initial, "jump");
        if jump != null {
            initial = jump;
        }
        sem_push(&value.items, initial);
    }
    var condition_syntax = sem_member(n, "condition");
    var condition: void* = null;
    if sem_child_count(condition_syntax) == 0 {
        condition = sem_control_literal(c, n, 1);
    } else {
        condition = sem_operand(c, sem_child(condition_syntax, 0), sem_type_new(c, SBool(), 0, null));
    }
    var step_syntax = sem_member(n, "step");
    var update: void* = null;
    if sem_child_count(step_syntax) != 0 && sem_ok(c) {
        c.surface_expressions = true;
        update = sem_control_node(c, n, SurfaceDiscard());
        sem_get(update).value = sem_surface_discard(c, sem_child(step_syntax, 0));
    }
    var body = sem_member(n, "body");
    c.loops++;
    var flow = sem_block(c, body, depth + 2);
    c.loops--;
    sem_scope_locals(c, c.scope, &value.locals);
    c.scope = saved;
    if !sem_ok(c) {
        return FlowNext();
    }

    var loop_node = sem_control_node(c, n, KLoop());
    var block = sem_control_node(c, loop_node, KBlock());
    sem_get(loop_node).body = block;
    var repeats = flow &FlowContinue();
    if update != null && repeats != 0 {
        var first = sem_control_local(c, n, sem_control_literal(c, n, 1));
        var start = sem_control_node(c, block, KBlock());
        var store = sem_control_node(c, start, KAssign());
        sem_get(store).target = sem_control_read(c, store, first);
        sem_get(store).value = sem_control_literal(c, store, 0);
        sem_push(&sem_get(start).items, store);
        var next = sem_control_branch(c, block, sem_control_read(c, block, first), start);
        sem_push(&sem_get(next).items, update);
    }
    sem_push(&value.items, loop_node);
    var known = sem_get(condition);
    var guard = condition;
    if !known.constant {
        guard = sem_control_read(c, block, sem_control_local(c, block, condition));
    }
    var otherwise = sem_control_branch(c, block, guard, body);
    sem_push(&sem_get(otherwise).items, sem_control_node(c, otherwise, KBreak()));
    if update != null && repeats == 0 {
        sem_push(&sem_get(block).items, update);
    }
    if(initial_flow &FlowNext()) == 0 {
        return initial_flow;
    }
    var result = flow &FlowReturn();
    if known.constant {
        if known.bits == 0 {
            return FlowNext();
        }
        if(flow &FlowBreak()) != 0 {
            result |= FlowNext();
        }
        return result;
    }
    return result | FlowNext();
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_statements;
import semantic_support;
import semantic_types;
import .library.vector;

// Compilation-local scope analysis. Programs retain only ordinary Foundation
// blocks and operations; this list is neither a runtime stack nor a public IR.
struct SemanticDeferred {
    previous: SemanticDeferred*;
    body: void*;
    loops: usize;
    flow: u32;
}

fn sem_defer_copy_text(destination: vector(u8)*, source: vector(u8)*): void {
    fill(destination, 0, sizeof(vector(u8)));
    if source.length == 0 {
        return;
    }
    sem_require(vector_reserve(u8, destination, source.length + 1));
    copy(destination.data, source.data, source.length);
    destination.data[source.length] = 0;
    destination.length = source.length;
}

fn sem_defer_clone(c: SemanticContext*, parent: void*, original: void*, clones: SemanticTable*, to: vector(void*)*): void* {
    if original == null || !sem_ok(c) {
        return null;
    }
    var found = sem_state(c, clones, original);
    if found.value != null {
        return found.value;
    }
    var source = sem_get(original);
    if source == null {
        sem_fail(c, original, "Deferred cleanup has an unchecked operation");
        return null;
    }
    var entity = sem_control_node(c, parent, source.kind);
    var value = sem_get(entity);
    found.value = entity;
    sem_push(to, entity);
    // Types and external bindings are shared references. Owned vectors and
    // operation edges are copied; a second pass remaps internal local bindings.
    copy(value, source, sizeof(FoundationNode));
    sem_defer_copy_text(&value.name, &source.name);
    sem_defer_copy_text(&value.comments, &source.comments);
    fill(&value.items, 0, sizeof(vector(void*)));
    fill(&value.locals, 0, sizeof(vector(void*)));
    fill(&value.parameters, 0, sizeof(vector(void*)));
    value.left = sem_defer_clone(c, entity, source.left, clones, to);
    value.right = sem_defer_clone(c, entity, source.right, clones, to);
    value.value = sem_defer_clone(c, entity, source.value, clones, to);
    value.target = sem_defer_clone(c, entity, source.target, clones, to);
    value.body = sem_defer_clone(c, entity, source.body, clones, to);
    value.otherwise = sem_defer_clone(c, entity, source.otherwise, clones, to);
    for(var i: usize = 0; i < source.items.length; i++) {
        sem_push(&value.items, sem_defer_clone(c, entity, source.items.data[i], clones, to));
    }
    for(var i: usize = 0; i < source.locals.length; i++) {
        sem_push(&value.locals, sem_defer_clone(c, entity, source.locals.data[i], clones, to));
    }
    for(var i: usize = 0; i < source.parameters.length; i++) {
        sem_push(&value.parameters, sem_defer_clone(c, entity, source.parameters.data[i], clones, to));
    }
    if value.kind == KDeclare() {
        sem_add_local(c, entity);
    }
    return entity;
}

fn sem_defer_emit(c: SemanticContext*, block: void*, stop: void*, loops: usize): u32 {
    var pending = bits(SemanticDeferred*, c.deferred);
    var flow = FlowNext();
    while pending != bits(SemanticDeferred*, stop) && sem_ok(c) {
        if pending == null || pending.loops < loops {
            break;
        }
        var clones = sem_table(c);
        var to = sem_list(c);
        var body = sem_defer_clone(c, block, pending.body, clones, to);
        for(var i: usize = 0; i < to.length; i++) {
            var value = sem_get(to.data[i]);
            if value.binding != null {
                var local = sem_find(clones, null, value.binding);
                if local != null {
                    value.binding = local.value;
                } else {
                    var binding = sem_get(value.binding);
                    if binding.kind == KDeclare() || binding.kind == KParameter() {
                        if c.defer_bindings == null {
                            c.defer_bindings = sem_table(c);
                            c.defer_order = sem_list(c);
                        }
                        var captured = sem_state(c, c.defer_bindings, value.binding);
                        if captured.value == null {
                            captured.value = value.binding;
                            sem_push(c.defer_order, value.binding);
                        }
                    }
                }
            }
        }
        sem_push(&sem_get(block).items, body);
        if(flow &FlowNext()) != 0 {
            flow =(flow & ~FlowNext()) | pending.flow;
        }
        pending = pending.previous;
    }
    return flow;
}

// An exit can occur inside a scope that shadows a captured source name. Give
// captured declarations unique Foundation spellings only after name resolution,
// so text reconstruction retains the direct bindings of the checked graph.
// Editor analysis keeps source names and never publishes an execution graph.
fn sem_defer_hygiene(c: SemanticContext*): void {
    if c.defer_bindings == null || c.editor != null || !sem_ok(c) {
        return;
    }
    // Encounter order is stable across hosts; pointer-keyed hash-table iteration
    // must never decide serialized names.
    for(var i: usize = 0; i < c.defer_order.length; i++) {
        sem_set_name(sem_get(c.defer_order.data[i]), sem_control_name(c));
    }
}

fn sem_defer_register(c: SemanticContext*, n: void*, depth: u32): u32 {
    if depth > 125 {
        sem_fail(c, n, "defer lowering exceeds Foundation block nesting limit of 128");
        return FlowNext();
    }
    if c.labels != null && c.labels.count != 0 {
        sem_fail(c, n, "defer cannot be combined with explicit function labels or jumps");
        return FlowNext();
    }
    sem_node(c, n, KBlock());
    c.has_defer = true;
    var body = sem_member(n, "body");
    var saved = c.deferred;
    var loops = c.loops;
    var function = sem_get(c.current);
    var locals = function.locals.length;
    var frame = function.frame_size;
    c.deferred = null;
    c.loops = 0;
    c.deferring++;
    var flow = sem_statement(c, body, depth + 1);
    c.deferring--;
    c.loops = loops;
    c.deferred = saved;
    // The checked prototype is metadata, not an executable local allocation.
    // Each emitted cleanup owns fresh declarations and frame slots.
    function.locals.length = locals;
    function.frame_size = frame;
    if !sem_ok(c) {
        return FlowNext();
    }
    var pending = bits(SemanticDeferred*, sem_allocate(c, sizeof(SemanticDeferred)));
    pending.previous = bits(SemanticDeferred*, saved);
    pending.body = body;
    pending.loops = loops;
    pending.flow = flow;
    c.deferred = bits(void*, pending);
    return FlowNext();
}

fn sem_defer_exit(c: SemanticContext*, n: void*, flow: u32): u32 {
    var value = sem_get(n);
    if value == null {
        return flow;
    }
    var returned = value.kind == KReturn();
    if returned && c.deferring != 0 {
        sem_fail(c, n, "A deferred cleanup cannot return from its enclosing function");
        return flow;
    }
    if !returned && value.kind != KBreak() && value.kind != KContinue() {
        return flow;
    }
    var pending = bits(SemanticDeferred*, c.deferred);
    if pending == null {
        return flow;
    }
    var loops: usize = 0;
    if !returned {
        loops = c.loops;
        if pending.loops < loops {
            return flow;
        }
    }
    var kind = value.kind;
    var result = value.value;
    value.kind = KBlock();
    value.value = null;
    // Evaluate a return value once before any cleanup can mutate its operands.
    if result != null {
        result = sem_control_read(c, n, sem_control_local(c, n, result));
    }
    var cleanup = sem_defer_emit(c, n, null, loops);
    var terminal = sem_control_node(c, n, kind);
    sem_get(terminal).value = result;
    sem_push(&value.items, terminal);
    if(cleanup &FlowNext()) == 0 {
        return 0;
    }
    return flow;
}

fn sem_defer_depth(c: SemanticContext*, n: void*, depth: u32): void {
    if n == null || !sem_ok(c) {
        return;
    }
    if depth > 128 {
        sem_fail(c, n, "defer expansion exceeds Foundation block nesting limit of 128");
        return;
    }
    var value = sem_get(n);
    if value == null {
        return;
    }
    if value.kind == KBlock() || value.kind == KProgram() {
        var child_depth = depth;
        if value.kind == KBlock() {
            child_depth++;
        }
        for(var i: usize = 0; i < value.items.length && sem_ok(c); i++) {
            sem_defer_depth(c, value.items.data[i], child_depth);
        }
    }
    if value.kind == KIf() || value.kind == KLoop() {
        sem_defer_depth(c, value.body, depth);
        sem_defer_depth(c, value.otherwise, depth);
    }
}

// An exit may be much deeper than the registration, and expression lifting may
// add branches. Check the final executable structure, not the prototype's depth.
fn sem_defer_validate(c: SemanticContext*): void {
    if !c.has_defer || !sem_ok(c) {
        return;
    }
    for(var i: usize = 0; i < c.program.functions.length && sem_ok(c); i++) {
        var function = c.program.functions.data[i];
        var body = sem_get(function).body;
        if function == c.program.root {
            body = function;
        }
        sem_defer_depth(c, body, 0);
    }
}

import tower;
import foundation_tags;
import semantic_support;

// Shared semantic spellings and arities for Foundation checking and formatting.
// Numeric tags are defined in foundation_tags on the shared component model,
// not a public instruction encoding; coordinate any renumbering.
export fn semantic_scalar_name(scalar: u32): u8* {
    if scalar == SI32() {
        return "i32";
    }
    if scalar == SU32() {
        return "u32";
    }
    if scalar == SBool() {
        return "bool";
    }
    if scalar == SVoid() {
        return "void";
    }
    if scalar == SStruct() {
        return "";
    }
    if scalar == SU8() {
        return "u8";
    }
    if scalar == SI64() {
        return "i64";
    }
    if scalar == SU64() {
        return "u64";
    }
    if scalar == SUSize() {
        return "usize";
    }
    return "";
}

export fn semantic_operator(op: u32): u8* {
    if op == OAdd() {
        return "+";
    }
    if op == OSub() {
        return "-";
    }
    if op == OMul() {
        return "*";
    }
    if op == ODiv() {
        return "/";
    }
    if op == ORem() {
        return "%";
    }
    if op == OAnd() {
        return "&";
    }
    if op == OOr() {
        return "|";
    }
    if op == OXor() {
        return "^";
    }
    if op == OEq() {
        return "==";
    }
    if op == ONe() {
        return "!=";
    }
    if op == OLt() {
        return "<";
    }
    if op == OLe() {
        return "<=";
    }
    if op == OGt() {
        return ">";
    }
    if op == OGe() {
        return ">=";
    }
    return "";
}

export fn semantic_builtin_name(kind: u32): u8* {
    if kind == 31 {
        return "label";
    }
    if kind == 32 {
        return "jump";
    }
    if kind == 33 {
        return "trap";
    }
    if kind == KPrint() {
        return "print";
    }
    if kind == KAllocate() {
        return "alloc";
    }
    if kind == KReallocate() {
        return "realloc";
    }
    if kind == KFree() {
        return "free";
    }
    if kind == KCopy() {
        return "copy";
    }
    if kind == KFill() {
        return "fill";
    }
    if kind == KSizeOf() {
        return "sizeof";
    }
    if kind == KAlignOf() {
        return "alignof";
    }
    if kind == KConvert() {
        return "convert";
    }
    if kind == KBits() {
        return "bits";
    }
    return null;
}

export fn semantic_builtin_arity(kind: u32): usize {
    if kind == 31 {
        return 1;
    }
    if kind == 32 {
        return 1;
    }
    if kind == 33 {
        return 2;
    }
    if kind == KPrint() {
        return 1;
    }
    if kind == KAllocate() {
        return 2;
    }
    if kind == KReallocate() {
        return 3;
    }
    if kind == KFree() {
        return 1;
    }
    if kind == KCopy() {
        return 3;
    }
    if kind == KFill() {
        return 3;
    }
    if kind == KSizeOf() {
        return 1;
    }
    if kind == KAlignOf() {
        return 1;
    }
    if kind == KConvert() {
        return 2;
    }
    if kind == KBits() {
        return 2;
    }
    return 0;
}

export fn semantic_builtin_kind(name: u8*): u32 {
    if sem_equal(name, "label") {
        return 31;
    }
    if sem_equal(name, "jump") {
        return 32;
    }
    if sem_equal(name, "trap") {
        return 33;
    }
    if sem_equal(name, "print") {
        return 17;
    }
    if sem_equal(name, "alloc") {
        return 26;
    }
    if sem_equal(name, "realloc") {
        return 27;
    }
    if sem_equal(name, "free") {
        return 28;
    }
    if sem_equal(name, "copy") {
        return 29;
    }
    if sem_equal(name, "fill") {
        return 30;
    }
    if sem_equal(name, "sizeof") {
        return 24;
    }
    if sem_equal(name, "alignof") {
        return 25;
    }
    if sem_equal(name, "convert") {
        return 9;
    }
    if sem_equal(name, "bits") {
        return 10;
    }
    return 0;
}

export fn semantic_builtin_at(index: usize): u32 {
    if index == 10 {
        return 31;
    }
    if index == 11 {
        return 32;
    }
    if index == 12 {
        return 33;
    }
    if index == 0 {
        return 17;
    }
    if index == 1 {
        return 26;
    }
    if index == 2 {
        return 27;
    }
    if index == 3 {
        return 28;
    }
    if index == 4 {
        return 29;
    }
    if index == 5 {
        return 30;
    }
    if index == 6 {
        return 24;
    }
    if index == 7 {
        return 25;
    }
    if index == 8 {
        return 9;
    }
    if index == 9 {
        return 10;
    }
    return 0;
}

import tower;
import foundation_tags;
import semantic_context;
import semantic_modules;
import semantic_support;
import semantic_types;
import semantic_values;

// Enum declarations/members are the original shared parse entities enriched
// with Foundation type/constant components. No copied semantic representation.
fn sem_enum_header(c: SemanticContext*, n: void*): void {
    var representation = sem_type(c, sem_member(n, "type"));
    var valid = semantic_integer(representation);
    if semantic_enum(representation) {
        valid = false;
    }
    if !valid {
        sem_fail(c, n, "An enum representation must be a built-in integer type");
        return;
    }
    sem_type_header(c, n, "");
    if !sem_ok(c) {
        return;
    }
    var value = sem_get(n);
    sem_set_type(&value.element, representation);
    value.type.scalar = representation.scalar;
}

fn sem_enum_fields(c: SemanticContext*, n: void*): void {
    var state = sem_state(c, c.fields_done, n);
    if state.number != 0 {
        return;
    }
    state.number = 1;
    var type = sem_get(n);
    var members = sem_collect(c, sem_member(n, "fields"), "CoreEnumMember");
    var names = sem_table(c);
    state.value = bits(void*, names);
    var values = sem_table(c);
    var mask = semantic_mask(&type.element);
    var maximum = mask;
    if semantic_signed(&type.element) {
        maximum = mask / 2;
    }
    var next: u64 = 0;
    var overflow = false;
    var i: usize = 0;
    loop {
        if !sem_ok(c) {
            return;
        }
        if i == members.length {
            return;
        }
        var member = members.data[i];
        var name = sem_identifier(c, sem_member(member, "name"));
        var initial = sem_member(member, "value");
        if initial != null {
            var literal = sem_operand(c, initial, &type.element);
            if !sem_ok(c) {
                return;
            }
            var constant = sem_get(literal);
            next = constant.bits;
        } else {
            if overflow {
                sem_fail(c, member, "Enum discriminant overflow; provide an explicit in-range value");
                return;
            }
        }
        if !sem_put(c, names, name, member) {
            sem_fail(c, member, sem_cat(c, "Duplicate enum member '", sem_cat(c, name, "'")));
            return;
        }
        var key = sem_decimal(c, next);
        if !sem_put(c, values, key, member) {
            sem_fail(c, member, "Duplicate enum discriminant");
            return;
        }
        var value = sem_node(c, member, KOperand());
        sem_set_name(value, name);
        sem_set_type(&value.type, &type.type);
        value.constant = true;
        value.bits = next;
        sem_push(&type.items, member);
        overflow = next == maximum;
        next++;
        next = next & mask;
        i++;
    }
}

// Type/member lookup applies only in value position. An enum member is not an
// addressable variable. A local/global value with the same name takes precedence.
fn sem_enum_operand(c: SemanticContext*, n: void*): bool {
    var base = sem_member(n, "base");
    var field = sem_member(n, "field");
    var possible = base != null;
    possible &&= field != null;
    if !possible {
        return false;
    }
    var identifier = sem_name_node(base);
    var name = sem_identifier(c, identifier);
    // Most member accesses are ordinary fields. Reject those before walking
    // lexical scopes; only a matching enum type needs the shadowing check.
    var definition = sem_resolve(c, c.types, base, name);
    if definition == null {
        return false;
    }
    var type = sem_get(definition);
    if !semantic_enum(&type.type) {
        return false;
    }
    var scope = c.scope;
    loop {
        if scope == null {
            break;
        }
        var shadowed = sem_lookup_table(scope.names, name) != null;
        if shadowed {
            return false;
        }
        scope = scope.parent;
    }
    var shadowed = sem_resolve(c, c.globals, base, name) != null;
    if shadowed {
        return false;
    }
    if sem_editor_capture(c, field, EditorEnumMembers(), &type.type) {
        return true;
    }
    var member_name = sem_identifier(c, field);
    // Reuse the per-definition derived member index; payloads remain on entities.
    var state = sem_state(c, c.fields_done, definition);
    var names = bits(SemanticTable*, state.value);
    var member = sem_lookup_table(names, member_name);
    if member == null {
        sem_fail(c, n, sem_cat(c, "Unknown enum member '", sem_cat(c, member_name, "'")));
        return true;
    }
    var item = sem_get(member);
    var value = sem_node(c, n, KOperand());
    value.binding = member;
    value.constant = true;
    value.bits = item.bits;
    sem_set_type(&value.type, &type.type);
    return true;
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_definitions;
import semantic_expressions;
import semantic_support;
import semantic_types;
import .library.vector;

// Expressions are normalized on the shared ECS entities into ordinary bound
// locals, calls, loads/stores and control flow. No backend sees surface tags.
fn sem_lift_append(block: void*, n: void*): void {
    var owner = sem_get(block);
    sem_push(&owner.items, n);
}

fn sem_lift_result(source: void*, result: void*): void* {
    // Keep the source entity useful to reflection after normalization. Its
    // syntax children/provenance remain; its semantic value is the bound result.
    var value = sem_get(source);
    var read = sem_get(result);
    value.kind = read.kind;
    value.binding = read.binding;
    value.constant = read.constant;
    value.bits = read.bits;
    value.op = read.op;
    value.left = null;
    value.right = null;
    value.value = null;
    value.target = null;
    sem_set_type(&value.type, &read.type);
    return result;
}

fn sem_lift_snapshot(c: SemanticContext*, block: void*, n: void*): void* {
    var value = sem_get(n);
    if value.constant {
        return n;
    }
    if value.kind == KString() {
        return n;
    }
    var local = sem_control_local(c, block, n);
    return sem_control_read(c, block, local);
}

fn sem_lift_binary(c: SemanticContext*, block: void*, op: u32, left: void*, right: void*, type: FoundationType*): void* {
    var entity = sem_control_node(c, block, KBinary());
    var value = sem_get(entity);
    value.op = op;
    value.left = left;
    value.right = right;
    sem_set_type(&value.type, type);
    return sem_lift_snapshot(c, block, entity);
}

fn sem_lift_store(c: SemanticContext*, block: void*, target: void*, value: void*): void {
    var entity = sem_control_node(c, block, KAssign());
    var assignment = sem_get(entity);
    assignment.target = target;
    assignment.value = value;
    sem_lift_append(block, entity);
}

fn sem_lift_place(c: SemanticContext*, block: void*, n: void*): void* {
    var value = sem_get(n);
    if value.kind == KLoad() {
        value.value = sem_lift_value(c, block, value.value);
        return n;
    }
    var field = value.kind == KField();
    var index = value.kind == KIndex();
    var projection = field;
    if index {
        projection = true;
    }
    if projection {
        if value.indirect {
            value.left = sem_lift_value(c, block, value.left);
        }
        else {
            value.left = sem_lift_place(c, block, value.left);
            var base = sem_get(value.left);
            if base.kind == KLoad() {
                // Foundation field paths already dereference a struct pointer.
                // An array dereference needs an explicit element pointer so its
                // indexed spelling reconstructs the same element type/stride.
                value.left = base.value;
                if index {
                    var pointer = sem_control_node(c, block, KBits());
                    var cast = sem_get(pointer);
                    cast.value = value.left;
                    sem_set_type(&cast.type, &value.type);
                    cast.type.pointers++;
                    value.left = sem_lift_snapshot(c, block, pointer);
                }
                value.indirect = true;
            }
        }
        if index {
            value.right = sem_lift_value(c, block, value.right);
        }
    }
    return n;
}

fn sem_lift_target(c: SemanticContext*, block: void*, n: void*): void* {
    n = sem_lift_place(c, block, n);
    var source = sem_get(n);
    if source.kind == KLoad() {
        return n;
    }
    var address = sem_control_node(c, block, KAddress());
    var pointer = sem_get(address);
    pointer.value = n;
    sem_set_type(&pointer.type, &source.type);
    pointer.type.pointers++;
    var saved = sem_lift_snapshot(c, block, address);
    var target = sem_control_node(c, block, KLoad());
    var load = sem_get(target);
    load.value = saved;
    sem_set_type(&load.type, &source.type);
    return target;
}

// Total shifts: counts are masked by (width - 1), signed right shift extends
// the sign, left shift wraps. This portable expansion uses Foundation integers;
// LLVM's existing optimization may recognize it, but no machine-code claim is made.
fn sem_lift_shift(c: SemanticContext*, block: void*, left: void*, right: void*, operation: u32): void* {
    var input = sem_get(left);
    var backwards = operation != SurfaceShiftLeft();
    if operation == SurfaceShiftUnsigned() && semantic_signed(&input.type) {
        var original = &input.type;
        var type = sem_type_copy(c, original);
        type.scalar = SU32();
        if original.scalar == SI64() {
            type.scalar = SU64();
        }
        var converted = sem_control_node(c, block, KBits());
        sem_get(converted).value = left;
        sem_set_type(&sem_get(converted).type, type);
        var shifted = sem_lift_shift(c, block, sem_lift_snapshot(c, block, converted), right, SurfaceShiftRight());
        var result = sem_control_node(c, block, KBits());
        sem_get(result).value = shifted;
        sem_set_type(&sem_get(result).type, original);
        return sem_lift_snapshot(c, block, result);
    }
    var count_type = sem_get(right);
    var width = semantic_size(&input.type) *8;
    var mask = convert(u64, width) -1;
    var count_mask = sem_surface_constant(c, block, &count_type.type, mask);
    var count = sem_lift_binary(c, block, OAnd(), right, count_mask, &count_type.type);
    var remaining = sem_control_local(c, block, count);
    var result = sem_control_local(c, block, left);
    var loop_node = sem_control_node(c, block, KLoop());
    var loop_value = sem_get(loop_node);
    var body = sem_control_node(c, loop_node, KBlock());
    loop_value.body = body;
    sem_lift_append(block, loop_node);
    var zero = sem_surface_constant(c, body, &count_type.type, 0);
    var current_count = sem_control_read(c, body, remaining);
    var boolean = sem_type_new(c, SBool(), 0, null);
    var finished = sem_lift_binary(c, body, OEq(), current_count, zero, boolean);
    var stop = sem_control_node(c, body, KBlock());
    sem_lift_append(stop, sem_control_node(c, stop, KBreak()));
    sem_control_branch(c, body, finished, stop);
    var current = sem_control_read(c, body, result);
    var two = sem_surface_constant(c, body, &input.type, 2);
    var op = OMul();
    if backwards {
        op = ODiv();
    }
    var next = sem_lift_binary(c, body, op, current, two, &input.type);
    if backwards {
        if semantic_signed(&input.type) {
            // Truncating division differs from arithmetic shift for negative odd values.
            var one = sem_surface_constant(c, body, &input.type, 1);
            var low = sem_lift_binary(c, body, OAnd(), current, one, &input.type);
            var negative = sem_lift_binary(c, body, OLt(), current,
            sem_surface_constant(c, body, &input.type, 0), boolean);
            var adjusted = sem_control_local(c, body, next);
            var correction = sem_control_node(c, body, KBlock());
            var rounded = sem_lift_binary(c, correction, OSub(), next, low, &input.type);
            sem_lift_store(c, correction, sem_control_read(c, correction, adjusted), rounded);
            sem_control_branch(c, body, negative, correction);
            next = sem_control_read(c, body, adjusted);
        }
    }
    sem_lift_store(c, body, sem_control_read(c, body, result), next);
    var one_count = sem_surface_constant(c, body, &count_type.type, 1);
    var next_count = sem_lift_binary(c, body, OSub(), current_count, one_count, &count_type.type);
    sem_lift_store(c, body, sem_control_read(c, body, remaining), next_count);
    return sem_control_read(c, block, result);
}

fn sem_lift_nonnull(c: SemanticContext*, block: void*, value: void*): void* {
    var zero = sem_surface_constant(c, block, &sem_get(value).type, 0);
    return sem_lift_binary(c, block, ONe(), value, zero, sem_type_new(c, SBool(), 0, null));
}

// Follow a null-conditional chain inside nested success blocks. Index operands
// and later receivers are evaluated only after the preceding guard succeeds.
// Intermediate struct fields remain places, so no aggregate copy is introduced.
fn sem_lift_guarded_path(c: SemanticContext*, selected: void**, n: void*): void* {
    var value = sem_get(n);
    if !sem_surface_optional(value) {
        return sem_lift_value(c, *selected, n);
    }
    var indexed = value.kind == SurfaceNullIndex();
    var left = sem_lift_guarded_path(c, selected, value.left);
    if sem_get(left).type.pointers != 0 {
        left = sem_lift_value(c, *selected, left);
    }
    if value.op != 0 {
        var present = sem_lift_nonnull(c, *selected, left);
        var yes = sem_control_node(c, *selected, KBlock());
        sem_control_branch(c, *selected, present, yes);
        *selected = yes;
    }
    value.kind = KField();
    if indexed {
        value.kind = KIndex();
    }
    value.op = 0;
    value.left = left;
    if indexed {
        value.right = sem_lift_value(c, *selected, value.right);
    }
    var projection = sem_control_node(c, *selected, value.kind);
    var data = sem_get(projection);
    data.left = value.left;
    data.right = value.right;
    data.binding = value.binding;
    data.indirect = value.indirect;
    data.byte_offset = value.byte_offset;
    sem_set_name(data, sem_name(value));
    sem_set_type(&data.type, &value.type);
    return projection;
}

fn sem_lift_coalesce(c: SemanticContext*, block: void*, left: void*, right: void*, target: void*): void* {
    var type = &sem_get(left).type;
    var result = sem_control_local(c, block, sem_surface_constant(c, block, type, 0));
    var boolean = sem_type_new(c, SBool(), 0, null);
    var found = sem_control_local(c, block, sem_surface_constant(c, block, boolean, 0));
    var selected = block;
    var first = sem_lift_guarded_path(c, &selected, left);
    first = sem_lift_value(c, selected, first);
    if type.pointers != 0 {
        var present = sem_lift_nonnull(c, selected, first);
        var yes = sem_control_node(c, selected, KBlock());
        sem_control_branch(c, selected, present, yes);
        selected = yes;
    }
    sem_lift_store(c, selected, sem_control_read(c, selected, result), first);
    sem_lift_store(c, selected, sem_control_read(c, selected, found), sem_surface_constant(c, selected, boolean, 1));
    var missing = sem_lift_binary(c, block, OEq(), sem_control_read(c, block, found),
    sem_surface_constant(c, block, boolean, 0), boolean);
    var fallback = sem_control_node(c, block, KBlock());
    sem_control_branch(c, block, missing, fallback);
    var second = sem_lift_value(c, fallback, right);
    sem_lift_store(c, fallback, sem_control_read(c, fallback, result), second);
    if target != null {
        sem_lift_store(c, fallback, target, second);
    }
    return sem_control_read(c, block, result);
}

fn sem_lift_logical(c: SemanticContext*, block: void*, left: void*, right: void*, operation: u32, target: void*): void* {
    var first = sem_lift_value(c, block, left);
    var result = sem_control_local(c, block, first);
    var yes = sem_control_node(c, block, KBlock());
    var no = sem_control_branch(c, block, first, yes);
    var chosen = yes;
    if operation == SurfaceOr() {
        chosen = no;
    }
    var second = sem_lift_value(c, chosen, right);
    sem_lift_store(c, chosen, sem_control_read(c, chosen, result), second);
    if target != null {
        sem_lift_store(c, chosen, target, second);
    }
    return sem_control_read(c, block, result);
}

fn sem_lift_value(c: SemanticContext*, block: void*, n: void*): void* {
    var absent = n == null;
    if absent {
        return null;
    }
    var value = sem_get(n);
    if value.constant {
        return n;
    }
    if sem_surface_optional(value) {
        var absent = sem_surface_constant(c, block, &value.type, 0);
        return sem_lift_result(n, sem_lift_coalesce(c, block, n, absent, null));
    }
    if value.kind == SurfaceCoalesce() {
        return sem_lift_result(n, sem_lift_coalesce(c, block, value.left, value.right, null));
    }
    if value.kind == SurfaceComma() {
        sem_lift_value(c, block, value.left);
        return sem_lift_result(n, sem_lift_value(c, block, value.right));
    }
    var select = value.kind == SurfaceSelect();
    var logical_and = value.kind == SurfaceAnd();
    var logical_or = value.kind == SurfaceOr();
    if logical_and || logical_or {
        return sem_lift_result(n, sem_lift_logical(c, block, value.left, value.right, value.kind, null));
    }
    if select {
        var condition = sem_lift_value(c, block, value.value);
        if value.type.scalar == SVoid() && value.type.pointers == 0 {
            var yes = sem_control_node(c, block, KBlock());
            var no = sem_control_branch(c, block, condition, yes);
            sem_lift_value(c, yes, value.left);
            sem_lift_value(c, no, value.right);
            value.kind = KBlock();
            value.left = null;
            value.right = null;
            value.value = null;
            return n;
        }
        var initial = sem_surface_constant(c, block, &value.type, 0);
        var result = sem_control_local(c, block, initial);
        var yes = sem_control_node(c, block, KBlock());
        var no = sem_control_branch(c, block, condition, yes);
        var left = sem_lift_value(c, yes, value.left);
        sem_lift_store(c, yes, sem_control_read(c, yes, result), left);
        var right = sem_lift_value(c, no, value.right);
        sem_lift_store(c, no, sem_control_read(c, no, result), right);
        return sem_lift_result(n, sem_control_read(c, block, result));
    }
    var assign = value.kind == SurfaceAssign();
    var modify = value.kind == SurfaceModify();
    var writes = assign;
    if modify {
        writes = true;
    }
    if writes {
        var target = sem_lift_target(c, block, value.target);
        var previous: void* = null;
        var compound = value.op != SurfaceSet();
        if compound {
            previous = sem_lift_snapshot(c, block, target);
        }
        if value.op == SurfaceCoalesce() {
            return sem_lift_result(n, sem_lift_coalesce(c, block, previous, value.value, target));
        }
        if value.op == SurfaceAnd() || value.op == SurfaceOr() {
            return sem_lift_result(n, sem_lift_logical(c, block, previous, value.value, value.op, target));
        }
        var next: void* = null;
        if modify {
            var type = &value.type;
            if type.pointers != 0 {
                type = sem_type_new(c, SUSize(), 0, null);
            }
            next = sem_surface_constant(c, block, type, 1);
        } else {
            next = sem_lift_value(c, block, value.value);
        }
        if compound {
            var shift = value.op >= SurfaceShiftLeft() && value.op <= SurfaceShiftUnsigned();
            if shift {
                next = sem_lift_shift(c, block, previous, next, value.op);
            }
            else {
                next = sem_lift_binary(c, block, value.op, previous, next, &value.type);
            }
        }
        sem_lift_store(c, block, target, next);
        if modify {
            if value.indirect {
                return sem_lift_result(n, previous);
            }
        }
        return sem_lift_result(n, next);
    }
    var shift = value.kind == SurfaceShift();
    var threeway = value.kind == SurfaceCompare();
    var binary = value.kind == KBinary();
    var pair = binary;
    if shift {
        pair = true;
    }
    if threeway {
        pair = true;
    }
    if pair {
        value.left = sem_lift_value(c, block, value.left);
        value.right = sem_lift_value(c, block, value.right);
        if shift {
            return sem_lift_result(n, sem_lift_shift(c, block, value.left, value.right, value.op));
        }
        if threeway {
            var boolean = sem_type_new(c, SBool(), 0, null);
            var less = sem_lift_binary(c, block, OLt(), value.left, value.right, boolean);
            var more = sem_lift_binary(c, block, OGt(), value.left, value.right, boolean);
            var low = sem_control_node(c, block, KConvert());
            var a = sem_get(low);
            a.value = less;
            sem_set_type(&a.type, &value.type);
            low = sem_lift_snapshot(c, block, low);
            var high = sem_control_node(c, block, KConvert());
            var b = sem_get(high);
            b.value = more;
            sem_set_type(&b.type, &value.type);
            high = sem_lift_snapshot(c, block, high);
            return sem_lift_result(n, sem_lift_binary(c, block, OSub(), high, low, &value.type));
        }
        return sem_lift_snapshot(c, block, n);
    }
    if value.kind == KAddress() {
        value.value = sem_lift_place(c, block, value.value);
        var location = sem_get(value.value);
        if location.kind == KLoad() {
            return location.value;
        }
    }
    else {
        var location = value.kind == KField();
        location ||= value.kind == KIndex();
        if location {
            sem_lift_place(c, block, n);
        }
        else {
            value.left = sem_lift_value(c, block, value.left);
            value.right = sem_lift_value(c, block, value.right);
            value.value = sem_lift_value(c, block, value.value);
        }
    }
    if value.kind == KCall() {
        for(var index: usize = 0; index != value.items.length; index++) {
            value.items.data[index] = sem_lift_value(c, block, value.items.data[index]);
        }
    }
    var discarded = value.type.pointers == 0;
    discarded &&= value.type.scalar == SVoid();
    if discarded {
        sem_lift_append(block, n);
        return n;
    }
    return sem_lift_snapshot(c, block, n);
}

fn sem_lift_block(c: SemanticContext*, block: void*): void {
    var value = sem_get(block);
    var source = sem_list(c);
    var index: usize = 0;
    for(; index != value.items.length; index++) {
        sem_push(source, value.items.data[index]);
    }
    value.items.length = 0;
    index = 0;
    loop {
        if index == source.length {
            return;
        }
        var n = source.data[index];
        index++;
        var statement = sem_get(n);
        if statement == null {
            sem_lift_append(block, n);
            continue;
        }
        if statement.kind == SurfaceDiscard() {
            sem_lift_value(c, block, statement.value);
            statement.kind = KBlock();
            statement.value = null;
            continue;
        }
        if statement.kind == KBlock() {
            sem_lift_block(c, n);
        }
        if statement.kind == KLoop() {
            sem_lift_block(c, statement.body);
        }
        if statement.kind == KIf() {
            statement.value = sem_lift_value(c, block, statement.value);
            sem_lift_block(c, statement.body);
            var otherwise = statement.otherwise != null;
            if otherwise {
                sem_lift_block(c, statement.otherwise);
            }
        }
        var declaration = statement.kind == KDeclare();
        var assignment = statement.kind == KAssign();
        var returned = statement.kind == KReturn();
        if assignment {
            statement.target = sem_lift_target(c, block, statement.target);
        }
        var initializer = declaration;
        if assignment {
            initializer = true;
        }
        if returned {
            initializer = true;
        }
        if initializer {
            statement.value = sem_lift_value(c, block, statement.value);
        }
        var call = statement.kind == KCall();
        call ||= statement.kind == KPrint();
        call ||= statement.kind == KFree();
        call ||= statement.kind == KCopy();
        call ||= statement.kind == KFill();
        if call {
            sem_lift_value(c, block, n);
        }
        else {
            sem_lift_append(block, n);
        }
    }
}

fn sem_lower_expressions(c: SemanticContext*): void {
    if !c.surface_expressions {
        return;
    }
    if !sem_ok(c) {
        return;
    }
    var index: usize = 0;
    loop {
        if index == c.program.functions.length {
            return;
        }
        c.current = c.program.functions.data[index];
        var function = sem_get(c.current);
        var block = function.body;
        if index == 0 {
            block = c.current;
        }
        index++;
        if block != null {
            sem_lift_block(c, block);
        }
    }
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_definitions;
import semantic_support;
import semantic_types;
import semantic_layout;
import semantic_values;

// Transient surface classifications on the same entities. These are eliminated
// before publishing a Foundation graph; they have no interpreter/cache encoding.
const SurfaceSelect: u32 = 100;
const SurfaceAnd: u32 = 101;
const SurfaceOr: u32 = 102;
const SurfaceAssign: u32 = 103;
const SurfaceModify: u32 = 104;
const SurfaceComma: u32 = 105;
const SurfaceShift: u32 = 106;
const SurfaceCompare: u32 = 107;
const SurfaceDiscard: u32 = 108;
const SurfaceCoalesce: u32 = 109;
const SurfaceNullField: u32 = 110;
const SurfaceNullIndex: u32 = 111;
const SurfaceShiftLeft: u32 = 14;
const SurfaceShiftRight: u32 = 15;
const SurfaceShiftUnsigned: u32 = 16;
const SurfaceSet: u32 = 4294967295;

fn sem_surface_unwrap(n: void*): void* {
    loop {
        var wrapper = sem_is(n, "TowerExpression");
        wrapper ||= sem_is(n, "TowerComma");
        wrapper ||= sem_is(n, "CoreOperand");
        wrapper ||= sem_is(n, "CoreCallArgument");
        wrapper ||= sem_is(n, "CoreValue");
        if !wrapper {
            return n;
        }
        if sem_child_count(n) == 1 {
            n = sem_child(n, 0);
        }
        else {
            var group = sem_member(n, "value");
            if group != null {
                n = group;
            } else {
                return n;
            }
        }
    }
}

fn sem_surface_expected(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if !sem_ok(c) {
        return n;
    }
    var value = sem_get(n);
    if value == null {
        return n;
    }
    if expected_type != null {
        if !semantic_type_equal(&value.type, expected_type) {
            sem_fail(c, n, sem_cat(c, "Expected ", sem_cat(c, sem_type_name(c, expected_type),
            sem_cat(c, ", got ", sem_type_name(c, &value.type)))));
        }
    }
    return n;
}

fn sem_surface_integer(c: SemanticContext*, n: void*): bool {
    var value = sem_get(n);
    var ok = semantic_integer(&value.type);
    if ok {
        if semantic_enum(&value.type) {
            ok = false;
        }
    }
    if !ok {
        sem_fail(c, n, "This operation requires integer operands");
    }
    return ok;
}

fn sem_surface_constant(c: SemanticContext*, parent: void*, type: FoundationType*, bits_value: u64): void* {
    var n = sem_control_node(c, parent, KOperand());
    var value = sem_get(n);
    value.constant = true;
    value.bits = bits_value;
    sem_set_type(&value.type, type);
    return n;
}

fn sem_surface_pointee(c: SemanticContext*, n: void*, pointer: FoundationType*): void {
    var element = sem_type_copy(c, pointer);
    element.pointers--;
    if semantic_aggregate(element) {
        sem_layout(c, element.record);
    }
    if semantic_size(element) == 0 {
        sem_fail(c, n, "Cannot offset a void pointer");
    }
}

fn sem_surface_optional(value: FoundationNode*): bool {
    return value.kind == SurfaceNullField() || value.kind == SurfaceNullIndex();
}

fn sem_surface_nullable(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if c.value_depth > 128 {
        sem_fail(c, n, "Foundation expression nesting limit is 128");
        return n;
    }
    c.value_depth++;
    var result = sem_surface_nullable_impl(c, n, expected_type);
    c.value_depth--;
    return result;
}

fn sem_surface_nullable_impl(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    n = sem_surface_unwrap(n);
    if !sem_is(n, "TowerNullAccess") {
        return sem_operand(c, n, expected_type);
    }
    if sem_get(n) != null {
        return n;
    }
    c.surface_expressions = true;
    var source = sem_surface_unwrap(sem_member(n, "base"));
    var base: void* = null;
    if sem_is(source, "CoreLocation") {
        base = sem_location(c, source, 0);
    }
    else {
        base = sem_surface_nullable(c, source, null);
    }
    if !sem_ok(c) {
        return n;
    }
    var guarded = sem_tokens(c, sem_child(n, 1))[0] == 63;
    if guarded && sem_get(base).type.pointers == 0 {
        sem_fail(c, n, "Null-conditional access requires a pointer receiver");
        return n;
    }
    sem_location(c, n, 0);
    if !sem_ok(c) {
        return n;
    }
    var value = sem_get(n);
    value.kind = SurfaceNullField();
    if sem_member(n, "index") != null {
        value.kind = SurfaceNullIndex();
    }
    value.op = convert(u32, guarded);
    return n;
}

// One operator classification is shared by binary and compound syntax.
// Compound assignment strips '=' and uses this same operation/type contract.
fn sem_surface_code(operation: u8*): u32 {
    if sem_equal(operation, "&&") {
        return SurfaceAnd();
    }
    if sem_equal(operation, "||") {
        return SurfaceOr();
    }
    if sem_equal(operation, "??") {
        return SurfaceCoalesce();
    }
    if sem_equal(operation, "<<") {
        return SurfaceShiftLeft();
    }
    if sem_equal(operation, ">>") {
        return SurfaceShiftRight();
    }
    if sem_equal(operation, ">>>") {
        return SurfaceShiftUnsigned();
    }
    for(var code: u32 = 0; code <= OGe(); code++) {
        if sem_equal(operation, semantic_operator(code)) {
            return code;
        }
    }
    return SurfaceSet();
}

fn sem_surface_compound(op: u8*): bool {
    var length = sem_length(op);
    if length < 2 || op[length -1] != 61 {
        return false;
    }
    return !sem_equal(op, "==") && !sem_equal(op, "!=")
    && !sem_equal(op, "<=") && !sem_equal(op, ">=");
}

fn sem_surface_binary(c: SemanticContext*, n: void*, left: void*, right: void*, op: u32, expected_type: FoundationType*): void* {
    var value = sem_node(c, n, KBinary());
    value.op = op;
    var comparison = op >= OEq();
    var input = expected_type;
    var infer = comparison;
    infer ||= input == null;
    if infer {
        var anchor = left;
        if sem_literal(c, left) {
            if !sem_literal(c, right) {
                anchor = right;
            }
        }
        var known = sem_operand(c, anchor, null);
        if !sem_ok(c) {
            return n;
        }
        input = &sem_get(known).type;
    }
    value.left = sem_operand(c, left, input);
    if !sem_ok(c) {
        return n;
    }
    var offset = input.pointers != 0;
    if offset {
        offset = op == OAdd();
        offset ||= op == OSub();
    }
    var right_type = input;
    if offset {
        right_type = null;
        if sem_literal(c, right) {
            right_type = sem_type_new(c, SUSize(), 0, null);
        }
    }
    value.right = sem_operand(c, right, right_type);
    if !sem_ok(c) {
        return n;
    }
    if comparison {
        sem_set_type(&value.type, sem_type_new(c, SBool(), 0, null));
    }
    else {
        sem_set_type(&value.type, input);
    }
    if offset {
        sem_surface_integer(c, value.right);
        sem_surface_pointee(c, n, input);
    } else {
        var equality = op == OEq();
        equality ||= op == ONe();
        if !equality {
            if semantic_enum(input) {
                sem_fail(c, n, "Enum operations require equality or inequality");
            } else {
                sem_surface_integer(c, value.left);
            }
        }
    }
    return sem_surface_expected(c, n, expected_type);
}

fn sem_surface_place(c: SemanticContext*, n: void*): void* {
    n = sem_surface_unwrap(n);
    if sem_is(n, "CoreLocation") {
        return sem_location(c, n, 0);
    }
    var value: void* = null;
    var dereference = sem_is(n, "TowerExpression") && sem_member(n, "left") == null
    && sem_member(n, "right") != null && sem_equal(sem_tokens(c, sem_child(n, 0)), "*");
    if dereference {
        value = sem_surface(c, n, null);
    }
    else {
        value = sem_operand(c, n, null);
    }
    if !sem_ok(c) {
        return value;
    }
    var data = sem_get(value);
    var place = data.kind == KLoad();
    place ||= data.kind == KField();
    place ||= data.kind == KIndex();
    if !place {
        sem_fail(c, n, "Operator requires an addressable location");
    }
    return value;
}

fn sem_surface_operator(c: SemanticContext*, n: void*, left: void*): u8* {
    var index: usize = 0;
    if left != null {
        index = 1;
    }
    var op = sem_tokens(c, sem_child(n, index));
    if sem_equal(op, "not") {
        return "!";
    }
    if sem_equal(op, "compl") {
        return "~";
    }
    if sem_equal(op, "bitand") {
        return "&";
    }
    if sem_equal(op, "bitor") {
        return "|";
    }
    if sem_equal(op, "xor") {
        return "^";
    }
    if sem_equal(op, "and") {
        return "&&";
    }
    if sem_equal(op, "or") {
        return "||";
    }
    if sem_equal(op, "not_eq") {
        return "!=";
    }
    if sem_equal(op, "and_eq") {
        return "&=";
    }
    if sem_equal(op, "or_eq") {
        return "|=";
    }
    if sem_equal(op, "xor_eq") {
        return "^=";
    }
    return op;
}

// A discarded/comma-left expression may be void. Value contexts still use the
// ordinary operand checker, so a void branch cannot initialize a local or argument.
fn sem_surface_discard(c: SemanticContext*, n: void*): void* {
    n = sem_surface_unwrap(n);
    if sem_is(n, "CoreCall") {
        return sem_call(c, n);
    }
    var condition = sem_member(n, "condition");
    var comma = sem_is(n, "TowerComma") && sem_member(n, "left") != null;
    if condition == null && !comma {
        var result = sem_operand(c, n, null);
        // Bare and module-qualified names can grow into void calls, including
        // for updates. Holes inside operands or arguments still need values.
        if c.editor != null && c.editor.found && sem_is(n, "CoreLocation") {
            var bare_name = c.editor.node == sem_member(n, "name");
            var module_name = c.editor.node == n && c.editor.module != null;
            if bare_name || module_name {
                c.editor.value_required = false;
            }
        }
        return result;
    }
    c.surface_expressions = true;
    var kind = SurfaceSelect();
    if comma {
        kind = SurfaceComma();
    }
    var value = sem_node(c, n, kind);
    var left = sem_member(n, "body");
    var right = sem_member(n, "otherwise");
    if comma {
        left = sem_member(n, "left");
        right = sem_member(n, "right");
    } else {
        value.value = sem_operand(c, condition, sem_type_new(c, SBool(), 0, null));
    }
    value.left = sem_surface_discard(c, left);
    if !sem_ok(c) {
        return n;
    }
    value.right = sem_surface_discard(c, right);
    if !sem_ok(c) {
        return n;
    }
    var left_value = sem_get(value.left);
    var right_value = sem_get(value.right);
    if !comma && !semantic_type_equal(&left_value.type, &right_value.type) {
        sem_fail(c, n, "Conditional branches must have the same type");
    }
    sem_set_type(&value.type, &right_value.type);
    return n;
}

fn sem_surface(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    var original = n;
    n = sem_surface_unwrap(n);
    if n != original {
        return sem_operand(c, n, expected_type);
    }
    var existing = sem_get(n);
    if existing != null {
        return sem_surface_expected(c, n, expected_type);
    }
    c.surface_expressions = true;
    var group = sem_member(n, "value");
    if group != null {
        return sem_operand(c, group, expected_type);
    }
    var left = sem_member(n, "left");
    var right = sem_member(n, "right");
    var condition = sem_member(n, "condition");
    if condition != null {
        var value = sem_node(c, n, SurfaceSelect());
        value.value = sem_operand(c, condition, sem_type_new(c, SBool(), 0, null));
        var body = sem_member(n, "body");
        var otherwise = sem_member(n, "otherwise");
        var input = expected_type;
        if input == null && sem_literal(c, body) && !sem_literal(c, otherwise) {
            var known = sem_operand(c, otherwise, null);
            if !sem_ok(c) {
                return n;
            }
            input = &sem_get(known).type;
        }
        value.left = sem_operand(c, body, input);
        if !sem_ok(c) {
            return n;
        }
        value.right = sem_operand(c, otherwise, &sem_get(value.left).type);
        sem_set_type(&value.type, &sem_get(value.left).type);
        return sem_surface_expected(c, n, expected_type);
    }
    var op = sem_surface_operator(c, n, left);
    if sem_equal(op, ",") {
        var value = sem_node(c, n, SurfaceComma());
        value.left = sem_surface_discard(c, left);
        if !sem_ok(c) {
            return n;
        }
        value.right = sem_operand(c, right, expected_type);
        if sem_ok(c) {
            sem_set_type(&value.type, &sem_get(value.right).type);
        }
        return n;
    }
    var postfix = left != null;
    var increment = sem_equal(op, "++");
    var decrement = sem_equal(op, "--");
    var modify = increment;
    if decrement {
        modify = true;
    }
    if modify {
        var place = right;
        if postfix {
            place = left;
        }
        var value = sem_node(c, n, SurfaceModify());
        value.target = sem_surface_place(c, place);
        if !sem_ok(c) {
            return n;
        }
        sem_set_type(&value.type, &sem_get(value.target).type);
        var pointer = value.type.pointers != 0;
        if pointer {
            sem_surface_pointee(c, n, &value.type);
        }
        else {
            sem_surface_integer(c, value.target);
        }
        value.op = OAdd();
        if decrement {
            value.op = OSub();
        }
        value.indirect = postfix;
        return sem_surface_expected(c, n, expected_type);
    }
    if left == null {
        var missing = right == null;
        if missing {
            sem_fail(c, n, "A pointer type spelling cannot be used as a value");
            return n;
        }
        var address = sem_equal(op, "&");
        var load = sem_equal(op, "*");
        var indirect = address;
        if load {
            indirect = true;
        }
        if indirect {
            var kind = KLoad();
            if address {
                kind = KAddress();
            }
            var value = sem_node(c, n, kind);
            if address {
                value.value = sem_surface_place(c, right);
            }
            else {
                value.value = sem_operand(c, right, null);
            }
            if !sem_ok(c) {
                return n;
            }
            sem_set_type(&value.type, &sem_get(value.value).type);
            if address {
                value.type.pointers++;
            }
            else {
                if value.type.pointers == 0 {
                    sem_fail(c, n, "Load requires a pointer");
                }
                else {
                    value.type.pointers--;
                    if value.type.pointers == 0 && value.type.scalar == SVoid() {
                        sem_fail(c, n, "Cannot load a void pointer");
                    }
                    if semantic_aggregate(&value.type) {
                        sem_layout(c, value.type.record);
                    }
                }
            }
            return sem_surface_expected(c, n, expected_type);
        }
        var negate = sem_equal(op, "!");
        var input = expected_type;
        if negate {
            input = sem_type_new(c, SBool(), 0, null);
        }
        // Preserve the existing signed minimum literal/range contract.
        if sem_equal(op, "-") {
            var text = sem_tokens(c, right);
            var literal = text[0] != 0;
            for(var index: usize = 0; !(text[index] == 0); index++) {
                var digit = text[index] >= 48;
                digit &&= text[index] <= 57;
                if !digit {
                    literal = false;
                    break;
                }
            }
            if literal {
                return sem_operand_leaf(c, n, expected_type);
            }
        }
        var operand = sem_operand(c, right, input);
        if !sem_ok(c) {
            return n;
        }
        if !negate {
            sem_surface_integer(c, operand);
        }
        if sem_equal(op, "+") {
            return sem_surface_expected(c, operand, expected_type);
        }
        var value = sem_node(c, n, KBinary());
        sem_set_type(&value.type, &sem_get(operand).type);
        value.op = OSub();
        value.left = sem_surface_constant(c, n, &value.type, 0);
        value.right = operand;
        if negate {
            value.op = OEq();
        }
        if sem_equal(op, "~") {
            value.op = OXor();
            sem_get(value.left).bits = semantic_mask(&value.type);
        }
        return sem_surface_expected(c, n, expected_type);
    }
    var missing = right == null;
    if missing {
        sem_fail(c, n, "A pointer type spelling cannot be used as a value");
        return n;
    }
    var logical_and = sem_equal(op, "&&");
    var logical_or = sem_equal(op, "||");
    var logical = logical_and;
    if logical_or {
        logical = true;
    }
    if logical {
        var kind = SurfaceAnd();
        if logical_or {
            kind = SurfaceOr();
        }
        var value = sem_node(c, n, kind);
        var boolean = sem_type_new(c, SBool(), 0, null);
        value.left = sem_operand(c, left, boolean);
        value.right = sem_operand(c, right, boolean);
        sem_set_type(&value.type, boolean);
        return sem_surface_expected(c, n, expected_type);
    }
    var length = sem_length(op);
    var assignment = sem_equal(op, "=");
    var compound = sem_surface_compound(op);
    var assign = assignment;
    if compound {
        assign = true;
    }
    var operation = op;
    if compound {
        var count = length -1;
        operation = sem_text(c, op, count);
    }
    var shift_left = sem_equal(operation, "<<");
    var shift_right = sem_equal(operation, ">>");
    var shift_unsigned = sem_equal(operation, ">>>");
    var shift = shift_left;
    if shift_right {
        shift = true;
    }
    if shift_unsigned {
        shift = true;
    }
    var threeway = sem_equal(operation, "<=>");
    var code = sem_surface_code(operation);
    if !assign && code == SurfaceCoalesce() {
        var value = sem_node(c, n, SurfaceCoalesce());
        var infer = sem_equal(sem_tokens(c, left), "null") && expected_type == null;
        var input = expected_type;
        if infer {
            var known = sem_operand(c, right, null);
            if !sem_ok(c) {
                return n;
            }
            input = &sem_get(known).type;
        }
        value.left = sem_surface_nullable(c, left, input);
        if !sem_ok(c) {
            return n;
        }
        var first = sem_get(value.left);
        if !sem_surface_optional(first) && first.type.pointers == 0 {
            sem_fail(c, n, "Null coalescing requires a pointer or null-conditional access");
            return n;
        }
        value.right = sem_operand(c, right, &first.type);
        sem_set_type(&value.type, &first.type);
        return sem_surface_expected(c, n, expected_type);
    }
    if assign {
        var value = sem_node(c, n, SurfaceAssign());
        value.target = sem_surface_place(c, left);
        if !sem_ok(c) {
            return n;
        }
        sem_set_type(&value.type, &sem_get(value.target).type);
        value.op = SurfaceSet();
        var input = &value.type;
        if compound {
            value.op = code;
            var pointer = input.pointers != 0;
            if code == SurfaceAnd() || code == SurfaceOr() {
                if input.scalar != SBool() || pointer {
                    sem_fail(c, n, "Logical compound assignment requires bool operands");
                }
            } else {
                if code == SurfaceCoalesce() {
                    if !pointer {
                        sem_fail(c, n, "Null-coalescing assignment requires a pointer location");
                    }
                } else {
                    if pointer {
                        var offset = code == OAdd();
                        offset ||= code == OSub();
                        if offset {
                            sem_surface_pointee(c, n, input);
                            input = null;
                        }
                        else {
                            sem_fail(c, n, "Only += and -= (or ??=) apply to pointers");
                        }
                    } else {
                        sem_surface_integer(c, value.target);
                    }
                    if shift {
                        input = null;
                    }
                }
            }
        }
        value.value = sem_operand(c, right, input);
        if sem_ok(c) {
            if input == null {
                sem_surface_integer(c, value.value);
            }
        }
        return sem_surface_expected(c, n, expected_type);
    }
    var special = shift;
    if threeway {
        special = true;
    }
    if special {
        var kind = SurfaceShift();
        if threeway {
            kind = SurfaceCompare();
        }
        var value = sem_node(c, n, kind);
        var input = expected_type;
        if threeway {
            input = null;
        }
        value.left = sem_operand(c, left, input);
        if !sem_ok(c) {
            return n;
        }
        sem_surface_integer(c, value.left);
        input = null;
        if threeway {
            input = &sem_get(value.left).type;
        }
        value.right = sem_operand(c, right, input);
        if !sem_ok(c) {
            return n;
        }
        sem_surface_integer(c, value.right);
        value.op = code;
        sem_set_type(&value.type, &sem_get(value.left).type);
        if threeway {
            sem_set_type(&value.type, sem_type_new(c, SI32(), 0, null));
        }
        return sem_surface_expected(c, n, expected_type);
    }
    return sem_surface_binary(c, n, left, right, code, expected_type);
}

import tower;
import inspection_policy;
import semantic_context;
import semantic_support;
import semantic_statements;
import semantic_types;
import semantic_modules;
import semantic_generic_values;
import .library.vector;

// Optional, disposable analysis on the original shared entities. The annotation
// is the actual type-expression tree, whose name leaves bind to declarations;
// it is not a second type language or a partially instantiated Foundation graph.
enum GenericInfoKind: u32 {
    Function, Constructor, TypeParameter, ConstantParameter, Parameter,
    Structure, Field, Variable, TypeExpression, Return,
    Member, Index, Binary, Value, Load, Assignment
}

enum GenericShapeState: u32 {
    Uninspected, Fixed, Unknown
}

// Query-local substitutions bind declaration entities to existing argument
// trees. They are a view of the shared graph, not another type representation.
struct GenericBinding {
    parameter: void*;
    argument: void*;
    bindings: GenericBinding*;
    next: GenericBinding*;
}

struct GenericInfo {
    kind: GenericInfoKind;
    definition: void*;
    declaration: void*;
    annotation: void*;
    resolved: void*;
    dependent: bool;
    bindings: GenericBinding*;
    shape_state: GenericShapeState;
    fixed_record: void*;
}

struct GenericAnalysis {
    context: SemanticContext*;
    component: void*;
    definition: void*;
    constructor: bool;
    resolve_types: bool;
    budget: usize;
    truncated: bool;
}

fn generic_info(node: void*, component: void*): GenericInfo* {
    if node == null {
        return null;
    }
    return bits(GenericInfo*, entity_component_data(entity_component_get(node, component)));
}

fn generic_info_add(a: GenericAnalysis*, node: void*, declaration: void*, kind: GenericInfoKind): GenericInfo* {
    var result = bits(GenericInfo*, entity_component_data(entity_component_add(node, a.component)));
    var allocated = result != null;
    sem_require(allocated);
    fill(result, 0, sizeof(GenericInfo));
    result.kind = kind;
    result.definition = a.definition;
    result.declaration = declaration;
    result.annotation = sem_member(declaration, "type");
    return result;
}

fn generic_info_bind(a: GenericAnalysis*, node: void*, declaration: void*): void {
    var meaning = generic_info(declaration, a.component);
    if meaning == null {
        return;
    }
    var result = generic_info_add(a, node, declaration, meaning.kind);
    copy(result, meaning, sizeof(GenericInfo));
}

fn generic_info_lookup(scope: SemanticScope*, name: u8*): void* {
    while scope != null {
        var found = sem_lookup_table(scope.names, name);
        if found != null {
            return found;
        }
        scope = scope.parent;
    }
    return null;
}

fn generic_info_name(a: GenericAnalysis*, scope: SemanticScope*, node: void*): void {
    var name = sem_member(node, "name");
    if name != null {
        // Duplicate/invalid unused bodies remain for ordinary instantiation to
        // diagnose. Never make a failed speculative check a document error.
        sem_put(a.context, scope.names, sem_identifier(a.context, name), node);
    }
}

fn generic_info_dependent(node: void*, component: void*, depth: usize): bool {
    var next = depth + 1;
    if node == null {
        return false;
    }
    if depth == InspectionDepthLimit() {
        return true;
    }
    var meaning = generic_info(node, component);
    if meaning != null {
        if meaning.kind == GenericInfoKind.TypeParameter {
            return true;
        }
        if meaning.kind == GenericInfoKind.ConstantParameter {
            return true;
        }
        if meaning.kind == GenericInfoKind.Structure {
            return true;
        }
    }
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        if generic_info_dependent(sem_child(node, i), component, next) {
            return true;
        }
    }
    return false;
}

fn generic_info_type(a: GenericAnalysis*, meaning: GenericInfo*): void {
    var annotation = meaning.annotation;
    if annotation == null {
        return;
    }
    meaning.dependent = generic_info_dependent(annotation, a.component, 0);
    if meaning.dependent {
        return;
    }
    // A failed check may leave a named type with an unfinished layout in the
    // ordinary registry. Its written annotation/bindings remain useful, but
    // querying that partial registry must not turn zeroed fields into a layout.
    if !a.resolve_types {
        return;
    }
    if sem_equal(sem_tokens(a.context, annotation), "type") {
        return;
    }
    var type = sem_type(a.context, annotation);
    if sem_ok(a.context) {
        meaning.resolved = sem_type_entity(a.context, type);
    }
    a.context.program.error.length = 0;
}

fn generic_info_walk(a: GenericAnalysis*, node: void*, values: SemanticScope*, types: SemanticScope*, depth: usize): void {
    var next = depth + 1;
    if node == null {
        return;
    }
    if depth == InspectionDepthLimit() {
        a.truncated = true;
        return;
    }
    if a.budget == 0 {
        a.truncated = true;
        return;
    }
    a.budget--;
    var c = a.context;
    var declaration = generic_info(node, a.component);
    var name: void* = null;
    if sem_is(node, "CoreStruct") {
        declaration = generic_info_add(a, node, node, GenericInfoKind.Structure);
        declaration.dependent = true;
        generic_info_name(a, types, node);
        name = sem_member(node, "name");
    }
    if sem_is(node, "CoreField") {
        declaration = generic_info_add(a, node, node, GenericInfoKind.Field);
        name = sem_member(node, "name");
    }
    var local = sem_is(node, "CoreDeclare");
    if local {
        declaration = generic_info_add(a, node, node, GenericInfoKind.Variable);
        name = sem_member(node, "name");
    }
    if sem_is(node, "CoreParameter") {
        name = sem_member(node, "name");
    }
    if node == a.definition {
        name = sem_member(node, "name");
    }
    if sem_is(node, "CoreType") {
        declaration = generic_info_add(a, node, node, GenericInfoKind.TypeExpression);
        declaration.annotation = node;
    }
    if sem_is(node, "CoreReturn") {
        declaration = generic_info_add(a, node, a.definition, GenericInfoKind.Return);
    }
    // Bind names by their semantic tree roles, not token spelling. In particular
    // a member name is never mistaken for a same-named parameter or local.
    var reference: void* = null;
    var type_name = sem_is(node, "CoreTypeName");
    var location = sem_is(node, "CoreLocation");
    var reference_role = type_name;
    if location {
        reference_role = true;
    }
    if reference_role {
        if sem_member(node, "base") == null {
            reference = sem_member(node, "name");
        }
    }
    if sem_is(node, "CoreArrayCount") {
        reference = node;
    }
    if reference != null {
        var text = sem_identifier(c, reference);
        var binding: void* = null;
        if type_name {
            binding = generic_info_lookup(types, text);
            // A type application's argument can name a compile-time integer.
            if binding == null {
                var value = generic_info_lookup(values, text);
                var meaning = generic_info(value, a.component);
                var constant = meaning != null;
                constant &&= meaning.kind == GenericInfoKind.ConstantParameter;
                if constant {
                    binding = value;
                }
            }
        }
        else {
            binding = generic_info_lookup(values, text);
            if binding == null {
                binding = generic_info_lookup(types, text);
            }
        }
        if binding != null {
            generic_info_bind(a, node, binding);
        }
    }
    if sem_is(node, "CoreBlock") {
        values = sem_scope(c, values);
        types = sem_scope(c, types);
    }
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        var child = sem_child(node, i);
        if child != name {
            generic_info_walk(a, child, values, types, next);
        }
    }
    if declaration != null {
        generic_info_type(a, declaration);
        if name != null {
            generic_info_bind(a, name, node);
        }
    }
    // Local scope begins after the initializer, preserving lexical shadowing.
    if local {
        generic_info_name(a, values, node);
    }
}

// Query clients opt into this pass; executable compilation still checks each
// concrete instance normally. Type/value bindings stay on the source entities.
fn sem_generic_inspect(c: SemanticContext*, resolve_types: bool, truncated: bool*): void* {
    var component = sem_create(c.program.root);
    sem_require(entity_register(component, sizeof(GenericInfo), alignof(GenericInfo), 0));
    var a: GenericAnalysis;
    a.context = c;
    a.component = component;
    a.resolve_types = resolve_types;
    a.budget = InspectionNodeLimit();
    a.truncated = false;
    var i: usize = 0;
    for(; i < c.template_nodes.length; i++) {
        var definition = c.template_nodes.data[i];
        a.definition = definition;
        a.constructor = sem_equal(sem_tokens(c, sem_member(definition, "type")), "type");
        var kind = GenericInfoKind.Function;
        if a.constructor {
            kind = GenericInfoKind.Constructor;
        }
        generic_info_add(&a, definition, definition, kind);
        var values = sem_scope(c, null);
        var types = sem_scope(c, null);
        var parameters = sem_collect(c, sem_member(definition, "params"), "CoreParameter");
        var p: usize = 0;
        for(; p < parameters.length; p++) {
            var parameter = parameters.data[p];
            var parameter_kind = GenericInfoKind.Parameter;
            if a.constructor {
                parameter_kind = GenericInfoKind.ConstantParameter;
            }
            var is_type = generic_type_parameter(c.generics, definition, p);
            if is_type {
                parameter_kind = GenericInfoKind.TypeParameter;
            }
            generic_info_add(&a, parameter, parameter, parameter_kind);
            if is_type {
                generic_info_name(&a, types, parameter);
            }
            else {
                generic_info_name(&a, values, parameter);
            }
        }
        generic_info_walk(&a, definition, values, types, 0);
    }
    // Bind every definition before following type applications. This preserves
    // module forward references and makes inspection independent of file order.
    i = 0;
    for(; i < c.template_nodes.length; i++) {
        a.definition = c.template_nodes.data[i];
        generic_value_walk(&a, a.definition, 0);
    }
    *truncated = a.truncated;
    return component;
}

import tower;
import semantic_generic_info;
import semantic_context;
import semantic_support;
import semantic_types;
