extern fn compiler_clone_tree(source: void*, limit: usize, copied: usize*): void*;

fn generic_step(a: GenericAnalysis*, depth: usize): bool {
    if depth >= InspectionDepthLimit() {
        a.truncated = true;
        return false;
    }
    if a.budget == 0 {
        a.truncated = true;
        return false;
    }
    a.budget--;
    return true;
}

fn generic_view(a: GenericAnalysis*, annotation: void*, bindings: GenericBinding*): GenericInfo* {
    var result = bits(GenericInfo*, sem_allocate(a.context, sizeof(GenericInfo)));
    fill(result, 0, sizeof(GenericInfo));
    result.kind = GenericInfoKind.TypeExpression;
    result.annotation = annotation;
    result.bindings = bindings;
    return result;
}

fn generic_view_copy(result: GenericInfo*, source: GenericInfo*): void {
    if source == null {
        return;
    }
    result.annotation = source.annotation;
    result.bindings = source.bindings;
    result.resolved = source.resolved;
    result.dependent = source.dependent;
}

fn generic_unwrap(node: void*): void* {
    loop {
        if sem_child_count(node) != 1 {
            return node;
        }
        // Unnamed single-child relationships are transparent, including the
        // parser's generated optional-capture wrappers. Named roles retain the
        // semantic node (e.g. a location's name or a type's base).
        var role = entity_child_name(node, 0);
        var named = role != null;
        named &&= role[0] != 0;
        if named {
            return node;
        }
        node = sem_child(node, 0);
    }
}

fn generic_literal(a: GenericAnalysis*, node: void*): bool {
    node = generic_unwrap(node);
    if node == null {
        return false;
    }
    if sem_is(node, "CoreBinary") {
        return false;
    }
    if sem_is(node, "TowerExpression") {
        return false;
    }
    if sem_is(node, "TowerComma") {
        return false;
    }
    if sem_is(node, "CoreLocation") {
        return false;
    }
    if sem_is(node, "CoreCall") {
        return false;
    }
    if sem_is(node, "CoreAddress") {
        return false;
    }
    if sem_is(node, "CoreLoad") {
        return false;
    }
    return sem_literal(a.context, node);
}

fn generic_binding(a: GenericAnalysis*, node: void*, bindings: GenericBinding*): GenericBinding* {
    var original = generic_info(node, a.component);
    var candidate = bindings;
    if original != null {
        while candidate != null {
            if candidate.parameter == original.declaration {
                return candidate;
            }
            candidate = candidate.next;
        }
    }
    node = generic_unwrap(node);
    if sem_is(node, "CoreType") {
        if sem_member(node, "base") != null {
            return null;
        }
        if sem_child_count(node) != 1 {
            return null;
        }
        node = sem_member(node, "name");
    }
    var info = generic_info(node, a.component);
    if info == null {
        return null;
    }
    while bindings != null {
        if bindings.parameter == info.declaration {
            return bindings;
        }
        bindings = bindings.next;
    }
    return null;
}

fn generic_normalize(a: GenericAnalysis*, view: GenericInfo*, depth: usize): void {
    for(; view.annotation != null; depth++) {
        if !generic_step(a, depth) {
            return;
        }
        view.annotation = generic_unwrap(view.annotation);
        var binding = generic_binding(a, view.annotation, view.bindings);
        if binding == null {
            return;
        }
        view.annotation = binding.argument;
        view.bindings = binding.bindings;
    }
}

fn generic_view_dependent(a: GenericAnalysis*, node: void*, bindings: GenericBinding*, depth: usize): bool {
    if node == null {
        return false;
    }
    if !generic_step(a, depth) {
        return true;
    }
    var next = depth + 1;
    var binding = generic_binding(a, node, bindings);
    if binding != null {
        return generic_view_dependent(a, binding.argument, binding.bindings, next);
    }
    var info = generic_info(node, a.component);
    if info != null {
        if info.kind == GenericInfoKind.TypeParameter {
            return true;
        }
        if info.kind == GenericInfoKind.ConstantParameter {
            return true;
        }
        if info.kind == GenericInfoKind.Structure {
            return true;
        }
    }
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        if generic_view_dependent(a, sem_child(node, i), bindings, next) {
            return true;
        }
    }
    return false;
}

fn generic_resolve_view(a: GenericAnalysis*, view: GenericInfo*, depth: usize): void {
    generic_normalize(a, view, depth);
    view.resolved = null;
    view.dependent = generic_view_dependent(a, view.annotation, view.bindings, depth);
    if view.dependent {
        return;
    }
    // After a document error, only the already registered primitive type
    // objects are trustworthy. Never query or expose unfinished nominal layouts.
    if !a.resolve_types {
        view.resolved = generic_primitive(a, view.annotation);
        return;
    }
    if view.annotation == null {
        return;
    }
    var substitutions = generic_format_substitutions(a, view.annotation, view.bindings, depth);
    if substitutions != null {
        return;
    }
    var type = sem_type(a.context, view.annotation);
    if sem_ok(a.context) {
        view.resolved = sem_type_entity(a.context, type);
    }
    a.context.program.error.length = 0;
}

fn generic_primitive(a: GenericAnalysis*, node: void*): void* {
    if !sem_is(node, "CoreType") {
        return null;
    }
    if !(sem_child_count(node) == 1) {
        return null;
    }
    var name = sem_member(node, "name");
    var found = sem_resolve(a.context, a.context.types, name, sem_identifier(a.context, name));
    a.context.program.error.length = 0;
    var value = sem_get(found);
    if value == null {
        return null;
    }
    var primitive = value.kind == KType();
    primitive &&= value.type.record == null;
    if primitive {
        return found;
    }
    return null;
}

// Accept only a fixed record returned directly by a type function: declarations
// followed by one return. No speculative execution, branch selection, effects,
// or first-specialization fallback. More general type programs remain unknown.
fn generic_record_result(a: GenericAnalysis*, definition: void*): void* {
    var meaning = generic_info(definition, a.component);
    if meaning == null {
        return null;
    }
    if meaning.shape_state != GenericShapeState.Uninspected {
        return meaning.fixed_record;
    }
    meaning.shape_state = GenericShapeState.Unknown;
    var statements = sem_collect(a.context, sem_member(definition, "body"), "Statement");
    var record: void* = null;
    var i: usize = 0;
    for(; i < statements.length; i++) {
        var node = generic_unwrap(statements.data[i]);
        var after = i + 1;
        if after == statements.length {
            if !sem_is(node, "CoreReturn") {
                return null;
            }
            var value = generic_unwrap(sem_member(node, "value"));
            var info = generic_info(value, a.component);
            if info == null {
                return null;
            }
            if info.kind != GenericInfoKind.Structure {
                return null;
            }
            record = info.declaration;
        } else {
            if !sem_is(node, "CoreStruct") {
                return null;
            }
        }
    }
    // The returned declaration must be one of those direct declarations.
    i = 0;
    for(; i < statements.length; i++) {
        if generic_unwrap(statements.data[i]) == record {
            meaning.shape_state = GenericShapeState.Fixed;
            meaning.fixed_record = record;
            return record;
        }
    }
    return null;
}

fn generic_record(a: GenericAnalysis*, source: GenericInfo*, depth: usize): GenericInfo* {
    if source == null {
        return null;
    }
    if !generic_step(a, depth) {
        return null;
    }
    var view = generic_view(a, source.annotation, source.bindings);
    generic_normalize(a, view, depth);
    var node = view.annotation;
    // Member access permits exactly one pointer indirection, as sem_location does.
    if sem_is(node, "CoreType") {
        var base = sem_member(node, "base");
        if base != null {
            if sem_member(node, "count") != null {
                return null;
            }
            view.annotation = base;
            generic_normalize(a, view, depth);
            node = view.annotation;
            if sem_member(node, "base") != null {
                return null;
            }
        }
    }
    var name = sem_member(node, "name");
    if name == null {
        return null;
    }
    if sem_child_count(node) > 1 {
        var definition = sem_resolve(a.context, a.context.type_functions, name, sem_identifier(a.context, name));
        a.context.program.error.length = 0;
        if definition == null {
            return null;
        }
        var record = generic_record_result(a, definition);
        if record == null {
            return null;
        }
        var parameters = sem_collect(a.context, sem_member(definition, "params"), "CoreParameter");
        var arguments = sem_collect(a.context, sem_member(node, "args"), "CoreTypeArgument");
        if parameters.length != arguments.length {
            return null;
        }
        var bindings: GenericBinding* = null;
        for(var i: usize = 0; i < parameters.length; i++) {
            var binding = bits(GenericBinding*, sem_allocate(a.context, sizeof(GenericBinding)));
            binding.parameter = parameters.data[i];
            binding.argument = arguments.data[i];
            binding.bindings = view.bindings;
            binding.next = bindings;
            bindings = binding;
        }
        return generic_view(a, record, bindings);
    }
    var meaning = generic_info(name, a.component);
    if meaning != null {
        if meaning.kind == GenericInfoKind.Structure {
            return generic_view(a, meaning.declaration, view.bindings);
        }
    }
    var record = sem_resolve(a.context, a.context.types, name, sem_identifier(a.context, name));
    a.context.program.error.length = 0;
    if sem_is(record, "CoreStruct") {
        return generic_view(a, record, view.bindings);
    }
    return null;
}

fn generic_member(a: GenericAnalysis*, node: void*, source: GenericInfo*, depth: usize): void {
    var info = generic_info_add(a, node, node, GenericInfoKind.Member);
    var record = generic_record(a, source, depth);
    if record == null {
        return;
    }
    var name = sem_identifier(a.context, sem_member(node, "field"));
    var fields = sem_collect(a.context, sem_member(record.annotation, "fields"), "CoreField");
    var field: void* = null;
    for(var i: usize = 0; i < fields.length; i++) {
        var candidate = fields.data[i];
        if sem_equal(name, sem_identifier(a.context, sem_member(candidate, "name"))) {
            if field != null {
                return;
            }
            field = candidate;
        }
    }
    if field == null {
        return;
    }
    info.kind = GenericInfoKind.Field;
    info.declaration = field;
    info.annotation = sem_member(field, "type");
    info.bindings = record.bindings;
    generic_resolve_view(a, info, depth);
    generic_info_bind(a, sem_member(node, "field"), node);
}

fn generic_element(a: GenericAnalysis*, info: GenericInfo*, source: GenericInfo*, depth: usize): void {
    if source == null {
        return;
    }
    var view = generic_view(a, source.annotation, source.bindings);
    generic_normalize(a, view, depth);
    var indexing = info.kind == GenericInfoKind.Index;
    if sem_is(view.annotation, "CoreType") {
        var base = sem_member(view.annotation, "base");
        if base != null {
            var array = sem_member(view.annotation, "count") != null;
            if array {
                if !indexing {
                    return;
                }
            }
            info.annotation = base;
            info.bindings = view.bindings;
            generic_resolve_view(a, info, depth);
            return;
        }
    }
    if source.resolved == null {
        return;
    }
    var resolved = sem_get(source.resolved);
    var type = sem_type_copy(a.context, &resolved.type);
    if type.pointers != 0 {
        type.pointers--;
    } else {
        if !indexing {
            return;
        }
        if type.scalar != SArray() {
            return;
        }
        var array = sem_get(type.record);
        type = &array.element;
    }
    info.resolved = sem_type_entity(a.context, type);
}

// Reuse the ordinary checker for concrete subexpressions. Only the temporary
// cloned query subtree receives Foundation components; original template nodes
// retain their symbolic metadata and are never partly lowered or executed.
fn generic_expression_seed(a: GenericAnalysis*, source: void*, copy: void*, depth: usize): bool {
    if !generic_step(a, depth) {
        return false;
    }
    if generic_literal(a, source) {
        return true;
    }
    if sem_is(source, "CoreLocation") {
        var info = generic_info(source, a.component);
        if info == null {
            return false;
        }
        if info.resolved == null {
            return false;
        }
        var value = sem_attach(copy, KOperand());
        var resolved = sem_get(info.resolved);
        sem_set_type(&value.type, &resolved.type);
        return true;
    }
    if sem_is(source, "CoreCall") {
        return false;
    }
    var i: usize = 0;
    var next = depth + 1;
    for(; i < sem_child_count(source); i++) {
        if !generic_expression_seed(a, sem_child(source, i), sem_child(copy, i), next) {
            return false;
        }
    }
    return true;
}

fn generic_expression_result(a: GenericAnalysis*, source: void*, copy: void*, depth: usize): void {
    if !generic_step(a, depth) {
        return;
    }
    var value = sem_get(copy);
    if value != null {
        var info = generic_info(source, a.component);
        if info != null {
            info.resolved = sem_type_entity(a.context, &value.type);
            info.dependent = false;
        }
    }
    var i: usize = 0;
    var next = depth + 1;
    for(; i < sem_child_count(source); i++) {
        generic_expression_result(a, sem_child(source, i), sem_child(copy, i), next);
    }
}

fn generic_expression_check(a: GenericAnalysis*, node: void*, expected_type: void*, depth: usize): void {
    node = generic_unwrap(node);
    var eligible = sem_is(node, "CoreBinary");
    if sem_is(node, "TowerExpression") {
        eligible = true;
    }
    if sem_is(node, "TowerComma") {
        eligible = true;
    }
    if generic_literal(a, node) {
        eligible = true;
    }
    if !eligible {
        return;
    }
    var copied: usize = 0;
    var clone = compiler_clone_tree(node, a.budget, &copied);
    a.budget = a.budget - copied;
    if clone == null {
        a.truncated = true;
        return;
    }
    if generic_expression_seed(a, node, clone, depth) {
        var type: FoundationType* = null;
        if expected_type != null {
            var resolved = sem_get(expected_type);
            type = &resolved.type;
        }
        var result: void* = null;
        if sem_is(node, "CoreBinary") {
            result = sem_expression(a.context, clone, type);
        } else {
            result = sem_operand(a.context, clone, type);
        }
        if sem_ok(a.context) {
            generic_expression_result(a, node, clone, depth);
            var info = generic_info(node, a.component);
            if info != null {
                if result != null {
                    var resolved = sem_get(result);
                    info.resolved = sem_type_entity(a.context, &resolved.type);
                }
            }
        }
        a.context.program.error.length = 0;
    }
    entity_release(clone);
}

fn generic_value_walk(a: GenericAnalysis*, node: void*, depth: usize): void {
    if node == null {
        return;
    }
    if !generic_step(a, depth) {
        return;
    }
    var next = depth + 1;
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        generic_value_walk(a, sem_child(node, i), next);
    }
    var info = generic_info(node, a.component);
    if info != null {
        var reference = info.kind == GenericInfoKind.Variable;
        if info.kind == GenericInfoKind.Parameter {
            reference = true;
        }
        if reference {
            if info.declaration != node {
                generic_view_copy(info, generic_info(info.declaration, a.component));
            }
        }
    }
    if sem_is(node, "CoreLocation") {
        var base = sem_member(node, "base");
        if base != null {
            var source = generic_info(base, a.component);
            if sem_member(node, "index") != null {
                info = generic_info_add(a, node, node, GenericInfoKind.Index);
                generic_element(a, info, source, next);
            } else {
                generic_member(a, node, source, next);
            }
        }
    }
    if sem_is(node, "CoreLoad") {
        info = generic_info_add(a, node, node, GenericInfoKind.Load);
        generic_element(a, info, generic_info(sem_member(node, "name"), a.component), next);
    }
    if sem_is(node, "CoreBinary") {
        generic_info_add(a, node, node, GenericInfoKind.Binary);
        generic_expression_check(a, node, null, next);
    }
    if sem_is(node, "TowerExpression") {
        var left = sem_member(node, "left");
        var right = sem_member(node, "right");
        if left != null && right != null {
            var op = sem_surface_operator(a.context, node, left);
            var assignment = sem_equal(op, "=") || sem_surface_compound(op);
            var kind = GenericInfoKind.Binary;
            if assignment {
                kind = GenericInfoKind.Assignment;
            }
            info = generic_info_add(a, node, node, kind);
            if assignment {
                generic_view_copy(info, generic_info(left, a.component));
            }
            generic_expression_check(a, node, null, next);
        } else {
            if sem_child_count(node) != 1 {
                info = generic_info_add(a, node, node, GenericInfoKind.Value);
                if left == null && right != null && sem_equal(sem_surface_operator(a.context, node, null), "*") {
                    info.kind = GenericInfoKind.Load;
                    generic_element(a, info, generic_info(right, a.component), next);
                }
                generic_expression_check(a, node, null, next);
            }
        }
    }
    var wrapper = sem_is(node, "CoreOperand");
    if sem_is(node, "TowerExpression") {
        wrapper = true;
    }
    if sem_is(node, "TowerComma") {
        wrapper = true;
    }
    if sem_is(node, "CoreValue") {
        wrapper = true;
    }
    if wrapper {
        if generic_literal(a, node) {
            var bare = generic_unwrap(node);
            generic_info_add(a, bare, bare, GenericInfoKind.Value);
            generic_expression_check(a, bare, null, next);
            if bare != node {
                generic_info_bind(a, node, bare);
            }
        } else {
            if sem_child_count(node) == 1 {
                generic_info_bind(a, node, sem_child(node, 0));
            }
        }
    }
    if sem_is(node, "CoreTarget") {
        var name = sem_member(node, "name");
        if sem_child_count(node) == 1 {
            generic_info_bind(a, node, name);
        } else {
            info = generic_info_add(a, node, node, GenericInfoKind.Assignment);
            generic_element(a, info, generic_info(name, a.component), next);
        }
    }
    if sem_is(node, "CoreAssign") {
        info = generic_info_add(a, node, node, GenericInfoKind.Assignment);
        var target = generic_info(sem_member(node, "target"), a.component);
        generic_view_copy(info, target);
        generic_expression_check(a, sem_member(node, "value"), info.resolved, next);
    }
    if sem_is(node, "CoreDeclare") {
        var value = sem_member(node, "value");
        info = generic_info(node, a.component);
        generic_expression_check(a, value, info.resolved, next);
        if info.annotation == null {
            generic_view_copy(info, generic_info(generic_unwrap(value), a.component));
            generic_info_bind(a, sem_member(node, "name"), node);
        }
    }
}

fn generic_format_substitutions(a: GenericAnalysis*, node: void*, bindings: GenericBinding*, depth: usize): FormatSubstitution* {
    if node == null {
        return null;
    }
    if bindings == null {
        return null;
    }
    if !generic_step(a, depth) {
        return null;
    }
    var next = depth + 1;
    // The list formatter skips transparent wrappers. Bind the actual type/name
    // or count entity it visits, rather than a generated list/capture parent.
    var bindable = sem_is(node, "CoreType");
    if sem_is(node, "CoreTypeName") {
        bindable = true;
    }
    if sem_is(node, "CoreArrayCount") {
        bindable = true;
    }
    var binding: GenericBinding* = null;
    if bindable {
        binding = generic_binding(a, node, bindings);
    }
    if binding != null {
        var result = bits(FormatSubstitution*, sem_allocate(a.context, sizeof(FormatSubstitution)));
        result.node = node;
        result.replacement = binding.argument;
        result.nested = generic_format_substitutions(a, binding.argument, binding.bindings, next);
        result.next = null;
        return result;
    }
    var result: FormatSubstitution* = null;
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        var child = generic_format_substitutions(a, sem_child(node, i), bindings, next);
        if child != null {
            var last = child;
            while last.next != null {
                last = last.next;
            }
            last.next = result;
            result = child;
        }
    }
    return result;
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_support;
import semantic_types;
import .library.vector;
import .library.work_graph;

const LayoutQuery: u32 = 1;
const LayoutMaximumBytes: usize = 4194304;

extern fn entity_view_open(anchor: void*): void*;

extern fn entity_view_close(view: void*): void;

// A layout kernel reads completed dependency layouts and writes only its type
// and field offsets. Discovery/scheduling is shared work-graph infrastructure.
// No graph traversal, recursion or dependency allocation belongs in this kernel.
fn sem_layout_compute(c: SemanticContext*, n: void*): void {
    var t = sem_get(n);
    t.size = 0;
    t.alignment = 1;
    if semantic_enum(&t.type) {
        t.size = semantic_size(&t.element);
        t.alignment = semantic_alignment(&t.element);
        return;
    }
    if t.type.scalar == SArray() {
        var size = semantic_size(&t.element);
        var empty = t.length == 0;
        if empty {
            sem_fail(c, n, "An array needs a positive length");
            return;
        }
        var limit = LayoutMaximumBytes() / t.length;
        var large = size > limit;
        if large {
            sem_fail(c, n, "Array storage exceeds 4 MiB");
            return;
        }
        t.size = size * t.length;
        t.alignment = semantic_alignment(&t.element);
        return;
    }
    var i: usize = 0;
    for(; i < t.items.length; i++) {
        var field = t.items.data[i];
        var value = sem_get(field);
        var alignment = semantic_alignment(&value.type);
        if alignment > t.alignment {
            t.alignment = alignment;
        }
        value.byte_offset = sem_round(t.size, alignment);
        var bytes = semantic_size(&value.type);
        var maximum = LayoutMaximumBytes() -value.byte_offset;
        var large = bytes > maximum;
        if large {
            sem_fail(c, field, "Foundation struct storage exceeds 4 MiB");
            return;
        }
        t.size = value.byte_offset + bytes;
    }
    t.size = sem_round(t.size, t.alignment);
    var empty = t.size == 0;
    if empty {
        t.size = 1;
    }
}

fn sem_layout_dependency(c: SemanticContext*, consumer: usize, type: FoundationType*): void {
    if semantic_aggregate(type) {
        var dependency = work_request(&c.layout_work, type.record, LayoutQuery(), 0);
        var present = dependency != 0;
        sem_require(present);
        sem_require(work_depend(&c.layout_work, consumer, dependency));
    }
}

fn sem_layout(c: SemanticContext*, n: void*): void {
    if !sem_ok(c) {
        return;
    }
    var g = &c.layout_work;
    var first = g.tasks.length;
    var root = work_request(g, n, LayoutQuery(), 0);
    var present = root != 0;
    sem_require(present);
    var task = work_task(g, root);
    var complete = task.state == WorkState.Succeeded;
    if complete {
        return;
    }
    // Work discovered while scanning is appended to this compact list. Each
    // layout and each by-value edge is indexed once for the whole compilation.
    // Pointer fields do not demand pointee layout, so recursive pointers work.
    var i = first;
    for(; i < g.tasks.length; i++) {
        var id = i + 1;
        task = work_task(g, id);
        var type = sem_get(task.subject);
        if type.type.scalar == SArray() {
            sem_layout_dependency(c, id, &type.element);
        } else {
            if !semantic_enum(&type.type) {
                var j: usize = 0;
                for(; j < type.items.length; j++) {
                    var field = sem_get(type.items.data[j]);
                    sem_layout_dependency(c, id, &field.type);
                }
            }
        }
        sem_require(work_seal(g, id));
    }
    sem_require(work_demand(g, root));
    // The coordinator owns this view until all admitted kernels have joined.
    // Discovery is complete: kernels may update their declared layout payloads,
    // but cannot invalidate query indexes or reclaim their borrowed entities.
    var view = entity_view_open(n);
    var pinned = view != null;
    sem_require(pinned);
    var ticket: WorkTicket;
    while work_take(g, &ticket) {
        task = work_task(g, ticket.task);
        sem_layout_compute(c, task.subject);
        var success = sem_ok(c);
        sem_require(work_finish(g, &ticket, success));
        if !success {
            entity_view_close(view);
            return;
        }
    }
    entity_view_close(view);
    task = work_task(g, root);
    complete = task.state == WorkState.Succeeded;
    if complete {
        return;
    }
    var cycle: vector(usize);
    vector_init(usize, &cycle);
    var found = work_cycle(g, root, &cycle);
    sem_require(work_ok(g));
    var chain: u8* = "";
    if found {
        i = 0;
        for(; i < cycle.length; i++) {
            task = work_task(g, cycle.data[i]);
            var value = sem_get(task.subject);
            if i != 0 {
                chain = sem_cat(c, chain, " -> ");
            }
            chain = sem_cat(c, chain, sem_name(value));
        }
    }
    vector_dispose(usize, &cycle);
    sem_fail(c, n, sem_cat(c, "Recursive by-value layout: ", sem_cat(c, chain, "; use a pointer")));
}

import semantic_program_types;
import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_definitions;
import semantic_statements;
import semantic_defer;
import semantic_support;
import semantic_expression_lowering;
import .library.stack;
import .library.vector;
import .library.work_graph;

// Semantic compiler over shared Foundation components.
// Temporary indexes and scratch allocations are scoped to one compilation.

fn sem_track(c: SemanticContext*, data: u8*): void {
    var step1 = bits(void*, data);
    sem_require(vector_push(void*, &c.allocations, step1));
}

fn sem_context_init(c: SemanticContext*, program: SemanticProgram*): void {
    var step1 = sizeof(SemanticContext);
    fill(c, 0, step1);
    c.program = program;
    c.current = program.root;
    c.node_limit = SemanticComponentBudgetBytes() / sizeof(FoundationNode);
    var step2 = sem_table(c);
    c.functions = step2;
    var step3 = sem_table(c);
    c.types = step3;
    var step4 = sem_table(c);
    c.globals = step4;
    var step5 = sem_table(c);
    c.templates = step5;
    var step6 = sem_table(c);
    c.type_functions = step6;
    var step7 = sem_table(c);
    c.type_results = step7;
    var step8 = sem_table(c);
    c.source_names = step8;
    var step9 = sem_table(c);
    c.source_bases = step9;
    c.output_names = sem_table(c);
    var step10 = sem_table(c);
    c.fields_done = step10;
    work_init(&c.layout_work, 1, convert(u64, program.pointer_bytes));
    var step12 = sem_table(c);
    c.declaration_state = step12;
    var step13 = sem_scope(c, null);
    c.scope = step13;
    for(var i: usize = 0; i < program.types.length; i++) {
        var n: void* = program.types.data[i];
        var step17 = sem_name(sem_get(n));
        sem_put(c, c.types, step17, n);
    }
}

fn sem_context_dispose(c: SemanticContext*): void {
    stack_dispose(void*, &c.scan);
    vector_dispose(u8, &c.token_text);
    work_dispose(&c.layout_work);
    var i: usize = 0;
    for(; i < c.lists.length; i++) {
        var step3 = bits(vector(void*)*, c.lists.data[i]);
        vector_dispose(void*, step3);
    }
    vector_dispose(void*, &c.lists);
    vector_dispose(void*, &c.type_arguments);
    vector_dispose(void*, &c.constant_arguments);
    vector_dispose(void*, &c.generated);
    vector_dispose(void*, &c.template_nodes);
    vector_dispose(void*, &c.inferring);
    i = 0;
    for(; i < c.allocations.length; i++) {
        free(c.allocations.data[i]);
    }
    vector_dispose(void*, &c.allocations);
}

export fn semantic_initialize(program: SemanticProgram*, root: void*, width: u32): void {
    var step1 = sizeof(SemanticProgram);
    fill(program, 0, step1);
    program.pointer_bytes = width;
    program.root = root;
    var n: FoundationNode* = sem_attach(root, KProgram());
    n.type.scalar = SVoid();
    sem_push(&program.functions, root);
    var scalar: u32 = 0;
    loop {
        if !(scalar <= SUSize()) {
            break;
        }
        if scalar == SStruct() {
            scalar++;
            continue;
        }
        var entity: void* = sem_create(root);
        var t: FoundationNode* = sem_attach(entity, KType());
        t.type.scalar = scalar;
        t.type.pointer_bytes = width;
        var step8 = semantic_scalar_name(scalar);
        sem_set_name(t, step8);
        var step9 = semantic_size(&t.type);
        t.size = step9;
        var step10 = semantic_alignment(&t.type);
        t.alignment = step10;
        sem_push(&program.types, entity);
        scalar++;
    }
}

export fn semantic_compile_budget(program: SemanticProgram*, roots: void**, bases: usize*, count: usize, source: u8*, component_bytes: usize): void {
    var context: SemanticContext;
    var c: SemanticContext* = &context;
    sem_context_init(c, program);
    c.node_limit = component_bytes / sizeof(FoundationNode);
    c.source = source;
    var step1 = generic_begin(program.root);
    c.generics = step1;
    for(var i: usize = 0; i < count; i++) {
        var step4 = sem_state(c, c.source_bases, roots[i]);
        step4.number = bases[i];
    }
    sem_run(c);
    sem_defer_hygiene(c);
    sem_lower_expressions(c);
    sem_defer_validate(c);
    sem_context_dispose(c);
}

export fn semantic_compile(program: SemanticProgram*, roots: void**, bases: usize*, count: usize, source: u8*): void {
    semantic_compile_budget(program, roots, bases, count, source, SemanticComponentBudgetBytes());
}

export fn semantic_program_dispose(program: SemanticProgram*): void {
    vector_dispose(void*, &program.functions);
    vector_dispose(void*, &program.types);
    vector_dispose(u8, &program.error);
}

export fn semantic_format_type(t: FoundationType*, output: vector(u8)*): void {
    var context: SemanticContext;
    var program: SemanticProgram;
    var step1 = sizeof(SemanticContext);
    fill(&context, 0, step1);
    var step2 = sizeof(SemanticProgram);
    fill(&program, 0, step2);
    context.program = &program;
    var text: u8* = sem_type_name(&context, t);
    var count: usize = sem_length(text);
    var step5 = count + 1;
    sem_require(vector_reserve(u8, output, step5));
    var step7 = count + 1;
    copy(output.data, text, step7);
    output.length = count;
    sem_context_dispose(&context);
}

export fn semantic_format_number(value: u64, t: FoundationType*, output: vector(u8)*): void {
    var context: SemanticContext;
    var step1 = sizeof(SemanticContext);
    fill(&context, 0, step1);
    var text: u8* = sem_number(&context, value, t);
    var count: usize = sem_length(text);
    var step4 = count + 1;
    sem_require(vector_reserve(u8, output, step4));
    var step6 = count + 1;
    copy(output.data, text, step6);
    output.length = count;
    sem_context_dispose(&context);
}

import tower;
import foundation_tags;
import frontend_compilation;
import semantic_context;
import semantic_definitions;
import semantic_support;

// Ownership/import components live on the same retained parse entities. The
// registry and lookup tables are compilation-local indexes, not another IR.
// Text is owned by ordinary entity relationship names; no context allocation
// escapes into a retained component. Foundation output encodes resolved bindings.
import semantic_program_types;

struct SemanticModuleLink {
    module: void*;
    base: usize;
}

extern fn frontend_module_name(module: void*): u8*;

extern fn frontend_module_import_count(module: void*): usize;

extern fn frontend_module_import_at(module: void*, index: usize): void*;

extern fn frontend_module_dependency_at(module: void*, index: usize): void*;

extern fn frontend_module_alias(module: void*, index: usize): u8*;

extern fn entity_child_name(node: void*, index: usize): u8*;

fn sem_module_kind(parent: void*, size: usize, alignment: usize): void* {
    var kind = sem_create(parent);
    sem_require(entity_register(kind, size, alignment, 0));
    return kind;
}

fn sem_modules_begin(program: SemanticProgram*): SemanticModules* {
    if program.modules != null {
        return program.modules;
    }
    var registry = tower_node_create();
    sem_require(entity_register(registry, sizeof(SemanticModules), alignof(SemanticModules), 0));
    var component = entity_component_add(program.root, registry);
    var modules = bits(SemanticModules*, entity_component_data(component));
    var present = modules != null;
    sem_require(present);
    fill(modules, 0, sizeof(SemanticModules));
    modules.root = registry;
    modules.owner_kind = sem_module_kind(registry, sizeof(SemanticModuleLink), alignof(SemanticModuleLink));
    modules.import_kind = sem_module_kind(registry, sizeof(SemanticModuleLink), alignof(SemanticModuleLink));
    modules.scopes = sem_create(registry);
    program.modules = modules;
    entity_release(registry);
    return modules;
}

fn sem_module_scope(program: SemanticProgram*, module: void*): void* {
    var registry = sem_modules_begin(program);
    var path = frontend_module_name(module);
    var scope = sem_member(registry.scopes, path);
    if scope == null {
        scope = tower_node_create();
        sem_require(entity_attach(scope, registry.scopes, path));
        entity_release(scope);
    }
    return scope;
}

fn sem_module_link(node: void*, kind: void*, scope: void*): void {
    var component = entity_component_add(node, kind);
    var link = bits(SemanticModuleLink*, entity_component_data(component));
    var present = link != null;
    sem_require(present);
    link.module = scope;
    link.base = 0;
}

fn sem_module_position(program: SemanticProgram*, module: void*, base: usize): void {
    var scope = sem_module_scope(program, module);
    sem_module_link(scope, program.modules.owner_kind, scope);
    var component = entity_component_get(scope, program.modules.owner_kind);
    var link = bits(SemanticModuleLink*, entity_component_data(component));
    link.base = base;
}

fn sem_module_record(program: SemanticProgram*, module: void*): void {
    var registry = sem_modules_begin(program);
    var scope = sem_module_scope(program, module);
    var count = frontend_module_roots(module);
    var i: usize = 0;
    for(; i < count; i++) {
        sem_module_link(frontend_module_tree(module, i), registry.owner_kind, scope);
    }
    count = frontend_module_import_count(module);
    i = 0;
    for(; i < count; i++) {
        var declaration = frontend_module_import_at(module, i);
        // Recovered editor parses may contribute a second source snapshot.
        // Each actual declaration keeps its own components and source spans.
        if entity_component_get(declaration, registry.import_kind) == null {
            var dependency = frontend_module_dependency_at(module, i);
            var target = sem_module_scope(program, dependency);
            var alias = frontend_module_alias(module, i);
            // Inspection retains the source wrapper too. Move the complete
            // tree so its children, roles and hover spans stay intact.
            var tree = sem_parent(declaration);
            if tree == null {
                tree = declaration;
            }
            sem_require(entity_attach(tree, scope, alias));
            sem_module_link(tree, registry.import_kind, target);
            sem_module_link(declaration, registry.import_kind, target);
            sem_module_link(declaration, registry.owner_kind, scope);
        }
    }
}

fn sem_module_graph(program: SemanticProgram*, module: void*): void {
    sem_module_record(program, module);
    var count = frontend_module_count(module);
    for(var i: usize = 0; i < count; i++) {
        var dependency = frontend_module_at(module, i);
        sem_module_record(program, dependency);
    }
}

fn sem_owner(c: SemanticContext*, node: void*): void* {
    var registry = c.program.modules;
    if registry == null {
        return null;
    }
    while node != null {
        var component = entity_component_get(node, registry.owner_kind);
        var link = bits(SemanticModuleLink*, entity_component_data(component));
        if link != null {
            return link.module;
        }
        if c.generics != null {
            var original = generic_definition(c.generics, node);
            if original != node {
                node = original;
                continue;
            }
        }
        node = sem_parent(node);
    }
    return null;
}

fn sem_module_path(c: SemanticContext*, module: void*): u8* {
    var scopes = c.program.modules.scopes;
    var count = sem_child_count(scopes);
    for(var i: usize = 0; i < count; i++) {
        if sem_child(scopes, i) == module {
            return entity_child_name(scopes, i);
        }
    }
    return "";
}

fn sem_owned(table: SemanticTable*, module: void*, name: u8*): void* {
    var entry = sem_find(table, name, module);
    if entry != null {
        return entry.value;
    }
    return null;
}

fn sem_define(c: SemanticContext*, table: SemanticTable*, node: void*, name: u8*): bool {
    var owner = sem_owner(c, node);
    var entry = sem_entry(c, table, name, owner);
    if entry.value != null {
        return false;
    }
    entry.value = node;
    return true;
}

fn sem_local(c: SemanticContext*, name: u8*): void* {
    var scope = c.scope;
    while scope != null {
        var found = sem_lookup_table(scope.names, name);
        if found != null {
            return found;
        }
        scope = scope.parent;
    }
    return null;
}

fn sem_import_target(c: SemanticContext*, edge: void*): void* {
    var component = entity_component_get(edge, c.program.modules.import_kind);
    var link = bits(SemanticModuleLink*, entity_component_data(component));
    if link != null {
        return link.module;
    }
    return null;
}

fn sem_import_alias(owner: void*, index: usize): u8* {
    var name = entity_child_name(owner, index);
    if name == null {
        return "";
    }
    return name;
}

fn sem_alias(c: SemanticContext*, owner: void*, name: u8*): void* {
    var i: usize = 0;
    var count = sem_child_count(owner);
    for(; i < count; i++) {
        var alias = sem_import_alias(owner, i);
        if sem_equal(alias, name) {
            return sem_import_target(c, sem_child(owner, i));
        }
    }
    return null;
}

fn sem_visible(c: SemanticContext*, table: SemanticTable*, node: void*, owner: void*, name: u8*): void* {
    var found = sem_owned(table, owner, name);
    if found != null {
        return found;
    }
    if owner == null {
        return null;
    }
    var count = sem_child_count(owner);
    for(var i: usize = 0; i < count; i++) {
        var alias = sem_import_alias(owner, i);
        if alias[0] == 0 {
            var target = sem_import_target(c, sem_child(owner, i));
            var candidate = sem_owned(table, target, name);
            if candidate != null {
                var different = found != null;
                different &&= found != candidate;
                if different {
                    sem_fail(c, node, sem_cat(c, "Ambiguous imported name '", sem_cat(c, name, "'; use an import alias")));
                    return null;
                }
                found = candidate;
            }
        }
    }
    if found == null {
        // Only the reflected Foundation primitive types are ownerless.
        var types = table == c.types;
        if types {
            found = sem_owned(table, null, name);
        }
    }
    return found;
}

fn sem_name_node(node: void*): void* {
    loop {
        var base = sem_member(node, "base");
        if base != null {
            return node;
        }
        var name = sem_member(node, "name");
        if name != null {
            node = name;
        } else {
            return node;
        }
    }
}

fn sem_callable_owned(c: SemanticContext*, owner: void*, name: u8*): void* {
    var found = sem_owned(c.functions, owner, name);
    var missing = found == null;
    if missing {
        found = sem_owned(c.templates, owner, name);
    }
    missing = found == null;
    if missing {
        found = sem_owned(c.type_functions, owner, name);
    }
    return found;
}

fn sem_callable_visible(c: SemanticContext*, table: SemanticTable*, node: void*, owner: void*, name: u8*): void* {
    var local = sem_callable_owned(c, owner, name);
    var present = local != null;
    if present {
        return sem_owned(table, owner, name);
    }
    var selected: void* = null;
    var found: void* = null;
    var i: usize = 0;
    var count = sem_child_count(owner);
    for(; i < count; i++) {
        var alias = sem_import_alias(owner, i);
        if alias[0] == 0 {
            var dependency = sem_import_target(c, sem_child(owner, i));
            var candidate = sem_callable_owned(c, dependency, name);
            present = candidate != null;
            if present {
                var different = found != null;
                different &&= found != candidate;
                if different {
                    sem_fail(c, node, sem_cat(c, "Ambiguous imported name '", sem_cat(c, name, "'; use an import alias")));
                    return null;
                }
                found = candidate;
                selected = dependency;
            }
        }
    }
    return sem_owned(table, selected, name);
}

fn sem_resolve(c: SemanticContext*, table: SemanticTable*, node: void*, spelling: u8*): void* {
    return sem_resolve_from(c, table, node, spelling, sem_owner(c, node));
}

fn sem_resolve_from(c: SemanticContext*, table: SemanticTable*, node: void*, spelling: u8*, owner: void*): void* {
    var name = sem_name_node(node);
    if sem_member(name, "index") != null {
        return null;
    }
    var base = sem_member(name, "base");
    var field = sem_member(name, "field");
    var qualified = base != null;
    qualified &&= field != null;
    if qualified {
        var target = sem_namespace_from(c, name, owner);
        if target != null {
            return sem_owned(table, target, sem_identifier(c, field));
        }
        return null;
    }
    var callable = table == c.functions;
    callable ||= table == c.templates;
    callable ||= table == c.type_functions;
    if callable {
        return sem_callable_visible(c, table, node, owner, spelling);
    }
    return sem_visible(c, table, node, owner, spelling);
}

fn sem_namespace(c: SemanticContext*, node: void*): void* {
    return sem_namespace_from(c, node, sem_owner(c, node));
}

fn sem_namespace_from(c: SemanticContext*, node: void*, owner: void*): void* {
    node = sem_name_node(node);
    var base = sem_member(node, "base");
    var field = sem_member(node, "field");
    var possible = base != null;
    possible &&= field != null;
    if !possible {
        return null;
    }
    base = sem_name_node(base);
    if sem_member(base, "base") != null {
        return null;
    }
    var name = sem_identifier(c, base);
    var shadowed = sem_local(c, name) != null;
    if c.generics != null {
        var parameter = generic_lookup(c.generics, base, base);
        if parameter != null {
            shadowed = true;
        }
    }
    if shadowed {
        return null;
    }
    return sem_alias(c, owner, name);
}

fn sem_editor_symbol(c: SemanticContext*, node: void*, kind: u32): bool {
    var name = sem_name_node(node);
    var field = sem_member(name, "field");
    var qualified = field != null;
    var target = name;
    if qualified {
        target = field;
    }
    var captured = sem_editor_capture(c, target, kind, null);
    if captured {
        c.editor.node = node;
        c.editor.module = sem_namespace(c, name);
    }
    return captured;
}

fn sem_completion_visible(c: SemanticContext*, editor: SemanticEditor*, table: SemanticTable*, node: void*): bool {
    var name = sem_identifier(c, sem_member(node, "name"));
    var value = sem_get(node);
    if name[0] == 0 {
        if value != null {
            name = sem_name(value);
        }
    }
    var found: void* = null;
    if editor.module != null {
        found = sem_owned(table, editor.module, name);
    } else {
        var callable = table == c.functions;
        callable ||= table == c.templates;
        callable ||= table == c.type_functions;
        if callable {
            found = sem_callable_visible(c, table, editor.node, sem_owner(c, editor.node), name);
        } else {
            found = sem_visible(c, table, editor.node, sem_owner(c, editor.node), name);
        }
    }
    var clean = sem_ok(c);
    c.program.error.length = 0;
    if clean {
        var same = found == node;
        return same;
    }
    return false;
}

// Keep familiar names when unique. Colliding module-local declarations get a
// deterministic, escaped Foundation spelling; bindings still point to entities.
fn sem_output_name(c: SemanticContext*, node: void*, name: u8*): u8* {
    var saved = sem_find(c.output_names, null, node);
    if saved != null {
        return bits(u8*, saved.value);
    }
    var spelling = name;
    var original = sem_find(c.source_names, name, null);
    var collision = original != null;
    collision &&= original.number != 0;
    if collision {
        var owner = sem_owner(c, node);
        if owner != null {
            spelling = sem_cat(c, name, sem_cat(c, "@", sem_module_path(c, owner)));
        }
    }
    var candidate = spelling;
    var suffix: u64 = 1;
    loop {
        var taken = sem_lookup_table(c.output_names, candidate);
        var available = taken == null;
        if sem_equal(candidate, name) == false {
            if sem_find(c.source_names, candidate, null) != null {
                available = false;
            }
        }
        if available {
            break;
        }
        suffix++;
        candidate = sem_cat(c, spelling, sem_cat(c, "_", sem_decimal(c, suffix)));
    }
    sem_put(c, c.output_names, candidate, node);
    saved = sem_state(c, c.output_names, node);
    saved.value = bits(void*, candidate);
    return candidate;
}

fn sem_validate_aliases(c: SemanticContext*): void {
    var registry = c.program.modules;
    if registry == null {
        return;
    }
    var root = sem_get(c.program.root);
    var count = sem_child_count(registry.scopes);
    for(var i: usize = 0; i < count; i++) {
        var scope = sem_child(registry.scopes, i);
        var imports = sem_child_count(scope);
        for(var edge: usize = 0; edge < imports; edge++) {
            var alias = sem_import_alias(scope, edge);
            if alias[0] != 0 {
                var conflict = semantic_builtin_kind(alias) != 0;
                conflict ||= sem_owned(c.types, null, alias) != null;
                for(var n: usize = 0; n < root.items.length; n++) {
                    var declaration = root.items.data[n];
                    if sem_owner(c, declaration) == scope {
                        var name = sem_member(declaration, "name");
                        if name != null {
                            if sem_equal(alias, sem_identifier(c, name)) {
                                conflict = true;
                            }
                        }
                    }
                }
                if conflict {
                    sem_fail(c, sem_child(scope, edge), sem_cat(c, "Import alias conflicts with declaration: ", alias));
                    return;
                }
            }
        }
    }
}

// Foreign declarations still denote explicit link symbols. Merge identical
// declarations (and their Tower export, if supplied) after checked signatures
// exist. Local Tower names never acquire foreign visibility from this step.
fn sem_link_functions(c: SemanticContext*): void {
    if !sem_ok(c) {
        return;
    }
    var symbols = sem_table(c);
    var i: usize = 1;
    for(; i < c.program.functions.length; i++) {
        var node = c.program.functions.data[i];
        var function = sem_get(node);
        var foreign = function.external;
        if function.exported {
            foreign = true;
        }
        if foreign {
            var name = sem_name(function);
            var entry = sem_entry(c, symbols, name, null);
            var previous = entry.value;
            var duplicate = previous != null;
            if duplicate {
                var old = sem_get(previous);
                var compatible = semantic_type_equal(&function.type, &old.type);
                compatible &&= function.parameters.length == old.parameters.length;
                var p: usize = 0;
                for(; p < function.parameters.length; p++) {
                    if compatible {
                        var left = sem_get(function.parameters.data[p]);
                        var right = sem_get(old.parameters.data[p]);
                        compatible = semantic_type_equal(&left.type, &right.type);
                    }
                }
                if !compatible {
                    sem_fail(c, node, sem_cat(c, "Incompatible declarations of foreign symbol '", sem_cat(c, name, "'")));
                    return;
                }
                var definitions = old.exported;
                definitions &&= function.exported;
                if definitions {
                    sem_fail(c, node, sem_cat(c, "Duplicate foreign export '", sem_cat(c, name, "'")));
                    return;
                }
                if function.exported {
                    old.binding = node;
                    entry.value = node;
                } else {
                    function.binding = previous;
                }
            } else {
                entry.value = node;
            }
        }
    }
    i = 0;
    for(; i < c.functions.capacity; i++) {
        var entry = c.functions.entries[i];
        if entry != null {
            var node = sem_get(entry.value);
            while node.binding != null {
                entry.value = node.binding;
                node = sem_get(entry.value);
            }
        }
    }
    var count: usize = 0;
    i = 0;
    for(; i < c.program.functions.length; i++) {
        var node = c.program.functions.data[i];
        var value = sem_get(node);
        if value.binding == null {
            value.index = count;
            c.program.functions.data[count] = node;
            count++;
        }
    }
    c.program.functions.length = count;
    var root = sem_get(c.program.root);
    count = 0;
    i = 0;
    for(; i < root.items.length; i++) {
        var node = root.items.data[i];
        var value = sem_get(node);
        var duplicate = value != null;
        duplicate &&= value.kind == KFunction();
        duplicate &&= value.binding != null;
        if !duplicate {
            root.items.data[count] = node;
            count++;
        }
    }
    root.items.length = count;
}

