// Semantic compiler over shared Foundation components.
// Temporary indexes and scratch allocations are scoped to one compilation.

fn sem_type_entity(c: SemanticContext*, t: FoundationType*): void* {
    var i: usize = 0;
    for(; i < c.program.types.length; i++) {
        var n: void* = c.program.types.data[i];
        var step3 = sem_get(n);
        if semantic_type_equal(&step3.type, t) {
            return n;
        }
    }
    i = 0;
    for(; i < c.type_arguments.length; i++) {
        var n: void* = c.type_arguments.data[i];
        var step7 = sem_get(n);
        if semantic_type_equal(&step7.type, t) {
            return n;
        }
    }
    var n: void* = sem_create(c.program.root);
    var value: FoundationNode* = sem_attach(n, KType());
    sem_set_type(&value.type, t);
    var step11 = sem_type_name(c, t);
    sem_set_name(value, step11);
    sem_push(&c.type_arguments, n);
    return n;
}

fn sem_type_uses_begin(c: SemanticContext*): void {
    c.type_uses = sem_create(c.program.root);
    sem_require(entity_register(c.type_uses, sizeof(SemanticTypeUse), alignof(SemanticTypeUse), 0));
}

fn sem_type_use(c: SemanticContext*, node: void*, type: FoundationType*): void {
    if c.type_uses == null {
        return;
    }
    var component = entity_component_add(node, c.type_uses);
    var use = bits(SemanticTypeUse*, entity_component_data(component));
    var allocated = use != null;
    sem_require(allocated);
    use.target = sem_type_entity(c, type);
}

fn sem_constant_argument(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    n = sem_surface_unwrap(n);
    loop {
        var step9 =(sem_is(n, "CoreTypeArgument") || sem_is(n, "CoreCallArgument") || sem_is(n, "CoreOperand") || sem_is(n, "CoreArrayCount")) && sem_child_count(n) == 1;
        if !step9 {
            break;
        }
        n = sem_child(n, 0);
    }
    var value: void* = generic_lookup(c.generics, n, n);
    if value == null {
        var text: u8* = sem_tokens(c, n);
        if text[0] == 0 || text[0] != 45 &&(text[0] < 48 || text[0] > 57) {
            sem_fail(c, n, "Expected a compile-time integer argument (an integer literal or a bound template value)");
            return null;
        }
        var size: FoundationType* = sem_type_new(c, SUSize(), 0, null);
        if expected_type != null {
            size = expected_type;
        }
        value = sem_operand(c, n, size);
        if !sem_ok(c) {
            return null;
        }
    }
    var constant: FoundationNode* = sem_get(value);
    if !constant.constant || !semantic_integer(&constant.type) {
        sem_fail(c, n, "Expected a compile-time integer argument");
        return null;
    }
    if expected_type != null && !semantic_type_equal(&constant.type, expected_type) {
        var step41 = sem_type_name(c, expected_type);
        var step42 = sem_cat(c, "Expected ", step41);
        var step43 = sem_type_name(c, &constant.type);
        var step44 = sem_cat(c, " compile-time argument, got ", step43);
        var step45 = sem_cat(c, step42, step44);
        sem_fail(c, n, step45);
        return null;
    }
    var i: usize = 0;
    for(; i < c.constant_arguments.length; i++) {
        var existing: void* = c.constant_arguments.data[i];
        var e: FoundationNode* = sem_get(existing);
        if semantic_type_equal(&e.type, &constant.type) && e.bits == constant.bits {
            return existing;
        }
    }
    var result: void* = sem_create(c.program.root);
    var out: FoundationNode* = sem_attach(result, KOperand());
    out.constant = true;
    sem_set_type(&out.type, &constant.type);
    out.bits = constant.bits;
    sem_push(&c.constant_arguments, result);
    return result;
}

fn sem_instance_name(c: SemanticContext*, definition: void*, arguments: vector(void*)*): u8* {
    var name: u8* = sem_cat(c, sem_identifier(c, sem_member(definition, "name")), "(");
    var i: usize = 0;
    for(; i < arguments.length; i++) {
        if i != 0 {
            name = sem_cat(c, name, ", ");
        }
        var arg: FoundationNode* = sem_get(arguments.data[i]);
        if arg.constant {
            name = sem_cat(c, name, sem_number(c, arg.bits, &arg.type));
        } else {
            name = sem_cat(c, name, sem_type_name(c, &arg.type));
        }
    }
    name = sem_cat(c, name, ")");
    var unique: u8* = name;
    var suffix: u64 = 1;
    loop {
        var step16 = sem_lookup_table(c.source_names, unique) != null || sem_lookup_table(c.output_names, unique) != null || sem_owned(c.functions, sem_owner(c, definition), unique) != null;
        if !step16 {
            break;
        }
        suffix++;
        unique = sem_cat(c, sem_cat(c, name, "_"), sem_decimal(c, suffix));
    }
    return unique;
}

fn sem_register_template(c: SemanticContext*, n: void*): void {
    var kind: u32 = generic_register(c.generics, n);
    if !sem_generic_ok(c, n) || kind == KProgram() {
        return;
    }
    var step7 = sem_member(n, "name");
    var name: u8* = sem_identifier(c, step7);
    if !sem_is(n, "CoreFunction") {
        sem_fail(c, n, "Templates cannot be extern or export declarations; export a concrete wrapper");
        return;
    }
    var names: SemanticTable* = sem_table(c);
    var step12 = sem_member(n, "params");
    var parameters: vector(void*)* = sem_collect(c, step12, "CoreParameter");
    for(var i: usize = 0; i < parameters.length; i++) {
        var p: void* = parameters.data[i];
        var step16 = sem_member(p, "name");
        var value: u8* = sem_identifier(c, step16);
        if !sem_put(c, names, value, p) {
            var step20 = sem_cat(c, "Duplicate template parameter '", value);
            var step21 = sem_cat(c, step20, "'");
            sem_fail(c, p, step21);
            return;
        }
    }
    var registry: SemanticTable* = c.templates;
    if kind == KParameter() {
        registry = c.type_functions;
    }
    var existing = sem_callable_owned(c, sem_owner(c, n), name);
    if existing != null {
        sem_fail(c, n, sem_cat(c, "Duplicate template '", sem_cat(c, name, "'")));
        return;
    }
    if !sem_define(c, registry, n, name) {
        var step25 = sem_cat(c, "Duplicate template '", name);
        var step26 = sem_cat(c, step25, "'");
        sem_fail(c, n, step26);
        return;
    }
    if semantic_builtin_kind(name) != 0 {
        var step29 = sem_cat(c, "Template name '", name);
        var step30 = sem_cat(c, step29, "' already names a foundation builtin");
        sem_fail(c, n, step30);
    }
    sem_push(&c.template_nodes, n);
}

fn sem_type_call(c: SemanticContext*, n: void*): FoundationType* {
    var step1 = sem_member(n, "name");
    var name: u8* = sem_identifier(c, step1);
    var definition: void* = sem_resolve(c, c.type_functions, step1, name);
    var invalid: FoundationType* = sem_type_new(c, SI32(), 0, null);
    if definition == null {
        var step6 = sem_cat(c, "Unknown type constructor '", name);
        var step7 = sem_cat(c, step6, "'");
        sem_fail(c, n, step7);
        return invalid;
    }
    var wanted: u8* = "CoreTypeArgument";
    if sem_is(n, "CoreCall") {
        wanted = "CoreCallArgument";
    }
    var step9 = sem_member(n, "args");
    var args: vector(void*)* = sem_collect(c, step9, wanted);
    if args.length == 0 && !sem_is(n, "CoreCall") {
        var step15 = sem_member(n, "args");
        args = sem_collect(c, step15, "CoreType");
    }
    var step17 = generic_parameter_count(c.generics, definition);
    if args.length != step17 {
        var step19 = sem_cat(c, "Wrong argument count for type constructor '", name);
        var step20 = sem_cat(c, step19, "'");
        sem_fail(c, n, step20);
        return invalid;
    }
    var arguments: vector(void*)* = sem_list(c);
    var step22 = sem_member(definition, "params");
    var parameters: vector(void*)* = sem_collect(c, step22, "CoreParameter");
    for(var i: usize = 0; i < args.length; i++) {
        if generic_type_parameter(c.generics, definition, i) {
            var step27 = sem_type(c, args.data[i]);
            sem_push(arguments, sem_type_entity(c, step27));
        } else {
            var step29 = sem_member(parameters.data[i], "type");
            var expected_type: FoundationType* = sem_type(c, step29);
            if !semantic_integer(expected_type) {
                sem_fail(c, parameters.data[i], "Compile-time value parameters currently require an integer type");
                return invalid;
            }
            sem_push(arguments, sem_constant_argument(c, args.data[i], expected_type));
        }
        if !sem_ok(c) {
            return invalid;
        }
    }
    var instance: void* = generic_instantiate(c.generics, definition, n, arguments.data, arguments.length);
    if !sem_generic_ok(c, n) || instance == null {
        return invalid;
    }
    var step42 = sem_state(c, c.source_bases, instance);
    var step43 = sem_source_base(c, definition);
    step42.number = step43;
    var entry: SemanticEntry* = sem_state(c, c.type_results, instance);
    if entry.value != null {
        return bits(FoundationType*, entry.value);
    }
    if entry.number != 0 {
        var step48 = sem_cat(c, "Recursive type constructor '", name);
        var step49 = sem_cat(c, step48, "' has no concrete struct to resolve");
        sem_fail(c, n, step49);
        return invalid;
    }
    entry.number = 1;
    var result: void* = generic_type_result(c.generics, instance);
    if !sem_generic_ok(c, n) || result == null {
        return invalid;
    }
    var step56 = sem_state(c, c.source_bases, result);
    var step57 = sem_source_base(c, definition);
    step56.number = step57;
    if sem_is(result, "CoreStruct") {
        var step59 = sem_instance_name(c, definition, arguments);
        sem_type_header(c, result, step59);
        if !sem_ok(c) {
            return invalid;
        }
        var step62 = sem_get(result);
        var t: FoundationType* = &step62.type;
        var step63 = bits(void*, t);
        entry.value = step63;
        sem_push(&c.generated, result);
        sem_type_fields(c, result);
        entry.number = 0;
        return t;
    }
    var t: FoundationType* = sem_type(c, result);
    var step65 = bits(void*, t);
    entry.value = step65;
    entry.number = 0;
    return t;
}

fn sem_type(c: SemanticContext*, n: void*): FoundationType* {
    if sem_editor_symbol(c, n, 2) {
        return sem_type_new(c, SI32(), 0, null);
    }
    c.type_depth++;
    var result: FoundationType* = sem_type_impl(c, n);
    c.type_depth--;
    if sem_ok(c) {
        sem_type_use(c, n, result);
    }
    return result;
}

fn sem_type_impl(c: SemanticContext*, n: void*): FoundationType* {
    n = sem_surface_unwrap(n);
    if sem_is(n, "TowerExpression") {
        var left = sem_member(n, "left");
        var present = left != null;
        if present {
            var op = sem_surface_operator(c, n, left);
            if sem_equal(op, "*") {
                var tail = sem_tokens(c, sem_member(n, "right"));
                var count: u32 = 1;
                for(var index: usize = 0; !(tail[index] == 0); index++) {
                    if tail[index] == 42 {
                        count++;
                    }
                    else {
                        sem_fail(c, n, "Expected a type spelling");
                        break;
                    }
                }
                var type = sem_type_copy(c, sem_type(c, left));
                type.pointers = type.pointers + count;
                if type.pointers > 16 {
                    sem_fail(c, n, "Foundation pointer nesting limit is 16");
                }
                return type;
            }
        }
    }
    var invalid: FoundationType* = sem_type_new(c, SI32(), 0, null);
    if c.type_depth > 128 {
        sem_fail(c, n, "Type construction nesting exceeds 128; check recursive type arguments");
        return invalid;
    }
    loop {
        if !((sem_is(n, "CoreTypeArgument") || sem_is(n, "CoreCallArgument") || sem_is(n, "CoreOperand")) && sem_child_count(n) == 1) {
            break;
        }
        n = sem_child(n, 0);
    }
    if(sem_is(n, "CoreType") || sem_is(n, "CoreCall")) && sem_member(n, "args") != null {
        return sem_type_call(c, n);
    }
    // A dotted type argument uses the ordinary location tree in call position.
    // Resolve its namespace before the pointer/array shape below.
    var qualified_name = sem_name_node(n);
    if sem_member(qualified_name, "field") != null {
        var spelling = sem_identifier(c, qualified_name);
        var declaration = sem_resolve(c, c.types, qualified_name, spelling);
        var present = declaration != null;
        if present {
            var value = sem_get(declaration);
            return &value.type;
        }
        sem_fail(c, n, sem_cat(c, "Unknown type '", sem_cat(c, spelling, "'")));
        return invalid;
    }
    var base: void* = sem_member(n, "base");
    if base != null {
        var step24 = sem_type(c, base);
        var t: FoundationType* = sem_type_copy(c, step24);
        var count: void* = sem_member(n, "count");
        if count == null {
            count = sem_member(n, "index");
        }
        if count != null {
            var value: void* = sem_constant_argument(c, count, null);
            if value == null {
                return t;
            }
            var v: FoundationNode* = sem_get(value);
            var length: u64 = v.bits;
            var sign: u64 = semantic_mask(&v.type) / 2;
            sign++;
            if semantic_signed(&v.type) &&(length &sign) != 0 {
                length = 0;
            }
            if length == 0 || length > 1048576 {
                sem_fail(c, n, "Array length must be between 1 and 1,048,576");
                return t;
            }
            if t.pointers == 0 && t.scalar == SVoid() {
                sem_fail(c, n, "An array cannot have void elements");
                return t;
            }
            var step46 = sem_type_name(c, t);
            var step47 = sem_cat(c, step46, "[");
            var step48 = sem_decimal(c, length);
            var step49 = sem_cat(c, step47, step48);
            var name: u8* = sem_cat(c, step49, "]");
            var i: usize = 0;
            for(; i < c.program.types.length; i++) {
                var a: FoundationNode* = sem_get(c.program.types.data[i]);
                if a.type.scalar == SArray() && semantic_type_equal(&a.element, t) && convert(u64, a.length) == length {
                    return &a.type;
                }
            }
            var entity: void* = sem_create(c.program.root);
            var a: FoundationNode* = sem_attach(entity, KType());
            sem_set_name(a, name);
            sem_set_type(&a.element, t);
            var step61 = convert(usize, length);
            a.length = step61;
            var step62 = sem_type_new(c, SArray(), 0, entity);
            sem_set_type(&a.type, step62);
            sem_push(&c.program.types, entity);
            return &a.type;
        }
        if sem_member(n, "field") != null {
            sem_fail(c, n, "Expected a type name, not field access");
            return t;
        }
        t.pointers++;
        if t.pointers > 16 {
            sem_fail(c, n, "Foundation pointer nesting limit is 16");
        }
        return t;
    }
    var text: u8* = sem_identifier(c, n);
    if generic_origin(c.generics, n) != null {
        var parent: void* = sem_parent(n);
        loop {
            if parent == null {
                break;
            }
            var step73 = sem_is(parent, "CoreStruct") && sem_get(parent) != null;
            if step73 {
                var step76 = sem_member(parent, "name");
                step73 = sem_equal(text, sem_identifier(c, step76));
            }
            if step73 {
                var step79 = sem_get(parent);
                return &step79.type;
            }
            parent = sem_parent(parent);
        }
    }
    var bound: void* = generic_lookup(c.generics, n, n);
    if bound != null {
        var step83 = sem_get(bound);
        if step83.kind != KType() {
            sem_fail(c, n, "Expected a type, got a compile-time integer value");
        }
        var step85 = sem_get(bound);
        return &step85.type;
    }
    if sem_equal(text, "type") {
        sem_fail(c, n, "Type values currently require a template parameter or a type-constructor result");
        return invalid;
    }
    var found: void* = sem_resolve(c, c.types, n, text);
    if found == null {
        var step89 = sem_cat(c, "Unknown type '", text);
        var step90 = sem_cat(c, step89, "'");
        sem_fail(c, n, step90);
        return invalid;
    }
    var step91 = sem_get(found);
    return &step91.type;
}

fn sem_type_header(c: SemanticContext*, n: void*, name: u8*): void {
    if !sem_shape(c, n, "name") || !sem_shape(c, n, "fields") {
        return;
    }
    var t: FoundationNode* = sem_node(c, n, KType());
    if name[0] == 0 {
        var step9 = sem_member(n, "name");
        name = sem_identifier(c, step9);
    }
    sem_set_name(t, sem_output_name(c, n, name));
    var step12 = name[0] == 0 || sem_equal(name, "type");
    if !step12 {
        var step16 = sem_owned(c.types, sem_owner(c, n), name);
        if step16 == null {
            step16 = sem_owned(c.types, null, name);
        }
        step12 = step16 != null;
    }
    step12 ||= sem_owned(c.type_functions, sem_owner(c, n), name) != null;
    if step12 {
        var step21 = sem_cat(c, "Missing or duplicate type '", name);
        var step22 = sem_cat(c, step21, "'");
        sem_fail(c, n, step22);
        return;
    }
    // Names use the shared hash index; layouts use the iterative work graph.
    // The compilation node/storage budgets apply instead of a 256-type cap.
    var step24 = sem_type_new(c, SStruct(), 0, n);
    sem_set_type(&t.type, step24);
    sem_define(c, c.types, n, name);
    sem_push(&c.program.types, n);
}

fn sem_type_fields(c: SemanticContext*, n: void*): void {
    var state: SemanticEntry* = sem_state(c, c.fields_done, n);
    if state.number != 0 {
        return;
    }
    state.number = 1;
    var t: FoundationNode* = sem_get(n);
    var names: SemanticTable* = sem_table(c);
    var fields: vector(void*)* = sem_collect(c, sem_member(n, "fields"), "CoreField");
    var i: usize = 0;
    for(; i < fields.length; i++) {
        var field: void* = fields.data[i];
        if !sem_shape(c, field, "name") || !sem_shape(c, field, "type") {
            return;
        }
        var f: FoundationNode* = sem_node(c, field, KFieldDeclaration());
        var name: u8* = sem_identifier(c, sem_member(field, "name"));
        sem_set_name(f, name);
        var step19 = sem_type(c, sem_member(field, "type"));
        sem_set_type(&f.type, step19);
        if name[0] == 0 || !sem_put(c, names, name, field) {
            var step25 = sem_cat(c, "Missing or duplicate field '", name);
            sem_fail(c, field, sem_cat(c, step25, "'"));
        }
        if f.type.pointers == 0 && f.type.scalar == SVoid() {
            sem_fail(c, field, "A field cannot have void type");
        }
        sem_push(&t.items, field);
    }
}

fn sem_round(size: usize, alignment: usize): usize {
    return(size + alignment -1) / alignment *alignment;
}

fn sem_add_local(c: SemanticContext*, n: void*): void {
    var local: FoundationNode* = sem_get(n);
    var function: FoundationNode* = sem_get(c.current);
    if semantic_aggregate(&local.type) {
        sem_layout(c, local.type.record);
    }
    var alignment: usize = semantic_alignment(&local.type);
    local.index = function.locals.length;
    var step5 = sem_round(function.frame_size, alignment);
    local.byte_offset = step5;
    var step6 = semantic_size(&local.type);
    var step7 = local.byte_offset + step6;
    function.frame_size = step7;
    if function.frame_size > 4194304 {
        sem_fail(c, n, "Foundation local storage exceeds 4 MiB");
    }
    sem_push(&function.locals, n);
}

fn sem_lookup(c: SemanticContext*, n: void*): void* {
    if sem_editor_capture(c, n, 1, null) {
        return null;
    }
    var name: u8* = sem_identifier(c, n);
    var scope: SemanticScope* = c.scope;
    loop {
        if scope == null {
            break;
        }
        var found: void* = sem_lookup_table(scope.names, name);
        if found != null {
            if sem_declaration_type(c, found) {
                return found;
            }
            return null;
        }
        scope = scope.parent;
    }
    var found: void* = sem_resolve(c, c.globals, n, name);
    if found != null {
        if sem_declaration_type(c, found) {
            return found;
        }
        return null;
    }
    var step10 = sem_cat(c, "Unknown local '", name);
    sem_fail(c, n, sem_cat(c, step10, "'"));
    return null;
}

fn sem_declaration_type(c: SemanticContext*, n: void*): bool {
    var value: FoundationNode* = sem_get(n);
    var state: SemanticEntry* = sem_state(c, c.declaration_state, n);
    if value.kind != KDeclare() || state.number == 2 {
        return true;
    }
    if state.number == 1 {
        var chain: u8* = "";
        var i: usize = 0;
        loop {
            if !(i < c.inferring.length && c.inferring.data[i] != n) {
                break;
            }
            i++;
        }
        for(; i < c.inferring.length; i++) {
            var step15 = sem_name(sem_get(c.inferring.data[i]));
            var step16 = sem_cat(c, step15, " -> ");
            chain = sem_cat(c, chain, step16);
        }
        var step18 = sem_name(value);
        var step19 = sem_cat(c, "Cannot infer the type of '", step18);
        var step20 = sem_cat(c, step19, "': initializer dependency cycle ");
        var step21 = sem_name(value);
        var step22 = sem_cat(c, chain, step21);
        var step23 = sem_cat(c, step22, "; add an explicit type annotation");
        var step24 = sem_cat(c, step20, step23);
        sem_fail(c, n, step24);
        return false;
    }
    var annotation: void* = sem_member(n, "type");
    if annotation != null {
        var step27 = sem_type(c, annotation);
        sem_set_type(&value.type, step27);
    } else {
        var initial: void* = sem_member(n, "value");
        if initial == null {
            var step30 = sem_name(value);
            var step31 = sem_cat(c, "Variable '", step30);
            var step32 = sem_cat(c, step31, "' requires a type annotation or an initializer");
            sem_fail(c, n, step32);
            return false;
        }
        if c.inferring.length >= 128 {
            sem_fail(c, n, "Foundation inferred-type dependency limit is 128");
            return false;
        }
        state.number = 1;
        sem_push(&c.inferring, n);
        var step34 = sem_expression(c, initial, null);
        value.value = step34;
        c.inferring.length--;
        if !sem_ok(c) || value.value == null {
            return false;
        }
        var step40 = sem_get(value.value);
        sem_set_type(&value.type, &step40.type);
        value.type.pointer_bytes = c.program.pointer_bytes;
    }
    if value.type.pointers == 0 && value.type.scalar == SVoid() {
        sem_fail(c, n, "A variable cannot have void type");
    }
    if !sem_ok(c) {
        return false;
    }
    state.number = 2;
    return true;
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_definitions;
import semantic_enums;
import semantic_layout;
import semantic_modules;
import semantic_statements;
import semantic_support;
import semantic_types;
import semantic_expressions;
import .library.vector;

// Semantic compiler over shared Foundation components.
// Temporary indexes and scratch allocations are scoped to one compilation.

fn sem_location_base(c: SemanticContext*, n: void*, depth: u32): void* {
    n = sem_surface_unwrap(n);
    if sem_is(n, "CoreLocation") {
        return sem_location(c, n, depth);
    }
    if sem_is(n, "TowerExpression") && sem_member(n, "left") == null
    && sem_member(n, "right") != null && sem_equal(sem_tokens(c, sem_child(n, 0)), "*") {
        return sem_surface_place(c, n);
    }
    return sem_operand(c, n, null);
}

fn sem_location(c: SemanticContext*, n: void*, depth: u32): void* {
    loop {
        if !((sem_is(n, "CoreCallArgument") || sem_is(n, "CoreOperand")) && sem_child_count(n) == 1) {
            break;
        }
        n = sem_child(n, 0);
    }
    if sem_is(n, "CorePointerArgument") {
        sem_node(c, n, KOperand());
        sem_fail(c, n, "Expected a value argument, got a type spelling");
        return n;
    }
    if depth > 128 {
        sem_node(c, n, KOperand());
        sem_fail(c, n, "Foundation field path limit is 128");
        return n;
    }
    if sem_get(n) != null {
        return n;
    }
    var module = sem_namespace(c, n);
    if module != null {
        if sem_editor_symbol(c, n, 1) {
            sem_node(c, n, KOperand());
            return n;
        }
        var name = sem_identifier(c, sem_member(n, "field"));
        var value = sem_node(c, n, KOperand());
        value.binding = sem_owned(c.globals, module, name);
        if value.binding != null {
            sem_declaration_type(c, value.binding);
            var declaration = sem_get(value.binding);
            sem_set_type(&value.type, &declaration.type);
        } else {
            sem_fail(c, n, sem_cat(c, "Unknown module variable '", sem_cat(c, name, "'")));
        }
        return n;
    }
    if sem_enum_operand(c, n) {
        sem_fail(c, n, "An enum member is a value, not an addressable location");
        return n;
    }
    if !(sem_is(n, "CoreLocation") || sem_is(n, "TowerNullAccess")) || sem_member(n, "base") == null {
        var name: void* = n;
        if sem_is(n, "CoreLocation") {
            name = sem_member(n, "name");
        }
        if name == null {
            sem_fail(c, n, "Malformed CoreLocation tree: missing capture 'name'");
            return n;
        }
        var value: FoundationNode* = sem_node(c, n, KOperand());
        var step24 = sem_lookup(c, name);
        value.binding = step24;
        if value.binding != null {
            var step26 = sem_get(value.binding);
            sem_set_type(&value.type, &step26.type);
        }
        return n;
    }
    var index: void* = sem_member(n, "index");
    if index != null {
        var value: FoundationNode* = sem_node(c, n, KIndex());
        var step30 = sem_member(n, "base");
        var step31 = depth + 1;
        var step32: void* = null;
        if sem_is(n, "TowerNullAccess") {
            step32 = sem_surface_nullable(c, step30, null);
        }
        else {
            step32 = sem_location_base(c, step30, step31);
        }
        value.left = step32;
        if !sem_ok(c) {
            return n;
        }
        var step35 = sem_get(value.left);
        var parent: FoundationType* = sem_type_copy(c, &step35.type);
        var step37 = parent.pointers != 0;
        value.indirect = step37;
        if parent.pointers != 0 {
            parent.pointers--;
            sem_set_type(&value.type, parent);
        } else {
            if parent.scalar == SArray() {
                var step40 = sem_get(parent.record);
                sem_set_type(&value.type, &step40.element);
            } else {
                sem_fail(c, n, "Indexing requires a pointer or an array");
                return n;
            }
        }
        if semantic_aggregate(&value.type) {
            sem_layout(c, value.type.record);
        }
        if semantic_size(&value.type) == 0 {
            sem_fail(c, n, "Cannot index a void pointer");
            return n;
        }
        var expected_type: FoundationType* = null;
        if sem_editor_contains(c, index) {
            c.editor.require_integer = true;
        }
        if sem_literal(c, index) {
            expected_type = sem_type_new(c, SUSize(), 0, null);
        }
        var step46 = sem_operand(c, index, expected_type);
        value.right = step46;
        if !sem_ok(c) {
            return n;
        }
        var step49 = sem_get(value.right);
        var step50 = semantic_integer(&step49.type);
        if semantic_enum(&step49.type) {
            step50 = false;
        }
        if !step50 {
            sem_fail(c, index, "An index must be an integer");
        }
        return n;
    }
    if !sem_shape(c, n, "base") || !sem_shape(c, n, "field") {
        return n;
    }
    var value: FoundationNode* = sem_node(c, n, KField());
    var step59 = sem_member(n, "base");
    var step60 = depth + 1;
    var step61: void* = null;
    if sem_is(n, "TowerNullAccess") {
        step61 = sem_surface_nullable(c, step59, null);
    }
    else {
        step61 = sem_location_base(c, step59, step60);
    }
    value.left = step61;
    if !sem_ok(c) {
        return n;
    }
    var step64 = sem_get(value.left);
    var parent: FoundationType* = &step64.type;
    var step65 = sem_member(n, "field");
    if sem_editor_capture(c, step65, 3, parent) {
        return n;
    }
    var step66 = sem_identifier(c, step65);
    sem_set_name(value, step66);
    var step67 = parent.pointers == 1;
    value.indirect = step67;
    if parent.scalar != SStruct() || parent.pointers > 1 {
        sem_fail(c, n, "Field access requires a struct or a single pointer to a struct");
        return n;
    }
    sem_layout(c, parent.record);
    if !sem_ok(c) {
        return n;
    }
    var step74 = sem_get(parent.record);
    var fields: vector(void*)* = &step74.items;
    for(var i: usize = 0; i < fields.length; i++) {
        var field: void* = fields.data[i];
        if sem_equal(sem_name(sem_get(field)), sem_name(value)) {
            value.binding = field;
        }
    }
    if value.binding == null {
        var step82 = sem_name(value);
        var step84 = sem_cat(c, sem_cat(c, "Unknown field '", step82), "' in '");
        var step87 = sem_cat(c, sem_name(sem_get(parent.record)), "'");
        sem_fail(c, n, sem_cat(c, step84, step87));
        return n;
    }
    var step89 = sem_get(value.binding);
    sem_set_type(&value.type, &step89.type);
    var step90 = sem_get(value.binding);
    value.byte_offset = step90.byte_offset;
    return n;
}

fn sem_operand(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if sem_editor_contains(c, n) {
        c.editor.value_required = true;
        c.editor.has_expected = expected_type != null;
        if c.editor.has_expected {
            sem_set_type(&c.editor.type, expected_type);
        }
    }
    if n == null {
        sem_fail(c, n, "Missing operand");
        return null;
    }
    c.value_depth++;
    var result: void* = sem_operand_impl(c, n, expected_type);
    c.value_depth--;
    return result;
}

fn sem_operand_impl(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if c.value_depth > 128 {
        sem_fail(c, n, "Foundation expression nesting limit is 128");
        return n;
    }
    n = sem_surface_unwrap(n);
    if sem_is(n, "TowerNullAccess") {
        var result = sem_surface_nullable(c, n, expected_type);
        if sem_ok(c) {
            var value = sem_get(result);
            if value.type.pointers == 0 {
                sem_fail(c, n, "A null-conditional scalar result must be consumed with ??; nullable scalar storage is not supported");
            } else {
                sem_surface_expected(c, result, expected_type);
            }
        }
        return result;
    }
    var surface = sem_is(n, "TowerExpression");
    surface ||= sem_is(n, "TowerComma");
    if surface {
        var result = sem_surface(c, n, expected_type);
        if sem_ok(c) {
            var value = sem_get(result);
            if semantic_aggregate(&value.type) {
                sem_fail(c, n, "Struct values require field access or a pointer; aggregate copies are not implemented");
            }
        }
        return result;
    }
    return sem_operand_leaf(c, n, expected_type);
}

fn sem_operand_leaf(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if c.value_depth > 128 {
        sem_fail(c, n, "Foundation expression nesting limit is 128");
        return n;
    }
    loop {
        if !((sem_is(n, "CoreCallArgument") || sem_is(n, "CoreOperand")) && sem_child_count(n) == 1) {
            break;
        }
        n = sem_child(n, 0);
    }
    var step11 = sem_is(n, "CoreCall");
    if sem_editor_contains(c, n) {
        if c.editor.has_expected {
            if sem_is(n, "CoreAddress") {
                if c.editor.type.pointers != 0 {
                    c.editor.type.pointers--;
                }
            }
            if sem_is(n, "CoreLoad") {
                c.editor.type.pointers++;
            }
        }
    }
    if step11 {
        if sem_get(n) == null && sem_call(c, n) == null || !sem_ok(c) {
            return n;
        }
        var v: FoundationNode* = sem_get(n);
        if v.type.pointers == 0 && v.type.scalar == SVoid() {
            sem_fail(c, n, "A void call cannot be used as a value");
            return n;
        }
    } else {
        if sem_is(n, "CoreAddress") || sem_is(n, "CoreLoad") {
            if !sem_shape(c, n, "name") {
                return n;
            }
            var address: bool = sem_is(n, "CoreAddress");
            var kind: u32 = 8;
            if address {
                kind = KAddress();
            }
            var value: FoundationNode* = sem_node(c, n, kind);
            if address {
                var step33 = sem_member(n, "name");
                var step34 = sem_location(c, step33, 0);
                value.value = step34;
            } else {
                var step35 = sem_member(n, "name");
                var load_expected: FoundationType* = null;
                if sem_editor_contains(c, step35) {
                    c.editor.require_pointer = true;
                    if c.editor.has_expected {
                        load_expected = &c.editor.type;
                    }
                }
                var step36 = sem_operand(c, step35, load_expected);
                value.value = step36;
            }
            if !sem_ok(c) {
                return n;
            }
            var step39 = sem_get(value.value);
            sem_set_type(&value.type, &step39.type);
            if address {
                value.type.pointers++;
            } else {
                if value.type.pointers == 0 {
                    sem_fail(c, n, "Load requires a pointer");
                    return n;
                } else {
                    value.type.pointers--;
                }
            }
        } else {
            if !sem_literal(c, n) {
                if !sem_enum_operand(c, n) {
                    n = sem_location(c, n, 0);
                }
            }
        }
    }
    if !sem_ok(c) {
        return n;
    }
    var value: FoundationNode* = sem_get(n);
    if value == null {
        value = sem_node(c, n, KOperand());
    }
    var text: u8* = sem_tokens(c, n);
    if sem_literal(c, n) {
        var nominal = expected_type != null;
        nominal &&= expected_type.pointers == 0;
        nominal &&= semantic_enum(expected_type);
        if nominal {
            sem_fail(c, n, "Enum values require a named member or an explicit conversion");
            return n;
        }
        value.constant = true;
        if sem_equal(text, "true") || sem_equal(text, "false") {
            var step55 = sem_type_new(c, SBool(), 0, null);
            sem_set_type(&value.type, step55);
            value.type.pointer_bytes = 4;
            var step56 = sem_equal(text, "true");
            var step57 = convert(u64, step56);
            value.bits = step57;
        } else {
            if sem_equal(text, "null") {
                if expected_type != null {
                    sem_set_type(&value.type, expected_type);
                } else {
                    var step60 = sem_type_new(c, SVoid(), 1, null);
                    sem_set_type(&value.type, step60);
                }
                value.bits = 0;
                if value.type.pointers == 0 {
                    sem_fail(c, n, "null requires a pointer type");
                }
            } else {
                if text[0] == 39 || text[0] == 34 {
                    value.kind = KString();
                    var step66 = sem_type_new(c, SU8(), 1, null);
                    sem_set_type(&value.type, step66);
                    var i: usize = 1;
                    var length: usize = sem_length(text);
                    loop {
                        if !(i + 1 < length) {
                            break;
                        }
                        var byte: u8 = text[i];
                        if byte == 92 && i + 2 < length {
                            i++;
                            byte = text[i];
                            if byte == 110 {
                                byte = 10;
                            } else {
                                if byte == 114 {
                                    byte = 13;
                                } else {
                                    if byte == 116 {
                                        byte = 9;
                                    }
                                }
                            }
                        }
                        sem_require(foundation_name_append(&value.name, byte));
                        i++;
                    }
                } else {
                    if expected_type != null {
                        sem_set_type(&value.type, expected_type);
                    } else {
                        var step80 = sem_type_new(c, SI32(), 0, null);
                        sem_set_type(&value.type, step80);
                        value.type.pointer_bytes = 4;
                    }
                    if !semantic_integer(&value.type) {
                        sem_fail(c, n, "An integer literal needs an integer type");
                        return n;
                    }
                    var negative: bool = text[0] == 45;
                    var number: u64 = 0;
                    var i: usize = 0;
                    if negative {
                        i = 1;
                    }
                    var length: usize = sem_length(text);
                    var maximum: u64 = 0;
                    maximum--;
                    for(; i < length; i++) {
                        var digit: u64 = convert(u64, text[i]);
                        digit = digit - 48;
                        var step89 = digit > 9;
                        if !step89 {
                            var step92 =(maximum -digit) / 10;
                            step89 = number > step92;
                        }
                        if step89 {
                            sem_fail(c, n, "Integer literal out of range");
                            break;
                        }
                        number = number * 10 + digit;
                    }
                    var mask: u64 = semantic_mask(&value.type);
                    var limit: u64 = mask;
                    var signed: bool = semantic_signed(&value.type);
                    if signed {
                        limit = mask / 2;
                        if negative {
                            limit++;
                        }
                    }
                    if number > limit || negative && !signed {
                        var step104 = sem_type_name(c, &value.type);
                        var step105 = sem_cat(c, "Integer literal out of range for ", step104);
                        sem_fail(c, n, step105);
                    }
                    if negative {
                        var negated: u64 = 0;
                        number = negated - number;
                    }
                    var step107 = number &mask;
                    value.bits = step107;
                }
            }
        }
    }
    if semantic_aggregate(&value.type) {
        sem_fail(c, n, "Struct values require field access or a pointer; aggregate copies are not implemented");
    }
    if expected_type != null && !semantic_type_equal(&value.type, expected_type) {
        var step113 = sem_type_name(c, expected_type);
        var step114 = sem_cat(c, "Expected ", step113);
        var step115 = sem_cat(c, step114, ", got ");
        var step116 = sem_type_name(c, &value.type);
        var step117 = sem_cat(c, step116, "; use an explicit conversion");
        var step118 = sem_cat(c, step115, step117);
        sem_fail(c, n, step118);
    }
    return n;
}

fn sem_builtin(c: SemanticContext*, n: void*, kind: u32, args: vector(void*)*): void* {
    var label = kind == 31;
    var jump = kind == 32;
    if label {
        sem_fail(c, n, "label is only valid as a function-body statement");
        return n;
    }
    if jump {
        sem_fail(c, n, "jump is only valid as a function-body statement");
        return n;
    }
    var value: FoundationNode* = sem_node(c, n, kind);
    var step2 = sem_type_new(c, SVoid(), 0, null);
    sem_set_type(&value.type, step2);
    value.type.pointer_bytes = 4;
    // Observe the argument at the editor hole even when later arguments have
    // not been written. Resolution still uses the ordinary type/value helpers.
    if sem_editor_contains(c, n) {
        for(var index: usize = 0; index != args.length; index++) {
            var argument = args.data[index];
            if sem_editor_contains(c, argument) {
                var type_argument = kind == KSizeOf();
                if kind == KAlignOf() {
                    type_argument = true;
                }
                if kind == KAllocate() {
                    type_argument = true;
                }
                if kind == KReallocate() {
                    type_argument = true;
                }
                if kind == KConvert() {
                    type_argument = true;
                }
                if kind == KBits() {
                    type_argument = true;
                }
                if index != 0 {
                    type_argument = false;
                }
                if type_argument {
                    sem_type(c, argument);
                } else {
                    var expected_type: FoundationType* = null;
                    var last = semantic_builtin_arity(kind);
                    last--;
                    var size_argument = kind == KAllocate();
                    if kind == KReallocate() {
                        size_argument = true;
                    }
                    if kind == KCopy() {
                        size_argument = true;
                    }
                    if kind == KFill() {
                        size_argument = true;
                    }
                    if index != last {
                        size_argument = false;
                    }
                    if size_argument {
                        expected_type = sem_type_new(c, SUSize(), 0, null);
                    }
                    if kind == KFree() {
                        c.editor.require_pointer = true;
                    }
                    if kind == KCopy() {
                        if index < 2 {
                            c.editor.require_pointer = true;
                        }
                    }
                    if kind == KFill() {
                        if index == 0 {
                            c.editor.require_pointer = true;
                        }
                        if index == 1 {
                            expected_type = sem_type_new(c, SU8(), 0, null);
                        }
                    }
                    if kind == KReallocate() {
                        if index == 1 {
                            expected_type = sem_type(c, args.data[0]);
                            expected_type.pointers++;
                        }
                    }
                    if kind == KTrap() {
                        if index == 0 {
                            expected_type = sem_type_new(c, SU8(), 1, null);
                        } else {
                            expected_type = sem_type_new(c, SU32(), 0, null);
                        }
                    }
                    sem_operand(c, argument, expected_type);
                }
                return n;
            }
        }
    }
    var count: usize = semantic_builtin_arity(kind);
    if args.length != count {
        var step5 = semantic_builtin_name(kind);
        var step7 = sem_cat(c, sem_cat(c, "Wrong argument count for '", step5), "': expected ");
        var step9 = sem_decimal(c, convert(u64, count));
        sem_fail(c, n, sem_cat(c, step7, step9));
        return n;
    }
    var step11 = sem_type_new(c, SUSize(), 0, null);
    if kind == KTrap() {
        value.left = sem_operand(c, args.data[0], sem_type_new(c, SU8(), 1, null));
        value.right = sem_operand(c, args.data[1], sem_type_new(c, SU32(), 0, null));
        return n;
    }
    var size: FoundationType* = step11;
    var byte: FoundationType* = sem_type_new(c, SU8(), 0, null);
    byte.pointer_bytes = 4;
    if kind == KPrint() {
        var step14 = sem_operand(c, args.data[0], null);
        value.value = step14;
    } else {
        if kind == KFree() || kind == KCopy() || kind == KFill() {
            var step21 = sem_operand(c, args.data[0], null);
            value.left = step21;
            if !sem_ok(c) {
                return n;
            }
            var step24 = sem_get(value.left);
            if step24.type.pointers == 0 {
                sem_fail(c, n, "Memory operations require a pointer");
            }
            if kind != KFree() {
                var step27 = sem_operand(c, args.data[2], size);
                value.value = step27;
                var expected_type: FoundationType* = null;
                if kind == KFill() {
                    expected_type = byte;
                }
                var step29 = sem_operand(c, args.data[1], expected_type);
                value.right = step29;
                if !sem_ok(c) {
                    return n;
                }
                var step33 = kind == KCopy();
                if step33 {
                    var step34 = sem_get(value.right);
                    step33 = step34.type.pointers == 0;
                }
                if step33 {
                    sem_fail(c, n, "copy requires source and destination pointers");
                }
            }
        } else {
            if kind == KSizeOf() || kind == KAlignOf() {
                var step40 = sem_type(c, args.data[0]);
                sem_set_type(&value.element, step40);
                if semantic_aggregate(&value.element) {
                    sem_layout(c, value.element.record);
                }
                sem_set_type(&value.type, size);
            } else {
                if kind == KAllocate() || kind == KReallocate() {
                    var step46 = sem_type(c, args.data[0]);
                    sem_set_type(&value.element, step46);
                    if semantic_aggregate(&value.element) {
                        sem_layout(c, value.element.record);
                    }
                    if semantic_size(&value.element) == 0 {
                        sem_fail(c, n, "Cannot allocate void elements");
                        return n;
                    }
                    sem_set_type(&value.type, &value.element);
                    value.type.pointers++;
                    var step50 = args.length -1;
                    var step51 = sem_operand(c, args.data[step50], size);
                    value.right = step51;
                    if kind == KReallocate() {
                        var step53 = sem_operand(c, args.data[1], &value.type);
                        value.left = step53;
                    }
                } else {
                    if kind == KConvert() || kind == KBits() {
                        var step58 = sem_type(c, args.data[0]);
                        sem_set_type(&value.type, step58);
                        var step59 = sem_operand(c, args.data[1], null);
                        value.value = step59;
                        if !sem_ok(c) {
                            return n;
                        }
                        var step62 = sem_get(value.value);
                        var source: FoundationType* = &step62.type;
                        if semantic_aggregate(&value.type) || value.type.pointers == 0 && value.type.scalar == SVoid() {
                            sem_fail(c, n, "Conversion requires scalar values");
                        }
                        if kind == KConvert() &&(value.type.pointers != 0 || source.pointers != 0) {
                            sem_fail(c, n, "Pointer reinterpretation requires bits");
                        }
                        var step76 = kind == KBits();
                        if step76 {
                            var step77 = semantic_width(&value.type);
                            var step78 = semantic_width(source);
                            step76 = step77 != step78 || !semantic_integer(&value.type) && value.type.pointers == 0 || !semantic_integer(source) && source.pointers == 0;
                        }
                        if step76 {
                            sem_fail(c, n, "bits requires equal-width integers or pointers");
                        }
                    } else {
                        sem_fail(c, n, "Unsupported foundation builtin");
                    }
                }
            }
        }
    }
    return n;
}

fn sem_call(c: SemanticContext*, n: void*): void* {
    if sem_editor_symbol(c, sem_member(n, "name"), 4) {
        sem_node(c, n, KCall());
        return n;
    }
    if !sem_shape(c, n, "name") {
        return null;
    }
    var step3 = sem_member(n, "name");
    var name: u8* = sem_identifier(c, step3);
    var step5 = sem_member(n, "args");
    var args: vector(void*)* = sem_collect(c, step5, "CoreCallArgument");
    var builtin: u32 = semantic_builtin_kind(name);
    if builtin != 0 {
        return sem_builtin(c, n, builtin, args);
    }
    if sem_resolve(c, c.type_functions, step3, name) != null {
        var step12 = sem_cat(c, "Type constructor '", name);
        var step13 = sem_cat(c, step12, "' produces a type, not a runtime value");
        sem_fail(c, n, step13);
        return n;
    }
    var definition: void* = sem_resolve(c, c.templates, step3, name);
    if definition != null {
        var step16 = generic_parameter_count(c.generics, definition);
        if args.length != step16 {
            var step18 = sem_cat(c, "Wrong argument count for template '", name);
            var step19 = sem_cat(c, step18, "'");
            sem_fail(c, n, step19);
            return n;
        }
        var arguments: vector(void*)* = sem_list(c);
        var values: vector(void*)* = sem_list(c);
        var i: usize = 0;
        for(; i < args.length; i++) {
            if generic_type_parameter(c.generics, definition, i) {
                var step25 = sem_type(c, args.data[i]);
                sem_push(arguments, sem_type_entity(c, step25));
            } else {
                sem_push(values, args.data[i]);
            }
            if !sem_ok(c) {
                return n;
            }
        }
        var instance: void* = generic_instantiate(c.generics, definition, n, arguments.data, arguments.length);
        if !sem_generic_ok(c, n) || instance == null {
            return n;
        }
        var step35 = sem_state(c, c.source_bases, instance);
        var step36 = sem_source_base(c, definition);
        step35.number = step36;
        if sem_get(instance) == null {
            var step39 = sem_instance_name(c, definition, arguments);
            sem_header(c, instance, step39, definition);
            if !sem_ok(c) {
                return n;
            }
            sem_push(&c.generated, instance);
        }
        var value: FoundationNode* = sem_node(c, n, KCall());
        var callee: FoundationNode* = sem_get(instance);
        value.binding = instance;
        sem_set_type(&value.type, &callee.type);
        i = 0;
        for(; i < values.length; i++) {
            var step46 = sem_get(callee.parameters.data[i]);
            var step47 = sem_operand(c, values.data[i], &step46.type);
            sem_push(&value.items, step47);
        }
        return n;
    }
    var value: FoundationNode* = sem_node(c, n, KCall());
    var step49 = sem_resolve(c, c.functions, step3, name);
    value.binding = step49;
    if value.binding == null {
        var step51 = sem_cat(c, "Unknown function '", name);
        var step52 = sem_cat(c, step51, "'");
        sem_fail(c, n, step52);
        return n;
    }
    var callee: FoundationNode* = sem_get(value.binding);
    sem_set_type(&value.type, &callee.type);
    var step54 = args.length != callee.parameters.length;
    // A completion snapshot may end before later arguments have been written.
    // Resolve every present argument using the real signature nonetheless.
    if sem_editor_contains(c, n) {
        step54 = args.length > callee.parameters.length;
    }
    if step54 {
        var step55 = sem_cat(c, "Wrong argument count for '", name);
        var step56 = sem_cat(c, step55, "'");
        sem_fail(c, n, step56);
        return n;
    }
    var i: usize = 0;
    for(; i < args.length; i++) {
        var step59 = sem_get(callee.parameters.data[i]);
        var step60 = sem_operand(c, args.data[i], &step59.type);
        sem_push(&value.items, step60);
    }
    return n;
}

fn sem_expression(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if sem_is(n, "CoreValue") && sem_child_count(n) == 1 {
        n = sem_child(n, 0);
    }
    var kind: u8* = sem_label(n);
    if sem_equal(kind, "CoreOperand") || sem_equal(kind, "CoreAddress") || sem_equal(kind, "CoreLoad") {
        return sem_operand(c, n, expected_type);
    }
    if n == null {
        sem_fail(c, n, "Missing expression");
        return null;
    }
    if sem_equal(kind, "CoreCall") {
        if sem_call(c, n) == null {
            return null;
        }
    } else {
        if sem_equal(kind, "CoreBinary") {
            if !sem_shape(c, n, "left") || !sem_shape(c, n, "op") || !sem_shape(c, n, "right") {
                return null;
            }
            var value: FoundationNode* = sem_node(c, n, KBinary());
            var op: u8* = sem_tokens(c, sem_member(n, "op"));
            var found: bool = false;
            for(var i: u32 = 0; i <= 13; i++) {
                if sem_equal(op, semantic_operator(i)) {
                    value.op = i;
                    found = true;
                    break;
                }
            }
            if !found {
                sem_fail(c, n, "Unknown foundation binary operation");
            }
            var input: FoundationType* = sem_type_new(c, SI32(), 0, null);
            input.pointer_bytes = 4;
            if expected_type != null {
                input = expected_type;
            }
            var comparison: bool = value.op >= OEq();
            var left: void* = sem_member(n, "left");
            var right: void* = sem_member(n, "right");
            if comparison || expected_type == null {
                var anchor: void* = left;
                if sem_literal(c, left) && !sem_literal(c, right) {
                    anchor = right;
                }
                var known: void* = sem_operand(c, anchor, null);
                if !sem_ok(c) || known == null {
                    return n;
                }
                var step54 = sem_get(known);
                input = &step54.type;
            }
            var step55 = sem_operand(c, left, input);
            value.left = step55;
            var nominal = input.pointers == 0;
            nominal &&= semantic_enum(input);
            if nominal {
                var equality = value.op == OEq();
                if value.op == ONe() {
                    equality = true;
                }
                if !equality {
                    sem_fail(c, n, "Enum operations require equality or an explicit integer conversion");
                }
            }
            if !sem_ok(c) {
                return n;
            }
            var pointer_offset: bool = input.pointers != 0 &&(value.op == OAdd() || value.op == OSub());
            var right_type: FoundationType* = input;
            if pointer_offset {
                right_type = null;
                if sem_literal(c, right) {
                    right_type = sem_type_new(c, SUSize(), 0, null);
                }
            }
            var step66 = sem_operand(c, right, right_type);
            value.right = step66;
            if !sem_ok(c) {
                return n;
            }
            if comparison {
                var step69 = sem_type_new(c, SBool(), 0, null);
                sem_set_type(&value.type, step69);
                value.type.pointer_bytes = 4;
            } else {
                sem_set_type(&value.type, input);
            }
            if pointer_offset {
                var step70 = sem_get(value.right);
                var step71 = semantic_integer(&step70.type);
                if semantic_enum(&step70.type) {
                    step71 = false;
                }
                if !step71 {
                    sem_fail(c, n, "A pointer offset must be an integer");
                }
                var element: FoundationType* = sem_type_copy(c, input);
                element.pointers--;
                if semantic_aggregate(element) {
                    sem_layout(c, element.record);
                }
                if semantic_size(element) == 0 {
                    sem_fail(c, n, "Cannot offset a void pointer");
                }
            } else {
                if !semantic_integer(input) && value.op != OEq() && value.op != ONe() {
                    sem_fail(c, n, "This operation requires integer operands");
                }
            }
        } else {
            var step82 = sem_cat(c, "Unsupported foundation expression '", kind);
            sem_fail(c, n, sem_cat(c, step82, "'"));
            return null;
        }
    }
    var value: FoundationNode* = sem_get(n);
    if value == null {
        return n;
    }
    if semantic_aggregate(&value.type) {
        sem_fail(c, n, "Struct values require field access or a pointer; aggregate copies are not implemented");
    }
    if expected_type != null && !semantic_type_equal(&value.type, expected_type) {
        var step91 = sem_type_name(c, expected_type);
        var step93 = sem_cat(c, sem_cat(c, "Expected ", step91), ", got ");
        var step94 = sem_type_name(c, &value.type);
        sem_fail(c, n, sem_cat(c, step93, step94));
    }
    return n;
}

