extern fn node_payload_init(kind: u32, data: void*): void;

extern fn syntax_node_init(data: SyntaxNode*): void;

extern fn foundation_node_init(data: FoundationNode*): void;

// Coordinator-owned identity and lifetime. Worlds do not share stores or type
// entities. The legacy host uses one default world until its sessions migrate.
struct CompilerWorld {
    store: EntityStore*;
    types: Entity*[9]; // CompilerComponentCount slots.
    registered: usize;
    grammar: CompilerGrammarCache;
}

export fn compiler_world_create(): CompilerWorld* {
    var world = alloc(CompilerWorld, 1);
    if world == null {
        return null;
    }
    fill(world, 0, sizeof(CompilerWorld));
    world.store = entity_store_create();
    if world.store == null {
        free(world);
        return null;
    }
    return world;
}

// Borrowed store and type handles; callers retain types they need to own.
export fn compiler_world_store(world: CompilerWorld*): EntityStore* {
    return world.store;
}

export fn compiler_world_grammar(world: CompilerWorld*): CompilerGrammarCache* {
    return &world.grammar;
}

export fn compiler_world_pinned(world: CompilerWorld*): bool {
    var pinned = world.store.views != 0;
    return pinned;
}

export fn compiler_world_type(world: CompilerWorld*, kind: u32): Entity* {
    if kind >= CompilerComponentCount() {
        return null;
    }
    var type = world.types[kind];
    if type != null {
        return type;
    }
    var size = sizeof(FoundationNode);
    var alignment = alignof(FoundationNode);
    var lifecycle = compiler_foundation_lifecycle();
    if kind == CompilerSyntax() {
        size = sizeof(SyntaxNode);
        alignment = alignof(SyntaxNode);
        lifecycle = compiler_syntax_lifecycle();
    }
    if kind <= CompilerParserMatch() {
        lifecycle = compiler_parser_lifecycle(kind);
        if kind == CompilerParserRule() {
            size = sizeof(ParserRuleData);
            alignment = alignof(ParserRuleData);
        }
        if kind == CompilerParserReference() {
            size = sizeof(ParserReferenceData);
            alignment = alignof(ParserReferenceData);
        }
        if kind == CompilerParserString() {
            size = sizeof(ParserStringData);
            alignment = alignof(ParserStringData);
        }
        if kind == CompilerParserRange() {
            size = sizeof(ParserRangeData);
            alignment = alignof(ParserRangeData);
        }
        if kind == CompilerParserMatch() {
            size = sizeof(ParserMatchData);
            alignment = alignof(ParserMatchData);
        }
    }
    if kind == CompilerSyntaxOrigin() {
        size = sizeof(SyntaxOrigin);
        alignment = alignof(SyntaxOrigin);
        lifecycle = compiler_origin_lifecycle();
    }
    if kind == CompilerSyntaxExpansion() {
        size = sizeof(SyntaxExpansion);
        alignment = alignof(SyntaxExpansion);
        lifecycle = compiler_expansion_lifecycle();
    }
    type = entity_create(world.store);
    if type == null {
        return null;
    }
    var registered = entity_register(type, size, alignment, lifecycle);
    if !registered {
        entity_release(type);
        return null;
    }
    world.types[kind] = type;
    world.registered++;
    return type;
}

export fn compiler_world_get(world: CompilerWorld*, owner: Entity*, kind: u32): void* {
    if owner == null {
        return null;
    }
    if owner.store != world.store {
        return null;
    }
    if kind >= CompilerComponentCount() {
        return null;
    }
    var type = world.types[kind];
    if type == null {
        return null;
    }
    return bits(void*, entity_component_data(entity_component_get(owner, type)));
}

// Reattachment preserves payload state. A failed attachment leaves the node
// unchanged; a successfully registered type may remain cached for a retry.
export fn compiler_world_component(world: CompilerWorld*, owner: Entity*, kind: u32): void* {
    if owner == null {
        return null;
    }
    if owner.store != world.store {
        return null;
    }
    var type = compiler_world_type(world, kind);
    if type == null {
        return null;
    }
    var data = compiler_world_get(world, owner, kind);
    if data != null {
        return data;
    }
    data = bits(void*, entity_component_data(entity_component_add(owner, type)));
    if data == null {
        return null;
    }
    if kind <= CompilerParserMatch() {
        node_payload_init(kind, data);
    }
    if kind == CompilerSyntax() {
        syntax_node_init(bits(SyntaxNode*, data));
    }
    if kind == CompilerFoundation() {
        foundation_node_init(bits(FoundationNode*, data));
    }
    if kind == CompilerSyntaxOrigin() {
        fill(data, 0, sizeof(SyntaxOrigin));
    }
    if kind == CompilerSyntaxExpansion() {
        fill(data, 0, sizeof(SyntaxExpansion));
    }
    return data;
}

// Failed disposal is non-mutating. All requests and views must drain first.
export fn compiler_world_dispose(world: CompilerWorld*): bool {
    // Drain frontend caches explicitly, after their requests have joined.
    var cached = world.grammar.bedrock != null;
    if cached {
        return false;
    }
    cached = world.grammar.patterns != null;
    if cached {
        return false;
    }
    if world.grammar.syntax is not null {
        return false;
    }
    if world.store.views != 0 {
        return false;
    }
    if entity_store_count(world.store) != world.registered {
        return false;
    }
    if entity_store_component_count(world.store) != 0 {
        return false;
    }
    var index: u32 = 0;
    for(; index < CompilerComponentCount(); index++) {
        var type = world.types[index];
        var present = type != null;
        if present {
            if entity_references(type) != 1 {
                return false;
            }
        }
    }
    index = 0;
    for(; index < CompilerComponentCount(); index++) {
        var type = world.types[index];
        var present = type != null;
        if present {
            entity_release(type);
        }
    }
    var disposed = entity_store_dispose(world.store);
    free(world);
    return disposed;
}

import bedrock;

// Shares Whitespace, LineComment, BlockComment, Identifier and String from bedrock.tower.
// The import applies Bedrock declarations before Foundation adds executable syntax.
token Number = /[0-9]+/ as number;

// Bootstrap semantic ABI: these Core* tree labels and captures name typed ops.
// No precedence hierarchy: a binary value has two operands and one operator.
parse CoreTypeName = $name:Identifier | $base:CoreTypeName '.' $field:Identifier;
parse CoreType = $name:CoreTypeName | $base:CoreType '*' | $base:CoreType '[' $count:CoreArrayCount ']'
                | $name:CoreTypeName '(' $args:CoreTypeArguments? ')';
parse CoreArrayCount = Number | Identifier | '-' Number;
parse CoreTypeArgument = CoreType | Number | '-' Number;
parse CoreTypeArguments = CoreTypeArgument | CoreTypeArguments ',' CoreTypeArgument;
parse CoreLocation = $name:Identifier | $base:CoreLocation '.' $field:Identifier;
parse CoreOperand = CoreLocation | Number | '-' Number | 'true' | 'false' | 'null' | String;
parse CoreLocation |= $base:CoreLocation '[' $index:CoreOperand ']';
parse CoreOperator = '+' | '-' | '*' | '/' | '%' | '&' | '|' | '^' | '==' | '!=' | '<' | '<=' | '>' | '>=';
parse CoreBinary = $left:CoreOperand $op:CoreOperator $right:CoreOperand;
parse CoreAddress = '&' $name:CoreLocation;
parse CoreLoad = '*' $name:CoreLocation;
parse CoreValue = CoreOperand | CoreBinary;
parse CoreTarget = $name:CoreLocation | '*' $name:CoreLocation;
parse CoreDeclare = 'var' $name:Identifier ':' $type:CoreType ';'
                   | 'var' $name:Identifier ':' $type:CoreType '=' $value:CoreValue ';'
                   | 'var' $name:Identifier '=' $value:CoreValue ';';
parse CoreAssign = $target:CoreTarget '=' $value:CoreValue ';';
parse Statement = CoreDeclare | CoreAssign;
parse CoreBlock = '{' Statement* '}';
parse CoreIf = 'if' $condition:CoreOperand $body:CoreBlock
              | 'if' $condition:CoreOperand $body:CoreBlock 'else' $otherwise:CoreBlock;
parse CoreLoop = 'loop' $body:CoreBlock;
parse CoreBreak = 'break' ';';
parse CoreContinue = 'continue' ';';
parse Statement |= CoreBlock | CoreIf | CoreLoop | CoreBreak | CoreContinue;

parse CoreParameter = $name:Identifier ':' $type:CoreType;
parse CoreParameters = CoreParameter | CoreParameters ',' CoreParameter;
// Calls share one argument grammar. Type arguments are resolved semantically.
parse CoreCallArgument = CoreOperand | CorePointerArgument;
parse CorePointerArgument = $base:CoreCallArgument '*' | $base:CorePointerArgument '[' $index:CoreOperand ']';
parse CoreArguments = CoreCallArgument | CoreArguments ',' CoreCallArgument;
parse CoreCall = $name:CoreLocation '(' $args:CoreArguments? ')';
parse CoreOperand |= CoreCall | CoreAddress | CoreLoad;
parse CoreFunction = 'fn' $name:Identifier '(' $params:CoreParameters? ')' ':' $type:CoreType $body:CoreBlock;
parse CoreReturn = 'return' $value:CoreOperand? ';';
parse CoreCallStatement = $call:CoreCall ';';
parse Statement |= CoreFunction | CoreReturn | CoreCallStatement;

parse CoreField = $name:Identifier ':' $type:CoreType ';';
parse CoreStruct = 'struct' $name:Identifier '{' $fields:CoreField* '}';
parse Statement |= CoreStruct;

// Nominal integer representations and members survive Foundation round trips.
// Tower may add automatic discriminants; canonical Foundation makes each explicit.
parse CoreEnumInteger = Number | '-' Number;
parse CoreEnumMember = $name:Identifier '=' $value:CoreEnumInteger;
parse CoreEnumMembers = CoreEnumMember | CoreEnumMembers ',' CoreEnumMember;
parse CoreEnum = 'enum' $name:Identifier ':' $type:CoreType '{' $fields:CoreEnumMembers ','? '}';
parse Statement |= CoreEnum;

// Raw memory and external symbols; safety policies can be layered above these.
parse CoreExternal = 'extern' 'fn' $name:Identifier '(' $params:CoreParameters? ')' ':' $type:CoreType ';';
parse CoreExport = 'export' 'fn' $name:Identifier '(' $params:CoreParameters? ')' ':' $type:CoreType $body:CoreBlock;
parse Statement |= CoreExternal | CoreExport;

