struct DriverCompilation {
    request: DriverRequest*;
    timing: DriverTiming*;
    execution: ExecutionSession;
    backend: void*;
    generated: ByteBuffer;
    output: ByteBuffer;
    text: u8*;
    length: usize;
    width: u32;
    profile: u32;
    packaged: bool;
}

fn driver_install_grammar(request: DriverRequest*, canonical: bool): bool {
    if canonical && !driver_request_canonical(request) {
        driver_error("", driver_request_error(request));
        return false;
    }
    var first = canonical ? DriverCanonicalBedrockText(): DriverBedrockText();
    // Large enough for each explicitly selected 64-bit standard-library profile.
    // Only the selected foreign callee writes this temporary ABI storage.
    var foreign: usize[4];
    driver_syntax_bedrock(&foreign[0], request.text[first].data);
    var message = driver_syntax_data(&foreign[0]);
    var ok = message[0] == 0;
    if !ok {
        driver_error("", message);
    }
    if driver_syntax_heap(&foreign[0]) {
        driver_syntax_delete(driver_syntax_storage(&foreign[0]));
    }
    if !ok {
        return false;
    }
    driver_syntax_foundation(&foreign[0], request.text[first + 1].data);
    message = driver_syntax_data(&foreign[0]);
    ok = message[0] == 0;
    if !ok {
        driver_error("", message);
    }
    if driver_syntax_heap(&foreign[0]) {
        driver_syntax_delete(driver_syntax_storage(&foreign[0]));
    }
    return ok;
}

fn driver_compile_report(state: DriverCompilation*, error: u8*, offset: usize): void {
    var request = state.request;
    // Original inputs remain pinned even after optimization replaces the source.
    driver_report(error, offset, request.text[DriverSourceText()].data,
    request.text[DriverSourceText()].length, request.options.source, request.modules);
}

fn driver_compile_program(state: DriverCompilation*): bool {
    if driver_execution_compile(&state.execution, state.text, state.length, state.width, *state.request.slot) {
        return true;
    }
    driver_compile_report(state, state.execution.error.data ?? "Unable to compile source", state.execution.machine.error_offset);
    return false;
}

fn driver_compile_backend(state: DriverCompilation*, target: u8*): bool {
    if state.backend != null {
        backend_close(state.backend);
    }
    state.backend = backend_open(target);
    if state.backend == null {
        driver_error("Unable to allocate backend storage", "");
        return false;
    }
    if backend_error(state.backend)[0] != 0 {
        driver_error("", backend_error(state.backend));
        return false;
    }
    return true;
}

fn driver_backend_failed(state: DriverCompilation*): bool {
    driver_compile_report(state, backend_error(state.backend), backend_error_offset(state.backend));
    return false;
}

fn driver_compile_format(state: DriverCompilation*, root: void*, out: ByteBuffer*): bool {
    var formatted: FormatResult;
    fill(&formatted, 0, sizeof(FormatResult));
    format_entity(&formatted, root, syntax_component_type(), null, parser_match_get_type());
    var ok = !formatted.failed && bytes_assign_text(out, formatted.text.data, formatted.text.length);
    format_dispose(&formatted);
    if !ok {
        driver_error("Unable to allocate canonical formatted source", "");
    }
    return ok;
}

fn driver_compile_ir(state: DriverCompilation*): bool {
    var options = state.request.options;
    var raw = backend_raw(state.backend);
    var optimized = backend_optimized(state.backend);
    return driver_write_ir(options.raw, raw, strlen(raw), options.optimized, optimized, strlen(optimized));
}

extern fn driver_write_ir(raw_path: u8*, raw: u8*, raw_length: usize, optimized_path: u8*, optimized: u8*, optimized_length: usize): bool;

fn driver_compile_normalize(state: DriverCompilation*): bool {
    if !driver_compile_program(state) {
        return false;
    }
    if !driver_compile_backend(state, state.width == 4 ? "wasm32-unknown-unknown": "wasm64-unknown-unknown") {
        return false;
    }
    var program = &state.execution.program;
    if !backend_lower(state.backend, program.root, program.functions.data, program.functions.length, state.width, false)
    || !backend_optimize_interpreter(state.backend, state.request.options.optimize) {
        return driver_backend_failed(state);
    }
    if !driver_compile_ir(state) {
        return false;
    }
    var imported: SemanticProgram;
    fill(&imported, 0, sizeof(SemanticProgram));
    semantic_initialize(&imported, tower_node_create(), state.width);
    var root = imported.root;
    var ok = backend_import_foundation(state.backend, root);
    if ok {
        ok = driver_compile_format(state, root, &state.generated);
    }
    else {
        driver_backend_failed(state);
    }
    semantic_program_dispose(&imported);
    entity_release(root);
    if !ok || !driver_install_grammar(state.request, true) {
        return false;
    }
    driver_request_stage(state.request);
    state.text = state.generated.data;
    state.length = state.generated.length;
    return true;
}

fn driver_compile_package(state: DriverCompilation*): bool {
    if !driver_install_grammar(state.request, true) {
        return false;
    }
    var data = state.text;
    if !execution_package_load(&state.execution, data, state.length, *state.request.slot) {
        if state.execution.program.error.length != 0 {
            driver_compile_report(state, state.execution.error.data, state.execution.machine.error_offset);
        } else {
            driver_error("", state.execution.error.data);
        }
        return false;
    }
    state.width = state.execution.program.pointer_bytes;
    state.profile = convert(u32, data[24]);
    state.length = bytecode_source_size(data);
    if !bytes_assign_text(&state.generated, data + 56, state.length) {
        return false;
    }
    state.text = state.generated.data;
    return true;
}

fn driver_compile_dependencies(state: DriverCompilation*, output: u8*): bool {
    if frontend_modules_depfile(state.request.modules, output, state.request.options.depfile) {
        return true;
    }
    driver_error("Cannot write dependency file: ", state.request.options.depfile);
    return false;
}

fn driver_compile_text_output(state: DriverCompilation*): i32 {
    var options = state.request.options;
    var emit = options.emit;
    var output = options.output;
    if output[0] == 0 {
        var suffix = ".disassembled.tower";
        if driver_same(emit, "bytecode") {
            suffix = ".towerbc";
        }
        if driver_same(emit, "c") {
            suffix = ".c";
        }
        if driver_same(emit, "brightscript") {
            suffix = ".brs";
        }
        if !bytes_append(&state.output, options.source, driver_extension(options.source))
        || !driver_text(&state.output, suffix) || !host_text_terminate(&state.output) {
            return 1;
        }
        output = state.output.data;
    }
    if !driver_output_safe(options.source, output) || !driver_compile_dependencies(state, output) {
        return 1;
    }
    var program = &state.execution.program;
    if !options.comments {
        semantic_strip_comments(program.root);
    }
    var text: ByteBuffer;
    var error: ByteBuffer;
    fill(&text, 0, sizeof(ByteBuffer));
    fill(&error, 0, sizeof(ByteBuffer));
    var ok = true;
    if driver_same(emit, "bytecode") {
        ok = driver_install_grammar(state.request, true);
        var profile = state.packaged ? state.profile:(options.optimize ? convert(u32, 1): convert(u32, 2));
        ok &&= execution_package_encode(program, *state.request.slot, profile, &text, &error);
    } else {
        if driver_same(emit, "foundation") {
            ok = driver_compile_format(state, program.root, &text);
        }
        else {
            if driver_same(emit, "c") {
                c_emit(&text, &error, program.root, state.width, options.comments);
            }
            else {
                roku_emit(&text, &error, program.root, state.width, options.comments);
            }
        }
    }
    if error.length != 0 {
        if host_text_terminate(&error) {
            driver_error("", error.data);
        }
        ok = false;
    }
    ok &&= driver_write_file(output, text.data, text.length);
    bytes_dispose(&text);
    bytes_dispose(&error);
    return ok ? 0: 1;
}

fn driver_compile_interpret(state: DriverCompilation*): i32 {
    var options = state.request.options;
    if !driver_compile_dependencies(state, options.output) {
        return 1;
    }
    driver_timing_mark(state.timing, options.timings, "compile");
    if options.fast || state.packaged {
        if !driver_execution_fast(&state.execution) {
            driver_error("Unable to allocate interpreter cache", "");
            return 1;
        }
        driver_timing_mark(state.timing, options.timings, "prepare");
    }
    var execution = &state.execution;
    if !driver_execution_start(execution) {
        driver_compile_report(state, execution.error.data, execution.machine.error_offset);
        return 1;
    }
    while !execution.machine.done {
        if execution.fast != null {
            fast_interpreter_step(&execution.machine, execution.fast, 10000);
        }
        else {
            interpreter_step(&execution.machine, 10000);
        }
        driver_execution_flush(execution);
    }
    driver_timing_mark(state.timing, options.timings, "execute");
    if execution.error.length != 0 {
        driver_compile_report(state, execution.error.data, execution.machine.error_offset);
        return 1;
    }
    return 0;
}

fn driver_compile_object(state: DriverCompilation*, started: u64): i32 {
    var options = state.request.options;
    var program = &state.execution.program;
    var parsed = driver_clock();
    if !backend_lower(state.backend, program.root, program.functions.data, program.functions.length, state.width, options.library) {
        driver_backend_failed(state);
        return 1;
    }
    var lowered = driver_clock();
    if !backend_optimize(state.backend, options.optimize) {
        driver_backend_failed(state);
        return 1;
    }
    var optimized = driver_clock();
    if !backend_emit(state.backend) {
        driver_backend_failed(state);
        return 1;
    }
    var emitted = driver_clock();
    if !driver_compile_dependencies(state, options.output) {
        return 1;
    }
    driver_timing_mark(state.timing, options.timings, "compile");
    if options.timings {
        driver_timing_value(state.timing, "parse", parsed -started);
        driver_timing_value(state.timing, "before", lowered -parsed);
        driver_timing_value(state.timing, "after", optimized -lowered);
        driver_timing_value(state.timing, "emit", emitted -optimized);
    }
    if !driver_compile_ir(state) {
        return 1;
    }
    var wasm = strstr(options.target, "wasm") == options.target;
    var windows = strstr(options.target, "windows") != null;
    var output = options.output[0] == 0 ? driver_output_name(options.emit, wasm, windows): options.output;
    if driver_same(options.emit, "object") {
        return driver_write_file(output, backend_bytes(state.backend), backend_size(state.backend)) ? 0: 1;
    }
    if driver_same(options.emit, "llvm") || driver_same(options.emit, "llvm-optimized") {
        var text = driver_same(options.emit, "llvm") ? backend_raw(state.backend): backend_optimized(state.backend);
        return driver_write_file(output, text, strlen(text)) ? 0: 1;
    }
    if !driver_same(options.emit, "exe") {
        driver_error("Unknown output kind: ", options.emit);
        return 1;
    }
    var i: usize = 0;
    while i < options.link_count {
        if !driver_platform_regular(options.links[i]) {
            driver_error("Missing link input: ", options.links[i]);
            return 1;
        }
        ++i;
    }
    var link = driver_link_open(options.target, options.cc, options.linker, options.sysroot, output,
    state.request.root, wasm, windows, state.timing, options.timings);
    if link == null {
        return 1;
    }
    i = 1;
    while i < program.functions.length {
        var function = sem_get(program.functions.data[i]);
        if function.external {
            driver_link_import(link, backend_function_name(state.backend, i));
        }
        if function.exported {
            driver_link_export(link, backend_function_name(state.backend, i));
        }
        ++i;
    }
    i = 0;
    while i < options.link_count {
        driver_link_input(link, options.links[i]);
        ++i;
    }
    return driver_link_run(link, backend_bytes(state.backend), backend_size(state.backend));
}

extern fn driver_output_name(emit: u8*, wasm: bool, windows: bool): u8*;

fn driver_compile_run(state: DriverCompilation*): i32 {
    var options = state.request.options;
    state.text = state.request.text[DriverSourceText()].data;
    state.length = state.request.text[DriverSourceText()].length;
    state.packaged = driver_same(options.source + driver_extension(options.source), ".towerbc");
    if state.packaged {
        if !driver_compile_package(state) {
            return 1;
        }
    } else {
        var i: usize = 0;
        while i < state.length {
            if state.text[i] == 0 {
                driver_error("Source contains NUL bytes", "");
                return 1;
            }
            ++i;
        }
        if !driver_compile_backend(state, options.target) {
            return 1;
        }
        state.width = backend_pointer_bytes(state.backend);
        var normalize = driver_same(options.emit, "bytecode") || driver_same(options.emit, "brightscript")
        ||(options.interpret && options.fast) ||(driver_same(options.emit, "c") && options.optimize);
        if normalize && !driver_compile_normalize(state) {
            return 1;
        }
        var started = driver_clock();
        if !driver_compile_program(state) {
            return 1;
        }
        var textual = driver_same(options.emit, "foundation") || driver_same(options.emit, "bytecode")
        || driver_same(options.emit, "c") || driver_same(options.emit, "brightscript");
        if !textual && !options.interpret {
            return driver_compile_object(state, started);
        }
    }
    if driver_same(options.emit, "foundation") || driver_same(options.emit, "bytecode")
    || driver_same(options.emit, "c") || driver_same(options.emit, "brightscript") {
        return driver_compile_text_output(state);
    }
    return driver_compile_interpret(state);
}

export fn driver_compile(options: DriverOptions*, resources: u8*, timing: DriverTiming*, request: DriverRequest*): i32 {
    driver_request_bind(request, driver_syntax_slot());
    if !driver_install_grammar(request, false) {
        return 1;
    }
    driver_timing_mark(timing, options.timings, "bootstrap");
    var state: DriverCompilation;
    fill(&state, 0, sizeof(DriverCompilation));
    state.request = request;
    state.timing = timing;
    var result = driver_compile_run(&state);
    driver_execution_close(&state.execution);
    if state.backend != null {
        backend_close(state.backend);
    }
    bytes_dispose(&state.generated);
    bytes_dispose(&state.output);
    return result;
}

import tower;
import driver_types;
import driver_prepare;
import driver_timing;
import driver_platform;
import driver_support;
import driver_request;
import driver_compile;
import .library.bytes_types;
import .library.bytes_interface;

extern fn LLVMGetDefaultTargetTriple(): u8*;

extern fn LLVMDisposeMessage(message: u8*): void;

extern fn driver_dispose(options: DriverOptions*): void;

extern fn driver_resource_root(out: ByteBuffer*, executable: u8*): bool;

// One invocation owns argv-derived options and all host buffers until compilation
// returns. No process-global request state is introduced by the entry point.
// Compiler services are synchronous and may only borrow these pinned views.
fn driver_entry_compile(options: DriverOptions*, timing: DriverTiming*): i32 {
    var executable: ByteBuffer;
    var resources: ByteBuffer;
    fill(&executable, 0, sizeof(ByteBuffer));
    fill(&resources, 0, sizeof(ByteBuffer));
    var located = driver_platform_executable(&executable);
    located &&= driver_resource_root(&resources, executable.data);
    var result: i32 = 1;
    if located {
        var request: DriverRequest;
        if driver_request_open(&request, options, resources.data) {
            result = driver_compile(options, resources.data, timing, &request);
        } else {
            driver_error("", driver_request_error(&request));
        }
        driver_request_close(&request);
    } else {
        driver_error("Cannot locate compiler resources", "");
    }
    bytes_dispose(&resources);
    bytes_dispose(&executable);
    return result;
}

export fn main(argc: i32, argv: u8**): i32 {
    var timing = driver_timing_open();
    var target = LLVMGetDefaultTargetTriple();
    if target == null {
        driver_error("Cannot determine default target", "");
        driver_timing_close(timing, false);
        return 1;
    }
    var options: DriverOptions;
    var parsed = driver_prepare(&options, convert(usize, argc), argv, target);
    var status: i32 = 1;
    if parsed == 0 {
        status = driver_entry_compile(&options, timing);
    } else {
        if parsed == 2 {
            status = 0;
        }
    }
    driver_dispose(&options);
    LLVMDisposeMessage(target);
    driver_timing_close(timing, options.timings);
    return status;
}

import tower;
import driver_api;
import .compiler.execution_session;
import driver_support;
import driver_platform;
import .library.bytes_interface;
import .library.bytes_types;
import .compiler.interpreter_types;
import .compiler.semantic_program_types;
import .compiler.foundation_types;

// Shared request ownership; only platform transport remains in this host.
fn driver_execution_close(execution: ExecutionSession*): void {
    execution_session_close(execution);
}

fn driver_execution_compile(execution: ExecutionSession*, text: u8*, length: usize, width: u32, modules: void*): bool {
    return execution_session_compile(execution, text, length, width, modules);
}

fn driver_execution_start(execution: ExecutionSession*): bool {
    return execution_session_start(execution);
}

fn driver_execution_fast(execution: ExecutionSession*): bool {
    return execution_session_fast(execution);
}

fn driver_execution_flush(execution: ExecutionSession*): void {
    driver_platform_write(1, execution.output.data, execution.output.length);
    execution.output.length = 0;
}

export fn im_pointer_bytes(machine: IMState*): usize {
    return convert(usize, bits(ExecutionSession*, machine).program.pointer_bytes);
}

export fn im_root(machine: IMState*): void* {
    return bits(ExecutionSession*, machine).program.root;
}

export fn im_has_foreign(machine: IMState*): bool {
    return true;
}

export fn im_fail(machine: IMState*, text: u8*, offset: usize): void {
    execution_session_fail(bits(ExecutionSession*, machine), text, offset);
}

extern fn abort(): void;

export fn im_missing_foreign(machine: IMState*, node: void*, offset: usize): void {
    var text: ByteBuffer;
    fill(&text, 0, sizeof(ByteBuffer));
    var function = sem_get(node);
    var ok = driver_text(&text, "No interpreter implementation registered for external function '");
    ok &&= bytes_append(&text, function.name.data, function.name.length);
    ok &&= driver_text(&text, "'");
    ok &&= host_text_terminate(&text);
    im_fail(machine, ok ? text.data: "Unable to allocate interpreter diagnostic", offset);
    bytes_dispose(&text);
}

export fn im_append(machine: IMState*, text: u8*, count: usize): void {
    execution_session_append(bits(ExecutionSession*, machine), text, count);
}

extern fn memcmp(left: u8*, right: u8*, count: usize): i32;

extern fn driver_platform_write_result(fd: i32, data: u8*, length: usize): bool;

export fn im_foreign(machine: IMState*, node: void*, args: u64*, count: usize): u64 {
    var function = sem_get(node);
    if function.name.length != 14 || memcmp(function.name.data, "platform_write", 14) != 0 || count != 3 {
        var text: ByteBuffer;
        fill(&text, 0, sizeof(ByteBuffer));
        var ok = driver_text(&text, "No native interpreter binding for '");
        ok &&= bytes_append(&text, function.name.data, function.name.length);
        ok &&= driver_text(&text, "'");
        ok &&= host_text_terminate(&text);
        im_fail(machine, ok ? text.data: "Unable to allocate interpreter diagnostic", 0);
        bytes_dispose(&text);
        return 0;
    }
    if args[0] != 1 && args[0] != 2 {
        return ~convert(u64, 0);
    }
    var data = interpreter_bytes(machine, args[1], convert(usize, args[2]), 0);
    if data == null {
        return ~convert(u64, 0);
    }
    driver_execution_flush(bits(ExecutionSession*, machine));
    if driver_platform_write_result(convert(i32, args[0]), data, convert(usize, args[2])) {
        return args[2];
    }
    return ~convert(u64, 0);
}

import tower;
import .compiler.host_text;
import .library.bytes_interface;
import .library.bytes_types;

// Opaque libc file handles are temporary platform services, not Tower values or
// program storage. Paths and bytes are explicit inputs; no host file is read
// during constant evaluation. The CLI calls these at its execution stage.
extern fn fopen(path: u8*, mode: u8*): void*;

extern fn fread(data: u8*, size: usize, count: usize, file: void*): usize;

extern fn fwrite(data: u8*, size: usize, count: usize, file: void*): usize;

extern fn ferror(file: void*): i32;

extern fn feof(file: void*): i32;

extern fn fclose(file: void*): i32;

// Success replaces out atomically, including the terminating NUL view. Failure
// leaves its old contents intact and closes the file on every path.
export fn driver_read_file(path: u8*, out: ByteBuffer*): bool {
    var file = fopen(path, "rb");
    if file == null {
        return false;
    }
    var next: ByteBuffer;
    fill(&next, 0, sizeof(ByteBuffer));
    var chunk: u8[16384];
    var ok = true;
    loop {
        var count = fread(&chunk[0], 1, 16384, file);
        ok = bytes_append(&next, &chunk[0], count);
        if !ok {
            break;
        }
        if ferror(file) != 0 {
            ok = false;
            break;
        }
        if feof(file) != 0 {
            break;
        }
        if count == 0 {
            ok = false;
            break;
        }
    }
    if !(fclose(file) == 0) {
        ok = false;
    }
    ok &&= host_text_terminate(&next);
    if ok {
        bytes_dispose(out);
        out.data = next.data;
        out.length = next.length;
        out.capacity = next.capacity;
    } else {
        bytes_dispose(&next);
    }
    return ok;
}

// Output is binary (including NUL). A write/close failure is reported; callers
// must not treat a partial output file as a successful compiler artifact.
export fn driver_write_file(path: u8*, data: u8*, count: usize): bool {
    var file = fopen(path, "wb");
    if file == null {
        return false;
    }
    var written: usize = 0;
    var ok = true;
    loop {
        if written == count {
            break;
        }
        var next = data + written;
        var remaining = count -written;
        var amount = fwrite(next, 1, remaining, file);
        if amount == 0 {
            ok = false;
            break;
        }
        written = written + amount;
    }
    if ferror(file) != 0 {
        ok = false;
    }
    if !(fclose(file) == 0) {
        ok = false;
    }
    return ok;
}

import tower;
import .library.bytes_types;
import .library.bytes_interface;
import driver_support;
import driver_timing;
import driver_platform;

struct DriverLink {
    target: u8*;
    cc: u8*;
    linker: u8*;
    sysroot: u8*;
    output: u8*;
    root: u8*;
    wasm: bool;
    windows: bool;
    timing: DriverTiming*;
    timings: bool;
    program: ByteBuffer;
    runtime: ByteBuffer;
    allowed: ByteBuffer;
    imports: ByteBuffer;
    exports: DriverArguments;
    inputs: DriverArguments;
    ok: bool;
}

export fn driver_link_open(target: u8*, cc: u8*, linker: u8*, sysroot: u8*, output: u8*, root: u8*, wasm: bool, windows: bool, timing: DriverTiming*, timings: bool): DriverLink* {
    var link = alloc(DriverLink, 1);
    if link == null {
        driver_error("Unable to allocate link storage", "");
        return null;
    }
    fill(link, 0, sizeof(DriverLink));
    link.target = target;
    link.cc = cc;
    link.linker = linker;
    link.sysroot = sysroot;
    link.output = output;
    link.root = root;
    link.wasm = wasm;
    link.windows = windows;
    link.timing = timing;
    link.timings = timings;
    driver_arguments_init(&link.exports);
    driver_arguments_init(&link.inputs);
    link.ok = driver_text(&link.imports, "tower_print\ntower_trap\n");
    return link;
}

export fn driver_link_import(link: DriverLink*, name: u8*): void {
    link.ok &&= driver_text(&link.imports, name);
    link.ok &&= driver_text(&link.imports, "\n");
}

export fn driver_link_export(link: DriverLink*, name: u8*): void {
    driver_argument(&link.exports, "", name);
}

export fn driver_link_input(link: DriverLink*, name: u8*): void {
    driver_argument(&link.inputs, "", name);
}

fn driver_link_compile_arguments(link: DriverLink*, args: DriverArguments*): void {
    driver_argument(args, "", link.cc);
    driver_argument(args, "--target=", link.target);
    driver_argument(args, "", "-O2");
    driver_argument(args, "", "-ffreestanding");
    driver_argument(args, "", "-fno-builtin");
    driver_argument(args, "", "-c");
    driver_argument(args, link.root, driver_runtime_resource(link.target));
    driver_argument(args, "", "-o");
    driver_argument(args, "", link.runtime.data);
    if link.sysroot[0] != 0 {
        driver_argument(args, "--sysroot=", link.sysroot);
    }
    driver_argument(args, "", "-mllvm");
    driver_argument(args, "", "-disable-loop-idiom-all");
    driver_argument(args, "", "-Wno-override-module");
}

extern fn strstr(text: u8*, part: u8*): u8*;

fn driver_runtime_resource(target: u8*): u8* {
    if strstr(target, "wasm32") == target {
        return "/runtime-wasm32.ll";
    }
    var arm = strstr(target, "aarch64") == target;
    arm ||= strstr(target, "arm64") == target;
    var x64 = strstr(target, "x86_64") == target;
    var supported = arm;
    if x64 {
        supported = true;
    }
    if !supported {
        return null;
    }
    if strstr(target, "windows") != null {
        if arm {
            return "/runtime-windows-arm64.ll";
        }
        return "/runtime-windows-x64.ll";
    }
    if strstr(target, "apple") != null {
        if arm {
            return "/runtime-macos-arm64.ll";
        }
        return "/runtime-macos-x64.ll";
    }
    if arm {
        return "/runtime-host-linux-arm64.ll";
    }
    return "/runtime-host-linux-x64.ll";
}

fn driver_link_arguments(link: DriverLink*, args: DriverArguments*): void {
    var linker = link.linker;
    if linker[0] == 0 {
        linker = link.cc;
        if link.windows {
            linker = "lld-link-19";
        }
        if link.wasm {
            linker = "wasm-ld-19";
        }
    }
    driver_argument(args, "", linker);
    if link.wasm {
        driver_argument(args, "", "--no-entry");
        driver_argument(args, "", "--export=tower_main");
        driver_argument(args, "", "--export-memory");
        driver_argument(args, "--allow-undefined-file=", link.allowed.data);
        driver_argument(args, "", "--stack-first");
        driver_argument(args, "", "-z");
        driver_argument(args, "", "stack-size=4194304");
        driver_argument(args, "", "--max-memory=268435456");
    } else {
        if link.windows {
            driver_argument(args, "", "/entry:mainCRTStartup");
            driver_argument(args, "", "/subsystem:console");
            driver_argument(args, "/out:", link.output);
        } else {
            driver_argument(args, "--target=", link.target);
        }
    }
    driver_argument(args, "", link.program.data);
    driver_argument(args, "", link.runtime.data);
    var exports = link.wasm;
    if link.windows {
        exports = true;
    }
    if exports {
        var prefix = "--export=";
        if link.windows {
            prefix = "/export:";
        }
        for(var i: usize = 0; i < link.exports.values.length; i++) {
            driver_argument(args, prefix, link.exports.values.data[i]);
        }
    } else {
        if link.sysroot[0] != 0 {
            driver_argument(args, "--sysroot=", link.sysroot);
        }
    }
    for(var i: usize = 0; i < link.inputs.values.length; i++) {
        driver_argument(args, "", link.inputs.values.data[i]);
    }
    if !link.windows {
        driver_argument(args, "", "-o");
        driver_argument(args, "", link.output);
    }
}

fn driver_link_execute(link: DriverLink*, data: u8*, length: usize): i32 {
    var runtime = driver_runtime_resource(link.target);
    if runtime == null {
        driver_error("No bundled executable runtime profile for target: ", link.target);
        return 1;
    }
    var ok = link.ok;
    ok &&= link.exports.ok;
    ok &&= link.inputs.ok;
    if !ok {
        driver_error("Unable to allocate link arguments", "");
        return 1;
    }
    if !driver_platform_temporary(&link.program) {
        return 1;
    }
    if !driver_platform_temporary(&link.runtime) {
        return 1;
    }
    if !driver_platform_temporary(&link.allowed) {
        return 1;
    }
    if !driver_write_file(link.program.data, data, length) {
        return 1;
    }
    var compile: DriverArguments;
    driver_arguments_init(&compile);
    driver_link_compile_arguments(link, &compile);
    var result = driver_command(&compile);
    driver_arguments_dispose(&compile);
    if result != 0 {
        return result;
    }
    driver_timing_mark(link.timing, link.timings, "runtimeCompile");
    if link.wasm {
        if !driver_write_file(link.allowed.data, link.imports.data, link.imports.length) {
            driver_error("Cannot write linker import list", "");
            return 1;
        }
    }
    var args: DriverArguments;
    driver_arguments_init(&args);
    driver_link_arguments(link, &args);
    result = driver_command(&args);
    driver_arguments_dispose(&args);
    driver_timing_mark(link.timing, link.timings, "link");
    return result;
}

fn driver_temporary_dispose(path: ByteBuffer*): void {
    if path.length != 0 {
        driver_platform_remove(path.data);
    }
    bytes_dispose(path);
}

export fn driver_link_close(link: DriverLink*): void {
    if link == null {
        return;
    }
    driver_temporary_dispose(&link.program);
    driver_temporary_dispose(&link.runtime);
    driver_temporary_dispose(&link.allowed);
    bytes_dispose(&link.imports);
    driver_arguments_dispose(&link.exports);
    driver_arguments_dispose(&link.inputs);
    free(link);
}

// The owning wrapper releases every temporary on all ordinary failure paths.
export fn driver_link_run(link: DriverLink*, data: u8*, length: usize): i32 {
    var result = driver_link_execute(link, data, length);
    driver_link_close(link);
    return result;
}

export fn driver_write_ir(raw_path: u8*, raw: u8*, raw_count: usize, optimized_path: u8*, optimized: u8*, optimized_count: usize): bool {
    var ok = true;
    var requested = raw_path[0] != 0;
    if requested {
        ok = driver_write_file(raw_path, raw, raw_count);
    }
    requested = optimized_path[0] != 0;
    if ok {
        if requested {
            ok = driver_write_file(optimized_path, optimized, optimized_count);
        }
    }
    if !ok {
        driver_error("Cannot write LLVM output", "");
    }
    return ok;
}

import tower;
import driver_posix;
import driver_support;
import .library.bytes_types;
import .library.bytes_interface;

extern fn __errno_location(): i32*;

extern fn readlink(path: u8*, output: u8*, capacity: usize): i64;

export fn driver_platform_executable(out: ByteBuffer*): bool {
    var capacity: usize = 256;
    loop {
        if !bytes_reserve(out, capacity) {
            return false;
        }
        var count = readlink("/proc/self/exe", out.data, capacity);
        if count < 0 {
            return false;
        }
        var length = convert(usize, count);
        if length < capacity {
            out.length = length;
            return host_text_terminate(out);
        }
        var maximum: usize = 0;
        maximum = maximum - 1;
        var limit = maximum / 2;
        if capacity > limit {
            return false;
        }
        capacity = capacity * 2;
    }
}

export fn driver_errno(): i32* {
    return __errno_location();
}

export fn driver_monotonic_clock(): i32 {
    return 1;
}

extern fn read(fd: i32, data: u8*, length: usize): i64;

extern fn pipe2(descriptors: i32*, flags: i32): i32;

const DriverCloseOnExec: i32 = 524288;

extern fn fork(): i32;

extern fn execv(file: u8*, argv: u8**): i32;

extern fn _exit(code: i32): void;

extern fn waitpid(pid: i32, status: i32*, flags: i32): i32;

export fn driver_posix_execute(executable: u8*, argv: u8**): i32 {
    // A close-on-exec pipe distinguishes exec failure from a tool returning 127.
    // The child only invokes libc async-signal-safe operations before exec/_exit.
    var descriptors: i32[2];
    if pipe2(&descriptors[0], DriverCloseOnExec()) != 0 {
        driver_error("Cannot start tool: ", strerror(driver_error_code()));
        return 1;
    }
    var pid = fork();
    if pid == 0 {
        close(descriptors[0]);
        execv(executable, argv);
        var error = driver_error_code();
        write(descriptors[1], bits(u8*, &error), sizeof(i32));
        _exit(127);
    }
    var fork_error = driver_error_code();
    close(descriptors[1]);
    if pid < 0 {
        close(descriptors[0]);
        driver_error("Cannot start tool: ", strerror(fork_error));
        return 1;
    }
    var error: i32 = 0;
    var received: usize = 0;
    while received < sizeof(i32) {
        var data = bits(u8*, &error) + received;
        var remaining = sizeof(i32) -received;
        var count = read(descriptors[0], data, remaining);
        if count < 0 {
            if driver_error_code() == 4 {
                continue;
            }
            error = 5;
            break;
        }
        if count == 0 {
            break;
        }
        received = received + convert(usize, count);
    }
    close(descriptors[0]);
    var status: i32 = 0;
    loop {
        var waited = waitpid(pid, &status, 0);
        if waited == pid {
            break;
        }
        if driver_error_code() == 4 {
            continue;
        }
        driver_error("Cannot wait for tool: ", strerror(driver_error_code()));
        return 1;
    }
    if error != 0 {
        if error == 2 {
            driver_error("Cannot find tool: ", argv[0]);
        }
        else {
            driver_error("Cannot execute tool: ", strerror(error));
        }
        return 1;
    }
    if status == 0 {
        return 0;
    }
    return 1;
}

