extern fn fopen(path: u8*, mode: u8*): void*;

extern fn fclose(file: void*): i32;

const DriverBedrockText: usize = 0;
const DriverFoundationText: usize = 1;
const DriverSourceText: usize = 2;
const DriverCanonicalBedrockText: usize = 3;
const DriverCanonicalFoundationText: usize = 4;

// One synchronous invocation owns these snapshots and environments. The native
// adapter lends its legacy module slot only until it returns; this does not make
// the syntax baseline or that slot safe for concurrent compilation.
struct DriverRequest {
    options: DriverOptions*;
    root: u8*;
    bedrock_path: ByteBuffer;
    foundation_path: ByteBuffer;
    text: ByteBuffer[5];
    error: ByteBuffer;
    modules: void*;
    generated: void*;
    slot: void**;
    previous: void*;
    canonical: bool;
}

fn driver_request_path(out: ByteBuffer*, override: u8*, root: u8*, name: u8*): bool {
    var custom = override[0] != 0;
    var ok = true;
    if custom {
        ok = driver_text(out, override);
    } else {
        ok = driver_text(out, root);
        ok &&= driver_text(out, "/");
        ok &&= driver_text(out, name);
    }
    ok &&= host_text_terminate(out);
    return ok;
}

fn driver_request_failure(request: DriverRequest*, prefix: u8*, detail: u8*): bool {
    request.error.length = 0;
    var ok = driver_text(&request.error, prefix);
    ok &&= driver_text(&request.error, detail);
    ok &&= host_text_terminate(&request.error);
    if !ok {
        request.error.length = 0;
    }
    return false;
}

export fn driver_request_error(request: DriverRequest*): u8* {
    if request.error.length != 0 {
        return request.error.data;
    }
    return "Unable to allocate compiler input storage";
}

fn driver_request_read(request: DriverRequest*, path: u8*, index: usize): bool {
    if driver_read_file(path, &request.text[index]) {
        return true;
    }
    return driver_request_failure(request, "Cannot read file: ", path);
}

fn driver_request_check_grammar(request: DriverRequest*, path: u8*): bool {
    var file = fopen(path, "rb");
    if file == null {
        return driver_request_failure(request, "Cannot read grammar module: ", path);
    }
    fclose(file);
    return true;
}

// Snapshot explicit inputs before entering the compiler. File failures return
// through the owner, so a failed read cannot bypass request/timing destruction.
export fn driver_request_open(request: DriverRequest*, options: DriverOptions*, root: u8*): bool {
    fill(request, 0, sizeof(DriverRequest));
    request.options = options;
    request.root = root;
    if !(driver_platform_exists(options.source)) {
        return driver_request_failure(request, "Supply a Tower source file; use --help for options", "");
    }
    if !(driver_request_path(&request.bedrock_path, options.bedrock, root, "bedrock.tower")) {
        return false;
    }
    if !(driver_request_path(&request.foundation_path, options.foundation, root, "foundation.tower")) {
        return false;
    }
    if !(driver_request_check_grammar(request, request.bedrock_path.data)) {
        return false;
    }
    if !(driver_request_check_grammar(request, request.foundation_path.data)) {
        return false;
    }
    if !(driver_request_read(request, request.bedrock_path.data, DriverBedrockText())) {
        return false;
    }
    if !(driver_request_read(request, request.foundation_path.data, DriverFoundationText())) {
        return false;
    }
    if !(driver_request_read(request, options.source, DriverSourceText())) {
        return false;
    }
    return true;
}

export fn driver_request_text(request: DriverRequest*, index: usize): ByteBuffer* {
    return &request.text[index];
}

// Canonical grammar is loaded only for the existing normalization/bytecode
// stages. A failed pair is never published as a complete snapshot.
export fn driver_request_canonical(request: DriverRequest*): bool {
    if request.canonical {
        return true;
    }
    var path: ByteBuffer;
    fill(&path, 0, sizeof(ByteBuffer));
    var ok = driver_request_path(&path, "", request.root, "bedrock.tower");
    ok &&= driver_request_read(request, path.data, DriverCanonicalBedrockText());
    path.length = 0;
    ok &&= driver_request_path(&path, "", request.root, "foundation.tower");
    ok &&= driver_request_read(request, path.data, DriverCanonicalFoundationText());
    bytes_dispose(&path);
    request.canonical = ok;
    return ok;
}

export fn driver_request_bind(request: DriverRequest*, slot: void**): void {
    request.slot = slot;
    request.previous = *slot;
    request.modules = frontend_modules_create();
    *slot = request.modules;
    // The parent view borrows the owned path, with its separator retained. This
    // preserves POSIX roots and Windows drive/UNC roots without host stat layouts.
    var path = request.foundation_path.data;
    var boundary: usize = 0;
    var i: usize = 0;
    while path[i] != 0 {
        var separator = path[i] == 47;
        separator ||= driver_platform_separator(path[i]);
        if separator {
            boundary = i + 1;
        }
        ++i;
    }
    var saved = path[boundary];
    path[boundary] = 0;
    frontend_modules_configure(request.modules, request.options.source, path);
    path[boundary] = saved;
    frontend_modules_fallback(request.modules, request.root);
    var custom = request.options.bedrock[0] != 0;
    if custom {
        frontend_modules_builtin(request.modules, "bedrock", request.bedrock_path.data);
    }
    custom = request.options.foundation[0] != 0;
    if custom {
        frontend_modules_builtin(request.modules, "foundation", request.foundation_path.data);
    }
}

export fn driver_request_stage(request: DriverRequest*): void {
    request.generated = frontend_modules_create();
    frontend_modules_configure(request.generated, request.options.source, request.root);
    *request.slot = request.generated;
}

export fn driver_request_close(request: DriverRequest*): void {
    if request.slot != null {
        *request.slot = request.previous;
    }
    var present = request.generated != null;
    if present {
        frontend_modules_destroy(request.generated);
    }
    present = request.modules != null;
    if present {
        frontend_modules_destroy(request.modules);
    }
    var i: usize = 0;
    while i < 5 {
        bytes_dispose(&request.text[i]);
        ++i;
    }
    bytes_dispose(&request.bedrock_path);
    bytes_dispose(&request.foundation_path);
    bytes_dispose(&request.error);
    fill(request, 0, sizeof(DriverRequest));
}

import tower;
import .compiler.host_text;
import driver_options;
import .library.bytes_interface;
import .library.bytes_types;

// Host policies consume explicit inputs. Locating the running executable is an
// OS service supplied by the caller; argv[0] alone is not a resolved filename.
// Resource text uses the shared buffer and has a borrowed terminating NUL.
export fn driver_resource_root(out: ByteBuffer*, executable: u8*): bool {
    var i: usize = 0;
    var boundary: usize = 0;
    loop {
        var c = executable[i];
        if c == 0 {
            break;
        }
        i++;
        var separator = c == 47;
        if c == 92 {
            separator = true;
        }
        if separator {
            boundary = i;
        }
    }
    if boundary == 0 {
        return false;
    }
    out.length = 0;
    var ok = bytes_append(out, executable, boundary);
    ok &&= bytes_append(out, "share/tower", 11);
    ok &&= host_text_terminate(out);
    return ok;
}

// Diagnostic columns count UTF-8 scalars, retaining the original driver's
// policy for offsets inside a scalar, CRLF and offsets beyond the input.
export fn driver_source_position(source: u8*, count: usize, offset: usize, line: usize*, column: usize*): void {
    *line = 1;
    *column = 1;
    if offset > count {
        offset = count;
    }
    var i: usize = 0;
    loop {
        if i == offset {
            return;
        }
        var c = source[i];
        if c == 10 {
            *line = *line + 1;
            *column = 1;
        } else {
            var prefix = c &192;
            if prefix != 128 {
                *column = *column + 1;
            }
        }
        i++;
    }
}

export fn driver_output_name(emit: u8*, wasm: bool, windows: bool): u8* {
    if driver_equal(emit, "object") {
        return "tower.o";
    }
    if driver_equal(emit, "llvm") {
        return "tower.ll";
    }
    if driver_equal(emit, "llvm-optimized") {
        return "tower.ll";
    }
    if wasm {
        return "tower.wasm";
    }
    if windows {
        return "tower.exe";
    }
    return "tower.out";
}

export fn driver_output_valid(emit: u8*): bool {
    if driver_equal(emit, "brightscript") {
        return true;
    }
    if driver_equal(emit, "c") {
        return true;
    }
    if driver_equal(emit, "bytecode") {
        return true;
    }
    if driver_equal(emit, "foundation") {
        return true;
    }
    if driver_equal(emit, "object") {
        return true;
    }
    if driver_equal(emit, "llvm") {
        return true;
    }
    if driver_equal(emit, "llvm-optimized") {
        return true;
    }
    return driver_equal(emit, "exe");
}

import tower;

// Linux AArch64 asm-generic struct stat: st_mode is the u32 at offset 16.
export fn driver_stat_mode(data: u8*): u32 {
    return *bits(u32*, data + 16);
}

import tower;

// Linux x86-64 struct stat: st_mode is the u32 at offset 24.
export fn driver_stat_mode(data: u8*): u32 {
    return *bits(u32*, data + 24);
}

import tower;

// Darwin 64-bit struct stat: little-endian mode_t at offset 4, width 2.
export fn driver_stat_mode(data: u8*): u32 {
    return convert(u32, data[4]) |(convert(u32, data[5]) *256);
}

import tower;
import .library.bytes_interface;
import .library.bytes_types;
import .library.vector;
import driver_platform;

extern fn strlen(text: u8*): usize;

extern fn strcmp(left: u8*, right: u8*): i32;

extern fn getenv(name: u8*): u8*;

extern fn strerror(code: i32): u8*;

extern fn fflush(file: void*): i32;

extern fn host_text_terminate(out: ByteBuffer*): bool;

extern fn host_json_unsigned(out: ByteBuffer*, value: u64): bool;

extern fn driver_read_file(path: u8*, out: ByteBuffer*): bool;

extern fn driver_write_file(path: u8*, data: u8*, length: usize): bool;

fn driver_text(out: ByteBuffer*, text: u8*): bool {
    return bytes_append(out, text, strlen(text));
}

fn driver_same(left: u8*, right: u8*): bool {
    var equal = strcmp(left, right) == 0;
    return equal;
}

// Each argument owns a stable allocation. Growing the pointer vector never
// invalidates the argv views, and no argument is interpreted by a shell.
struct DriverArguments {
    values: vector(u8*);
    ok: bool;
}

fn driver_arguments_init(args: DriverArguments*): void {
    fill(args, 0, sizeof(DriverArguments));
    args.ok = true;
}

fn driver_argument(args: DriverArguments*, prefix: u8*, value: u8*): void {
    if !args.ok {
        return;
    }
    var text: ByteBuffer;
    fill(&text, 0, sizeof(ByteBuffer));
    args.ok = driver_text(&text, prefix);
    args.ok &&= driver_text(&text, value);
    args.ok &&= host_text_terminate(&text);
    args.ok &&= vector_push(u8*, &args.values, text.data);
    if !args.ok {
        bytes_dispose(&text);
    }
}

fn driver_arguments_dispose(args: DriverArguments*): void {
    for(var i: usize = 0; i < args.values.length; i++) {
        free(args.values.data[i]);
    }
    vector_dispose(u8*, &args.values);
}

export fn driver_message(stream: i32, message: u8*, detail: u8*, newline: bool): void {
    fflush(null);
    driver_platform_write(stream, message, strlen(message));
    driver_platform_write(stream, detail, strlen(detail));
    if newline {
        driver_platform_write(stream, "\n", 1);
    }
}

export fn driver_error(message: u8*, detail: u8*): void {
    driver_message(2, message, detail, true);
}

extern fn frontend_modules_location(modules: void*, offset: usize, line: usize*, column: usize*): u8*;

extern fn driver_source_position(source: u8*, length: usize, offset: usize, line: usize*, column: usize*): void;

// Module provenance is supplied by the existing frontend API. UTF-8 positions,
// fallback filenames and diagnostic composition all belong to the Tower host.
export fn driver_report(error: u8*, offset: usize, text: u8*, length: usize, source: u8*, modules: void*): void {
    fflush(null);
    var line: usize = 1;
    var column: usize = 1;
    driver_source_position(text, length, offset, &line, &column);
    var file = frontend_modules_location(modules, offset, &line, &column);
    if file[0] == 0 {
        file = source;
    }
    var out: ByteBuffer;
    fill(&out, 0, sizeof(ByteBuffer));
    var ok = driver_text(&out, file);
    ok &&= driver_text(&out, ":");
    ok &&= host_json_unsigned(&out, convert(u64, line));
    ok &&= driver_text(&out, ":");
    ok &&= host_json_unsigned(&out, convert(u64, column));
    ok &&= driver_text(&out, ": ");
    ok &&= driver_text(&out, error);
    ok &&= driver_text(&out, "\n");
    if ok {
        driver_platform_write(2, out.data, out.length);
    }
    else {
        driver_error("Unable to allocate diagnostic: ", error);
    }
    bytes_dispose(&out);
}

fn driver_command(args: DriverArguments*): i32 {
    args.ok &&= vector_push(u8*, &args.values, null);
    if !args.ok {
        driver_error("Unable to allocate tool arguments", "");
        return 1;
    }
    var result = driver_platform_run(args.values.data);
    args.values.length--;
    return result;
}

import tower;

// Native Darwin libc++ ABI 1: the low tag bit selects the long representation.
export fn driver_syntax_heap(value: usize*): bool {
    return(value[0] &1) != 0;
}

export fn driver_syntax_data(value: usize*): u8* {
    if driver_syntax_heap(value) {
        return bits(u8*, value[2]);
    }
    return bits(u8*, value) + 1;
}

export fn driver_syntax_storage(value: usize*): u8* {
    return bits(u8*, value[2]);
}

import tower;

// libc++ alternate string layout on little-endian 64-bit targets.
export fn driver_syntax_heap(value: usize*): bool {
    return(bits(u8*, value)[23] &128) != 0;
}

export fn driver_syntax_data(value: usize*): u8* {
    if driver_syntax_heap(value) {
        return bits(u8*, value[0]);
    }
    return bits(u8*, value);
}

export fn driver_syntax_storage(value: usize*): u8* {
    return bits(u8*, value[0]);
}

import tower;

// Linux libstdc++ C++11 ABI: data, length, and 16 bytes of inline storage.
export fn driver_syntax_data(value: usize*): u8* {
    return bits(u8*, value[0]);
}

export fn driver_syntax_heap(value: usize*): bool {
    return bits(u8*, value[0]) != bits(u8*, value + 2);
}

export fn driver_syntax_storage(value: usize*): u8* {
    return bits(u8*, value[0]);
}

import tower;

// Release MSVC x64/ARM64 string: inline buffer/pointer, length, capacity.
export fn driver_syntax_heap(value: usize*): bool {
    return value[3] > 15;
}

export fn driver_syntax_data(value: usize*): u8* {
    if driver_syntax_heap(value) {
        return bits(u8*, value[0]);
    }
    return bits(u8*, value);
}

extern fn driver_syntax_vector_alignment(): bool;

export fn driver_syntax_storage(value: usize*): u8* {
    var data = bits(u8*, value[0]);
    // MSVC boosts allocations of at least 4096 bytes on x86/x64 only.
    // The actual allocation address precedes the aligned character buffer.
    if driver_syntax_vector_alignment() && value[3] >= 4095 {
        return bits(u8*, *(bits(usize*, data) -1));
    }
    return data;
}

import tower;
import .library.bytes_types;
import .library.bytes_interface;
import driver_support;
import driver_platform;

struct DriverTiming {
    start: u64;
    previous: u64;
    values: u64[11];
    present: bool[11];
}

fn driver_timing_name(index: usize): u8* {
    match index {
        0 => {
            return "after";
        }
        1 => {
            return "before";
        }
        2 => {
            return "bootstrap";
        }
        3 => {
            return "compile";
        }
        4 => {
            return "emit";
        }
        5 => {
            return "execute";
        }
        6 => {
            return "link";
        }
        7 => {
            return "parse";
        }
        8 => {
            return "prepare";
        }
        9 => {
            return "runtimeCompile";
        }
        _ => {
            return "total";
        }
    }
}

export fn driver_timing_open(): DriverTiming* {
    var timing = alloc(DriverTiming, 1);
    if timing != null {
        fill(timing, 0, sizeof(DriverTiming));
        timing.start = driver_clock();
        timing.previous = timing.start;
    }
    return timing;
}

export fn driver_timing_value(timing: DriverTiming*, name: u8*, nanoseconds: u64): void {
    if timing == null {
        return;
    }
    for(var i: usize = 0; i < 11; i++) {
        if driver_same(name, driver_timing_name(i)) {
            timing.values[i] = nanoseconds;
            timing.present[i] = true;
            return;
        }
    }
}

export fn driver_timing_mark(timing: DriverTiming*, enabled: bool, name: u8*): void {
    if !enabled {
        return;
    }
    if timing == null {
        return;
    }
    var now = driver_clock();
    var elapsed: u64 = 0;
    if now >= timing.previous {
        elapsed = now - timing.previous;
    }
    driver_timing_value(timing, name, elapsed);
    timing.previous = now;
}

// Locale-independent JSON numbers, milliseconds with six fractional digits.
// Measurements are host effects only and never enter compiler/cache identity.
fn driver_timing_render(out: ByteBuffer*, timing: DriverTiming*): bool {
    var ok = driver_text(out, "Tower timings (ms): {");
    var first = true;
    for(var i: usize = 0; i < 11; i++) {
        if timing.present[i] {
            if !first {
                ok &&= driver_text(out, ",");
            }
            first = false;
            ok &&= driver_text(out, "\"");
            ok &&= driver_text(out, driver_timing_name(i));
            ok &&= driver_text(out, "\":");
            var whole = timing.values[i] / 1000000;
            var fraction = timing.values[i] % 1000000;
            ok &&= host_json_unsigned(out, whole);
            ok &&= driver_text(out, ".");
            var divisor: u64 = 100000;
            while divisor != 0 {
                var digit = fraction / divisor;
                digit = digit + 48;
                ok &&= bytes_push(out, convert(u8, digit));
                fraction = fraction % divisor;
                divisor = divisor / 10;
            }
        }
    }
    ok &&= driver_text(out, "}\n");
    return ok;
}

export fn driver_timing_close(timing: DriverTiming*, enabled: bool): void {
    if timing == null {
        return;
    }
    if enabled {
        var now = driver_clock();
        var elapsed: u64 = 0;
        if now >= timing.start {
            elapsed = now - timing.start;
        }
        driver_timing_value(timing, "total", elapsed);
        var out: ByteBuffer;
        fill(&out, 0, sizeof(ByteBuffer));
        if driver_timing_render(&out, timing) {
            driver_platform_write(2, out.data, out.length);
        }
        bytes_dispose(&out);
    }
    free(timing);
}

