fn ide_grammar(out: ByteBuffer*, syntax: void*, query: void*): void {
    var listing: IdeForeignVector;
    `cpp_name(std::vector<SyntaxRuleInfo> syntax_get_rules(SyntaxSession*))`(&listing, syntax);
    var rules = bits(IdeForeignRule*, listing.data);
    var count = ide_foreign_count(&listing, sizeof(IdeForeignRule));
    var json = out != null;
    if json {
        ide_text(out, ",\"rules\":[");
    }
    var i: usize = 0;
    for(; i < count; i++) {
        var rule = &rules[i];
        if json {
            ide_comma(out, i);
            ide_text(out, "{\"name\":");
            ide_foreign_quote(out, &rule.name);
            ide_key(out, "definition");
            ide_foreign_quote(out, &rule.definition);
            ide_key(out, "pending");
            ide_bool(out, rule.pending);
            ide_text(out, "}");
        } else {
            completion_offer(query, ide_foreign_data(&rule.name), "type", "grammar rule", 2);
        }
        ide_foreign_dispose(&rule.name);
        ide_foreign_dispose(&rule.definition);
    }
    ide_foreign_free(&listing);
    `cpp_name(std::vector<std::string> syntax_get_keywords(SyntaxSession*))`(&listing, syntax);
    var keywords = bits(IdeForeignString*, listing.data);
    count = ide_foreign_count(&listing, sizeof(IdeForeignString));
    if json {
        ide_text(out, "],\"keywords\":[");
    }
    i = 0;
    for(; i < count; i++) {
        if json {
            ide_comma(out, i);
            ide_foreign_quote(out, &keywords[i]);
        }
        else {
            completion_offer(query, ide_foreign_data(&keywords[i]), "keyword", "active grammar", 0);
        }
        ide_foreign_dispose(&keywords[i]);
    }
    ide_foreign_free(&listing);
    `cpp_name(std::vector<SyntaxTokenInfo> syntax_get_tokens(SyntaxSession*))`(&listing, syntax);
    var tokens = bits(IdeForeignToken*, listing.data);
    count = ide_foreign_count(&listing, sizeof(IdeForeignToken));
    if json {
        ide_text(out, "] ,\"tokens\":[");
    }
    i = 0;
    for(; i < count; i++) {
        var item = &tokens[i];
        if json {
            ide_comma(out, i);
            ide_text(out, "{\"name\":");
            ide_foreign_quote(out, &item.name);
            ide_key(out, "pattern");
            ide_foreign_quote(out, &item.pattern);
            ide_key(out, "kind");
            ide_foreign_quote(out, &item.kind);
            ide_key(out, "skip");
            ide_bool(out, item.`skip`);
            ide_key(out, "contextual");
            ide_bool(out, item.contextual);
            ide_text(out, "}");
        } else {
            if !(item.`skip`) {
                completion_offer(query, ide_foreign_data(&item.name), "type", "token rule", 2);
            }
        }
        ide_foreign_dispose(&item.name);
        ide_foreign_dispose(&item.pattern);
        ide_foreign_dispose(&item.kind);
    }
    ide_foreign_free(&listing);
    if json {
        ide_text(out, "]");
    }
}

fn ide_status(out: ByteBuffer*, syntax: void*, status: u8*): void {
    ide_assign(out, "{\"status\":");
    ide_quote(out, status);
    ide_field(out, "revision", syntax_get_revision(syntax));
    ide_field(out, "offset", `cpp_name(unsigned long syntax_get_offset(SyntaxSession*))`(syntax));
    ide_string(out, "error", syntax_get_error(syntax));
    ide_field(out, "errorOffset", syntax_get_error_offset(syntax));
    if `cpp_name(bool syntax_get_error_insertion(SyntaxSession*))`(syntax) {
        ide_field(out, "errorLength", 0);
    }
}

fn ide_parser_create(source: u8*, bytes: usize, mode: u32): u32 {
    if !ide_valid(source, bytes) {
        return 0;
    }
    var state = ide_state();
    if host_handles_count(&state.handles, 0) >= 32 {
        ide_error("Too many open parser sessions");
        return 0;
    }
    var copy = ide_copy(source, bytes);
    var syntax = syntax_completion_create(copy, mode);
    free(copy);
    var error = syntax_get_error(syntax);
    var reject = mode == 0;
    reject &&= error[0] != 0;
    if reject {
        ide_error(error);
        syntax_destroy(syntax);
        return 0;
    }
    var session = alloc(IdeParser, 1);
    var failed = session == null;
    if failed {
        syntax_destroy(syntax);
        ide_error("Cannot allocate parser handle");
        return 0;
    }
    fill(session, 0, sizeof(IdeParser));
    session.syntax = syntax;
    var handle = host_handles_insert(&state.handles, 0, bits(void*, session));
    failed = handle == 0;
    if failed {
        syntax_destroy(syntax);
        free(session);
        ide_error("Cannot allocate parser handle");
    }
    return handle;
}

export fn tw_create(source: u8*, bytes: usize): u32 {
    return ide_parser_create(source, bytes, 0);
}

export fn tw_create_foundation(source: u8*, bytes: usize): u32 {
    return ide_parser_create(source, bytes, 1);
}

export fn tw_create_bedrock(source: u8*, bytes: usize): u32 {
    return ide_parser_create(source, bytes, 2);
}

export fn tw_destroy(handle: u32): void {
    var state = ide_state();
    var session = bits(IdeParser*, host_handles_take(&state.handles, 0, handle));
    if session == null {
        return;
    }
    syntax_destroy(session.syntax);
    bytes_dispose(&session.response);
    free(session);
}

export fn tw_reset(handle: u32, source: u8*, bytes: usize): i32 {
    if !ide_valid(source, bytes) {
        return 0;
    }
    var session = ide_parser(handle);
    if session == null {
        ide_error("Invalid session handle");
        return 0;
    }
    var copy = ide_copy(source, bytes);
    syntax_reset(session.syntax, copy, null);
    free(copy);
    session.response.length = 0;
    var error = syntax_get_error(session.syntax);
    if error[0] != 0 {
        ide_error(error);
        return 0;
    }
    return 1;
}

export fn tw_inspect(handle: u32): u8* {
    var session = ide_parser(handle);
    if session == null {
        return "{\"status\":\"error\",\"error\":\"Invalid session handle\"}";
    }
    var out = &session.response;
    var error = syntax_get_error(session.syntax);
    var failed = error[0] != 0;
    var status: u8* = "snapshot";
    if failed {
        status = "error";
    }
    ide_status(out, session.syntax, status);
    var stats: IdeForeignStats;
    `cpp_name(SyntaxCacheStats syntax_get_cache_stats(SyntaxSession*))`(&stats, session.syntax);
    ide_field(out, "grammarBuilds", stats.first);
    ide_field(out, "grammarCacheHits", stats.second);
    ide_field(out, "cachedGrammars", stats.third);
    ide_grammar(out, session.syntax, null);
    var listing: IdeForeignVector;
    `cpp_name(std::vector<SyntaxHighlight> syntax_get_highlights(SyntaxSession*))`(&listing, session.syntax);
    var highlights = bits(IdeForeignHighlight*, listing.data);
    var count = ide_foreign_count(&listing, sizeof(IdeForeignHighlight));
    ide_text(out, ",\"highlights\":[");
    var i: usize = 0;
    for(; i < count; i++) {
        var span = &highlights[i];
        ide_comma(out, i);
        ide_text(out, "{\"start\":");
        ide_number(out, span.start);
        ide_field(out, "end", span.end);
        ide_field(out, "revision", span.revision);
        ide_key(out, "kind");
        ide_foreign_quote(out, &span.kind);
        ide_text(out, "}");
        ide_foreign_dispose(&span.kind);
    }
    ide_foreign_free(&listing);
    ide_text(out, "]}");
    return ide_result(out);
}

fn ide_spans(out: ByteBuffer*, spans: FormatSpan*, count: usize): void {
    ide_text(out, ",\"spans\":[");
    var i: usize = 0;
    for(; i < count; i++) {
        var span = &spans[i];
        ide_comma(out, i);
        ide_text(out, "{\"begin\":");
        ide_number(out, span.begin);
        ide_field(out, "end", span.end);
        ide_field(out, "source", span.source);
        ide_text(out, "}");
    }
    ide_text(out, "]");
}

export fn tw_format(handle: u32): u8* {
    var session = ide_parser(handle);
    if session == null {
        return "{\"error\":\"Invalid session handle\"}";
    }
    var out = &session.response;
    ide_assign(out, "{");
    if !(`cpp_name(bool syntax_can_format(SyntaxSession*))`(session.syntax)) {
        ide_text(out, "\"error\":\"Formatting requires a complete, valid source document\"}");
        return ide_result(out);
    }
    var formatted: IdeForeignText;
    `cpp_name(TowerText syntax_format(SyntaxSession*))`(&formatted, session.syntax);
    if ide_foreign_size(&formatted.error) != 0 {
        ide_text(out, "\"error\":");
        ide_foreign_quote(out, &formatted.error);
    }
    else {
        ide_text(out, "\"source\":");
        ide_foreign_quote(out, &formatted.source);
        ide_spans(out, bits(FormatSpan*, formatted.spans.data), ide_foreign_count(&formatted.spans, sizeof(FormatSpan)));
    }
    ide_foreign_dispose(&formatted.source);
    ide_foreign_dispose(&formatted.error);
    ide_foreign_free(&formatted.spans);
    ide_text(out, "}");
    return ide_result(out);
}

import tower;
import .compiler.host_text;
import .library.bytes_interface;
import .library.bytes_types;

// Ide transport policies. These consume borrowed values from the compiler;
// JSON is not a second semantic model or a Tower interchange format.
extern fn tower_utf8_validate(source: u8*, count: usize, reject_nul: u32): u32;

export fn tw_abi_version(): u32 {
    return 3;
}

export fn tw_alloc(count: usize): u8* {
    return alloc(u8, count);
}

export fn tw_free(pointer: u8*): void {
    free(pointer);
}

export fn host_source_error(source: u8*, count: usize): u8* {
    if count > 8388608 {
        return "Compilation source limit is 8 MiB";
    }
    if source == null {
        return "Source must be valid UTF-8 without NUL bytes";
    }
    if tower_utf8_validate(source, count, 1) != 0 {
        return "";
    }
    return "Source must be valid UTF-8 without NUL bytes";
}

fn host_protocol_text(out: ByteBuffer*, text: u8*): bool {
    var count: usize = 0;
    for(; !(text[count] == 0); count++) {}
    return bytes_append(out, text, count);
}

// On allocation failure callers must discard the partial response. IDE transport
// retains the existing abort-on-transport-allocation-failure policy.
export fn host_execution_json(out: ByteBuffer*, error: u8*, error_count: usize, offset: usize, done: bool, output: u8*, output_count: usize, steps: u64, truncated: bool): bool {
    out.length = 0;
    var status: u8* = "executing";
    if done {
        status = "done";
    }
    if error_count != 0 {
        status = "error";
    }
    var ok = host_protocol_text(out, "{\"status\":\"");
    ok &&= host_protocol_text(out, status);
    ok &&= host_protocol_text(out, "\",\"error\":");
    ok &&= host_json_quote(out, error, error_count);
    ok &&= host_protocol_text(out, ",\"errorOffset\":");
    if ok {
        var wide = convert(u64, offset);
        ok = host_json_unsigned(out, wide);
    }
    ok &&= host_protocol_text(out, ",\"outputBytes\":[");
    for(var i: usize = 0; i != output_count; i++) {
        if !ok {
            break;
        }
        if i != 0 {
            ok = bytes_push(out, 44);
        }
        if ok {
            var byte = convert(u64, output[i]);
            ok = host_json_unsigned(out, byte);
        }
    }
    ok &&= host_protocol_text(out, "],\"steps\":");
    ok &&= host_json_unsigned(out, steps);
    if ok {
        if truncated {
            ok = host_protocol_text(out, ",\"outputTruncated\":true}");
        } else {
            ok = host_protocol_text(out, ",\"outputTruncated\":false}");
        }
    }
    return ok;
}

import tower;
import ide_types;
import ide_api;
import ide_text;

// Worker-instance lifetime, just like the former native static handle table.
// The host owns this component on its existing world type registry; it is not a
// syntax/semantic node and never enters a compiled program. No global native
// storage, second entity registry, or cross-worker mutable state is introduced.
fn ide_state(): IdeState* {
    var owner = core_component_type();
    var slot = entity_member_index(owner, "ide.transport");
    var absent = slot == ide_missing();
    var type: void* = null;
    if absent {
        type = tower_node_create();
        ide_require(entity_register(type, sizeof(IdeState), alignof(IdeState), 0));
        var component = entity_component_add(owner, type);
        var ok = component != null;
        ide_require(ok);
        var state = bits(IdeState*, entity_component_data(component));
        fill(state, 0, sizeof(IdeState));
        ide_require(entity_attach(type, owner, "ide.transport"));
        entity_release(type);
        return state;
    }
    type = entity_child_at(owner, slot);
    return bits(IdeState*, entity_component_data(entity_component_get(owner, type)));
}

fn ide_error(message: u8*): void {
    var state = ide_state();
    ide_assign(&state.error, message);
}

fn ide_valid(data: u8*, length: usize): bool {
    var error = host_source_error(data, length);
    ide_error(error);
    var ok = error[0] == 0;
    return ok;
}

fn ide_parser(handle: u32): IdeParser* {
    var state = ide_state();
    return bits(IdeParser*, host_handles_get(&state.handles, 0, handle));
}

fn ide_execution(handle: u32): IdeExecution* {
    var state = ide_state();
    return bits(IdeExecution*, host_handles_get(&state.handles, 1, handle));
}

export fn tw_last_error(): u8* {
    var state = ide_state();
    return ide_result(&state.error);
}

export fn tw_live_nodes(): usize {
    ide_state();
    return tower_node_get_allocated_count();
}

export fn tw_live_allocations(): usize {
    ide_state();
    return tower_memory_get_allocated_count();
}

