// Existing syntax API, lowered for wasm32 WASI SDK 34 / libc++ __2. Nontrivial
// returns use an explicit sret pointer. Foreign containers are temporary ABI
// views only and are disposed after copying into request-owned Tower buffers.
// Retire this module when syntax's owner exposes the remaining Tower views.
struct IdeForeignString {
    words: usize[3];
}

// SDK 34 enables libc++ ABI v2's alternate string and bounded vector layouts.
struct IdeForeignVector {
    data: u8*;
    size: usize;
    capacity: usize;
}

struct IdeForeignRule {
    name: IdeForeignString;
    definition: IdeForeignString;
    pending: bool;
}

struct IdeForeignToken {
    name: IdeForeignString;
    pattern: IdeForeignString;
    kind: IdeForeignString;
    `skip`: bool;
    contextual: bool;
}

struct IdeForeignHighlight {
    start: usize;
    end: usize;
    revision: usize;
    kind: IdeForeignString;
    opaque: bool;
    `token`: u32;
}

struct IdeForeignText {
    source: IdeForeignString;
    spans: IdeForeignVector;
    error: IdeForeignString;
}

struct IdeForeignStats {
    first: usize;
    second: usize;
    third: usize;
}

extern fn `cpp_name(unsigned long syntax_get_offset(SyntaxSession*))`(session: void*): usize;

extern fn `cpp_name(bool syntax_get_error_insertion(SyntaxSession*))`(session: void*): bool;

extern fn `cpp_name(bool syntax_can_format(SyntaxSession*))`(session: void*): bool;

extern fn `cpp_name(TowerText syntax_format(SyntaxSession*))`(result: IdeForeignText*, session: void*): void;

extern fn `cpp_name(SyntaxCacheStats syntax_get_cache_stats(SyntaxSession*))`(result: IdeForeignStats*, session: void*): void;

extern fn `cpp_name(SyntaxExpansionStats syntax_get_expansion_stats(SyntaxSession*))`(result: IdeForeignStats*, session: void*): void;

extern fn `cpp_name(std::vector<SyntaxRuleInfo> syntax_get_rules(SyntaxSession*))`(result: IdeForeignVector*, session: void*): void;

extern fn `cpp_name(std::vector<SyntaxTokenInfo> syntax_get_tokens(SyntaxSession*))`(result: IdeForeignVector*, session: void*): void;

extern fn `cpp_name(std::vector<SyntaxHighlight> syntax_get_lexemes(SyntaxSession*))`(result: IdeForeignVector*, session: void*): void;

extern fn `cpp_name(std::vector<SyntaxHighlight> syntax_get_highlights(SyntaxSession*))`(result: IdeForeignVector*, session: void*): void;

extern fn `cpp_name(std::vector<std::string> syntax_get_keywords(SyntaxSession*))`(result: IdeForeignVector*, session: void*): void;

extern fn `cpp_name(std::string syntax_set_bootstrap(char const*))`(result: IdeForeignString*, source: u8*): void;

extern fn `cpp_name(void operator delete(void*))`(data: u8*): void;

extern fn tower_tests(): void;

extern fn parser_tests(): void;

extern fn `cpp_name(void syntax_tests())`(): void;

fn ide_foreign_long(value: IdeForeignString*): bool {
    var raw = bits(u8*, value);
    var flag = raw[11] &128;
    var yes = flag != 0;
    return yes;
}

fn ide_foreign_data(value: IdeForeignString*): u8* {
    if ide_foreign_long(value) {
        return bits(u8*, value.words[0]);
    }
    return bits(u8*, value);
}

fn ide_foreign_size(value: IdeForeignString*): usize {
    if ide_foreign_long(value) {
        return value.words[1];
    }
    var raw = bits(u8*, value);
    var length = convert(usize, raw[11]);
    return length;
}

fn ide_foreign_dispose(value: IdeForeignString*): void {
    if ide_foreign_long(value) {
        `cpp_name(void operator delete(void*))`(ide_foreign_data(value));
    }
}

fn ide_foreign_quote(out: ByteBuffer*, value: IdeForeignString*): void {
    ide_quote_bytes(out, ide_foreign_data(value), ide_foreign_size(value));
}

fn ide_foreign_count(value: IdeForeignVector*, size: usize): usize {
    return value.size;
}

fn ide_foreign_free(value: IdeForeignVector*): void {
    `cpp_name(void operator delete(void*))`(value.data);
}

export fn tw_self_test(): i32 {
    tower_tests();
    parser_tests();
    `cpp_name(void syntax_tests())`();
    return 0;
}

import tower;
import ide_api;
import ide_types;
import .library.bytes_types;
import .library.bytes_interface;

fn ide_require(ok: bool): void {
    if !ok {
        abort();
    }
}

fn ide_length(text: u8*): usize {
    var n: usize = 0;
    if text == null {
        return 0;
    }
    loop {
        if text[n] == 0 {
            return n;
        }
        n++;
    }
}

fn ide_text(out: ByteBuffer*, text: u8*): void {
    ide_require(bytes_append(out, text, ide_length(text)));
}

fn ide_assign(out: ByteBuffer*, text: u8*): void {
    ide_require(bytes_assign_text(out, text, ide_length(text)));
}

fn ide_quote_bytes(out: ByteBuffer*, data: u8*, length: usize): void {
    ide_require(host_json_quote(out, data, length));
}

fn ide_quote(out: ByteBuffer*, text: u8*): void {
    ide_quote_bytes(out, text, ide_length(text));
}

fn ide_number(out: ByteBuffer*, number: usize): void {
    ide_require(host_json_unsigned(out, convert(u64, number)));
}

fn ide_key(out: ByteBuffer*, name: u8*): void {
    ide_text(out, ",");
    ide_quote(out, name);
    ide_text(out, ":");
}

fn ide_field(out: ByteBuffer*, name: u8*, number: usize): void {
    ide_key(out, name);
    ide_number(out, number);
}

fn ide_string(out: ByteBuffer*, name: u8*, value: u8*): void {
    ide_key(out, name);
    ide_quote(out, value);
}

fn ide_bool(out: ByteBuffer*, value: bool): void {
    if value {
        ide_text(out, "true");
    } else {
        ide_text(out, "false");
    }
}

fn ide_result(out: ByteBuffer*): u8* {
    ide_require(host_text_terminate(out));
    return out.data;
}

fn ide_copy(data: u8*, length: usize): u8* {
    var size = length + 1;
    var result = alloc(u8, size);
    var ok = result != null;
    ide_require(ok);
    copy(result, data, length);
    result[length] = 0;
    return result;
}

fn ide_missing(): usize {
    var value: usize = 0;
    value--;
    return value;
}

fn ide_comma(out: ByteBuffer*, index: usize): void {
    if index != 0 {
        ide_text(out, ",");
    }
}

fn ide_index(out: ByteBuffer*, index: usize): void {
    if index == ide_missing() {
        ide_text(out, "null");
    } else {
        ide_number(out, index);
    }
}

