import tower;

// Borrow the target's C allocator directly. Foreign declaration identifiers
// distinguish these calls from Foundation realloc/free operations.
// usize is the selected target's size_t; pointers remain ordinary raw addresses.
extern fn `c_name(void* realloc(void*, size_t))`(pointer: void*, bytes: usize): void*;

extern fn `c_name(void free(void*))`(pointer: void*): void;

import tower;

// POSIX and wasi-libc ssize_t have the same width as size_t. Ignore only the
// signed error sentinel; no C++ stream or locale is involved in trap reporting.
extern fn write(fd: i32, data: u8*, length: usize): usize;

const CompilerErrorStream: i32 = 2;

export fn compiler_runtime_write(data: u8*, length: usize): void {
    while length != 0 {
        var count = write(CompilerErrorStream(), data, length);
        if count == 0 {
            return;
        }
        var sentinel: usize = 0;
        sentinel = sentinel - 1;
        var failed = count == sentinel;
        if failed {
            return;
        }
        failed = count > length;
        if failed {
            return;
        }
        data = data + count;
        length = length - count;
    }
}

export fn platform_write(stream: u32, data: u8*, length: usize): i64 {
    var valid = stream == 1;
    valid ||= stream == 2;
    if !valid {
        return -1;
    }
    var count = write(convert(i32, stream), data, length);
    var sentinel: usize = 0;
    sentinel = sentinel - 1;
    var failed = count == sentinel;
    if failed {
        return -1;
    }
    failed = count > length;
    if failed {
        return -1;
    }
    return convert(i64, count);
}

import tower;

extern fn _write(fd: i32, data: u8*, length: u32): i32;

const CompilerWriteChunk: usize = 65536;

export fn platform_write(stream: u32, data: u8*, length: usize): i64 {
    var valid = stream == 1;
    valid ||= stream == 2;
    if !valid {
        return -1;
    }
    var count = length;
    if count > CompilerWriteChunk() {
        count = CompilerWriteChunk();
    }
    return convert(i64, _write(convert(i32, stream), data, convert(u32, count)));
}

export fn compiler_runtime_write(data: u8*, length: usize): void {
    while length != 0 {
        var written = platform_write(2, data, length);
        if written <= 0 {
            return;
        }
        var count = convert(usize, written);
        data = data + count;
        length = length - count;
    }
}

