fn runtime_platform_declaration(module: void*, name: u8*, type: void*): void* {
    var function = LLVMGetNamedFunction(module, name);
    if function == null {
        puts("Missing runtime platform declaration");
        puts(name);
        return null;
    }
    var valid = LLVMIsDeclaration(function) != 0;
    valid &&= LLVMGlobalGetValueType(function) == type;
    if !valid {
        puts("Runtime platform declaration has an incompatible ABI");
        puts(name);
        return null;
    }
    return function;
}

fn runtime_platform_return(context: void*, function: void*, value: void*): void {
    var builder = LLVMCreateBuilderInContext(context);
    var block = LLVMAppendBasicBlockInContext(context, function, "entry");
    LLVMPositionBuilderAtEnd(builder, block);
    LLVMBuildRet(builder, value);
    LLVMDisposeBuilder(builder);
}

fn runtime_platform_wasm(context: void*, module: void*): bool {
    var pointer = LLVMPointerTypeInContext(context, 0);
    var signature = LLVMFunctionType(pointer, null, 0, 0);
    var state = runtime_platform_declaration(module, "guest_wasm_context", signature);
    var heap = runtime_platform_declaration(module, "guest_wasm_heap_base", signature);
    var missing = state == null;
    missing ||= heap == null;
    if missing {
        return false;
    }
    var existing = LLVMGetNamedGlobal(module, "__heap_base");
    if existing != null {
        puts("Unexpected pre-existing heap-base binding");
        return false;
    }
    var base = LLVMAddGlobal(module, LLVMInt8TypeInContext(context), "__heap_base");
    // wasm32 GuestHeap is exactly three 32-bit words: available, cursor, limit.
    // Each unshared Wasm instance owns its zero-initialized runtime storage;
    // ordinary Tower globals retain their existing initialization semantics.
    var layout = LLVMArrayType2(LLVMInt32TypeInContext(context), 3);
    var storage = LLVMAddGlobal(module, layout, "tower.runtime.wasm.heap");
    LLVMSetLinkage(storage, RuntimePrivateLinkage());
    LLVMSetAlignment(storage, 4);
    LLVMSetInitializer(storage, LLVMConstNull(layout));
    runtime_platform_return(context, state, storage);
    runtime_platform_return(context, heap, base);
    return true;
}

export fn runtime_test_state(context: void*, module: void*): bool {
    var width = LLVMPointerSize(LLVMGetModuleDataLayout(module));
    var integer = LLVMInt32TypeInContext(context);
    if width == 8 {
        integer = LLVMInt64TypeInContext(context);
    }
    else {
        if !(width == 4) {
            puts("Unsupported runtime test-state layout");
            return false;
        }
    }
    var signature = LLVMFunctionType(LLVMPointerTypeInContext(context, 0), null, 0, 0);
    var function = runtime_platform_declaration(module, "compiler_test_state", signature);
    if function == null {
        return false;
    }
    var values: void*[3];
    values[0] = LLVMConstNull(integer);
    values[1] = values[0];
    values[2] = LLVMConstAllOnes(integer);
    var global = LLVMAddGlobal(module, LLVMArrayType2(integer, 3), "tower.runtime.compiler.test");
    LLVMSetLinkage(global, RuntimePrivateLinkage());
    LLVMSetAlignment(global, width);
    LLVMSetInitializer(global, LLVMConstArray2(integer, &values[0], 3));
    runtime_platform_return(context, function, global);
    return true;
}

fn runtime_platform_linux(context: void*, module: void*, arm: bool): bool {
    var integer = LLVMInt64TypeInContext(context);
    var parameters: void*[7];
    var i: u32 = 0;
    while i < 7 {
        parameters[i] = integer;
        ++i;
    }
    var signature = LLVMFunctionType(integer, &parameters[0], 7, 0);
    var function = runtime_platform_declaration(module, "system_call", signature);
    if function == null {
        return false;
    }
    var assembly = "syscall";
    var constraints = "={ax},{ax},{di},{si},{dx},{r10},{r8},{r9},~{rcx},~{r11},~{memory},~{dirflag},~{fpsr},~{flags}";
    if arm {
        assembly = "svc 0";
        constraints = "={x0},{x8},{x0},{x1},{x2},{x3},{x4},{x5},~{memory}";
    }
    var instruction = LLVMGetInlineAsm(signature, assembly, strlen(assembly), constraints, strlen(constraints), 1, 0, 0, 0);
    var arguments: void*[7];
    i = 0;
    while i < 7 {
        arguments[i] = LLVMGetParam(function, i);
        ++i;
    }
    var builder = LLVMCreateBuilderInContext(context);
    LLVMPositionBuilderAtEnd(builder, LLVMAppendBasicBlockInContext(context, function, "entry"));
    var result = LLVMBuildCall2(builder, signature, instruction, &arguments[0], 7, "result");
    LLVMBuildRet(builder, result);
    var existing = LLVMGetNamedFunction(module, "_start");
    if existing != null {
        LLVMDisposeBuilder(builder);
        puts("Runtime entry is already defined");
        return false;
    }
    signature = LLVMFunctionType(LLVMVoidTypeInContext(context), null, 0, 0);
    function = LLVMAddFunction(module, "_start", signature);
    var kind = LLVMGetEnumAttributeKindForName("naked", 5);
    LLVMAddAttributeAtIndex(function, RuntimeFunctionAttributes(), LLVMCreateEnumAttribute(context, kind, 0));
    LLVMPositionBuilderAtEnd(builder, LLVMAppendBasicBlockInContext(context, function, "entry"));
    assembly = "xor %rbp, %rbp\n\tand $$-16, %rsp\n\tcall tower_start";
    constraints = "~{dirflag},~{fpsr},~{flags}";
    if arm {
        assembly = "bl tower_start";
        constraints = "";
    }
    instruction = LLVMGetInlineAsm(signature, assembly, strlen(assembly), constraints, strlen(constraints), 1, 0, 0, 0);
    LLVMBuildCall2(builder, signature, instruction, null, 0, "");
    LLVMBuildUnreachable(builder);
    LLVMDisposeBuilder(builder);
    return true;
}

export fn runtime_platform(context: void*, module: void*, profile: u8*): bool {
    var target = LLVMGetTarget(module);
    if strcmp(profile, "wasm32") == 0 {
        var valid = strcmp(target, "wasm32-unknown-unknown") == 0;
        if valid {
            return runtime_platform_wasm(context, module);
        }
    }
    if strcmp(profile, "linux-x64") == 0 {
        var valid = strcmp(target, "x86_64-unknown-linux-gnu") == 0;
        if valid {
            return runtime_platform_linux(context, module, false);
        }
    }
    if strcmp(profile, "linux-arm64") == 0 {
        var valid = strcmp(target, "aarch64-unknown-linux-gnu") == 0;
        if valid {
            return runtime_platform_linux(context, module, true);
        }
    }
    puts("Unsupported runtime platform or target/profile mismatch");
    return false;
}

import tower;

import bytes_types;

export fn bytes_init(buffer: ByteBuffer*): void {
    buffer.data = null;
    buffer.length = 0;
    buffer.capacity = 0;
}

export fn bytes_reserve(buffer: ByteBuffer*, needed: usize): bool {
    if needed <= buffer.capacity {
        return true;
    }
    var capacity = buffer.capacity *2;
    if capacity < buffer.capacity {
        capacity = needed;
    }
    var small = capacity < needed;
    if small {
        capacity = needed;
    }
    small = capacity < 16;
    if small {
        capacity = 16;
    }
    var next = realloc(u8, buffer.data, capacity);
    if next == null {
        return false;
    }
    buffer.data = next;
    buffer.capacity = capacity;
    return true;
}

// Source must be readable; self-append may read only the buffer's live bytes.
export fn bytes_append(buffer: ByteBuffer*, source: u8*, count: usize): bool {
    if count == 0 {
        return true;
    }
    var total = buffer.length + count;
    if total < buffer.length {
        return false;
    }
    var start = bits(usize, source);
    var base = bits(usize, buffer.data);
    var offset = start -base;
    var inside = offset < buffer.capacity;
    if inside {
        if offset > buffer.length {
            return false;
        }
        var remaining = buffer.length -offset;
        if count > remaining {
            return false;
        }
    }
    var ok = bytes_reserve(buffer, total);
    if ok {
        if inside {
            source = buffer.data + offset;
        }
        var dest = buffer.data + buffer.length;
        copy(dest, source, count);
        buffer.length = total;
    }
    return ok;
}

export fn bytes_push(buffer: ByteBuffer*, value: u8): bool {
    return bytes_append(buffer, &value, 1);
}

// Replace text atomically, including overlapping self-slices. Length excludes NUL.
// Embedded NUL bytes are copied; source-text validation is a separate policy.
export fn bytes_assign_text(buffer: ByteBuffer*, source: u8*, count: usize): bool {
    var needed = count + 1;
    if needed == 0 {
        return false;
    }
    var start = bits(usize, source);
    var base = bits(usize, buffer.data);
    var offset = start -base;
    var inside = offset < buffer.capacity;
    if inside {
        if offset > buffer.length {
            return false;
        }
        var remaining = buffer.length -offset;
        if count > remaining {
            return false;
        }
    }
    var ok = bytes_reserve(buffer, needed);
    if ok {
        if count != 0 {
            if inside {
                source = buffer.data + offset;
            }
            copy(buffer.data, source, count);
        }
        buffer.data[count] = 0;
        buffer.length = count;
    }
    return ok;
}

export fn bytes_dispose(buffer: ByteBuffer*): void {
    free(buffer.data);
    bytes_init(buffer);
}

import tower;

import bytes_types;

extern fn bytes_reserve(buffer: ByteBuffer*, needed: usize): bool;

extern fn bytes_append(buffer: ByteBuffer*, source: u8*, count: usize): bool;

extern fn bytes_push(buffer: ByteBuffer*, value: u8): bool;

extern fn bytes_dispose(buffer: ByteBuffer*): void;

import tower;

// Raw byte-buffer ownership. Initialize once, dispose once; structs are not copied.
// Growth may move data. Failure preserves the pointer, length, capacity and bytes.
struct ByteBuffer {
    data: u8*;
    length: usize;
    capacity: usize;
}

import tower;
import work_graph;

enum CompilerQuery: u32 {
    Unit, Join
}

// Transport-independent coordinator for isolated compilation contexts. Unit
// ordinals are stable recipe/source order. The host transports sources and owned
// artifacts; it never shares entity pointers or LLVM contexts between workers.
struct CompilerWork {
    graph: WorkGraph;
    units: usize;
    workers: usize;
    completed: usize;
    settled: usize;
    failed: usize;
    peak: usize;
}

export fn compiler_work_close(work: CompilerWork*): void {
    if work != null {
        work_dispose(&work.graph);
        free(work);
    }
}

export fn compiler_work_create(units: usize, workers: usize, revision: u64, profile: u64): CompilerWork* {
    var invalid = units == 0;
    invalid ||= workers == 0;
    if invalid {
        return null;
    }
    var work = alloc(CompilerWork, 1);
    if work == null {
        return null;
    }
    fill(work, 0, sizeof(CompilerWork));
    work_init(&work.graph, revision, profile);
    work.units = units;
    work.workers = workers;
    var i: usize = 0;
    for(; i < units; i++) {
        var task = work_request(&work.graph, null, convert(u32, CompilerQuery.Unit), convert(u64, i));
        if !work_seal(&work.graph, task) {
            compiler_work_close(work);
            return null;
        }
    }
    var join = work_request(&work.graph, null, convert(u32, CompilerQuery.Join), 0);
    i = 0;
    for(; i < units; i++) {
        var task = i + 1;
        if !work_depend(&work.graph, join, task) {
            compiler_work_close(work);
            return null;
        }
    }
    var valid = work_seal(&work.graph, join);
    valid &&= work_demand(&work.graph, join);
    if !valid {
        compiler_work_close(work);
        return null;
    }
    return work;
}

export fn compiler_work_next(work: CompilerWork*): usize {
    // Tickets are admitted in source order. After a failure, every earlier
    // ordinal has already been admitted; settle those, never start later work.
    var failed = work.failed != 0;
    if failed {
        return 0;
    }
    if work.graph.running >= work.workers {
        return 0;
    }
    var ticket: WorkTicket;
    if work_take(&work.graph, &ticket) {
        if ticket.task > work.units {
            work_finish(&work.graph, &ticket, true);
            return 0;
        }
        if work.graph.running > work.peak {
            work.peak = work.graph.running;
        }
        return ticket.task;
    }
    return 0;
}

export fn compiler_work_accept(work: CompilerWork*, unit: usize, revision: u64, profile: u64, success: bool): bool {
    var invalid = unit == 0;
    invalid ||= unit > work.units;
    if invalid {
        return false;
    }
    var ticket: WorkTicket;
    ticket.task = unit;
    ticket.revision = revision;
    ticket.profile = profile;
    if !work_finish(&work.graph, &ticket, success) {
        return false;
    }
    work.completed++;
    // Advance a dense completion prefix once per unit, rather than rescanning
    // every earlier task for every out-of-order receipt in a large project.
    while work.settled < work.units {
        var next = work.settled + 1;
        var task = work_task(&work.graph, next);
        var settled = task.state == WorkState.Succeeded;
        settled ||= task.state == WorkState.Failed;
        if !settled {
            break;
        }
        work.settled = next;
    }
    if !success {
        var earlier = work.failed == 0;
        earlier ||= unit < work.failed;
        if earlier {
            work.failed = unit;
        }
    }
    return true;
}

export fn compiler_work_done(work: CompilerWork*): bool {
    var done = work.completed == work.units;
    var failed = work.failed != 0;
    if failed {
        // A later unit cannot change the first diagnostic. Do not wait for a
        // large unrelated compilation before reporting an earlier failure.
        done = work.settled >= work.failed;
    }
    done &&= work_ok(&work.graph);
    return done;
}

// Failures are decided after all earlier work settles. The executor must then
// cancel/drain later workers before closing the coordinator. No failed-build
// artifact is published, independent of completion order.
export fn compiler_work_failed(work: CompilerWork*): usize {
    return work.failed;
}

export fn compiler_work_peak(work: CompilerWork*): usize {
    return work.peak;
}

export fn compiler_work_cancel(work: CompilerWork*): void {
    work_cancel(&work.graph);
}

import tower;

// Shared compiler entities. Raw pointers are valid only while their owner lives.
// Components keep stable addresses; type indexes support component-wise queries.
struct EntityStore {
    next_id: usize;
    entity_count: usize;
    component_count: usize;
    views: usize;
    deferred: Entity*;
    reclaiming: usize;
}

struct EntityChild {
    entity: Entity*;
    name: u8*;
}

struct Entity {
    store: EntityStore*;
    id: usize;
    references: usize;
    parent: Entity*;
    children: EntityChild*;
    child_count: usize;
    child_capacity: usize;
    components: EntityComponent**;
    component_count: usize;
    component_capacity: usize;
    instances: EntityComponent**;
    instance_count: usize;
    instance_capacity: usize;
    registered: bool;
    queued: bool;
    data_size: usize;
    data_alignment: usize;
    lifecycle: usize;
    deferred: Entity*;
}

// The coordinator opens/closes views and owns refcounts. Workers borrow the
// view and query ranges until they join; no worker mutates this bookkeeping.
// Payload access still needs declared read/write permissions. A view pins
// structure and lifetime, not arbitrary writes through Foundation raw pointers.
struct EntityView {
    store: EntityStore*;
}

struct EntityQuery {
    data: EntityComponent**;
    length: usize;
}

struct EntityComponent {
    owner: Entity*;
    type: Entity*;
    allocation: u8*;
    data: u8*;
    type_index: usize;
}

// Transitional host bridge for existing native payload destructors; zero means none.
// A Tower client can supply its own ordinary Tower dispatch function instead.
extern fn tower_entity_finalize(lifecycle: usize, component: EntityComponent*, data: u8*): void;

export fn entity_store_create(): EntityStore* {
    var store = alloc(EntityStore, 1);
    if store != null {
        fill(store, 0, sizeof(EntityStore));
    }
    return store;
}

// The store is borrowed by its entities and cannot be disposed while any live.
export fn entity_store_dispose(store: EntityStore*): bool {
    var occupied = store.entity_count != 0;
    occupied ||= store.views != 0;
    if occupied {
        return false;
    }
    free(store);
    return true;
}

export fn entity_create(store: EntityStore*): Entity* {
    if store.views != 0 {
        return null;
    }
    var next = store.next_id + 1;
    if next == 0 {
        return null;
    }
    var entity = alloc(Entity, 1);
    if entity == null {
        return null;
    }
    fill(entity, 0, sizeof(Entity));
    entity.store = store;
    entity.id = store.next_id;
    entity.references = 1;
    store.next_id = next;
    store.entity_count++;
    return entity;
}

export fn entity_retain(entity: Entity*): usize {
    entity.references++;
    return entity.references;
}

// Allocate an unattached entity in an existing entity's store.
export fn entity_create_related(entity: Entity*): Entity* {
    return entity_create(entity.store);
}

// Ownership must be acyclic. Query cursors are invalidated by structural edits.
export fn entity_release(entity: Entity*): usize {
    entity.references--;
    var remaining = entity.references;
    if remaining != 0 {
        return remaining;
    }
    var pinned = entity.store.views != 0;
    pinned ||= entity.queued;
    if pinned {
        if !entity.queued {
            entity.deferred = entity.store.deferred;
            entity.store.deferred = entity;
            entity.queued = true;
        }
    } else {
        entity_reclaim(entity);
    }
    return 0;
}

fn entity_reclaim(entity: Entity*): void {
    var store = entity.store;
    store.reclaiming++;
    var i: usize = 0;
    for(; i != entity.child_count; i++) {
        var child = entity.children[i].entity;
        child.parent = null;
        free(entity.children[i].name);
        entity_release(child);
    }
    i = 0;
    for(; i != entity.component_count; i++) {
        entity_component_dispose(entity.components[i]);
    }
    free(entity.children);
    free(entity.components);
    free(entity.instances);
    store.entity_count--;
    free(entity);
    store.reclaiming--;
}

// Opening a view is an owning operation on the store's lifetime. The anchor
// need not be the root; every type index in this same store becomes stable.
// Close exactly once, after all borrowed queries/workers finish.
export fn entity_view_open(anchor: Entity*): EntityView* {
    var missing = anchor == null;
    if missing {
        return null;
    }
    var store = anchor.store;
    var reclaiming = store.reclaiming != 0;
    if reclaiming {
        return null;
    }
    var next = store.views + 1;
    if next == 0 {
        return null;
    }
    var view = alloc(EntityView, 1);
    missing = view == null;
    if missing {
        return null;
    }
    view.store = store;
    store.views = next;
    return view;
}

export fn entity_view_close(view: EntityView*): void {
    var store = view.store;
    free(view);
    store.views--;
    if store.views != 0 {
        return;
    }
    while store.deferred != null {
        var entity = store.deferred;
        store.deferred = entity.deferred;
        entity.deferred = null;
        entity.queued = false;
        if entity.references == 0 {
            entity_reclaim(entity);
        }
    }
}

// A borrowed dense pointer range over the authoritative stable payloads.
// Empty/end batches succeed, invalid/cross-world ranges preserve the output.
export fn entity_view_query(view: EntityView*, type: Entity*, first: usize, count: usize, result: EntityQuery*): bool {
    var invalid = type.store != view.store;
    if invalid {
        return false;
    }
    invalid = first > type.instance_count;
    if invalid {
        return false;
    }
    var remaining = type.instance_count -first;
    invalid = count > remaining;
    if invalid {
        return false;
    }
    var data: EntityComponent** = null;
    if count != 0 {
        data = type.instances + first;
    }
    result.data = data;
    result.length = count;
    return true;
}

// Component types are ordinary entities with a consistent layout/lifecycle.
export fn entity_register(type: Entity*, size: usize, alignment: usize, lifecycle: usize): bool {
    if alignment == 0 {
        return false;
    }
    var mask = alignment -1;
    var bits = alignment &mask;
    if bits != 0 {
        return false;
    }
    if type.registered {
        var same = type.data_size == size;
        same &&= type.data_alignment == alignment;
        same &&= type.lifecycle == lifecycle;
        return same;
    }
    if type.store.views != 0 {
        return false;
    }
    type.data_size = size;
    type.data_alignment = alignment;
    type.lifecycle = lifecycle;
    type.registered = true;
    return true;
}

export fn entity_component_get(owner: Entity*, type: Entity*): EntityComponent* {
    var i: usize = 0;
    loop {
        if i == owner.component_count {
            return null;
        }
        var component = owner.components[i];
        if component.type == type {
            return component;
        }
        i++;
    }
}

// Reserve helpers keep indexes separate from component payloads.
fn entity_reserve_components(data: EntityComponent***, capacity: usize*, count: usize): bool {
    if count < *capacity {
        return true;
    }
    var next = *capacity *2;
    if next < *capacity {
        return false;
    }
    if next < 4 {
        next = 4;
    }
    var memory = realloc(EntityComponent*, *data, next);
    if memory == null {
        return false;
    }
    *data = memory;
    *capacity = next;
    return true;
}

export fn entity_component_add(owner: Entity*, type: Entity*): EntityComponent* {
    var present = entity_component_get(owner, type);
    if present != null {
        return present;
    }
    if owner.store.views != 0 {
        return null;
    }
    if owner.store != type.store {
        return null;
    }
    if !type.registered {
        return null;
    }
    var ok = entity_reserve_components(&owner.components, &owner.component_capacity, owner.component_count);
    ok &&= entity_reserve_components(&type.instances, &type.instance_capacity, type.instance_count);
    if !ok {
        return null;
    }
    var alignment = type.data_alignment;
    var pointer_size = sizeof(EntityComponent*);
    if alignment < pointer_size {
        alignment = pointer_size;
    }
    var extra = alignment -1;
    extra = extra + pointer_size;
    var wrapped = extra < alignment;
    if wrapped {
        return null;
    }
    var bytes = type.data_size + extra;
    wrapped = bytes < type.data_size;
    if wrapped {
        return null;
    }
    var payload_bytes = bytes;
    bytes = bytes + sizeof(EntityComponent);
    wrapped = bytes < payload_bytes;
    if wrapped {
        return null;
    }
    var allocation = alloc(u8, bytes);
    if allocation == null {
        return null;
    }
    var component = bits(EntityComponent*, allocation);
    var address = bits(usize, allocation);
    address = address + sizeof(EntityComponent);
    address = address + extra;
    address = address / alignment;
    address = address * alignment;
    var data = bits(u8*, address);
    var back = bits(EntityComponent **, data);
    back--;
    *back = component;
    component.owner = owner;
    component.type = type;
    component.allocation = allocation;
    component.data = data;
    component.type_index = type.instance_count;
    owner.components[owner.component_count] = component;
    owner.component_count++;
    type.instances[type.instance_count] = component;
    type.instance_count++;
    entity_retain(type);
    var store = owner.store;
    store.component_count++;
    return component;
}

fn entity_component_dispose(component: EntityComponent*): void {
    var type = component.type;
    type.instance_count--;
    var last = type.instances[type.instance_count];
    type.instances[component.type_index] = last;
    last.type_index = component.type_index;
    if type.lifecycle != 0 {
        tower_entity_finalize(type.lifecycle, component, component.data);
    }
    var store = type.store;
    store.component_count--;
    free(component.allocation);
    entity_release(type);
}

export fn entity_component_remove(owner: Entity*, type: Entity*): bool {
    if owner.store.views != 0 {
        return false;
    }
    var i: usize = 0;
    loop {
        if i == owner.component_count {
            return false;
        }
        var component = owner.components[i];
        if component.type == type {
            owner.component_count--;
            var following = i + 1;
            var count = owner.component_count -i;
            var bytes = count *sizeof(EntityComponent*);
            copy(&owner.components[i], &owner.components[following], bytes);
            entity_component_dispose(component);
            return true;
        }
        i++;
    }
}

export fn entity_component_data(component: EntityComponent*): u8* {
    if component == null {
        return null;
    }
    return component.data;
}

export fn entity_component_from_data(data: u8*): EntityComponent* {
    if data == null {
        return null;
    }
    var back = bits(EntityComponent **, data);
    back--;
    return *back;
}

export fn entity_query_count(type: Entity*): usize {
    return type.instance_count;
}

export fn entity_query_at(type: Entity*, index: usize): EntityComponent* {
    if index >= type.instance_count {
        return null;
    }
    return type.instances[index];
}

fn entity_name_equal(left: u8*, right: u8*): bool {
    var missing = left == null;
    if missing {
        var both_missing = right == null;
        return both_missing;
    }
    missing = right == null;
    if missing {
        return false;
    }
    var i: usize = 0;
    loop {
        if left[i] != right[i] {
            return false;
        }
        if left[i] == 0 {
            return true;
        }
        i++;
    }
}

export fn entity_child_index(parent: Entity*, child: Entity*): usize {
    var i: usize = 0;
    loop {
        if i == parent.child_count {
            var invalid: usize = 0;
            invalid--;
            return invalid;
        }
        if parent.children[i].entity == child {
            return i;
        }
        i++;
    }
}

export fn entity_member_index(parent: Entity*, name: u8*): usize {
    var i: usize = 0;
    loop {
        if i == parent.child_count {
            var invalid: usize = 0;
            invalid--;
            return invalid;
        }
        if entity_name_equal(parent.children[i].name, name) {
            return i;
        }
        i++;
    }
}

fn entity_unlink(child: Entity*): void {
    var parent = child.parent;
    var index = entity_child_index(parent, child);
    free(parent.children[index].name);
    parent.child_count--;
    var following = index + 1;
    var count = parent.child_count -index;
    var bytes = count *sizeof(EntityChild);
    copy(&parent.children[index], &parent.children[following], bytes);
    child.parent = null;
}

// Ordered, named containment owns children. Other semantic links remain borrowed.
// Reserve/copy before changing ownership; a failed allocation leaves links intact.
export fn entity_attach(child: Entity*, parent: Entity*, name: u8*): bool {
    if child.store.views != 0 {
        return false;
    }
    if child == parent {
        return false;
    }
    var named: u8* = null;
    var attaching = parent != null;
    if attaching {
        if parent.store != child.store {
            return false;
        }
        if parent.child_count == parent.child_capacity {
            var capacity = parent.child_capacity *2;
            if capacity < parent.child_capacity {
                return false;
            }
            if capacity < 4 {
                capacity = 4;
            }
            var next = realloc(EntityChild, parent.children, capacity);
            var failed = next == null;
            if failed {
                return false;
            }
            parent.children = next;
            parent.child_capacity = capacity;
        }
        var has_name = name != null;
        has_name &&= *name != 0;
        if has_name {
            var length: usize = 0;
            for(; !(name[length] == 0); length++) {}
            length++;
            named = alloc(u8, length);
            var failed = named == null;
            if failed {
                return false;
            }
            copy(named, name, length);
        }
    }
    var attached = child.parent != null;
    if attached {
        // Transfer the old parent's reference directly to the new relationship.
        entity_unlink(child);
    } else {
        if attaching {
            entity_retain(child);
        }
    }
    if attaching {
        var has_name = named != null;
        if has_name {
            var previous = entity_member_index(parent, named);
            if previous < parent.child_count {
                var replaced = parent.children[previous].entity;
                entity_unlink(replaced);
                entity_release(replaced);
            }
        }
        parent.children[parent.child_count].entity = child;
        parent.children[parent.child_count].name = named;
        parent.child_count++;
        child.parent = parent;
    } else {
        if attached {
            entity_release(child);
        }
    }
    return true;
}

export fn entity_replace_child(parent: Entity*, index: usize, replacement: Entity*): bool {
    if parent.store.views != 0 {
        return false;
    }
    var invalid = index >= parent.child_count;
    if invalid {
        return false;
    }
    invalid = replacement.parent != null;
    if invalid {
        return false;
    }
    invalid = replacement == parent;
    if invalid {
        return false;
    }
    invalid = replacement.store != parent.store;
    if invalid {
        return false;
    }
    var previous = parent.children[index].entity;
    entity_retain(replacement);
    replacement.parent = parent;
    parent.children[index].entity = replacement;
    previous.parent = null;
    entity_release(previous);
    return true;
}

export fn entity_take_last_child(parent: Entity*): Entity* {
    if parent.store.views != 0 {
        return null;
    }
    if parent.child_count == 0 {
        return null;
    }
    parent.child_count--;
    var child = parent.children[parent.child_count].entity;
    free(parent.children[parent.child_count].name);
    child.parent = null;
    return child;
}

